INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93431, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "刑法", "is_correct": true, "explanation": "xíng fǎ（第二声、第三声），指规定犯罪与刑罚的法律，即目标词。"}, {"text": "刑罚", "is_correct": false, "explanation": "fá（第二声）与 fǎ（第三声）声调不同，刑罚指对罪犯的处罚，不是法律。"}, {"text": "想法", "is_correct": false, "explanation": "xiǎng（第三声）与 xíng（第二声）韵母 ang 与 ing 不同，声调也不同，想法指念头。"}, {"text": "新法", "is_correct": false, "explanation": "xīn（第一声）与 xíng（第二声）韵母 in 与 ing 不同，声调也不同，新法指新颁布的法律。"}], "explanations": {"刑法": "xíng fǎ（第二声、第三声），指规定犯罪与刑罚的法律，即目标词。", "刑罚": "fá（第二声）与 fǎ（第三声）声调不同，刑罚指对罪犯的处罚，不是法律。", "想法": "xiǎng（第三声）与 xíng（第二声）韵母 ang 与 ing 不同，声调也不同，想法指念头。", "新法": "xīn（第一声）与 xíng（第二声）韵母 in 与 ing 不同，声调也不同，新法指新颁布的法律。"}, "sentence_index": null, "correct_answer": "刑法"}, "level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的功课，不能规定偷东西要受什么罚。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是能够作出规定的东西。"}, {"text": "菜谱", "is_correct": false, "explanation": "搭配：“规定”的主语通常是法律、制度或章程，菜谱是做菜的说明，不能说“菜谱规定……”。"}, {"text": "刑法", "is_correct": true, "explanation": "刑法规定做坏事要怎样受罚，正是这句话所说的内容。"}], "explanations": {"作业": "语义：作业是学生的功课，不能规定偷东西要受什么罚。", "天气": "语义：天气是自然现象，不是能够作出规定的东西。", "菜谱": "搭配：“规定”的主语通常是法律、制度或章程，菜谱是做菜的说明，不能说“菜谱规定……”。", "刑法": "刑法规定做坏事要怎样受罚，正是这句话所说的内容。"}, "sentence_index": 0, "correct_answer": "刑法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法官宣布了他的刑法：十年监禁。", "explanation": "这里应该用〈刑罚〉。刑罚是对罪犯的具体处罚，刑法是规定这些处罚的法律本身，不能用来指判决结果。"}, {"text": "我们的刑法规定每个公民都有选举权。", "explanation": "这里应该用〈宪法〉。选举权由宪法规定；刑法只规定犯罪与刑罚，不规定公民的选举权。"}, {"text": "学校的刑法规定不许迟到。", "explanation": "这里应该用〈校规〉。刑法只规定国家的犯罪与刑罚，学校的纪律不属于刑法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93431, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地图", "is_correct": false, "explanation": "语义：地图标示地理位置，不能告诉人们哪些事不能做。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的用具，不能告诉人们哪些事不能做。"}, {"text": "镜子", "is_correct": false, "explanation": "搭配：“告诉人们哪些事不能做”的主语多是法律、规章或人，“镜子”不能充当这一动作的主语。"}, {"text": "刑法", "is_correct": true, "explanation": "刑法明确规定哪些行为是犯罪，正与句意相符。"}], "explanations": {"地图": "语义：地图标示地理位置，不能告诉人们哪些事不能做。", "雨伞": "语义：雨伞是遮雨的用具，不能告诉人们哪些事不能做。", "镜子": "搭配：“告诉人们哪些事不能做”的主语多是法律、规章或人，“镜子”不能充当这一动作的主语。", "刑法": "刑法明确规定哪些行为是犯罪，正与句意相符。"}, "sentence_index": 6, "correct_answer": "刑法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "房东和租客的纠纷要按刑法来处理。", "explanation": "这里应该用〈民法〉。房东与租客的纠纷属于民事关系，要用民法处理；刑法只规定犯罪和刑罚。"}, {"text": "这个刑法已经审完了。", "explanation": "这里应该用〈案件〉。审完的是案件，刑法是法律条文，不能被审理；“这个案件已经审完了”才通顺。"}, {"text": "他的刑法是抢劫。", "explanation": "这里应该用〈罪名〉。刑法是规定犯罪与刑罚的法律，不是某人的罪；“他的罪名是抢劫”才说得通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多年轻人跟刑法感兴趣。", "corrected_sentence": "很多年轻人对刑法感兴趣。", "error_description": "介词错误：“感兴趣”的对象要用介词“对”引出，应写作“对刑法感兴趣”，不能用“跟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆里有一张新的刑法。", "corrected_sentence": "图书馆里有一部新的刑法。", "error_description": "量词错误：“张”用于纸张、桌子等平面的东西，刑法是法典，应该用“部”，写作“一部新的刑法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93432, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
