INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93432, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "规定犯罪和刑罚的法律。", "primary_collocate": null, "pronunciation": "xíng fǎ", "ipa": "ɕiŋ˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "刑法规定了什么是犯罪。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的刑法一直在修改。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是研究刑法的教授。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刑法里有很多关于抢劫的内容。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家用刑法保护大家的安全。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子要按刑法来处理。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师熟悉刑法的每一条。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新刑法昨天开始实行了。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刑法对杀人的规定很严。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学法律的学生必须学刑法。", "target_word": "刑法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}], "register": "中性", "sense_fingerprint": "刑法：规定什么是犯罪以及如何处罚的法律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30121eb2-4bca-4011-9a89-398f42fd683f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93432, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "刑法", "is_correct": true, "explanation": "xíng fǎ（第二声、第三声），指规定什么是犯罪以及如何处罚的法律，即目标词。"}, {"text": "刑罚", "is_correct": false, "explanation": "fá（第二声）与 fǎ（第三声）声调不同，刑罚指对罪犯的处罚，不是法律。"}, {"text": "想法", "is_correct": false, "explanation": "xiǎng（第三声）与 xíng（第二声）韵母 ang 与 ing 不同，声调也不同，想法指念头。"}, {"text": "新法", "is_correct": false, "explanation": "xīn（第一声）与 xíng（第二声）韵母 in 与 ing 不同，声调也不同，新法指新颁布的法律。"}], "explanations": {"刑法": "xíng fǎ（第二声、第三声），指规定什么是犯罪以及如何处罚的法律，即目标词。", "刑罚": "fá（第二声）与 fǎ（第三声）声调不同，刑罚指对罪犯的处罚，不是法律。", "想法": "xiǎng（第三声）与 xíng（第二声）韵母 ang 与 ing 不同，声调也不同，想法指念头。", "新法": "xīn（第一声）与 xíng（第二声）韵母 in 与 ing 不同，声调也不同，新法指新颁布的法律。"}, "sentence_index": null, "correct_answer": "刑法"}, "level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不能规定什么是犯罪。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能规定什么是犯罪。"}, {"text": "菜谱", "is_correct": false, "explanation": "搭配：“规定什么是犯罪”要以法律、制度为主语，菜谱不能这样说。"}, {"text": "刑法", "is_correct": true, "explanation": "刑法规定了什么是犯罪，正与句意相符。"}], "explanations": {"作业": "语义：作业是学习任务，不能规定什么是犯罪。", "天气": "语义：天气是自然现象，不能规定什么是犯罪。", "菜谱": "搭配：“规定什么是犯罪”要以法律、制度为主语，菜谱不能这样说。", "刑法": "刑法规定了什么是犯罪，正与句意相符。"}, "sentence_index": 0, "correct_answer": "刑法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他承认了自己的刑法。", "explanation": "这里应该用〈罪行〉。罪行指犯人做的坏事，刑法是法律，不能指某人所做的事。"}, {"text": "公民的基本权利由刑法规定。", "explanation": "这里应该用〈宪法〉。公民的基本权利由宪法规定，刑法只规定犯罪与刑罚，不规定权利。"}, {"text": "房屋买卖的纠纷要按刑法来处理。", "explanation": "这里应该用〈民法〉。房屋买卖属于民事纠纷，应按民法处理；刑法只规定犯罪和刑罚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：河流没有条文，律师不会熟悉河流的每一条。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾是衣物，“熟悉围巾的每一条”讲不通，律师不需要熟悉围巾。"}, {"text": "镜子", "is_correct": false, "explanation": "搭配：“熟悉……的每一条”的对象多是条文、规定，“镜子”不能这样搭配。"}, {"text": "刑法", "is_correct": true, "explanation": "刑法的条文是律师需要熟悉的，句中“每一条”指刑法的条文。"}], "explanations": {"河流": "语义：河流没有条文，律师不会熟悉河流的每一条。", "围巾": "语义：围巾是衣物，“熟悉围巾的每一条”讲不通，律师不需要熟悉围巾。", "镜子": "搭配：“熟悉……的每一条”的对象多是条文、规定，“镜子”不能这样搭配。", "刑法": "刑法的条文是律师需要熟悉的，句中“每一条”指刑法的条文。"}, "sentence_index": 6, "correct_answer": "刑法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同的刑法写得很清楚。", "explanation": "这里应该用〈条款〉。条款是合同中的具体规定；刑法是法律体系，不能指合同里的条文。"}, {"text": "这份刑法很有说服力。", "explanation": "这里应该用〈证据〉。证据才有说服力；刑法是法律条文，不能用来证明事实或说服别人。"}, {"text": "警察抓住了那个刑法。", "explanation": "这里应该用〈嫌疑人〉。刑法是法律，不是人，不能被抓；“那个嫌疑人”才是被抓的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把刑法规定得很细。", "corrected_sentence": "这部刑法规定得很细。", "error_description": "量词错误：“把”用于有柄的器具，刑法是法典，应该用“部”，写作“这部刑法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学法律的人都要刑法有所了解。", "corrected_sentence": "学法律的人都要对刑法有所了解。", "error_description": "介词缺失：“有所了解”的对象要用介词“对”引出，应写作“对刑法有所了解”，不能让名词“刑法”直接跟在“要”后面再接“有所了解”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
