INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93433, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "望是用眼睛往远处看。", "primary_collocate": null, "pronunciation": "wàng", "ipa": "wɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "她站在海边，望着远方的小船。", "target_word": "望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我抬头望天，天空一朵云也没有。", "target_word": "望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸坐在门前，望着远处的田地。", "target_word": "望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从火车窗口望出去，外面全是山。", "target_word": "望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们望着天空中的飞机，不停地叫。", "target_word": "望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登上高楼，我们可以望见整个城市。", "target_word": "望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人站在路口，望了很久。", "target_word": "望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你往前面望一望，那儿有没有车？", "target_word": "望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他望着远处的灯光，慢慢走回家。", "target_word": "望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们爬上山顶，向南望去，是一片大湖。", "target_word": "望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "望着", "label": "体标"}, {"form": "望了", "label": "体标"}, {"form": "望过", "label": "体标"}, {"form": "望一望", "label": "重叠"}], "register": "书面", "sense_fingerprint": "用眼睛往远处看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef5a13e9-5998-47ea-85ae-a1bc01b8e6de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93433, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "望", "is_correct": true, "explanation": "望 wàng：目标词，表示用眼睛往远处看。"}, {"text": "王", "is_correct": false, "explanation": "wáng（第二声）与 wàng（第四声）声调不同，意思是君王。"}, {"text": "网", "is_correct": false, "explanation": "wǎng（第三声）与 wàng（第四声）声调不同，意思是网子。"}, {"text": "万", "is_correct": false, "explanation": "wàn 与 wàng 韵母不同（-n 与 -ng），意思是一万。"}, {"text": "烫", "is_correct": false, "explanation": "tàng 与 wàng 声母不同（t 与 w），意思是烫热。"}], "explanations": {"望": "望 wàng：目标词，表示用眼睛往远处看。", "王": "wáng（第二声）与 wàng（第四声）声调不同，意思是君王。", "网": "wǎng（第三声）与 wàng（第四声）声调不同，意思是网子。", "万": "wàn 与 wàng 韵母不同（-n 与 -ng），意思是一万。", "烫": "tàng 与 wàng 声母不同（t 与 w），意思是烫热。"}, "sentence_index": null, "correct_answer": "望"}, "level_3": {"options": [{"text": "望", "is_correct": true, "explanation": "望：与「站在海边」搭配，表示朝远方看小船。"}, {"text": "摸", "is_correct": false, "explanation": "语义：远方的小船无法用手摸到，与“远方”矛盾。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”通常指扔近处的东西，不能说扔远方的小船。"}, {"text": "修", "is_correct": false, "explanation": "语义：远方的小船不能被修理，与“远方”矛盾。"}], "explanations": {"望": "望：与「站在海边」搭配，表示朝远方看小船。", "摸": "语义：远方的小船无法用手摸到，与“远方”矛盾。", "扔": "搭配：“扔”通常指扔近处的东西，不能说扔远方的小船。", "修": "语义：远方的小船不能被修理，与“远方”矛盾。"}, "sentence_index": 0, "correct_answer": "望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在屋里望一本书。", "explanation": "这里应该用〈看〉。望指朝远处看，读书要用“看”。"}, {"text": "老师望了作业，很快就批改完了。", "explanation": "这里应该用〈批改〉。望指朝远处看，给作业打分要用“批改”。"}, {"text": "他站在镜子前，望好了领带。", "explanation": "这里应该用〈系〉。望是用眼睛远看，给领带打结要用“系”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93433, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "望", "is_correct": true, "explanation": "望 wàng：目标词，表示用眼睛往远处看。"}, {"text": "往", "is_correct": false, "explanation": "wǎng（第三声）与 wàng（第四声）声调不同，意思是朝、向。"}, {"text": "问", "is_correct": false, "explanation": "wèn 与 wàng 韵母不同（-n 与 -ng），意思是询问。"}, {"text": "放", "is_correct": false, "explanation": "fàng 与 wàng 声母不同（f 与 w），意思是放置。"}, {"text": "样", "is_correct": false, "explanation": "yàng 与 wàng 声母不同（y 与 w），意思是样子。"}], "explanations": {"望": "望 wàng：目标词，表示用眼睛往远处看。", "往": "wǎng（第三声）与 wàng（第四声）声调不同，意思是朝、向。", "问": "wèn 与 wàng 韵母不同（-n 与 -ng），意思是询问。", "放": "fàng 与 wàng 声母不同（f 与 w），意思是放置。", "样": "yàng 与 wàng 声母不同（y 与 w），意思是样子。"}, "sentence_index": null, "correct_answer": "望"}, "level_3": {"options": [{"text": "望", "is_correct": true, "explanation": "望：与「站在路口」搭配，表示朝远处看，符合「望了很久」。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”与“站在路口”矛盾，人不能一边站着一边跑。"}, {"text": "走", "is_correct": false, "explanation": "语义：“走”与“站在路口”矛盾，句子前后的动作不一致。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”是一次性的动作，不能与表示持续时间的“很久”搭配。"}], "explanations": {"望": "望：与「站在路口」搭配，表示朝远处看，符合「望了很久」。", "跑": "语义：“跑”与“站在路口”矛盾，人不能一边站着一边跑。", "走": "语义：“走”与“站在路口”矛盾，句子前后的动作不一致。", "摔": "搭配：“摔”是一次性的动作，不能与表示持续时间的“很久”搭配。"}, "sentence_index": 6, "correct_answer": "望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在本子上望字，写得很认真。", "explanation": "这里应该用〈写〉。望指朝远处看，在本子上写字要用“写”。"}, {"text": "我在房间里望音乐，很放松。", "explanation": "这里应该用〈听〉。望是用眼睛看，听音乐要用“听”。"}, {"text": "妈妈望了一口汤，觉得咸了。", "explanation": "这里应该用〈尝〉。望是用眼睛远看，尝味道要用“尝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我站在楼上，望着了远处的湖。", "corrected_sentence": "我站在楼上，望见了远处的湖。", "error_description": "错误在于“望”的补语。“望着”表示持续地看，不能与“了”连用；表示看到要用补语“见”，说“望见了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她窗外望了一眼，什么也没看见。", "corrected_sentence": "她往窗外望了一眼，什么也没看见。", "error_description": "错误在于处所“窗外”前缺少介词。应加“往”引出方向，说“往窗外望了一眼”，不能直接说“窗外望了一眼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d48d0ce-3300-4f95-9c4b-08120cf47d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
