INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93436, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "重大日子或事件到来之前的晚上或时期。", "primary_collocate": null, "pronunciation": "qián xī", "ipa": "tɕʰjɛn˧˥ ɕi˥", "syllable_count": 2, "sentences": [{"text": "比赛前夕，队员们都很紧张。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节前夕，街上挂满了红灯笼。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前夕，他一直在复习功课。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼前夕，新娘一直睡不着。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业前夕，同学们互相写了留言。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发前夕，我又检查了一遍行李。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国庆前夕，广场上摆满了鲜花。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大会前夕，工作人员忙到很晚。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争前夕，这个小城还很平静。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出前夕，演员们在台上最后排练了一次。", "target_word": "前夕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "重大日子或事件到来之前的晚上或时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe3a350-bc50-478f-b45d-f14fb4a51d8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "墨水", "is_correct": false, "explanation": "语义：墨水是液体，不表示时间，“比赛墨水”说不通。"}, {"text": "前夕", "is_correct": true, "explanation": "“前夕”指比赛这类大事来临前的一段时间，放在“比赛”后面正合适。"}, {"text": "假期", "is_correct": false, "explanation": "搭配：“比赛”后面不能接“假期”，二者无法组合成表示时间的词语。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是随身的物品，与比赛的时间无关。"}], "explanations": {"墨水": "语义：墨水是液体，不表示时间，“比赛墨水”说不通。", "前夕": "“前夕”指比赛这类大事来临前的一段时间，放在“比赛”后面正合适。", "假期": "搭配：“比赛”后面不能接“假期”，二者无法组合成表示时间的词语。", "钱包": "语义：钱包是随身的物品，与比赛的时间无关。"}, "sentence_index": 0, "correct_answer": "前夕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个项目前夕进展很顺利。", "explanation": "这里应该用〈前期〉。“前期”指项目的初始阶段，“前夕”指重大日子来临前的晚上或时期，不能用来指项目的阶段。"}, {"text": "我前夕收到了一封信。", "explanation": "这里应该用〈前天〉。“前夕”只用于重大日子或事件来临前，普通的日子不能用。"}, {"text": "前夕我睡得很好。", "explanation": "这里应该用〈前一晚〉。“前夕”要指大事来临前，普通的前一晚不能说“前夕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "树叶", "is_correct": false, "explanation": "语义：树叶是植物的一部分，不表示节日前的时间，“国庆树叶”说不通。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是物品，不能指节日来临前的时间段。"}, {"text": "前夕", "is_correct": true, "explanation": "“前夕”指国庆这样的节日来临前的时间，与“国庆”搭配正确。"}, {"text": "期中", "is_correct": false, "explanation": "搭配：“期中”指学期的中间阶段，不能与“国庆”组合。"}], "explanations": {"树叶": "语义：树叶是植物的一部分，不表示节日前的时间，“国庆树叶”说不通。", "鞋子": "语义：鞋子是物品，不能指节日来临前的时间段。", "前夕": "“前夕”指国庆这样的节日来临前的时间，与“国庆”搭配正确。", "期中": "搭配：“期中”指学期的中间阶段，不能与“国庆”组合。"}, "sentence_index": 6, "correct_answer": "前夕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我前夕去跑步了。", "explanation": "这里应该用〈早晨〉。“前夕”指重大事件来临前的时间，普通的早晨去跑步不能用“前夕”。"}, {"text": "这个计划的前夕很好。", "explanation": "这里应该用〈前景〉。“前景”指发展的前途，“前夕”只指时间，不能用来说计划的前途。"}, {"text": "这首歌的前夕太长了。", "explanation": "这里应该用〈前奏〉。“前奏”指歌曲开头的部分，“前夕”指重大日子之前的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台风登陆前夕地，超市里挤满了人。", "corrected_sentence": "台风登陆前夕，超市里挤满了人。", "error_description": "“前夕”是名词，后面不能加“地”修饰，应说“台风登陆前夕，……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司年会前夕们，大家都在加班。", "corrected_sentence": "公司年会前夕，大家都在加班。", "error_description": "“前夕”后面多加了“们”。“前夕”是表示时间的名词，不能加“们”表示复数，应说“公司年会前夕，……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93437, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93437, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93437, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "本就是一开始就是这样，不是后来才这样。", "primary_collocate": null, "pronunciation": "běn jiù", "ipa": "pən˨˩ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个湖本就在这里，不是人造的。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的性格本就开朗，不是现在才变的。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路本就很窄，不是因为修路才窄。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她本就是南方人，不是搬去的。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地本就是我家的，不是借来的。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音本就很小，不是感冒才这样。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的毛本就是白色的，不是洗白的。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥本就叫长桥，不是后来改的名。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本就不会游泳，不是今天才怕水。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那件衣服本就破了，不是我弄坏的。", "target_word": "本就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，强调状态从一开始就如此，不是后来形成的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f5f24a-08cb-4f02-a962-6cffc7a480b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93437, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "本就", "is_correct": true, "explanation": "正确答案。本就（běn jiù）意思是从一开始就如此。"}, {"text": "本剧", "is_correct": false, "explanation": "jù（第四声）与 jiù（第四声）的韵母不同，少了 i，意思是这部剧。"}, {"text": "本届", "is_correct": false, "explanation": "jiè（第四声）与 jiù（第四声）的韵母不同（è 与 ù），意思是这一届。"}, {"text": "本季", "is_correct": false, "explanation": "jì（第四声）与 jiù（第四声）的韵母不同，少了 u，意思是本季度。"}, {"text": "很旧", "is_correct": false, "explanation": "hěn（第三声）与 běn（第三声）的声母不同（h 与 b），意思是很旧。"}], "explanations": {"本就": "正确答案。本就（běn jiù）意思是从一开始就如此。", "本剧": "jù（第四声）与 jiù（第四声）的韵母不同，少了 i，意思是这部剧。", "本届": "jiè（第四声）与 jiù（第四声）的韵母不同（è 与 ù），意思是这一届。", "本季": "jì（第四声）与 jiù（第四声）的韵母不同，少了 u，意思是本季度。", "很旧": "hěn（第三声）与 běn（第三声）的声母不同（h 与 b），意思是很旧。"}, "sentence_index": null, "correct_answer": "本就"}, "level_3": {"options": [{"text": "本就", "is_correct": true, "explanation": "正确。本就表示湖从一开始就在这里，与“不是人造的”相合。"}, {"text": "又", "is_correct": false, "explanation": "语义：又表示再次或累加，句中没有先前的情况，“这个湖又在这里”说不通。"}, {"text": "更", "is_correct": false, "explanation": "搭配：更通常修饰形容词或用于比较句，不与“在这里”这样的处所动词搭配。"}, {"text": "突然", "is_correct": false, "explanation": "语义：突然表示事情忽然发生，与“不是人造的”强调湖原本就在的背景不符。"}], "explanations": {"本就": "正确。本就表示湖从一开始就在这里，与“不是人造的”相合。", "又": "语义：又表示再次或累加，句中没有先前的情况，“这个湖又在这里”说不通。", "更": "搭配：更通常修饰形容词或用于比较句，不与“在这里”这样的处所动词搭配。", "突然": "语义：突然表示事情忽然发生，与“不是人造的”强调湖原本就在的背景不符。"}, "sentence_index": 0, "correct_answer": "本就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她本就刚搬来这里，大家都不熟悉。", "explanation": "这里不能用〈本就〉。〈本就〉表示一直如此、不是后来形成，而句中说的是新近才发生的变动，两者意思矛盾。"}, {"text": "她本就变成了南方人，口音早就变了。", "explanation": "这里不能用〈本就〉。〈本就〉表示从一开始就如此，而句中说的是后来才发生的改变，两者意思矛盾。"}, {"text": "她本就已经搬走了，现在几乎找不到她。", "explanation": "这里不能用〈本就〉。〈本就〉表示从一开始就是这样，而句中说的是后来才发生的搬离，两者意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93437, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "本就", "is_correct": true, "explanation": "正确答案。本就（běn jiù）意思是从一开始就如此。"}, {"text": "半旧", "is_correct": false, "explanation": "bàn（第四声）与 běn（第三声）的声调不同，后一音节 jiù 相同，意思是半新不旧。"}, {"text": "本局", "is_correct": false, "explanation": "jú（第二声）与 jiù（第四声）的韵母和声调都不同，前一音节 běn 相同，意思是这一局。"}, {"text": "本价", "is_correct": false, "explanation": "jià（第四声）与 jiù（第四声）的韵母不同（a 与 u），意思是这个价格。"}], "explanations": {"本就": "正确答案。本就（běn jiù）意思是从一开始就如此。", "半旧": "bàn（第四声）与 běn（第三声）的声调不同，后一音节 jiù 相同，意思是半新不旧。", "本局": "jú（第二声）与 jiù（第四声）的韵母和声调都不同，前一音节 běn 相同，意思是这一局。", "本价": "jià（第四声）与 jiù（第四声）的韵母不同（a 与 u），意思是这个价格。"}, "sentence_index": null, "correct_answer": "本就"}, "level_3": {"options": [{"text": "本就", "is_correct": true, "explanation": "正确。本就表示小狗的毛从一开始就是白色，与“不是洗白的”相合。"}, {"text": "终于", "is_correct": false, "explanation": "语义：终于表示经过一段过程后才出现，与“本就是白色的”的从来如此相反。"}, {"text": "渐渐", "is_correct": false, "explanation": "搭配：渐渐修饰逐步发生的变化，不与“是白色的”这种判断搭配。"}, {"text": "逐渐", "is_correct": false, "explanation": "搭配：逐渐与渐渐同义，同样只修饰变化过程，不能用于“是……的”判断。"}], "explanations": {"本就": "正确。本就表示小狗的毛从一开始就是白色，与“不是洗白的”相合。", "终于": "语义：终于表示经过一段过程后才出现，与“本就是白色的”的从来如此相反。", "渐渐": "搭配：渐渐修饰逐步发生的变化，不与“是白色的”这种判断搭配。", "逐渐": "搭配：逐渐与渐渐同义，同样只修饰变化过程，不能用于“是……的”判断。"}, "sentence_index": 6, "correct_answer": "本就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那件衣服本就突然破了，我还没碰过它。", "explanation": "这里不能用〈本就〉。〈本就〉表示一直就是这样，而句中说的是新近才出现的情况，两者意思矛盾。"}, {"text": "那件衣服本就被我弄坏了，我很后悔。", "explanation": "这里不能用〈本就〉。〈本就〉表示从一开始就如此，而句中说的是后来才造成的损坏，两者意思矛盾。"}, {"text": "那件衣服本就送给了朋友，我再也没见过它。", "explanation": "这里不能用〈本就〉。〈本就〉表示从一开始就如此，而句中说的是后来才发生的转送，两者意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套家具本就了木头做的，不是塑料的。", "corrected_sentence": "这套家具本就是木头做的，不是塑料的。", "error_description": "错误形式：“本就了木头做的”，“了”不能用作判断动词。正确形式：“本就是木头做的”，判断句应用“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子本就了朝南，冬天很暖和。", "corrected_sentence": "这间屋子本就朝南，冬天很暖和。", "error_description": "“本就”后面不能直接加动态助词“了”：“本就了朝南”不通。“朝南”是静态状态，不需要“了”，去掉即可，说“这间屋子本就朝南”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
