INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93439, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93439, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "勇士是不怕危险，胆子很大的人。", "primary_collocate": null, "pronunciation": "yǒng shì", "ipa": "jʊŋ˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他是一位不怕危险的勇士。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个勇士一个人走进了山洞。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的勇士打败了大龙。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "勇士们一起冲进火里救人。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都说他是真正的勇士。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做勇士不容易，要有很大的胆子。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个勇士从来没有怕过黑夜。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他像勇士一样，跳进河里救孩子。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里有一个勇士的传说。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明想当勇士，不怕黑，也不怕狗。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位勇士", "label": "量词"}, {"form": "一个勇士", "label": "量词"}, {"form": "勇士们", "label": "复数"}], "register": "中性", "sense_fingerprint": "不怕危险、胆子大的人；故事、救人情境中的英勇者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b15c5566-b911-4b10-82c3-0d833210f232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93439, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病人", "is_correct": false, "explanation": "搭配：“病人”指患病的人，“不怕危险的病人”搭配不通。"}, {"text": "懦夫", "is_correct": false, "explanation": "语义：“懦夫”指胆小怕事的人，与“不怕危险”正相反。"}, {"text": "勇士", "is_correct": true, "explanation": "正确：“勇士”指不怕危险、胆子很大的人，与句意一致。"}, {"text": "胆小鬼", "is_correct": false, "explanation": "语义：“胆小鬼”指胆子小、怕事的人，与“不怕危险”矛盾。"}], "explanations": {"病人": "搭配：“病人”指患病的人，“不怕危险的病人”搭配不通。", "懦夫": "语义：“懦夫”指胆小怕事的人，与“不怕危险”正相反。", "勇士": "正确：“勇士”指不怕危险、胆子很大的人，与句意一致。", "胆小鬼": "语义：“胆小鬼”指胆子小、怕事的人，与“不怕危险”矛盾。"}, "sentence_index": 0, "correct_answer": "勇士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在山脚下看见一棵勇士。", "explanation": "这里应该用〈位〉或〈个〉。“棵”用于树木，“勇士”指人，不能用“棵”计数。"}, {"text": "他手里拿着一把勇士。", "explanation": "这里应该用〈位〉或〈个〉。“把”用于有柄的器具，不能用来数人。"}, {"text": "山上立着一座勇士。", "explanation": "这里应该用〈位〉或〈个〉。“座”用于山、房屋等大型固定物，“勇士”指人，不能说“一座勇士”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93439, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头没有感觉，不会“怕”，“石头从来没有怕过黑夜”不通。"}, {"text": "勇气", "is_correct": false, "explanation": "配价：“怕”要求有生命的施事，“勇气”是抽象名词，不能做“怕”的主语。"}, {"text": "勇士", "is_correct": true, "explanation": "正确：“勇士”是人，可以“从来没有怕过黑夜”，与句意相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有心理活动，不会“怕过黑夜”，与句意矛盾。"}], "explanations": {"石头": "语义：石头没有感觉，不会“怕”，“石头从来没有怕过黑夜”不通。", "勇气": "配价：“怕”要求有生命的施事，“勇气”是抽象名词，不能做“怕”的主语。", "勇士": "正确：“勇士”是人，可以“从来没有怕过黑夜”，与句意相合。", "桌子": "语义：桌子没有心理活动，不会“怕过黑夜”，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "勇士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明很有勇士，不怕黑，也不怕狗。", "explanation": "这里应该用〈勇气〉。“勇士”指人，不能说“很有勇士”，表示胆量要用“勇气”。"}, {"text": "这个孩子有很大的勇士。", "explanation": "这里应该用〈胆量〉。“勇士”指人，不能说“很大的勇士”，说胆子大要用“胆量”。"}, {"text": "勇士是一种很好的品质。", "explanation": "这里应该用〈勇敢〉。“勇士”指人，不能作为品质，表示品质要用“勇敢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93439, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里来了一把不怕危险的勇士。", "corrected_sentence": "村里来了一位不怕危险的勇士。", "error_description": "量词错误：“勇士”指人，应用“位”或“个”，“把”用于有柄的器具，应说“一位不怕危险的勇士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93439, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他救人时像一个不怕危险勇士。", "corrected_sentence": "他救人时像一个不怕危险的勇士。", "error_description": "漏字：「不怕危险」修饰「勇士」，中间要加「的」，应说「不怕危险的勇士」，不能省略「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
