INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93440, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "勇敢而有力量的人。", "primary_collocate": null, "pronunciation": "yǒng shì", "ipa": "jʊŋ˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这位勇士又高又壮，力气很大。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草原上的勇士骑着马跑过来。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王请来了最强的勇士。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的勇士手里拿着长剑。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "勇士一拳就打开了大门。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的第一名是一位年轻的勇士。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "勇士们把大石头搬走了。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的爸爸是村里有名的勇士。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个勇士用力拉开了大弓。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都想成为强壮的勇士。", "target_word": "勇士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位勇士", "label": "量词"}, {"form": "一个勇士", "label": "量词"}, {"form": "勇士们", "label": "复数"}], "register": "中性", "sense_fingerprint": "勇敢又有力量的人；强壮的武士、壮士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b15c5566-b911-4b10-82c3-0d833210f232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矮个子", "is_correct": false, "explanation": "体貌：“矮个子”指个子矮，与“又高又壮”矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”身体虚弱，与“力气很大”矛盾。"}, {"text": "勇士", "is_correct": true, "explanation": "正确：“勇士”指勇敢有力的人，与“又高又壮，力气很大”相合。"}, {"text": "瘦子", "is_correct": false, "explanation": "体貌：“瘦子”指身材瘦的人，与“又高又壮”矛盾。"}], "explanations": {"矮个子": "体貌：“矮个子”指个子矮，与“又高又壮”矛盾。", "病人": "语义：“病人”身体虚弱，与“力气很大”矛盾。", "勇士": "正确：“勇士”指勇敢有力的人，与“又高又壮，力气很大”相合。", "瘦子": "体貌：“瘦子”指身材瘦的人，与“又高又壮”矛盾。"}, "sentence_index": 0, "correct_answer": "勇士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书架上放着一本勇士。", "explanation": "这里应该用〈位〉或〈个〉。“本”用于书本，“勇士”指人，不能说“一本勇士”。"}, {"text": "路边停着一辆勇士。", "explanation": "这里应该用〈位〉或〈个〉。“辆”用于车，“勇士”指人，不能说“一辆勇士”。"}, {"text": "桌上放着一张勇士。", "explanation": "这里应该用〈位〉或〈个〉。“张”用于纸张、桌子等平面的东西，“勇士”指人，不能说“一张勇士”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蝴蝶", "is_correct": false, "explanation": "语义：蝴蝶不能搬动大石头，“蝴蝶们把大石头搬走了”与常识矛盾。"}, {"text": "勇士", "is_correct": true, "explanation": "正确：“勇士们”有力气、敢出力，能把大石头搬走，与句意相合。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人身体虚弱，搬不动大石头，与句意矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“搬走”的施事要能动，“石头”不能做“搬”的施事。"}], "explanations": {"蝴蝶": "语义：蝴蝶不能搬动大石头，“蝴蝶们把大石头搬走了”与常识矛盾。", "勇士": "正确：“勇士们”有力气、敢出力，能把大石头搬走，与句意相合。", "病人": "语义：病人身体虚弱，搬不动大石头，与句意矛盾。", "石头": "配价：“搬走”的施事要能动，“石头”不能做“搬”的施事。"}, "sentence_index": 6, "correct_answer": "勇士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿出很大的勇士，跳进河里救人。", "explanation": "这里应该用〈勇气〉。“勇士”指人，不能说“拿出很大的勇士”，表示胆量要用“勇气”。"}, {"text": "她很有勇士，什么都不怕。", "explanation": "这里应该用〈勇气〉。“勇士”指人，不能说“很有勇士”，表示胆量要用“勇气”。"}, {"text": "做人要勇士，不能怕事。", "explanation": "这里应该用〈勇敢〉。“勇士”是人，不能作为做人的要求，要求品质应说“勇敢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里有一只勇士。", "corrected_sentence": "村里有一位勇士。", "error_description": "量词错误：“勇士”指人，应用量词“位”或“个”，说“一位勇士”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位很勇敢勇士救了小孩。", "corrected_sentence": "那位很勇敢的勇士救了小孩。", "error_description": "漏字：“很勇敢”修饰“勇士”，中间要加“的”，应说“很勇敢的勇士”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93441, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93441, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93441, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "游泳是人在水里，用手和脚动一动，身体就能向前走。", "primary_collocate": null, "pronunciation": "yóu yǒng", "ipa": "joʊ˧˥ jʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我喜欢在夏天去游泳。", "target_word": "游泳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他会游泳，我不会。", "target_word": "游泳", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明每个周末都和爸爸去游泳。", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想不想跟我们一起去游泳？", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在河里游泳，玩得很开心。", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天太热了，我们去游泳吧。", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我四岁的时候就学会了游泳。", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每天早上游泳一个小时。", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，今天不能去游泳了。", "target_word": "游泳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妹妹怕水，不敢游泳。", "target_word": "游泳", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "游过泳", "label": "体标"}, {"form": "游泳池", "label": "复合"}, {"form": "游泳衣", "label": "复合"}], "register": "中性", "sense_fingerprint": "人在水里用手脚动，身体向前；日常去游泳、会不会游泳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c6126fc-082d-4972-80f0-b37b1dacae83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93441, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游泳", "is_correct": true, "explanation": "正确：“游泳”指在水中用手脚划动身体，与“在夏天去”搭配，句意自然。"}, {"text": "取暖", "is_correct": false, "explanation": "语义：取暖是冬天御寒的做法，与“夏天”冲突。"}, {"text": "烤火", "is_correct": false, "explanation": "语义：烤火是冬天取暖的做法，与“夏天”冲突。"}, {"text": "下雪", "is_correct": false, "explanation": "配价：“下雪”是自然现象，不是人能去做的动作，不能放在“去”后面。"}], "explanations": {"游泳": "正确：“游泳”指在水中用手脚划动身体，与“在夏天去”搭配，句意自然。", "取暖": "语义：取暖是冬天御寒的做法，与“夏天”冲突。", "烤火": "语义：烤火是冬天取暖的做法，与“夏天”冲突。", "下雪": "配价：“下雪”是自然现象，不是人能去做的动作，不能放在“去”后面。"}, "sentence_index": 0, "correct_answer": "游泳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车在马路上游泳。", "explanation": "这里应该用〈行驶〉。游泳指人或动物在水中划动身体前进，汽车在马路上只能行驶，不能说游泳。"}, {"text": "这个周末我们去长城游泳。", "explanation": "这里应该用〈游览〉。游泳是在水中划动身体前进，长城上没有水，去长城应说游览。"}, {"text": "周末我们去图书馆游泳。", "explanation": "这里应该用〈看书〉。游泳要在水中划动身体前进，图书馆里不能游泳，这里应说看书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93441, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游泳", "is_correct": true, "explanation": "正确：“学会了”后面接的是一项技能，“游泳”符合句意。"}, {"text": "开车", "is_correct": false, "explanation": "语义：四岁的孩子不能学开车，与“四岁的时候”冲突。"}, {"text": "喝酒", "is_correct": false, "explanation": "语义：四岁的孩子不会学喝酒，与“四岁的时候”冲突。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“学会”后接技能，“考试”是活动，不能说“学会了考试”。"}], "explanations": {"游泳": "正确：“学会了”后面接的是一项技能，“游泳”符合句意。", "开车": "语义：四岁的孩子不能学开车，与“四岁的时候”冲突。", "喝酒": "语义：四岁的孩子不会学喝酒，与“四岁的时候”冲突。", "考试": "搭配：“学会”后接技能，“考试”是活动，不能说“学会了考试”。"}, "sentence_index": 6, "correct_answer": "游泳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上在操场游泳。", "explanation": "这里应该用〈跑步〉。游泳要在水中划动身体前进，操场上不能游泳，这种锻炼应说跑步。"}, {"text": "他在床上游泳。", "explanation": "这里应该用〈睡觉〉。游泳要在水中划动身体，床上不能游泳，这里说的是躺在床上睡觉，应说睡觉。"}, {"text": "我们坐在教室里游泳。", "explanation": "这里应该用〈上课〉。游泳要在水中划动身体前进，教室里没有水，不能游泳，坐在教室里应说上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他游泳得很快。", "corrected_sentence": "他游泳游得很快。", "error_description": "错误在于“得”的用法。“游泳”是离合词（动词“游”＋宾语“泳”），后面带“得”补语时要重复动词，应说“游泳游得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每星期去游泳一个。", "corrected_sentence": "我每星期去游泳一次。", "error_description": "错误在于“游泳”的量词。游泳的次数要用量词“次”，不能用“个”。正确说法是“去游泳一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
