INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93443, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93443, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "勉强是不太想做，可还是用力去做。", "primary_collocate": null, "pronunciation": "miǎn qiǎng", "ipa": "mjɛn˨˩˦ tɕʰjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他不想去，可是勉强去了。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她勉强笑了笑，没有说话。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让他吃药，他勉强吃了一点。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不饿，但还是勉强吃完了。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师叫他回答问题，他勉强站了起来。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他勉强答应了朋友的要求。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很累，他还是勉强上完了课。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然不想唱，还是勉强唱了一首歌。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他勉强同意了这个办法。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里不高兴，却勉强说了声谢谢。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "勉勉强强", "label": "重叠"}, {"form": "勉强地", "label": "状语形式"}, {"form": "勉強", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不情愿地做；硬着头皮去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8a7dd2-9f6a-4ef8-b570-0eaeae1a1cd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93443, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高兴地", "is_correct": false, "explanation": "语义：“高兴”表示乐意，与“不想去”矛盾，不能用在这里。"}, {"text": "勉强", "is_correct": true, "explanation": "“勉强”表示不情愿但仍然去做，与“他不想去，可是……去了”的语境一致。"}, {"text": "欣然地", "is_correct": false, "explanation": "语域：“欣然”偏书面语，且表示乐意地去，与“不想去”语义相反。"}, {"text": "兴冲冲地", "is_correct": false, "explanation": "语义：“兴冲冲”形容兴致勃勃，与“不想去”矛盾。"}], "explanations": {"高兴地": "语义：“高兴”表示乐意，与“不想去”矛盾，不能用在这里。", "勉强": "“勉强”表示不情愿但仍然去做，与“他不想去，可是……去了”的语境一致。", "欣然地": "语域：“欣然”偏书面语，且表示乐意地去，与“不想去”语义相反。", "兴冲冲地": "语义：“兴冲冲”形容兴致勃勃，与“不想去”矛盾。"}, "sentence_index": 0, "correct_answer": "勉强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很喜欢音乐，每天勉强练琴。", "explanation": "这里应该用〈坚持〉。“勉强”表示不情愿地做，与“很喜欢音乐”相矛盾；自觉、持续地做要用“坚持”。"}, {"text": "他很想赢，所以勉强地训练。", "explanation": "这里应该用〈努力〉。“勉强”表示不情愿，与“很想赢”矛盾；为目标主动付出心力要用“努力”。"}, {"text": "一听到可以去海边玩，她就勉强地收拾了行李。", "explanation": "这里应该用〈高兴地〉。“勉强”表示不情愿，与“一听到可以去海边玩”的兴奋语境矛盾；愉快地行动要用“高兴地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93443, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻而易举地", "is_correct": false, "explanation": "语义：“轻而易举”表示不费力，与“虽然很累”矛盾。"}, {"text": "勉强", "is_correct": true, "explanation": "“勉强”表示累得很却仍尽力做完，符合“虽然很累，他还是……”的转折。"}, {"text": "悠然自得地", "is_correct": false, "explanation": "语域：“悠然自得”是书面成语，形容闲适，且与“很累”矛盾，不适合这里的口语叙述。"}, {"text": "一蹶不振地", "is_correct": false, "explanation": "语义：“一蹶不振”指消沉到底，与把课上完的叙述相矛盾。"}], "explanations": {"轻而易举地": "语义：“轻而易举”表示不费力，与“虽然很累”矛盾。", "勉强": "“勉强”表示累得很却仍尽力做完，符合“虽然很累，他还是……”的转折。", "悠然自得地": "语域：“悠然自得”是书面成语，形容闲适，且与“很累”矛盾，不适合这里的口语叙述。", "一蹶不振地": "语义：“一蹶不振”指消沉到底，与把课上完的叙述相矛盾。"}, "sentence_index": 6, "correct_answer": "勉强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到他来了，妈妈非常高兴，勉强地迎了出去。", "explanation": "这里应该用〈热情〉。“勉强”表示不情愿，与“非常高兴”矛盾；迎接客人的热情要用“热情”。"}, {"text": "收到录取通知，她勉强地笑了起来。", "explanation": "这里应该用〈开心地〉。“勉强”表示不情愿，与“收到录取通知”的喜悦语境矛盾；高兴地笑要用“开心地”。"}, {"text": "他一看到邻居有困难，就勉强地赶过去帮忙。", "explanation": "这里应该用〈主动〉。“勉强”表示不情愿，与“一看到……就赶过去”的积极行为矛盾；自觉去做要用“主动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不想参加，但还是勉强得参加了聚会。", "corrected_sentence": "他不想参加，但还是勉强地参加了聚会。", "error_description": "错误在结构助词：“勉强”作状语修饰动词“参加”，后面应用“地”，不能用“得”。正确形式：“勉强地参加了聚会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很怕坐飞机，但还是勉强的上了飞机。", "corrected_sentence": "他很怕坐飞机，但还是勉强地上了飞机。", "error_description": "错误形式：“勉强的上了飞机”，用了“的”。正确形式：“勉强地上了飞机”。“勉强”在这里是表示不情愿地做的状语，修饰动词要用“地”，不用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
