INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93444, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93444, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能力或条件不太够，刚刚能做到；不充分。", "primary_collocate": null, "pronunciation": "miǎn qiǎng", "ipa": "mjɛn˨˩˦ tɕʰjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的汉语水平勉强能看懂新闻。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点钱勉强够我们吃一个星期。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的字写得不好，但勉强能看清。", "target_word": "勉强", "complexity_tier": "T3", "furigana": "tā de zì xiě de bù hǎo, dàn miǎn qiǎng néng kàn qīng.", "sentence_source": "generated"}, {"text": "这个月的生活费只能勉强维持。", "target_word": "勉强", "complexity_tier": "T3", "furigana": "zhè gè yuè de shēnghuófèi zhǐ néng miǎn qiǎng wéichí.", "sentence_source": "generated"}, {"text": "这次考试，我勉强及格了。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百块勉强够买这本书。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图画得不完整，只能勉强看出方向。", "target_word": "勉强", "complexity_tier": "T3", "furigana": "zhè zhāng dìtú huà de bù wánzhěng, zhǐ néng miǎn qiǎng kàn chū fāngxiàng.", "sentence_source": "generated"}, {"text": "这么多人，房间勉强坐得下。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病刚好，他勉强能走几步路。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的汉语勉强可以和他聊天。", "target_word": "勉强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "勉勉强强", "label": "重叠"}, {"form": "勉强地", "label": "状语形式"}, {"form": "勉強", "label": "繁体"}], "register": "中性", "sense_fingerprint": "能力或条件不足，勉强做到；不充分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8a7dd2-9f6a-4ef8-b570-0eaeae1a1cd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "充分", "is_correct": false, "explanation": "搭配：“充分”修饰准备、条件，不修饰“能看懂”这一能力结果，这里搭配不当。"}, {"text": "勉强", "is_correct": true, "explanation": "“勉强”表示能力刚好够用，符合“汉语水平……能看懂新闻”只够看懂的语境。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”表示程度，不直接修饰“能看懂新闻”这一结果，这里不通。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容对人对事的态度，不能修饰“能看懂新闻”这一能力，这里不通。"}], "explanations": {"充分": "搭配：“充分”修饰准备、条件，不修饰“能看懂”这一能力结果，这里搭配不当。", "勉强": "“勉强”表示能力刚好够用，符合“汉语水平……能看懂新闻”只够看懂的语境。", "非常": "搭配：“非常”表示程度，不直接修饰“能看懂新闻”这一结果，这里不通。", "热情": "搭配：“热情”形容对人对事的态度，不能修饰“能看懂新闻”这一能力，这里不通。"}, "sentence_index": 0, "correct_answer": "勉强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间很宽敞，勉强能放下三张床。", "explanation": "这里应该用〈刚好〉。“勉强”表示数量或空间不充分，与“很宽敞”矛盾；空间正好够用要用“刚好”。"}, {"text": "这个月的生活费很勉强，我们可以去旅行。", "explanation": "这里应该用〈宽裕〉。“勉强”表示只够刚刚，与“我们可以去旅行”的富足语境矛盾；钱多够用要用“宽裕”。"}, {"text": "这个月的收入勉强，可以买一台新电脑。", "explanation": "这里应该用〈有富余〉。“勉强”表示刚刚够，与“可以买一台新电脑”矛盾；收入多、够花要用“有富余”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”表示不费力，与“只能”和“画得不完整”的困难语境矛盾。"}, {"text": "勉强", "is_correct": true, "explanation": "“勉强”表示只能刚刚看出，符合地图画得不完整的语境。"}, {"text": "彻底", "is_correct": false, "explanation": "语义：“彻底”表示完全，与“画得不完整”相矛盾。"}, {"text": "详细", "is_correct": false, "explanation": "搭配：“详细”多修饰说明、描述，不修饰“看出”，这里不通。"}], "explanations": {"轻松": "语义：“轻松”表示不费力，与“只能”和“画得不完整”的困难语境矛盾。", "勉强": "“勉强”表示只能刚刚看出，符合地图画得不完整的语境。", "彻底": "语义：“彻底”表示完全，与“画得不完整”相矛盾。", "详细": "搭配：“详细”多修饰说明、描述，不修饰“看出”，这里不通。"}, "sentence_index": 6, "correct_answer": "勉强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店的菜很丰盛，勉强够四个人吃。", "explanation": "这里应该用〈绰绰有余〉。“勉强”表示数量刚好、不充分，与“很丰盛”矛盾；数量充足、有余裕要用“绰绰有余”。"}, {"text": "我的汉语说得特别好，勉强可以和他聊天。", "explanation": "这里应该用〈流利〉。“勉强”表示刚刚够、不充分，与“说得特别好”矛盾；语言表达顺畅要用“流利”。"}, {"text": "我们的交流很勉强，可以聊很久。", "explanation": "这里应该用〈顺畅〉。“勉强”指刚刚够、不充分，与“可以聊很久”矛盾；交流顺利、没有障碍要用“顺畅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔钱很勉强够他们度过冬天。", "corrected_sentence": "这笔钱勉强够他们度过冬天。", "error_description": "错误形式：“很勉强够他们度过冬天”。正确形式：“勉强够他们度过冬天”。“勉强”作状语修饰能愿动词或补语“够”，前面不能加程度副词“很”，应直接说“勉强够”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间小屋勉强的能住两个人。", "corrected_sentence": "这间小屋勉强能住两个人。", "error_description": "错误形式：“勉强的能住两个人”，“勉强”后多加了“的”。正确形式：“勉强能住两个人”。“勉强”作状语修饰能愿动词“能”，后面不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
