INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93446, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "陆地上被陆地围着的大片积水区域。", "primary_collocate": null, "pronunciation": "hú", "ipa": "xu˧˥", "syllable_count": 1, "sentences": [{"text": "中国有很多大湖。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖在两座山中间。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖的四周都是树。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖里有一个小岛，湖很蓝。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们开车绕着湖转了一圈。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上这个湖很大。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是中国最大的湖。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有一个湖，叫天池。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，很多鸟在湖上飞。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖里的水来自山上的河。", "target_word": "湖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "湖水", "label": "复合"}, {"form": "湖泊", "label": "复合"}], "register": "中性", "sense_fingerprint": "湖：被陆地围着的大片积水区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4240d01-219b-4bd2-9ad0-703dd789f62b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93446, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湖", "is_correct": true, "explanation": "正确答案。湖读作 hú，指陆地上被陆地围着的大片积水区域。"}, {"text": "虎", "is_correct": false, "explanation": "hǔ（第三声）与 hú（第二声）声调不同，虎的意思是老虎。"}, {"text": "互", "is_correct": false, "explanation": "hù（第四声）与 hú（第二声）声调不同，互的意思是互相。"}, {"text": "呼", "is_correct": false, "explanation": "hū（第一声）与 hú（第二声）声调不同，呼的意思是呼喊。"}], "explanations": {"湖": "正确答案。湖读作 hú，指陆地上被陆地围着的大片积水区域。", "虎": "hǔ（第三声）与 hú（第二声）声调不同，虎的意思是老虎。", "互": "hù（第四声）与 hú（第二声）声调不同，互的意思是互相。", "呼": "hū（第一声）与 hú（第二声）声调不同，呼的意思是呼喊。"}, "sentence_index": null, "correct_answer": "湖"}, "level_3": {"options": [{"text": "湖", "is_correct": true, "explanation": "正确。“大湖”指大片积水，中国有很多这样的湖。"}, {"text": "脑", "is_correct": false, "explanation": "语义：“大脑”是人体器官，不能说“中国有很多大脑”。"}, {"text": "洲", "is_correct": false, "explanation": "语义：“大洲”指亚洲等大陆，中国是国家，不能说“中国有很多大洲”。"}, {"text": "手", "is_correct": false, "explanation": "语义：“大手”指人的手，不是地理对象，“中国有很多大手”说不通。"}], "explanations": {"湖": "正确。“大湖”指大片积水，中国有很多这样的湖。", "脑": "语义：“大脑”是人体器官，不能说“中国有很多大脑”。", "洲": "语义：“大洲”指亚洲等大陆，中国是国家，不能说“中国有很多大洲”。", "手": "语义：“大手”指人的手，不是地理对象，“中国有很多大手”说不通。"}, "sentence_index": 0, "correct_answer": "湖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在一头湖边钓鱼。", "explanation": "这里应该用〈个〉。“头”多用于牲畜，不用于湖。"}, {"text": "这个湖的四周没有陆地，一望无际。", "explanation": "这里应该用〈海〉。湖是被陆地围着的水域，不能说四周没有陆地。"}, {"text": "湖水一直向东流。", "explanation": "这里应该用〈河〉。湖的水是积聚不动的，不说“一直向东流”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93446, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "湖", "is_correct": true, "explanation": "正确答案。湖读作 hú，指被陆地围着的大片积水区域。"}, {"text": "福", "is_correct": false, "explanation": "fú（第二声）与 hú 声母不同（f 与 h），福的意思是福气。"}, {"text": "符", "is_correct": false, "explanation": "fú（第二声）与 hú 声母不同（f 与 h），符的意思是符号。"}, {"text": "伏", "is_correct": false, "explanation": "fú（第二声）与 hú 声母不同（f 与 h），伏的意思是趴下。"}], "explanations": {"湖": "正确答案。湖读作 hú，指被陆地围着的大片积水区域。", "福": "fú（第二声）与 hú 声母不同（f 与 h），福的意思是福气。", "符": "fú（第二声）与 hú 声母不同（f 与 h），符的意思是符号。", "伏": "fú（第二声）与 hú 声母不同（f 与 h），伏的意思是趴下。"}, "sentence_index": null, "correct_answer": "湖"}, "level_3": {"options": [{"text": "湖", "is_correct": true, "explanation": "正确。“中国最大的湖”指规模最大的湖泊，与“最大”相合。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“饭”不能用“最大”来比较地理规模，句子说的是湖。"}, {"text": "歌", "is_correct": false, "explanation": "语义：“歌”不是地理实体，不能说“中国最大的歌”。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛”是器官，不作“中国最大的”这种地理范围的修饰对象。"}], "explanations": {"湖": "正确。“中国最大的湖”指规模最大的湖泊，与“最大”相合。", "饭": "语义：“饭”不能用“最大”来比较地理规模，句子说的是湖。", "歌": "语义：“歌”不是地理实体，不能说“中国最大的歌”。", "眼睛": "搭配：“眼睛”是器官，不作“中国最大的”这种地理范围的修饰对象。"}, "sentence_index": 6, "correct_answer": "湖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个湖的水一直流到山下。", "explanation": "这里应该用〈溪流〉。湖是积水的大片水域，不会一直流到山下。"}, {"text": "湖里涨潮了，岸边的船都漂起来了。", "explanation": "这里应该用〈海〉。涨潮是海水的现象，湖里没有潮汐。"}, {"text": "湖很薄，可以夹在书里。", "explanation": "这里应该用〈纸〉。湖是大片积水，不可能很薄、夹在书里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一条湖边钓了一个下午的鱼。", "corrected_sentence": "我们在湖边钓了一个下午的鱼。", "error_description": "量词错误：“湖”前不能加“一条”，“条”不用于湖。正确说法是“我们在湖边钓了一个下午的鱼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天去那位湖钓鱼。", "corrected_sentence": "我们明天去那个湖钓鱼。", "error_description": "量词错误：“湖”前应该用“个”，“位”用于人，不用于湖。正确说法是“我们明天去那个湖钓鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "奖金是做得好时，得到的额外的钱。", "primary_collocate": null, "pronunciation": "jiǎng jīn", "ipa": "tɕjɑŋ˨˩˦ tɕin˥˥", "syllable_count": 2, "sentences": [{"text": "我这个月工作做得好，拿到了奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他东西卖得多，所以得到一笔奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用奖金给我买了新手机。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做得好的人，月底会有奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿了奖金，请大家吃饭。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月我多拿了两百元奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她努力工作，年底拿了很多奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "拿到奖金以后，我马上告诉了家人。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把奖金存进了银行。", "target_word": "奖金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这个月的奖金比上个月少。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔奖金", "label": "量词"}, {"form": "年终奖金", "label": "复合"}, {"form": "獎金", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工作做得好时额外拿到的钱，从得到的人角度说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c6126fc-082d-4972-80f0-b37b1dacae83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学费", "is_correct": false, "explanation": "语义：学费是学生交给学校的钱，与“工作做得好”无关。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的学习任务，与“工作做得好”不搭配。"}, {"text": "奖金", "is_correct": true, "explanation": "正确：“拿到奖金”指工作表现好而得到的额外的钱，符合语境。"}, {"text": "迟到", "is_correct": false, "explanation": "搭配：“迟到”是动作，不能作“拿到”的宾语，也与“工作做得好”矛盾。"}], "explanations": {"学费": "语义：学费是学生交给学校的钱，与“工作做得好”无关。", "作业": "语义：作业是学生的学习任务，与“工作做得好”不搭配。", "奖金": "正确：“拿到奖金”指工作表现好而得到的额外的钱，符合语境。", "迟到": "搭配：“迟到”是动作，不能作“拿到”的宾语，也与“工作做得好”矛盾。"}, "sentence_index": 0, "correct_answer": "奖金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板给他的奖金是一张表扬信。", "explanation": "这里应该用〈奖励〉。奖金只指钱，表扬信属于奖励，不能说成奖金。"}, {"text": "他违约了，要付一笔奖金。", "explanation": "这里应该用〈违约金〉。奖金是做得好时得到的钱，违约金是违约后要付给对方的钱，不能说“要付一笔奖金”。"}, {"text": "商家道歉后，他拿到了一笔奖金。", "explanation": "这里应该用〈赔偿〉（或〈退款〉）。奖金是因工作、成绩得到的奖励，因商家过失得到的钱不叫奖金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批评", "is_correct": false, "explanation": "语义：努力工作的人不会得到批评，与“努力工作”的句意矛盾。"}, {"text": "工伤", "is_correct": false, "explanation": "搭配：工伤是工作中受的伤，不说“拿了很多工伤”。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：感冒是疾病，不能说“拿了很多感冒”。"}, {"text": "奖金", "is_correct": true, "explanation": "正确：“拿了很多奖金”指年底得到很多额外的钱，符合语境。"}], "explanations": {"批评": "语义：努力工作的人不会得到批评，与“努力工作”的句意矛盾。", "工伤": "搭配：工伤是工作中受的伤，不说“拿了很多工伤”。", "感冒": "搭配：感冒是疾病，不能说“拿了很多感冒”。", "奖金": "正确：“拿了很多奖金”指年底得到很多额外的钱，符合语境。"}, "sentence_index": 6, "correct_answer": "奖金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个学期都要交一笔奖金。", "explanation": "这里应该用〈学费〉。奖金是工作做得好时得到的钱，不是要交给学校的钱。"}, {"text": "他租房子时，交给房东一笔奖金。", "explanation": "这里应该用〈押金〉。奖金是奖励，不能用来指租房时交给房东的钱。"}, {"text": "车祸后，他拿到了一笔奖金。", "explanation": "这里应该用〈赔偿金〉。奖金是对工作表现的奖励，因车祸得到的钱叫赔偿金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个月拿到了一个奖金。", "corrected_sentence": "他这个月拿到了一笔奖金。", "error_description": "“奖金”前的量词应为“笔”，说“一笔奖金”；“个”不能用来计量钱款，这是学习者常见的量词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年底，她终于拿了到奖金。", "corrected_sentence": "年底，她终于拿到了奖金。", "error_description": "“拿到”是动词加结果补语，“了”应放在“拿到”之后；“拿了到”把“了”插在补语前，属于补语与“了”的语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
