INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "作为奖励发给的钱。", "primary_collocate": null, "pronunciation": "jiǎng jīn", "ipa": "tɕjɑŋ˨˩˦ tɕin˥˥", "syllable_count": 2, "sentences": [{"text": "公司今天给大家发了奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板给每个人发了一笔奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "财务部下午会把奖金发给大家。", "target_word": "奖金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的奖金是五千元。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校给第一名的同学发奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司每年年底都会发奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理已经把奖金放进了信封里。", "target_word": "奖金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛的奖金由主办方发给选手。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们在办公室门口排队领奖金。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年发的奖金比去年多。", "target_word": "奖金", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔奖金", "label": "量词"}, {"form": "年终奖金", "label": "复合"}, {"form": "獎金", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公司、学校、比赛主办方作为奖励发出的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c6126fc-082d-4972-80f0-b37b1dacae83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奖学金", "is_correct": false, "explanation": "语义：奖学金只发给在校学生，公司不会向员工发奖学金，与“公司给大家”不符。"}, {"text": "奖金", "is_correct": true, "explanation": "正确：“发奖金”指公司把钱作为奖励发给员工，符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是老师布置给学生的学习任务，公司不会给大家发作业。"}, {"text": "病假", "is_correct": false, "explanation": "搭配：病假是请假的时间，只说“批准病假”，不说“发病假”。"}], "explanations": {"奖学金": "语义：奖学金只发给在校学生，公司不会向员工发奖学金，与“公司给大家”不符。", "奖金": "正确：“发奖金”指公司把钱作为奖励发给员工，符合句意。", "作业": "语义：作业是老师布置给学生的学习任务，公司不会给大家发作业。", "病假": "搭配：病假是请假的时间，只说“批准病假”，不说“发病假”。"}, "sentence_index": 0, "correct_answer": "奖金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛的奖金是一台电视机。", "explanation": "这里应该用〈奖品〉。奖金指发的钱，实物奖励要用奖品，不能说奖金是一台电视机。"}, {"text": "他因为闯红灯，被交警处以一笔奖金。", "explanation": "这里应该用〈罚款〉。奖金是对做得好的人发的奖励，罚款是对违规的处罚，不能说“处以一笔奖金”。"}, {"text": "那位工人因为工伤，获得了一笔奖金。", "explanation": "这里应该用〈赔偿金〉。奖金是对工作或成绩的奖励，因工伤得到的钱叫赔偿金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱体积太大，装不进信封，句子不成立。"}, {"text": "奖金", "is_correct": true, "explanation": "正确：奖金是钱，可以装进信封，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子远比信封大，根本装不进去。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：友谊是抽象的情感，不能像物品一样“放进”信封。"}], "explanations": {"冰箱": "语义：冰箱体积太大，装不进信封，句子不成立。", "奖金": "正确：奖金是钱，可以装进信封，符合句意。", "房子": "语义：房子远比信封大，根本装不进去。", "友谊": "搭配：友谊是抽象的情感，不能像物品一样“放进”信封。"}, "sentence_index": 6, "correct_answer": "奖金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他租房子时交了一笔奖金。", "explanation": "这里应该用〈押金〉。奖金是对工作或成绩的奖励，不是租房时交给房东的钱。"}, {"text": "他每个学期都要交一笔奖金。", "explanation": "这里应该用〈学费〉。奖金是奖励，不是学生要交给学校的钱。"}, {"text": "他向银行借了一笔奖金。", "explanation": "这里应该用〈贷款〉。奖金是奖励，是发给人的钱，不是借来要还的钱，向银行借钱要说贷款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板给了每个人一笔奖金们。", "corrected_sentence": "老板给了每个人一笔奖金。", "error_description": "“们”只能加在指人的名词后面，表示复数；“奖金”是钱，不能说“奖金们”，而且前面已有“一笔”，更不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司已经把奖金发了完。", "corrected_sentence": "公司已经把奖金发完了。", "error_description": "结果补语“完”应紧接动词，说“发完”，再加“了”；“发了完”把补语放错了位置，属于补语语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39cc395d-73f6-48ad-8678-94fb426ac48f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93451, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "薄", "is_correct": true, "explanation": "薄与厚相对，指东西上下的距离小。"}, {"text": "软", "is_correct": false, "explanation": "软指质地柔软，与厚薄不是反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "亮指光线或颜色明亮，与厚没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "快指速度高，与厚没有反义关系。"}], "correct_answer": "薄", "explanations": {"薄": "薄与厚相对，指东西上下的距离小。", "软": "软指质地柔软，与厚薄不是反义关系。", "亮": "亮指光线或颜色明亮，与厚没有反义关系。", "快": "快指速度高，与厚没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93451, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "薄", "is_correct": true, "explanation": "薄与厚相对，指东西上下的距离小。"}, {"text": "慢", "is_correct": false, "explanation": "慢指速度低，与厚没有反义关系。"}, {"text": "短", "is_correct": false, "explanation": "短指长度小，与厚的上下距离没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "快指速度高，与厚没有反义关系。"}], "correct_answer": "薄", "explanations": {"薄": "薄与厚相对，指东西上下的距离小。", "慢": "慢指速度低，与厚没有反义关系。", "短": "短指长度小，与厚的上下距离没有反义关系。", "快": "快指速度高，与厚没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93451, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "厚是东西上下的距离大，不薄。", "primary_collocate": null, "pronunciation": "hòu", "ipa": "xoʊ˥˩", "syllable_count": 1, "sentences": [{"text": "冬天到了，我要穿厚衣服。", "target_word": "厚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很厚，我看了一个星期。", "target_word": "厚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面很冷，你穿一件厚一点的外套吧。", "target_word": "厚", "complexity_tier": "T3", "furigana": "wàimiàn hěn lěng, nǐ chuān yí jiàn hòu yìdiǎn de wàitào ba.", "sentence_source": "generated"}, {"text": "这块木板太厚了，锯不动。", "target_word": "厚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙很厚，听不到外面的声音。", "target_word": "厚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的积雪很厚，到处都是白的。", "target_word": "厚", "complexity_tier": "T3", "furigana": "lùshang de jīxuě hěn hòu, dàochù dōu shì bái de.", "sentence_source": "generated"}, {"text": "这条毯子又大又厚，很暖和。", "target_word": "厚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的字典比我的厚多了。", "target_word": "厚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包切得太厚，我吃不下。", "target_word": "厚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰很厚，孩子们可以在上面走。", "target_word": "厚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "厚厚", "label": "重叠"}, {"form": "厚度", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西上下距离大，不薄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2661f93-1077-4bd1-98fe-0202873548b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93451, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "厚", "is_correct": true, "explanation": "厚（hòu，第四声）指东西上下的距离大，不薄。"}, {"text": "猴", "is_correct": false, "explanation": "hóu（第二声）与 hòu 声调不同，意思是猴子。"}, {"text": "吼", "is_correct": false, "explanation": "hǒu（第三声）与 hòu 声调不同，意思是大声叫。"}, {"text": "豆", "is_correct": false, "explanation": "dòu 与 hòu 声母不同（d 与 h），意思是豆子。"}, {"text": "透", "is_correct": false, "explanation": "tòu 与 hòu 声母不同（t 与 h），意思是透过、透明。"}], "explanations": {"厚": "厚（hòu，第四声）指东西上下的距离大，不薄。", "猴": "hóu（第二声）与 hòu 声调不同，意思是猴子。", "吼": "hǒu（第三声）与 hòu 声调不同，意思是大声叫。", "豆": "dòu 与 hòu 声母不同（d 与 h），意思是豆子。", "透": "tòu 与 hòu 声母不同（t 与 h），意思是透过、透明。"}, "sentence_index": null, "correct_answer": "厚"}, "level_3": {"options": [{"text": "厚", "is_correct": true, "explanation": "厚是东西上下的距离大，冬天要穿厚衣服保暖。"}, {"text": "薄", "is_correct": false, "explanation": "语义：“薄”与“厚”相反，冬天到了穿薄衣服不保暖，与语境矛盾。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”是味道，不能形容衣服。"}, {"text": "凉", "is_correct": false, "explanation": "语义：“凉”说温度低，冬天穿凉衣服与“冬天到了”的语境冲突。"}], "explanations": {"厚": "厚是东西上下的距离大，冬天要穿厚衣服保暖。", "薄": "语义：“薄”与“厚”相反，冬天到了穿薄衣服不保暖，与语境矛盾。", "甜": "语义：“甜”是味道，不能形容衣服。", "凉": "语义：“凉”说温度低，冬天穿凉衣服与“冬天到了”的语境冲突。"}, "sentence_index": 0, "correct_answer": "厚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室很厚，坐了五十个人。", "explanation": "这里应该用〈大〉。厚指东西上下的距离大，房间的长宽要用“大”。"}, {"text": "这口井很厚，要用绳子才能下去。", "explanation": "这里应该用〈深〉。厚多指扁平物体的厚薄，井的上下距离要用“深”。"}, {"text": "这座楼很厚，我们坐电梯上去。", "explanation": "这里应该用〈高〉。楼的高度要用“高”，厚指东西的厚薄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93451, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "厚", "is_correct": true, "explanation": "厚（hòu，第四声）指东西上下的距离大，不薄。"}, {"text": "扣", "is_correct": false, "explanation": "kòu 与 hòu 声母不同（k 与 h），意思是扣子。"}, {"text": "漏", "is_correct": false, "explanation": "lòu 与 hòu 声母不同（l 与 h），意思是漏水。"}, {"text": "奏", "is_correct": false, "explanation": "zòu 与 hòu 声母不同（z 与 h），意思是演奏。"}], "explanations": {"厚": "厚（hòu，第四声）指东西上下的距离大，不薄。", "扣": "kòu 与 hòu 声母不同（k 与 h），意思是扣子。", "漏": "lòu 与 hòu 声母不同（l 与 h），意思是漏水。", "奏": "zòu 与 hòu 声母不同（z 与 h），意思是演奏。"}, "sentence_index": null, "correct_answer": "厚"}, "level_3": {"options": [{"text": "厚", "is_correct": true, "explanation": "厚是东西上下的距离大，毯子又大又厚，所以很暖和。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”说质地，毯子又大又硬，与“很暖和”不协调。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”与后半句的“很暖和”直接矛盾。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：“窄”与前面的“又大又”并列矛盾，毯子不说“窄”。"}], "explanations": {"厚": "厚是东西上下的距离大，毯子又大又厚，所以很暖和。", "硬": "语义：“硬”说质地，毯子又大又硬，与“很暖和”不协调。", "冷": "语义：“冷”与后半句的“很暖和”直接矛盾。", "窄": "搭配：“窄”与前面的“又大又”并列矛盾，毯子不说“窄”。"}, "sentence_index": 6, "correct_answer": "厚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很厚，两辆车能并排走。", "explanation": "这里应该用〈宽〉。厚指东西上下的距离大，路面左右的距离要用“宽”。"}, {"text": "这桶水很厚，我提不动。", "explanation": "这里应该用〈重〉。厚指东西上下的距离大，水的分量要用“重”。"}, {"text": "这根绳子很厚，我抓不住。", "explanation": "这里应该用〈粗〉。厚指东西上下的距离大，绳子这类圆长东西的粗细要用“粗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
