INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93452, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "厚", "is_correct": true, "explanation": "厚（hòu，第四声）指扁平物体上下两面的距离大，与薄相对。"}, {"text": "扣", "is_correct": false, "explanation": "kòu 与 hòu 声母不同（k 与 h），意思是扣子。"}, {"text": "漏", "is_correct": false, "explanation": "lòu 与 hòu 声母不同（l 与 h），意思是漏水。"}, {"text": "奏", "is_correct": false, "explanation": "zòu 与 hòu 声母不同（z 与 h），意思是演奏。"}], "explanations": {"厚": "厚（hòu，第四声）指扁平物体上下两面的距离大，与薄相对。", "扣": "kòu 与 hòu 声母不同（k 与 h），意思是扣子。", "漏": "lòu 与 hòu 声母不同（l 与 h），意思是漏水。", "奏": "zòu 与 hòu 声母不同（z 与 h），意思是演奏。"}, "sentence_index": null, "correct_answer": "厚"}, "level_3": {"options": [{"text": "厚", "is_correct": true, "explanation": "厚指扁平物体上下两面距离大，地毯太厚才会让门关不上。"}, {"text": "薄", "is_correct": false, "explanation": "语义：地毯太薄不会挡住门，与“门关不上”矛盾。"}, {"text": "轻", "is_correct": false, "explanation": "语义：“轻”说重量，地毯轻也不会挡住门，与后半句矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”形容光线或颜色，不说地毯太亮挡住门。"}], "explanations": {"厚": "厚指扁平物体上下两面距离大，地毯太厚才会让门关不上。", "薄": "语义：地毯太薄不会挡住门，与“门关不上”矛盾。", "轻": "语义：“轻”说重量，地毯轻也不会挡住门，与后半句矛盾。", "亮": "搭配：“亮”形容光线或颜色，不说地毯太亮挡住门。"}, "sentence_index": 6, "correct_answer": "厚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果很厚，我搬不动。", "explanation": "这里应该用〈重〉。厚指扁平物体上下两面的距离，苹果的分量要用“重”。"}, {"text": "这座山很厚，我们爬了三个小时。", "explanation": "这里应该用〈高〉。厚指扁平物体上下两面的距离，山的高矮要用“高”。"}, {"text": "这棵树很厚，要用两只手才能抱住。", "explanation": "这里应该用〈粗〉。厚指扁平物体上下两面的距离，树干的粗细要用“粗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一本厚得词典。", "corrected_sentence": "我买了一本厚词典。", "error_description": "补语错误：形容词“厚”作定语修饰名词时不能带补语标记“得”，应说“厚词典”，不说“厚得词典”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张床垫厚很，睡着很舒服。", "corrected_sentence": "这张床垫很厚，睡着很舒服。", "error_description": "位置错误：程度副词“很”要放在形容词“厚”前面，应说“很厚”，不说“厚很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
