INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93453, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "参选是报名去参加选人的比赛。", "primary_collocate": null, "pronunciation": "cān xuǎn", "ipa": "tsʰan˥ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "小林报名参选学校的形象大使。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想参选今年的校花。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想参选的同学请先报名。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参选班长，同学们都支持他。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参选过一次选美比赛。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区选“最美邻居”，王阿姨报名参选了。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次参选的人有二十多个。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有参选，只是来看比赛。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要选优秀员工，你为什么不参选？", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友让她去参选，她有点紧张。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参选了", "label": "完成体"}, {"form": "参选过", "label": "经历体"}, {"form": "参选者", "label": "复合词"}, {"form": "參選", "label": "繁体"}], "register": "中性", "sense_fingerprint": "报名参加评选人的比赛；校花、班长、形象大使等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b15c5566-b911-4b10-82c3-0d833210f232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93453, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举办", "is_correct": false, "explanation": "搭配：“举办”后面接活动或比赛，不能接“形象大使”这样的职位，“报名举办”也不通。"}, {"text": "参选", "is_correct": true, "explanation": "正确：“参选”是报名参加选人的比赛，“报名参选学校的形象大使”符合语境。"}, {"text": "颁发", "is_correct": false, "explanation": "语义：“颁发”是组织者授予，与“报名”由本人申请的意思相反，“报名颁发”自相矛盾。"}, {"text": "退出", "is_correct": false, "explanation": "语义：“退出”与“报名”方向相反，“报名退出”自相矛盾。"}], "explanations": {"举办": "搭配：“举办”后面接活动或比赛，不能接“形象大使”这样的职位，“报名举办”也不通。", "参选": "正确：“参选”是报名参加选人的比赛，“报名参选学校的形象大使”符合语境。", "颁发": "语义：“颁发”是组织者授予，与“报名”由本人申请的意思相反，“报名颁发”自相矛盾。", "退出": "语义：“退出”与“报名”方向相反，“报名退出”自相矛盾。"}, "sentence_index": 0, "correct_answer": "参选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天参选了城市的马拉松比赛。", "explanation": "这里应该用〈参加〉。参选只用于报名竞选人选（如班长、校花），马拉松是跑步比赛，不选人，不能说参选。"}, {"text": "我们班参选了这个环保项目。", "explanation": "这里应该用〈参与〉。参选是报名争取当选，环保项目不是选人的比赛，参与项目要说参与。"}, {"text": "我参选了学校的合唱团。", "explanation": "这里应该用〈报名〉。参选的对象是选人的比赛，合唱团是团体，想加入要说报名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93453, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撤销", "is_correct": false, "explanation": "配价：“撤销”要带“申请”之类的宾语，不能直接修饰“人”，“撤销的人”不通。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“下雨”是天气现象，没有施事的人，“这次下雨的人”不通。"}, {"text": "参选", "is_correct": true, "explanation": "正确：“参选”是报名竞选，“这次参选的人有二十多个”指报名竞选的人数。"}, {"text": "发生", "is_correct": false, "explanation": "搭配：“发生”的主体是事情，不是人，“这次发生的人”不通。"}], "explanations": {"撤销": "配价：“撤销”要带“申请”之类的宾语，不能直接修饰“人”，“撤销的人”不通。", "下雨": "搭配：“下雨”是天气现象，没有施事的人，“这次下雨的人”不通。", "参选": "正确：“参选”是报名竞选，“这次参选的人有二十多个”指报名竞选的人数。", "发生": "搭配：“发生”的主体是事情，不是人，“这次发生的人”不通。"}, "sentence_index": 6, "correct_answer": "参选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春节那天我们全家去寺庙参选。", "explanation": "这里应该用〈参拜〉。参选是报名竞选人选，去寺庙烧香拜佛要说参拜。"}, {"text": "他参选了三件颜色不同的衣服。", "explanation": "这里应该用〈挑选〉。参选指报名竞选，衣服不能参选，挑选衣服要说挑选。"}, {"text": "放假时我们参选了一座老房子。", "explanation": "这里应该用〈参观〉。参选是报名竞选人选，老房子不是选人的比赛，去看要说参观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明年参选了班长。", "corrected_sentence": "他明年参选班长。", "error_description": "时态错误：“明年”指将来，“参选”后不能加“了”。应说“他明年参选班长”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友劝她去参选过班长。", "corrected_sentence": "朋友劝她去参选班长。", "error_description": "动态助词错误：“劝她去”是对将来的建议，“参选”后不能加表示经历的“过”，应说“去参选班长”，去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
