INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93454, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "参加选举，争取当选。", "primary_collocate": null, "pronunciation": "cān xuǎn", "ipa": "tsʰan˥ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他决定明年参选市长。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师想参选人大代表。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小张去年参选议员，没有成功。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想参选的人要先提交材料。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次参选就赢了。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生今年不参选了。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有三个人参选这次的村长。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参选是为了帮助大家。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要参选的话，我支持你。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参选过两次，都没有当选。", "target_word": "参选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参选了", "label": "完成体"}, {"form": "参选过", "label": "经历体"}, {"form": "参选者", "label": "复合词"}, {"form": "參選", "label": "繁体"}], "register": "中性", "sense_fingerprint": "参加选举、争取当选；市长、议员、代表等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b15c5566-b911-4b10-82c3-0d833210f232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93454, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颁发", "is_correct": false, "explanation": "语义：“颁发”是授予，由组织者发出，与“他决定”的主动报名相矛盾。"}, {"text": "参选", "is_correct": true, "explanation": "正确：“参选”是报名参加选人的比赛，“决定明年参选市长”符合语境。"}, {"text": "赞助", "is_correct": false, "explanation": "搭配：“赞助”的对象是活动或团体，不能是“市长”这种职位，“赞助市长”不通。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”后面要接活动，“举办市长”没有意义。"}], "explanations": {"颁发": "语义：“颁发”是授予，由组织者发出，与“他决定”的主动报名相矛盾。", "参选": "正确：“参选”是报名参加选人的比赛，“决定明年参选市长”符合语境。", "赞助": "搭配：“赞助”的对象是活动或团体，不能是“市长”这种职位，“赞助市长”不通。", "举办": "搭配：“举办”后面要接活动，“举办市长”没有意义。"}, "sentence_index": 0, "correct_answer": "参选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末他参选了一场环保论坛。", "explanation": "这里应该用〈参加〉。参选指报名竞选人选，论坛不是选人的比赛，参加论坛要说参加。"}, {"text": "他也参选了这次实验。", "explanation": "这里应该用〈参与〉。参选用于竞选人选，实验不是选人的比赛，参与实验要说参与。"}, {"text": "我参选了一个英语班。", "explanation": "这里应该用〈报名〉。参选的对象是选人的比赛，英语班是学习班，报名参加要说报名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当选", "is_correct": false, "explanation": "语义：村长只有一位，“有三个人当选这次的村长”自相矛盾。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”后面要接活动，不能接“村长”这种职位。"}, {"text": "参选", "is_correct": true, "explanation": "正确：“参选”是报名竞选，“有三个人参选这次的村长”指三人报名竞选村长。"}, {"text": "辞去", "is_correct": false, "explanation": "搭配：“辞去”后面接的是职务，要说“辞去村长职务”，不能直接说“辞去这次的村长”。"}], "explanations": {"当选": "语义：村长只有一位，“有三个人当选这次的村长”自相矛盾。", "举办": "搭配：“举办”后面要接活动，不能接“村长”这种职位。", "参选": "正确：“参选”是报名竞选，“有三个人参选这次的村长”指三人报名竞选村长。", "辞去": "搭配：“辞去”后面接的是职务，要说“辞去村长职务”，不能直接说“辞去这次的村长”。"}, "sentence_index": 6, "correct_answer": "参选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他参选了学医，将来当医生。", "explanation": "这里应该用〈选择〉。参选只用于报名竞选人选，学医是选专业，要说选择。"}, {"text": "妈妈在超市参选了三袋水果。", "explanation": "这里应该用〈挑选〉。参选指报名竞选，水果不能参选，挑选水果要说挑选。"}, {"text": "我们在剧院参选了演出。", "explanation": "这里应该用〈观看〉。参选是报名竞选人选，演出不是选人的比赛，观看演出要说观看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下个月要参选过市长。", "corrected_sentence": "他下个月要参选市长。", "error_description": "时态错误：“过”表示已经有过的经历，与“下个月”的将来时间矛盾，应说“要参选市长”，去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明年参选了市长。", "corrected_sentence": "他明年参选市长。", "error_description": "时态错误：“明年”指将来，“参选”后不能加“了”，应说“他明年参选市长”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aedad2c-7ae0-439d-b5a8-8cfacfc157ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93455, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93455, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93455, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "留言是不能当面说的时候，把话写下来留给别人。", "primary_collocate": null, "pronunciation": "liú yán", "ipa": "ljoʊ̯˧˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我不在家，你可以在桌子上留言。", "target_word": "留言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没找到老师，就在门上留言了。", "target_word": "留言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当面说不方便，你给我留言吧。", "target_word": "留言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈出门前，在冰箱上留言：晚饭在锅里。", "target_word": "留言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学不在教室，我在他的本子上留言。", "target_word": "留言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有事就在纸上留言，我回来就看。", "target_word": "留言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人来过，看你不在，就给你留言了。", "target_word": "留言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我怕打扰他，就给他留言，说我来过了。", "target_word": "留言", "complexity_tier": "T3", "furigana": "wǒ pà dǎ rǎo tā, jiù gěi tā liú yán, shuō wǒ lái guò le.", "sentence_source": "generated"}, {"text": "我不想打扰你睡觉，就在桌上留言了。", "target_word": "留言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居不在家，我在他家门口留言了。", "target_word": "留言", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "留言板", "label": "复合"}, {"form": "留了言", "label": "体标"}, {"form": "留过言", "label": "体标"}], "register": "中性", "sense_fingerprint": "不能当面说时，把话写下来留给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '432c6f3e-dab6-42df-a5ff-3707d97e69dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93455, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "留言", "is_correct": true, "explanation": "正确：「留言」是把话写下来留给不在家的人，与「我不在家」的语境相符。"}, {"text": "回家", "is_correct": false, "explanation": "搭配：「回家」不能带「在桌子上」这样的处所，句子不通。"}, {"text": "进门", "is_correct": false, "explanation": "配价：「进门」的宾语是门或房间，不能以「在桌子上」作处所。"}, {"text": "生气", "is_correct": false, "explanation": "语义：「生气」是情绪，不能留给别人，也与「在桌子上」搭配不通。"}], "explanations": {"留言": "正确：「留言」是把话写下来留给不在家的人，与「我不在家」的语境相符。", "回家": "搭配：「回家」不能带「在桌子上」这样的处所，句子不通。", "进门": "配价：「进门」的宾语是门或房间，不能以「在桌子上」作处所。", "生气": "语义：「生气」是情绪，不能留给别人，也与「在桌子上」搭配不通。"}, "sentence_index": 0, "correct_answer": "留言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站起来在会上留言，提出了很多建议。", "explanation": "这里应该用〈发言〉。留言是把话写下来留给不在场的人，在会上当众讲话要用发言。"}, {"text": "婚礼上，他站在台上留言，祝福新人。", "explanation": "这里应该用〈致辞〉。留言是写下话留给别人，婚礼上当众说祝福话要用致辞。"}, {"text": "他在大会上留言，介绍了新的研究成果。", "explanation": "这里应该用〈作报告〉。留言是写话留给不在场的人，在大会上介绍成果要用作报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93455, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "留言", "is_correct": true, "explanation": "正确：「留言」是把话写下来留给人，与「看你不在」的情节相符。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：「感谢」直接带对象，不说「给你感谢了」，句子不通。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：「迟到」指到得晚，不能「给你迟到」，与「看你不在」的情节不合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：客人来访时不会「给你睡觉」，与「看你不在」的情节不合。"}], "explanations": {"留言": "正确：「留言」是把话写下来留给人，与「看你不在」的情节相符。", "感谢": "配价：「感谢」直接带对象，不说「给你感谢了」，句子不通。", "迟到": "语义：「迟到」指到得晚，不能「给你迟到」，与「看你不在」的情节不合。", "睡觉": "语义：客人来访时不会「给你睡觉」，与「看你不在」的情节不合。"}, "sentence_index": 6, "correct_answer": "留言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩在门口留言，吵得很凶。", "explanation": "这里应该用〈吵架〉。留言是写话留给别人，不能用来指两人争吵。"}, {"text": "孩子在屋里留言，哭了很久。", "explanation": "这里应该用〈哭泣〉。留言是把话写下或录下留给别人，不能用来指哭泣这种情绪表现。"}, {"text": "他在舞台上留言，唱了一首歌。", "explanation": "这里应该用〈演唱〉。留言是把话写下或录下留给别人，不能用来指在台上唱歌；舞台上唱歌要用演唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天给老师留言了。", "corrected_sentence": "我明天给老师留言。", "error_description": "时间错误：「明天」是将来，不能用「了」表示已完成；应去掉「了」，说「我明天给老师留言」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前给他留言过，但他没回复。", "corrected_sentence": "我以前给他留过言，但他没回复。", "error_description": "体标位置错误：「留言过」。体标「过」应紧跟动词「留」，说「留过言」，不能说「留言过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
