INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93459, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "目录是书前面的一页，写着书里有什么、在第几页。", "primary_collocate": null, "pronunciation": "mù lù", "ipa": "mu˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "请先看目录，再找第五章。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的目录在最前面。", "target_word": "目录", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我看了目录，才知道故事在哪一页。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们翻到目录，找第三课。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从目录上看，这本书有八章。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看目录就知道，这本书一共有多少课。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "目录里没有这个故事，我找不到。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他翻开目录，找到了春天那一课。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买书前，我喜欢先读一下目录。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "目录在书的最前面，页码写在右边。", "target_word": "目录", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份目录", "label": "量词搭配"}, {"form": "目录页", "label": "复合词"}, {"form": "目錄", "label": "繁体"}], "register": "中性", "sense_fingerprint": "书前面列出内容和页码的那一页", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e00da9fe-c9f4-4fde-8aa7-2a7d288258f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93459, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "目录", "is_correct": true, "explanation": "目录（mù lù）：书前面列出篇章名称和页码的一页。"}, {"text": "母鹿", "is_correct": false, "explanation": "mǔ（第三声）与 mù（第四声）声调不同，母鹿指雌性的鹿，不是书前面的目录。"}, {"text": "木炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，木炉指木制的炉子。"}, {"text": "墓庐", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，墓庐指守墓时住的小屋，与书的目录无关。"}], "explanations": {"目录": "目录（mù lù）：书前面列出篇章名称和页码的一页。", "母鹿": "mǔ（第三声）与 mù（第四声）声调不同，母鹿指雌性的鹿，不是书前面的目录。", "木炉": "lú（第二声）与 lù（第四声）声调不同，木炉指木制的炉子。", "墓庐": "lú（第二声）与 lù（第四声）声调不同，墓庐指守墓时住的小屋，与书的目录无关。"}, "sentence_index": null, "correct_answer": "目录"}, "level_3": {"options": [{"text": "目录", "is_correct": true, "explanation": "目录：书前面列出篇章和页码的一页，符合“再找第五章”的语境。"}, {"text": "配方", "is_correct": false, "explanation": "语义：配方是做菜或配药的方子，没有章节，不能在里面找第五章。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是书面内容，没有章节可以查找。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”一般不接“声音”，这里应该说“听”。"}], "explanations": {"目录": "目录：书前面列出篇章和页码的一页，符合“再找第五章”的语境。", "配方": "语义：配方是做菜或配药的方子，没有章节，不能在里面找第五章。", "天气": "语义：天气不是书面内容，没有章节可以查找。", "声音": "搭配：“看”一般不接“声音”，这里应该说“听”。"}, "sentence_index": 0, "correct_answer": "目录"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书后面的目录按字母顺序排列，查找很方便。", "explanation": "这里应该用〈索引〉。目录按篇章顺序列在书的前面，不按字母排在书后。"}, {"text": "我去超市前先写了一份目录，免得忘记买什么。", "explanation": "这里应该用〈清单〉。目录指书或文件中按顺序列出的篇章名称及页码，购物单不叫目录。"}, {"text": "我翻开了一只目录，里面写着书的内容。", "explanation": "这里量词不对。目录用〈份〉或〈本〉，〈只〉用于动物，不能用于纸页。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93459, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "目录", "is_correct": true, "explanation": "目录（mù lù）：书前面列出篇章名称和页码的一页。"}, {"text": "牡鹿", "is_correct": false, "explanation": "mǔ（第三声）与 mù（第四声）声调不同，牡鹿指雄性的鹿，不是书前面的目录。"}, {"text": "木橹", "is_correct": false, "explanation": "lǔ（第三声）与 lù（第四声）声调不同，木橹指划船用的木桨。"}, {"text": "木炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，木炉指木制的炉子。"}], "explanations": {"目录": "目录（mù lù）：书前面列出篇章名称和页码的一页。", "牡鹿": "mǔ（第三声）与 mù（第四声）声调不同，牡鹿指雄性的鹿，不是书前面的目录。", "木橹": "lǔ（第三声）与 lù（第四声）声调不同，木橹指划船用的木桨。", "木炉": "lú（第二声）与 lù（第四声）声调不同，木炉指木制的炉子。"}, "sentence_index": null, "correct_answer": "目录"}, "level_3": {"options": [{"text": "目录", "is_correct": true, "explanation": "目录：书前面列出篇章和页码的一页，里面有没有这个故事一看便知。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，里面不会有故事。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不是可以查找故事的书面内容。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“里”一般接容器或范围，“脚步里”不通。"}], "explanations": {"目录": "目录：书前面列出篇章和页码的一页，里面有没有这个故事一看便知。", "钥匙": "语义：钥匙是开锁的工具，里面不会有故事。", "饭菜": "语义：饭菜是食物，不是可以查找故事的书面内容。", "脚步": "搭配：“里”一般接容器或范围，“脚步里”不通。"}, "sentence_index": 6, "correct_answer": "目录"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在书里夹了一个目录，下次就能接着看。", "explanation": "这里应该用〈书签〉。目录是印在书前面的一页，不能夹在书里当标记。"}, {"text": "这本书的目录里每一课都配有生词表和练习题。", "explanation": "这里应该用〈正文〉。目录只列篇章名称和页码，不含生词表和练习题。"}, {"text": "这本书有一块目录，很清楚。", "explanation": "这里量词不对。目录用〈份〉，〈块〉用于块状的东西，不用于目录。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93459, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看了一只目录，很快找到了第三章。", "corrected_sentence": "我看了一份目录，很快找到了第三章。", "error_description": "量词错误：“目录”应用“份”，“只”用于动物等，不能用于目录。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93459, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书有一棵很清楚的目录。", "corrected_sentence": "这本书有一份很清楚的目录。", "error_description": "量词错误：“目录”应用“份”，“棵”用于树木，不能用于目录。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
