INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93461, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "吃住是吃饭，还有睡觉住的地方。", "primary_collocate": null, "pronunciation": "chī zhù", "ipa": "ʈʂʰɨ˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他在公司的吃住都很好。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门在外，吃住都不太方便。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校的吃住很方便。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板包我吃住。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作很累，但吃住不用担心。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶家的吃住我都很满意。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在外地打工，吃住都在工厂。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在北京的吃住都是朋友安排的。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，吃住的地方要先找好。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上吃住很简单。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包吃住", "label": "复合"}], "register": "口语", "sense_fingerprint": "吃饭和睡觉住的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ef20229-854f-45a8-be5e-aab94d82e2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93461, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃住", "is_correct": true, "explanation": "吃住：吃饭和住宿，指在公司的饮食与住宿，与“都很好”搭配，符合句意。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是学校收取的钱，与“在公司”矛盾，句子不成立。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能用“在公司的”限定，“身高都很好”也不合常规。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“生日”不能说“在公司的生日都很好”，句意不通。"}], "explanations": {"吃住": "吃住：吃饭和住宿，指在公司的饮食与住宿，与“都很好”搭配，符合句意。", "学费": "语义：学费是学校收取的钱，与“在公司”矛盾，句子不成立。", "身高": "搭配：“身高”不能用“在公司的”限定，“身高都很好”也不合常规。", "生日": "搭配：“生日”不能说“在公司的生日都很好”，句意不通。"}, "sentence_index": 0, "correct_answer": "吃住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家养了一只吃住。", "explanation": "这里应该用〈小狗〉。“吃住”指饮食和住宿，不是动物，不能“养”，也不能用“只”计量。"}, {"text": "他买了一把吃住。", "explanation": "这里应该用〈雨伞〉。“吃住”指饮食和住宿，不是能买来的器物，不能用“把”计量。"}, {"text": "这件衣服的吃住很漂亮。", "explanation": "这里应该用〈款式〉。吃住指饮食与住宿，不能用来形容衣服的样式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93461, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃住", "is_correct": true, "explanation": "吃住：吃饭和住宿，表示生活安排，与“都在工厂”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的外观特征，不能“都在工厂”，句意不通。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言是语言，不是可以放在工厂的事物，句子不成立。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“年纪”不能说“都在工厂”，搭配不当。"}], "explanations": {"吃住": "吃住：吃饭和住宿，表示生活安排，与“都在工厂”相符。", "颜色": "语义：颜色是事物的外观特征，不能“都在工厂”，句意不通。", "方言": "语义：方言是语言，不是可以放在工厂的事物，句子不成立。", "年纪": "搭配：“年纪”不能说“都在工厂”，搭配不当。"}, "sentence_index": 6, "correct_answer": "吃住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做的吃住很香。", "explanation": "这里应该用〈饭〉。吃住指饮食和住宿，不能用来形容“香”这种气味。"}, {"text": "吃住都凉了，我们快吃。", "explanation": "这里应该用〈饭菜〉。吃住泛指饮食与住宿，不能指已经凉掉的食物。"}, {"text": "这道菜的吃住很鲜。", "explanation": "这里应该用〈味道〉。“吃住”是名词，不能表示菜的鲜味，“鲜”不能用来形容饮食与住宿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司借吃住，我很满意。", "corrected_sentence": "公司包吃住，我很满意。", "error_description": "“借”用错了。“吃住”是“包”的搭配宾语，“借”不能带“吃住”作宾语。应说“公司包吃住”，不说“公司借吃住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93461, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把吃住修理好了。", "corrected_sentence": "我把吃住安排好了。", "error_description": "“修理”用错了。“吃住”是生活安排，“修理”只用于器物或房屋，不能用于“吃住”。应说“我把吃住安排好了”，不说“我把吃住修理好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
