INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93462, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "饮食和住宿。", "primary_collocate": null, "pronunciation": "chī zhù", "ipa": "ʈʂʰɨ˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这次旅行的吃住费用不高。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的吃住由学校解决。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店吃住一天两百块。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每月的吃住要三千块。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人的吃住都有人管。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃住问题解决了，我们就出发。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司包吃住，工资也不错。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的吃住很便宜，我花钱很少。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把吃住都安排好了。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里吃住便宜，很多人愿意来。", "target_word": "吃住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包吃住", "label": "复合"}], "register": "口语", "sense_fingerprint": "饮食和住宿的费用与安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ef20229-854f-45a8-be5e-aab94d82e2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃住", "is_correct": true, "explanation": "吃住：饮食和住宿的花费，与“费用不高”搭配，符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是旅行花费的对象，“作业费用”说不通。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：歌词不是旅行的花费项目，“歌词费用不高”句子不成立。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“名字”不能与“费用”搭配，搭配不当。"}], "explanations": {"吃住": "吃住：饮食和住宿的花费，与“费用不高”搭配，符合句意。", "作业": "语义：作业不是旅行花费的对象，“作业费用”说不通。", "歌词": "语义：歌词不是旅行的花费项目，“歌词费用不高”句子不成立。", "名字": "搭配：“名字”不能与“费用”搭配，搭配不当。"}, "sentence_index": 0, "correct_answer": "吃住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的吃住很大。", "explanation": "这里应该用〈饭量〉。吃住指饮食与住宿，不能用来说一个人的食量。"}, {"text": "这条路的吃住很长。", "explanation": "这里应该用〈长度〉。吃住指饮食与住宿，不能用来形容路的长短。"}, {"text": "这台吃住很便宜。", "explanation": "这里应该用〈电脑〉。“台”用于机器，“吃住”指饮食和住宿，不是机器，不能用“台”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃住", "is_correct": true, "explanation": "吃住：饮食和住宿，作“公司包”的宾语，符合句意。"}, {"text": "学位", "is_correct": false, "explanation": "语义：学位是学历称号，不能由公司包，句子不成立。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“包”后不接“天气”，搭配不当。"}, {"text": "学业", "is_correct": false, "explanation": "语义：学业是学习事务，不能由公司包揽，句意不通。"}], "explanations": {"吃住": "吃住：饮食和住宿，作“公司包”的宾语，符合句意。", "学位": "语义：学位是学历称号，不能由公司包，句子不成立。", "天气": "搭配：“包”后不接“天气”，搭配不当。", "学业": "语义：学业是学习事务，不能由公司包揽，句意不通。"}, "sentence_index": 6, "correct_answer": "吃住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的吃住可以买一台电脑。", "explanation": "这里应该用〈工资〉。吃住指饮食和住宿的费用，不能用来购买物品。"}, {"text": "这些吃住只够买一瓶水。", "explanation": "这里应该用〈零钱〉。吃住是花费的项目，不是可以拿去购买东西的钱。"}, {"text": "吃住都花在买玩具上了。", "explanation": "这里应该用〈压岁钱〉。吃住是饮食与住宿的花费，不能用来买玩具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被吃住安排好了。", "corrected_sentence": "他把吃住安排好了。", "error_description": "“被”用错了。“他被吃住安排好了”把“他”说成被动的受事，意思是他被吃住安排，句意不通；这里是他主动安排，应用“把”，说“他把吃住安排好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂开吃住，大家都想去。", "corrected_sentence": "这家工厂包吃住，大家都想去。", "error_description": "“开”用错了。表示由工厂负担饮食和住宿，要说“包吃住”。“开”不能带“吃住”作宾语。应说“这家工厂包吃住”，不说“这家工厂开吃住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45d1615c-624c-4cb4-baee-bf5d4060e446') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
