INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93463, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93463, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词是用来叫人、东西或地方名字的词。", "primary_collocate": null, "pronunciation": "míng cí", "ipa": "miŋ˧˥ tsʰɨ˧˥", "syllable_count": 2, "sentences": [{"text": "老师问我：“医生是名词吗？”", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“桌子”是名词，“跑”是动词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名词能告诉我们人或东西叫什么。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个句子里，“朋友”是名词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把课文里的名词都画了出来。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他分不清名词和形容词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“动词”和“名词”都是词类名称。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的地名也是名词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先学名词，再学动词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上有很多名词的例子。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "用来叫人、东西或地方名字的词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe3a350-bc50-478f-b45d-f14fb4a51d8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93463, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名著", "is_correct": false, "explanation": "语义：“名著”是著名的书，与“医生”属于哪类词无关。"}, {"text": "名词", "is_correct": true, "explanation": "“名词”是语法类别，问“医生是不是名词”正确。"}, {"text": "名额", "is_correct": false, "explanation": "语义：“名额”指数量上的限定，不能用来说“医生”的词类。"}, {"text": "名牌", "is_correct": false, "explanation": "搭配：“名牌”指商品的牌子，不能用来说明“医生”是什么类别。"}], "explanations": {"名著": "语义：“名著”是著名的书，与“医生”属于哪类词无关。", "名词": "“名词”是语法类别，问“医生是不是名词”正确。", "名额": "语义：“名额”指数量上的限定，不能用来说“医生”的词类。", "名牌": "搭配：“名牌”指商品的牌子，不能用来说明“医生”是什么类别。"}, "sentence_index": 0, "correct_answer": "名词"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是我的名词。", "explanation": "这里应该用〈名片〉。“名词”是语法术语，不能用来指递给别人的卡片。"}, {"text": "班级名词贴在墙上。", "explanation": "这里应该用〈名单〉。“名词”指语法类别，不能用来指班级的名单。"}, {"text": "他以老师的名词参加了会议。", "explanation": "这里应该用〈名义〉。“名词”是语法术语，不能用于“以……的名义”的说法。“名义”指以某人或某单位的身份做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名声", "is_correct": false, "explanation": "语义：“名声”指社会上的评价，不是词类名称，不能与“动词”并列。"}, {"text": "名词", "is_correct": true, "explanation": "“名词”是词类名称，“动词和名词都是词类名称”正确。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”指人或事物的称呼，不是词类名称，“动词和名字都是词类名称”不成立。"}, {"text": "名片", "is_correct": false, "explanation": "搭配：“名片”是具体的卡片，不是词类名称，不能与“动词”并列。"}], "explanations": {"名声": "语义：“名声”指社会上的评价，不是词类名称，不能与“动词”并列。", "名词": "“名词”是词类名称，“动词和名词都是词类名称”正确。", "名字": "语义：“名字”指人或事物的称呼，不是词类名称，“动词和名字都是词类名称”不成立。", "名片": "搭配：“名片”是具体的卡片，不是词类名称，不能与“动词”并列。"}, "sentence_index": 6, "correct_answer": "名词"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商场里有很多名词。", "explanation": "这里应该用〈名牌〉。“名词”是语法术语，不能用来指商场里的品牌。"}, {"text": "他的名词很好。", "explanation": "这里应该用〈名声〉。“名词”指语法类别，不能用来说人的名声。"}, {"text": "我们班分到了三个名词。", "explanation": "这里应该用〈名额〉。“名词”是语法术语，不能用来指分到的人数。“名额”指分配给某个集体的人数或数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“城市”是一条名词。", "corrected_sentence": "“城市”是一个名词。", "error_description": "量词用错了。“名词”前面应该用“个”，“条”用于长条形的东西，不能用于名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个名词们都很重要。", "corrected_sentence": "这几个名词都很重要。", "error_description": "“名词”后面多加了“们”。“们”用于指人，“名词”是事物名称，不能加“们”，应说“这几个名词”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
