INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93464, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示人、事物、地点或抽象概念名称的词类。", "primary_collocate": null, "pronunciation": "míng cí", "ipa": "miŋ˧˥ tsʰɨ˧˥", "syllable_count": 2, "sentences": [{"text": "老师、书、北京都是名词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“苹果”是一个名词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子里有三个名词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你找出句子里的名词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名词可以表示人和东西。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“学校”和“桌子”都是名词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“动词”和“名词”都是词类名称。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天学习了名词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英语和汉语里都有名词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名词前面常常可以加量词。", "target_word": "名词", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "表示人、事物、地点或抽象概念名称的词类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe3a350-bc50-478f-b45d-f14fb4a51d8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形容词", "is_correct": false, "explanation": "语义：“老师、书、北京”不是形容词，说它们“都是形容词”与事实不符。"}, {"text": "名词", "is_correct": true, "explanation": "“名词”是词类名称，“老师、书、北京”都属于这一类，正确。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“名字”指称呼，不是词类，不能用“都是”来说明“老师、书、北京”的类别。"}, {"text": "动词", "is_correct": false, "explanation": "语义：“老师、书、北京”表示人和事物，不是动词，说它们“都是动词”与事实不符。"}], "explanations": {"形容词": "语义：“老师、书、北京”不是形容词，说它们“都是形容词”与事实不符。", "名词": "“名词”是词类名称，“老师、书、北京”都属于这一类，正确。", "名字": "搭配：“名字”指称呼，不是词类，不能用“都是”来说明“老师、书、北京”的类别。", "动词": "语义：“老师、书、北京”表示人和事物，不是动词，说它们“都是动词”与事实不符。"}, "sentence_index": 0, "correct_answer": "名词"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个产品的名词很好听。", "explanation": "这里应该用〈名称〉。“名词”是语法术语，指人、事物、地点等名称的词类，不能用来指产品的名字。"}, {"text": "我的名词叫小王。", "explanation": "这里应该用〈名字〉。“名词”是语法术语，不能用来说一个人的名字。"}, {"text": "他的包是名词，很贵。", "explanation": "这里应该用〈名牌〉。“名词”是语法术语，指人、事物、地点等名称的词类，不能用来指品牌。“名牌”指有名的品牌，多用于衣服、包等商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名著", "is_correct": false, "explanation": "语义：“名著”指著名的作品，不是词类名称，不能与“动词”并列。"}, {"text": "动物", "is_correct": false, "explanation": "语义：“动物”是生物的名称，不是词类名称，“动词和动物都是词类名称”不成立。"}, {"text": "名词", "is_correct": true, "explanation": "“名词”是词类名称，“动词和名词都是词类名称”正确。"}, {"text": "名牌", "is_correct": false, "explanation": "搭配：“名牌”指商品的品牌，不是词类名称。"}], "explanations": {"名著": "语义：“名著”指著名的作品，不是词类名称，不能与“动词”并列。", "动物": "语义：“动物”是生物的名称，不是词类名称，“动词和动物都是词类名称”不成立。", "名词": "“名词”是词类名称，“动词和名词都是词类名称”正确。", "名牌": "搭配：“名牌”指商品的品牌，不是词类名称。"}, "sentence_index": 6, "correct_answer": "名词"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有很多名词，大家都很喜欢他。", "explanation": "这里应该用〈称呼〉。“名词”是语法术语，不能用来指人的绰号或称呼。"}, {"text": "这个部队有一个名词。", "explanation": "这里应该用〈代号〉。“名词”指语法类别，不能用来指部队的代号。"}, {"text": "这次比赛我们班有三个名词。", "explanation": "这里应该用〈名额〉。“名词”是语法术语，不能用来指分到的人数。“名额”指分配给某个单位或集体的数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“房间”也是一只名词。", "corrected_sentence": "“房间”也是一个名词。", "error_description": "量词用错了。“名词”前面应该用“个”，“只”多用于动物，不能用于名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些名词们都要背下来。", "corrected_sentence": "这些名词都要背下来。", "error_description": "“名词”后面多加了“们”。“们”用于指人的复数，“名词”是事物名称，不能加“们”，应说“这些名词”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
