INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93465, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "瞧是看的意思，是说话时常用的词。", "primary_collocate": null, "pronunciation": "qiáo", "ipa": "tɕʰjau˧˥", "syllable_count": 1, "sentences": [{"text": "你瞧，外面下雪了。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瞧那只小猫，它在睡觉。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回头瞧了我一眼。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈站在门口瞧着我。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你瞧这件衣服怎么样？", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没瞧过这么大的鱼。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瞧，公共汽车来了！", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直瞧着窗外。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你瞧他笑得多高兴。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "让我瞧一下你的作业。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瞧瞧", "label": "重叠"}, {"form": "瞧了", "label": "体标"}, {"form": "瞧着", "label": "体标"}, {"form": "瞧过", "label": "体标"}], "register": "口语", "sense_fingerprint": "口语中表示“看”，常用来提醒别人注意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9409145b-2236-4775-a2e2-57b5c7a49d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93465, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "瞧", "is_correct": true, "explanation": "正确答案。“瞧”（qiáo，第二声）意思是看，多用于口语。"}, {"text": "敲", "is_correct": false, "explanation": "qiāo（第一声）与 qiáo（第二声）声调不同，意思是敲打。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo（第三声）与 qiáo（第二声）声调不同，意思是灵巧、恰好。"}, {"text": "俏", "is_correct": false, "explanation": "qiào（第四声）与 qiáo（第二声）声调不同，意思是俊俏、好看。"}], "explanations": {"瞧": "正确答案。“瞧”（qiáo，第二声）意思是看，多用于口语。", "敲": "qiāo（第一声）与 qiáo（第二声）声调不同，意思是敲打。", "巧": "qiǎo（第三声）与 qiáo（第二声）声调不同，意思是灵巧、恰好。", "俏": "qiào（第四声）与 qiáo（第二声）声调不同，意思是俊俏、好看。"}, "sentence_index": null, "correct_answer": "瞧"}, "level_3": {"options": [{"text": "瞧", "is_correct": true, "explanation": "正确。“你瞧”是口语，用来提醒对方注意外面的景象。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃与“外面下雪”无关，不能用来提醒对方注意景象。"}, {"text": "摸", "is_correct": false, "explanation": "语义：摸是用手触碰，无法用来提醒对方看外面下雪。"}, {"text": "扔", "is_correct": false, "explanation": "配价：扔需要受事宾语，句中没有可扔的东西。"}], "explanations": {"瞧": "正确。“你瞧”是口语，用来提醒对方注意外面的景象。", "吃": "语义：吃与“外面下雪”无关，不能用来提醒对方注意景象。", "摸": "语义：摸是用手触碰，无法用来提醒对方看外面下雪。", "扔": "配价：扔需要受事宾语，句中没有可扔的东西。"}, "sentence_index": 0, "correct_answer": "瞧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在教室里瞧了一首新歌。", "explanation": "这里应该用〈听〉。瞧指用眼睛看，听歌要用耳朵。"}, {"text": "我饿了，就瞧了一个苹果。", "explanation": "这里应该用〈吃〉。瞧指用眼睛看，吃苹果要用“吃”。"}, {"text": "他着急地瞧了一声。", "explanation": "这里应该用〈喊〉。瞧指用眼睛看，发出声音要用“喊”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93465, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "瞧", "is_correct": true, "explanation": "正确答案。“瞧”（qiáo，第二声）意思是看，多用于口语。"}, {"text": "敲", "is_correct": false, "explanation": "qiāo（第一声）与 qiáo（第二声）声调不同，意思是敲打。"}, {"text": "撬", "is_correct": false, "explanation": "qiào（第四声）与 qiáo（第二声）声调不同，意思是用工具把东西撬开。"}, {"text": "窍", "is_correct": false, "explanation": "qiào（第四声）与 qiáo（第二声）声调不同，意思是孔窍、窍门。"}], "explanations": {"瞧": "正确答案。“瞧”（qiáo，第二声）意思是看，多用于口语。", "敲": "qiāo（第一声）与 qiáo（第二声）声调不同，意思是敲打。", "撬": "qiào（第四声）与 qiáo（第二声）声调不同，意思是用工具把东西撬开。", "窍": "qiào（第四声）与 qiáo（第二声）声调不同，意思是孔窍、窍门。"}, "sentence_index": null, "correct_answer": "瞧"}, "level_3": {"options": [{"text": "瞧", "is_correct": true, "explanation": "正确。“瞧”在口语中用来提醒对方注意，与“公共汽车来了”相合。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡觉与“公共汽车来了”无关，不能用来提醒对方注意。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗与提醒对方注意公共汽车无关。"}, {"text": "接", "is_correct": false, "explanation": "配价：接需要接的对象，句中没有宾语。"}], "explanations": {"瞧": "正确。“瞧”在口语中用来提醒对方注意，与“公共汽车来了”相合。", "睡": "语义：睡觉与“公共汽车来了”无关，不能用来提醒对方注意。", "洗": "语义：洗与提醒对方注意公共汽车无关。", "接": "配价：接需要接的对象，句中没有宾语。"}, "sentence_index": 6, "correct_answer": "瞧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤太烫，我先瞧一口。", "explanation": "这里应该用〈尝〉。瞧指用眼睛看，尝味道要用嘴。"}, {"text": "这块蛋糕很松软，我用手瞧了瞧。", "explanation": "这里应该用〈摸〉。瞧指用眼睛看，检验松软要用手摸。"}, {"text": "他生气了，瞧了我一拳。", "explanation": "这里应该用〈打〉。瞧指用眼睛看，打人要用“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直瞧了天上的云。", "corrected_sentence": "他一直瞧着天上的云。", "error_description": "错误：表示动作持续进行，应用“瞧着”，不能用“瞧了”。正确说法是“一直瞧着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
