INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93466, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看（口语）。", "primary_collocate": null, "pronunciation": "qiáo", "ipa": "tɕʰjau˧˥", "syllable_count": 1, "sentences": [{"text": "别光站着，过来瞧一瞧。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去隔壁瞧了他一下。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想瞧瞧你的新手机。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着书瞧了半天。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她偷偷瞧了我两眼。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩好奇地瞧着蛋糕。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你瞧那边，那是谁？", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在街上瞧过他。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "让我瞧瞧这是什么。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踮着脚往里瞧。", "target_word": "瞧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瞧瞧", "label": "重叠"}, {"form": "瞧了", "label": "体标"}, {"form": "瞧着", "label": "体标"}, {"form": "瞧过", "label": "体标"}], "register": "口语", "sense_fingerprint": "口语中的“看”，指用眼睛看人或物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 踮 (Zipf 2.12)']::text[], '9409145b-2236-4775-a2e2-57b5c7a49d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93466, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "瞧", "is_correct": true, "explanation": "正确答案。“瞧”（qiáo，第二声）意思是看，多用于口语。"}, {"text": "悄", "is_correct": false, "explanation": "qiāo（第一声）与 qiáo（第二声）声调不同，意思是安静、不声张，如“悄悄”。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo（第三声）与 qiáo（第二声）声调不同，意思是灵巧、恰好。"}, {"text": "俏", "is_correct": false, "explanation": "qiào（第四声）与 qiáo（第二声）声调不同，意思是俊俏、好看。"}], "explanations": {"瞧": "正确答案。“瞧”（qiáo，第二声）意思是看，多用于口语。", "悄": "qiāo（第一声）与 qiáo（第二声）声调不同，意思是安静、不声张，如“悄悄”。", "巧": "qiǎo（第三声）与 qiáo（第二声）声调不同，意思是灵巧、恰好。", "俏": "qiào（第四声）与 qiáo（第二声）声调不同，意思是俊俏、好看。"}, "sentence_index": null, "correct_answer": "瞧"}, "level_3": {"options": [{"text": "瞧", "is_correct": true, "explanation": "正确。“过来瞧一瞧”是口语，表示走过来看看。"}, {"text": "发生", "is_correct": false, "explanation": "语义：发生指事情出现，不能用在“过来……一……”的结构里表示看看。"}, {"text": "进行", "is_correct": false, "explanation": "配价：进行需要宾语，如“进行讨论”，句中不能这样单独使用。"}, {"text": "举行", "is_correct": false, "explanation": "配价：举行需要活动作宾语，如“举行会议”，不能用“举行一举行”的重叠形式，也不表示看看。"}], "explanations": {"瞧": "正确。“过来瞧一瞧”是口语，表示走过来看看。", "发生": "语义：发生指事情出现，不能用在“过来……一……”的结构里表示看看。", "进行": "配价：进行需要宾语，如“进行讨论”，句中不能这样单独使用。", "举行": "配价：举行需要活动作宾语，如“举行会议”，不能用“举行一举行”的重叠形式，也不表示看看。"}, "sentence_index": 0, "correct_answer": "瞧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一边做饭，一边瞧广播。", "explanation": "这里应该用〈听〉。瞧指用眼睛看，广播要用耳朵听。"}, {"text": "小猫在草地上玩，它用鼻子瞧了瞧花。", "explanation": "这里应该用〈闻〉。瞧指用眼睛看，用鼻子感受气味要说“闻”。"}, {"text": "他下班后瞧了我一个电话。", "explanation": "这里应该用〈打〉。瞧指用眼睛看，给人打电话要用“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93466, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "瞧", "is_correct": true, "explanation": "正确答案。“瞧”（qiáo，第二声）意思是看，多用于口语。"}, {"text": "敲", "is_correct": false, "explanation": "qiāo（第一声）与 qiáo（第二声）声调不同，意思是敲打。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo（第三声）与 qiáo（第二声）声调不同，意思是灵巧、恰好。"}, {"text": "撬", "is_correct": false, "explanation": "qiào（第四声）与 qiáo（第二声）声调不同，意思是用工具把东西撬开。"}], "explanations": {"瞧": "正确答案。“瞧”（qiáo，第二声）意思是看，多用于口语。", "敲": "qiāo（第一声）与 qiáo（第二声）声调不同，意思是敲打。", "巧": "qiǎo（第三声）与 qiáo（第二声）声调不同，意思是灵巧、恰好。", "撬": "qiào（第四声）与 qiáo（第二声）声调不同，意思是用工具把东西撬开。"}, "sentence_index": null, "correct_answer": "瞧"}, "level_3": {"options": [{"text": "瞧", "is_correct": true, "explanation": "正确。“你瞧那边”是口语，用来提醒对方看某个方向。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱不能和“那边”组合来提醒对方注意方向。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：嚼是咀嚼食物，与提醒对方看方向无关。"}, {"text": "穿", "is_correct": false, "explanation": "配价：穿需要衣物作宾语，“穿那边”不成立。"}], "explanations": {"瞧": "正确。“你瞧那边”是口语，用来提醒对方看某个方向。", "唱": "搭配：唱不能和“那边”组合来提醒对方注意方向。", "嚼": "语义：嚼是咀嚼食物，与提醒对方看方向无关。", "穿": "配价：穿需要衣物作宾语，“穿那边”不成立。"}, "sentence_index": 6, "correct_answer": "瞧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他渴了，就瞧了一杯水。", "explanation": "这里应该用〈喝〉。瞧指用眼睛看，喝水要用嘴。"}, {"text": "他生气，瞧了一脚门。", "explanation": "这里应该用〈踢〉。瞧指用眼睛看，用脚踢门要用“踢”。"}, {"text": "这块布很软，他用手瞧了瞧。", "explanation": "这里应该用〈摸〉。瞧指用眼睛看，检验软硬要用手摸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我站得太远，没清瞧他的脸。", "corrected_sentence": "我站得太远，没瞧清他的脸。", "error_description": "错误：结果补语“清”应紧跟在动词“瞧”后面，说“瞧清”，不能说“清瞧”。正确说法是“没瞧清他的脸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前在窗口瞧了过那辆车。", "corrected_sentence": "我以前在窗口瞧过那辆车。", "error_description": "错误：表示经历过的动作用“瞧过”，“了”与“过”不能同时用在动词后面。正确说法是“瞧过那辆车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '042578da-9301-4dce-9c1c-bc9a6d907488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
