INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93467, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "唱片是圆圆的盘，里面有歌可以放出来。", "primary_collocate": null, "pronunciation": "chàng piàn", "ipa": "tʂʰɑŋ˥˩ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷有一张旧唱片。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把唱片放进了唱机里。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一张圆圆的唱片。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张唱片里有很多老歌。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在商店买了两张唱片。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱片转起来，音乐就响了。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈小心地擦着唱片。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家里有很多唱片。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张唱片是爸爸送我的。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店专门卖老唱片。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "黑胶唱片", "label": "复合"}], "register": "中性", "sense_fingerprint": "圆圆的盘，里面有歌可以放出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe3a350-bc50-478f-b45d-f14fb4a51d8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93467, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱片", "is_correct": true, "explanation": "正确：唱片是圆盘，量词用“张”，“一张旧唱片”符合句意。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“歌”的量词是“首”，不说“一张旧歌”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”的量词是“本”，不说“一张旧书”。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：“孩子”指人，不是能用“张”来数的旧物件。"}], "explanations": {"唱片": "正确：唱片是圆盘，量词用“张”，“一张旧唱片”符合句意。", "歌": "搭配：“歌”的量词是“首”，不说“一张旧歌”。", "书": "搭配：“书”的量词是“本”，不说“一张旧书”。", "孩子": "语义：“孩子”指人，不是能用“张”来数的旧物件。"}, "sentence_index": 0, "correct_answer": "唱片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这张唱片洗出来，挂在墙上。", "explanation": "这里应该用〈照片〉。照片可以洗印、挂在墙上，唱片是音乐圆盘，不能洗印。"}, {"text": "我们今天用唱片看了一部电影。", "explanation": "这里应该用〈录像带〉。唱片只能放声音，看电影要用录像带。"}, {"text": "妈妈用这张唱片切菜。", "explanation": "这里应该用〈菜刀〉。唱片是圆盘，没有刀刃，不能切东西，切菜要用菜刀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93467, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱片", "is_correct": true, "explanation": "正确：“擦着唱片”指擦拭唱片，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“擦”搭桌子、玻璃等物体，不说擦空气。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：“噪音”是声音，不能用布擦。"}, {"text": "思念", "is_correct": false, "explanation": "配价：“擦”要带具体的物体作宾语，“思念”是抽象的感情，不能擦。"}], "explanations": {"唱片": "正确：“擦着唱片”指擦拭唱片，符合句意。", "空气": "搭配：“擦”搭桌子、玻璃等物体，不说擦空气。", "噪音": "语义：“噪音”是声音，不能用布擦。", "思念": "配价：“擦”要带具体的物体作宾语，“思念”是抽象的感情，不能擦。"}, "sentence_index": 6, "correct_answer": "唱片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天买了一把唱片。", "explanation": "这里应该用〈张〉。“把”用于有把手的东西，唱片的量词是“张”。"}, {"text": "他送给我一本唱片。", "explanation": "这里应该用〈张〉。“本”用于书籍和册子，唱片不能用“本”来数。"}, {"text": "我家有两台唱片。", "explanation": "这里应该用〈张〉。“台”用于机器，唱片要用“张”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93467, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我唱片放进了柜子里。", "corrected_sentence": "我把唱片放进了柜子里。", "error_description": "错误形式：“我唱片放进了柜子里”。正确形式：“我把唱片放进了柜子里”。“我”和“唱片”直接相连，成分混乱，句子不通；加上“把”，“唱片”作“放进”的宾语，句子才通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
