INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93468, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "刻录有声音、可用唱机播放的圆盘。", "primary_collocate": null, "pronunciation": "chàng piàn", "ipa": "tʂʰɑŋ˥˩ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这张唱片要用唱机来播放。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张唱片的声音很温暖。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最喜欢收集老唱片。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手新出了一张唱片。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱片上刻着一圈细细的纹路。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把唱片放回封套里。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把唱片放到唱机上。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张唱片已经卖完了。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手在我的唱片上签了名。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱片掉在地上，裂开了。", "target_word": "唱片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "黑胶唱片", "label": "复合"}], "register": "中性", "sense_fingerprint": "刻录有声音、可用唱机播放的圆盘", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe3a350-bc50-478f-b45d-f14fb4a51d8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱片", "is_correct": true, "explanation": "正确：唱片能用唱机播放，量词“张”也对，句子通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能用唱机播放。"}, {"text": "画", "is_correct": false, "explanation": "语义：画是给人看的，不能用唱机播放。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”的量词是“本”，不说“这张书”；而且书也不能用唱机播放。"}], "explanations": {"唱片": "正确：唱片能用唱机播放，量词“张”也对，句子通顺。", "桌子": "语义：桌子是家具，不能用唱机播放。", "画": "语义：画是给人看的，不能用唱机播放。", "书": "搭配：“书”的量词是“本”，不说“这张书”；而且书也不能用唱机播放。"}, "sentence_index": 0, "correct_answer": "唱片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位歌手新出了一本唱片。", "explanation": "这里应该用〈张〉。“本”用于书籍，唱片要用“张”来数。"}, {"text": "我昨天买了两条唱片。", "explanation": "这里应该用〈张〉。“条”用于长条形的东西，唱片的量词是“张”。"}, {"text": "爸爸送了我一台唱片。", "explanation": "这里应该用〈张〉。“台”用于机器，唱片要用“张”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱片", "is_correct": true, "explanation": "正确：“放到唱机上”的是唱片，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见摸不着，不能放到唱机上。"}, {"text": "思想", "is_correct": false, "explanation": "配价：“放”要求具体的物体作宾语，“思想”是抽象的，不能放。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“把……放到”搭配具体的物体，不说把声音放到唱机上。"}], "explanations": {"唱片": "正确：“放到唱机上”的是唱片，符合句意。", "空气": "语义：空气看不见摸不着，不能放到唱机上。", "思想": "配价：“放”要求具体的物体作宾语，“思想”是抽象的，不能放。", "声音": "搭配：“把……放到”搭配具体的物体，不说把声音放到唱机上。"}, "sentence_index": 6, "correct_answer": "唱片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用这张唱片扇风。", "explanation": "这里应该用〈扇子〉。唱片是圆盘，不能扇风，扇风要用扇子。"}, {"text": "我用这张唱片看了一部电影。", "explanation": "这里应该用〈影碟〉。唱片只放声音，看电影要用影碟。"}, {"text": "我把论文存在这张唱片里。", "explanation": "这里应该用〈磁盘〉。唱片是音乐载体，不能存文件，存论文要用磁盘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸的每条唱片都要用唱机播放。", "corrected_sentence": "爸爸的每张唱片都要用唱机播放。", "error_description": "错误形式：“每条唱片”。正确形式：“每张唱片”。“唱片”是扁平圆盘，量词是“张”，不能用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "唱片从桌上掉下来，裂了开。", "corrected_sentence": "唱片从桌上掉下来，裂开了。", "error_description": "错误形式：“裂了开”。正确形式：“裂开了”。“裂开”是动词加补语的固定结构，不能把“了”插进中间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
