INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93469, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "研究生是大学毕业后，还继续在学校学习和研究的人。", "primary_collocate": null, "pronunciation": "yán jiū shēng", "ipa": "jɛn˧˥ tɕjoʊ˥ ʂɤŋ˥", "syllable_count": 3, "sentences": [{"text": "小王大学毕业后，又当了研究生。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究生的生活很忙。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们学校的研究生。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年考上了研究生。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究生常常在图书馆学习。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让研究生帮忙做实验。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想读研究生，继续学习。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位研究生住在学校里。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究生和本科生一起上课。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他哥哥是学历史的研究生。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "硕士研究生", "label": "复合"}], "register": "中性", "sense_fingerprint": "大学毕业后还在学校学习研究的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81bc4bc-44c8-4cf6-a5b7-596f28b237e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93469, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究生", "is_correct": true, "explanation": "正确：大学毕业后继续在学校学习研究的人是研究生，与“又当了”搭配。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小王已经大学毕业，不会再回去当小学生，与句中的时间顺序矛盾。"}, {"text": "幼儿园", "is_correct": false, "explanation": "搭配：“当”接职业或身份，不接机构名称，不能说“当了幼儿园”。"}, {"text": "中学", "is_correct": false, "explanation": "搭配：“当”接职业或身份，不能说“当了中学”。"}], "explanations": {"研究生": "正确：大学毕业后继续在学校学习研究的人是研究生，与“又当了”搭配。", "小学生": "语义：小王已经大学毕业，不会再回去当小学生，与句中的时间顺序矛盾。", "幼儿园": "搭配：“当”接职业或身份，不接机构名称，不能说“当了幼儿园”。", "中学": "搭配：“当”接职业或身份，不能说“当了中学”。"}, "sentence_index": 0, "correct_answer": "研究生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她刚进大学，是新来的研究生。", "explanation": "这里应该用〈大学生〉。刚进大学的人是大学生，研究生须本科毕业后才能读。"}, {"text": "这位研究生在大学教了三十年书。", "explanation": "这里应该用〈教授〉。研究生是在读学生，不能说在大学任教三十年。"}, {"text": "他去年才从高中毕业，现在是一名研究生。", "explanation": "这里应该用〈高中生〉。研究生须大学本科毕业，刚从高中毕业的人不能读研究生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93469, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究生", "is_correct": true, "explanation": "正确：“读研究生”是常见搭配，与“继续学习”相符。"}, {"text": "驾照", "is_correct": false, "explanation": "搭配：“读”接书籍、学位，不能接“驾照”，应说“考”驾照。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“读”不接“电影”，电影是用来看的。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“工作”不是学习的内容，与“继续学习”相矛盾。"}], "explanations": {"研究生": "正确：“读研究生”是常见搭配，与“继续学习”相符。", "驾照": "搭配：“读”接书籍、学位，不能接“驾照”，应说“考”驾照。", "电影": "搭配：“读”不接“电影”，电影是用来看的。", "工作": "语义：“工作”不是学习的内容，与“继续学习”相矛盾。"}, "sentence_index": 6, "correct_answer": "研究生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位研究生已经七十岁，在大学教了四十年书。", "explanation": "这里应该用〈学者〉。研究生是在读学生，不会七十岁还在大学教书四十年。"}, {"text": "我们的数学研究生上个月退休了。", "explanation": "这里应该用〈老师〉。研究生是学生，不会“退休”。"}, {"text": "这个研究生刚满三岁，还不会写字。", "explanation": "这里应该用〈小孩〉。研究生须大学本科毕业，不能说刚满三岁还不会写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那本研究生教我们数学。", "corrected_sentence": "那位研究生教我们数学。", "error_description": "量词错误：“研究生”指人，量词应用“位”或“名”。“本”是书的量词，不能用于研究生，应说“那位研究生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我认识两只研究生，他们都学历史。", "corrected_sentence": "我认识两位研究生，他们都学历史。", "error_description": "量词错误：“只”用于动物，指人应用“位”或“名”。错误形式是“两只研究生”，正确形式是“两位研究生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
