INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大学本科毕业后，继续在高等学校或研究机构学习和研究的学生。", "primary_collocate": null, "pronunciation": "yán jiū shēng", "ipa": "jɛn˧˥ tɕjoʊ˥ ʂɤŋ˥", "syllable_count": 3, "sentences": [{"text": "她本科毕业后读了研究生。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐是北京大学的研究生。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究生每周要看很多书。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打算考研究生。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位研究生的论文写得很好。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究生宿舍在学校东边。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究生要做自己的研究。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学院有两百名研究生。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一名学经济的研究生。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究生一般要读两三年。", "target_word": "研究生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "硕士研究生", "label": "复合"}], "register": "中性", "sense_fingerprint": "本科毕业后继续读书做研究的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81bc4bc-44c8-4cf6-a5b7-596f28b237e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究生", "is_correct": true, "explanation": "正确：本科毕业后继续读书做研究的是研究生，与“读了”搭配。"}, {"text": "高中", "is_correct": false, "explanation": "语义：“本科毕业后”已超过高中阶段，说“读了高中”与句中的时间条件矛盾。"}, {"text": "驾照", "is_correct": false, "explanation": "搭配：“读”接书籍、学位、学校，不能接“驾照”，应说“考”或“拿”驾照。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园是学前教育机构，与“本科毕业后”的时间顺序相矛盾。"}], "explanations": {"研究生": "正确：本科毕业后继续读书做研究的是研究生，与“读了”搭配。", "高中": "语义：“本科毕业后”已超过高中阶段，说“读了高中”与句中的时间条件矛盾。", "驾照": "搭配：“读”接书籍、学位、学校，不能接“驾照”，应说“考”或“拿”驾照。", "幼儿园": "语义：幼儿园是学前教育机构，与“本科毕业后”的时间顺序相矛盾。"}, "sentence_index": 0, "correct_answer": "研究生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚进大学，还是一年级的研究生。", "explanation": "这里应该用〈大学生〉。刚进大学的人是大学生，研究生须本科毕业后才能读，不能说“一年级的研究生”。"}, {"text": "她在中学当了三十年的研究生。", "explanation": "这里应该用〈老师〉。研究生是在读学生，不能说在中学当了三十年的研究生。"}, {"text": "他在小学读五年级，是一名研究生。", "explanation": "这里应该用〈学生〉。研究生须大学本科毕业，在小学读书的人不能称研究生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究生", "is_correct": true, "explanation": "正确：研究生是做研究的主体，作主语合适。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有研究能力，不能做研究。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑构件，不能做研究。"}, {"text": "出租车", "is_correct": false, "explanation": "配价：“做研究”要求施事是有研究能力的人，出租车不能充当施事。"}], "explanations": {"研究生": "正确：研究生是做研究的主体，作主语合适。", "石头": "语义：石头没有研究能力，不能做研究。", "窗户": "语义：窗户是建筑构件，不能做研究。", "出租车": "配价：“做研究”要求施事是有研究能力的人，出租车不能充当施事。"}, "sentence_index": 6, "correct_answer": "研究生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位研究生七十岁了，在大学教了四十年书。", "explanation": "这里应该用〈学者〉。研究生是在读学生，不会七十岁还在大学教书四十年。"}, {"text": "这个研究生刚学会写字，还不认识很多字。", "explanation": "这里应该用〈小学生〉。研究生须大学本科毕业，不能说刚学会写字。"}, {"text": "这个研究生刚满三岁，还不会说话。", "explanation": "这里应该用〈幼儿〉。研究生是已完成本科学业的人，不能说刚满三岁还不会说话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校今年招了三本研究生。", "corrected_sentence": "学校今年招了三名研究生。", "error_description": "量词错误：“研究生”指人，量词应用“名”或“位”。“本”是书的量词，不能用于研究生，应说“三名研究生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学院里有三百条研究生。", "corrected_sentence": "学院里有三百名研究生。", "error_description": "量词错误：“条”用于细长的东西，指人应用“名”或“位”，应说“三百名研究生”，不能说“三百条研究生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
