INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93471, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "嘲笑是笑别人，让他觉得难过。", "primary_collocate": null, "pronunciation": "cháo xiào", "ipa": "ʈʂʰɑʊ˧˥ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "同学们都嘲笑他的新发型。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要嘲笑别人的错误。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔倒了，大家却在嘲笑他。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我嘲笑过一个同学，现在很后悔。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们嘲笑着我的口音，我很难过。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么总是嘲笑弟弟？", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人应该嘲笑穷人。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱错了一句，朋友们就嘲笑她。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别嘲笑我，我已经很努力了。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不让我们嘲笑成绩差的同学。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嘲笑了", "label": "完成体"}, {"form": "嘲笑过", "label": "经历体"}, {"form": "嘲笑着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "笑话别人，让人难过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9732594-50f6-455c-99d9-7791dffce9b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93471, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”指思念过去的人或事，与“新”发型矛盾，句子不通。"}, {"text": "嘲笑", "is_correct": true, "explanation": "正确：“嘲笑”指讥笑别人使其难过，与“同学们都……”的态度相符。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”的对象是喜事或成就，不能用于发型。"}, {"text": "打扮", "is_correct": false, "explanation": "配价：“打扮”的宾语是人，不能以“发型”作宾语。"}], "explanations": {"怀念": "语义：“怀念”指思念过去的人或事，与“新”发型矛盾，句子不通。", "嘲笑": "正确：“嘲笑”指讥笑别人使其难过，与“同学们都……”的态度相符。", "祝贺": "搭配：“祝贺”的对象是喜事或成就，不能用于发型。", "打扮": "配价：“打扮”的宾语是人，不能以“发型”作宾语。"}, "sentence_index": 0, "correct_answer": "嘲笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板见到我，对我嘲笑了一下，表示感谢。", "explanation": "这里应该用〈微笑〉。嘲笑含有讥讽之意，表示感谢的笑应用微笑，与“表示感谢”矛盾。"}, {"text": "孩子们在草地上嘲笑着奔跑，玩得很开心。", "explanation": "这里应该用〈欢笑〉。嘲笑专指讥笑别人使其难过，孩子快乐奔跑时的笑应说欢笑，与“玩得很开心”矛盾。"}, {"text": "孩子大哭起来，妈妈连忙蹲下，轻声嘲笑他，好让他安静下来。", "explanation": "这里应该用〈安慰〉。嘲笑是讥笑人，使其难过；要让哭泣的孩子安静下来应用安慰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93471, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”是为喜事欢庆，与“穷人”的处境不相容，句意荒谬。"}, {"text": "嘲笑", "is_correct": true, "explanation": "正确：“嘲笑”指讥笑，句子说的是不应该讥笑穷人。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能用来指人。"}, {"text": "解释", "is_correct": false, "explanation": "配价：“解释”的宾语是事理，不能直接以“穷人”作宾语。"}], "explanations": {"庆祝": "语义：“庆祝”是为喜事欢庆，与“穷人”的处境不相容，句意荒谬。", "嘲笑": "正确：“嘲笑”指讥笑，句子说的是不应该讥笑穷人。", "参观": "搭配：“参观”的对象是场所或展览，不能用来指人。", "解释": "配价：“解释”的宾语是事理，不能直接以“穷人”作宾语。"}, "sentence_index": 6, "correct_answer": "嘲笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在班会上嘲笑了他的进步，还给他颁了奖。", "explanation": "这里应该用〈表扬〉。嘲笑是讥笑人，与“颁了奖”这种肯定进步的做法矛盾；公开肯定进步应说表扬。"}, {"text": "妈妈看我大胆表达，就轻轻嘲笑了我一下，鼓励我多说。", "explanation": "这里应该用〈鼓励〉。嘲笑含讥笑之意，与“鼓励我多说”的支持态度矛盾。"}, {"text": "大家都嘲笑这位新同学的加入，纷纷表示欢迎。", "explanation": "这里应该用〈欢迎〉。嘲笑是讥笑人，与“纷纷表示欢迎”的接纳态度矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她不嘲笑过别人的梦想。", "corrected_sentence": "她没嘲笑过别人的梦想。", "error_description": "否定经历要用“没”，“不”不能与表示经历的“过”搭配。应把“不”改为“没”，说“没嘲笑过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是嘲笑了我。", "corrected_sentence": "他总是嘲笑我。", "error_description": "体标误用：“总是”表示经常、习惯性的动作，不能和表示完成的“了”一起用。应去掉“了”，说“他总是嘲笑我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93472, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93472, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93472, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用言语讥笑别人。", "primary_collocate": null, "pronunciation": "cháo xiào", "ipa": "ʈʂʰɑʊ˧˥ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他用难听的话嘲笑我。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的画不太好，有人嘲笑了几句。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家嘲笑他说话慢。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有嘲笑过别人的名字。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥总爱嘲笑我胖。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们嘲笑那个人的旧衣服。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样嘲笑他，他会很伤心。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人嘲笑他，他只是笑一笑。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事嘲笑他又迟到了。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不怕别人嘲笑，还是继续练习。", "target_word": "嘲笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嘲笑了", "label": "完成体"}, {"form": "嘲笑过", "label": "经历体"}, {"form": "嘲笑着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "用话语讥笑别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9732594-50f6-455c-99d9-7791dffce9b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞，与“难听的话”矛盾。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：“拥抱”是身体动作，不能用“话”来进行。"}, {"text": "嘲笑", "is_correct": true, "explanation": "正确：“嘲笑”指用言语讥笑人，与“用难听的话”相符。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”是抚慰，与“难听的话”矛盾。"}], "explanations": {"赞美": "语义：“赞美”是称赞，与“难听的话”矛盾。", "拥抱": "搭配：“拥抱”是身体动作，不能用“话”来进行。", "嘲笑": "正确：“嘲笑”指用言语讥笑人，与“用难听的话”相符。", "安慰": "语义：“安慰”是抚慰，与“难听的话”矛盾。"}, "sentence_index": 0, "correct_answer": "嘲笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师当众嘲笑她的作文，并为她的进步感到骄傲。", "explanation": "这里应该用〈赞扬〉。嘲笑是用言语讥笑人，与“为她的进步感到骄傲”的肯定态度矛盾。"}, {"text": "老师耐心地嘲笑学生的写作，帮他们改正。", "explanation": "这里应该用〈指导〉。嘲笑是讥笑，与“耐心”“帮他们改正”的语境矛盾。"}, {"text": "她哭得很厉害，我连忙嘲笑她，好让她安心。", "explanation": "这里应该用〈安慰〉。嘲笑是讥笑人，会使人难过；让哭泣的人安心应用安慰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是肯定，与“他会很伤心”的结果矛盾。"}, {"text": "陪伴", "is_correct": false, "explanation": "搭配：“陪伴”没有伤人的意味，与“你这样……”的贬损方式不搭配。"}, {"text": "嘲笑", "is_correct": true, "explanation": "正确：“嘲笑”指讥笑，“你这样……他会很伤心”的因果关系成立。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是接纳，与“他会很伤心”的因果不符。"}], "explanations": {"表扬": "语义：“表扬”是肯定，与“他会很伤心”的结果矛盾。", "陪伴": "搭配：“陪伴”没有伤人的意味，与“你这样……”的贬损方式不搭配。", "嘲笑": "正确：“嘲笑”指讥笑，“你这样……他会很伤心”的因果关系成立。", "欢迎": "语义：“欢迎”是接纳，与“他会很伤心”的因果不符。"}, "sentence_index": 6, "correct_answer": "嘲笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家热情地嘲笑新来的同学。", "explanation": "这里应该用〈欢迎〉。嘲笑是讥笑，与“热情”的接纳态度相反。"}, {"text": "老师看到我们大胆发言，就嘲笑我们，并鼓励大家多提问。", "explanation": "这里应该用〈鼓励〉。嘲笑是讥笑人，与老师鼓励大家多提问的态度相反。"}, {"text": "妈妈温柔地嘲笑哭泣的弟弟。", "explanation": "这里应该用〈劝解〉。嘲笑是讥笑，与“温柔”的劝解态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从来没有嘲笑了我的朋友。", "corrected_sentence": "他从来没有嘲笑过我的朋友。", "error_description": "“没有”否定过去的经历时，动词后应用体标“过”，不能用“了”。应说“从来没有嘲笑过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们正在嘲笑了我的口音。", "corrected_sentence": "他们正在嘲笑我的口音。", "error_description": "“正在”表示动作进行，不能与表示完成的“了”同用，应去掉“了”，说“正在嘲笑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b4d08d8-e630-48b7-9ee5-3c360bc6f4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗", "is_correct": true, "explanation": "“粗”与“精”（做工细致）相对，指做工粗糙、不细致。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”与“精”没有反义关系，不能用来与做工的精细相对。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”与“精”没有反义关系，句中说的是做工，不是重量。"}, {"text": "暖", "is_correct": false, "explanation": "“暖”与“精”没有反义关系，不能用来评价做工。"}], "correct_answer": "粗", "explanations": {"粗": "“粗”与“精”（做工细致）相对，指做工粗糙、不细致。", "慢": "“慢”与“精”没有反义关系，不能用来与做工的精细相对。", "轻": "“轻”与“精”没有反义关系，句中说的是做工，不是重量。", "暖": "“暖”与“精”没有反义关系，不能用来评价做工。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
