INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "精是做工、手艺细致讲究，一点都不马虎。", "primary_collocate": null, "pronunciation": "jīng", "ipa": "tɕiŋ˥", "syllable_count": 1, "sentences": [{"text": "这件衣服的做工很精。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手艺很精，做得一点不马虎。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画画得很精。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶绣的花又细又精。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅干活儿很精，从不出错。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套茶具做得真精。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他切菜的刀工特别精。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个模型的零件拼得很精，连缝隙都看不出来。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表修得很精，一点毛病也没有。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这活儿干得精，客人都很满意。", "target_word": "精", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精细", "label": "复合"}], "register": "口语", "sense_fingerprint": "做工、手艺细致讲究，不马虎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'add8433b-3ae1-4b98-b82a-1589f89692b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精", "is_correct": true, "explanation": "精（jīng）指做工细致、不马虎，正是本词的意思。"}, {"text": "静", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是安静。"}, {"text": "景", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是风景。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 jīng 韵母不同（in 与 ing），声调相同，意思是金子。"}, {"text": "星", "is_correct": false, "explanation": "xīng 与 jīng 声母不同（x 与 j），意思是星星。"}], "explanations": {"精": "精（jīng）指做工细致、不马虎，正是本词的意思。", "静": "jìng（第四声）与 jīng（第一声）声调不同，意思是安静。", "景": "jǐng（第三声）与 jīng（第一声）声调不同，意思是风景。", "金": "jīn 与 jīng 韵母不同（in 与 ing），声调相同，意思是金子。", "星": "xīng 与 jīng 声母不同（x 与 j），意思是星星。"}, "sentence_index": null, "correct_answer": "精"}, "level_3": {"options": [{"text": "精", "is_correct": true, "explanation": "“精”指做工细致、不马虎，正好描述“做工”。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”说厚度，不能用来评价做工是否细致。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线或颜色，与做工是否细致无关。"}, {"text": "大", "is_correct": false, "explanation": "体貌：“大”说体积，不能用来评价做工是否细致。"}], "explanations": {"精": "“精”指做工细致、不马虎，正好描述“做工”。", "厚": "搭配：“厚”说厚度，不能用来评价做工是否细致。", "亮": "语义：“亮”说光线或颜色，与做工是否细致无关。", "大": "体貌：“大”说体积，不能用来评价做工是否细致。"}, "sentence_index": 0, "correct_answer": "精"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市很精，晚上的灯光特别好看。", "explanation": "这里应该用〈美丽〉。“精”形容做工或技艺细致，不用来形容城市的样子，形容景色要用美丽。"}, {"text": "这朵花的颜色很精。", "explanation": "这里应该用〈漂亮〉。“精”说做工细致，不说颜色好看，形容颜色要用漂亮。"}, {"text": "今天的天气很精，适合去公园散步。", "explanation": "这里应该用〈晴朗〉。“精”形容做工或技艺细致，不用来形容天气，形容天气好要用晴朗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "精", "is_correct": true, "explanation": "精（jīng）指做工细致、不马虎，正是本词的意思。"}, {"text": "净", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是干净。"}, {"text": "井", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是水井。"}, {"text": "兴", "is_correct": false, "explanation": "xīng 与 jīng 声母不同（x 与 j），意思是兴旺。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 jīng 韵母不同（in 与 ing），声调相同，意思是金子。"}, {"text": "轻", "is_correct": false, "explanation": "qīng 与 jīng 声母不同（q 与 j），声调相同，意思是轻重的轻。"}], "explanations": {"精": "精（jīng）指做工细致、不马虎，正是本词的意思。", "净": "jìng（第四声）与 jīng（第一声）声调不同，意思是干净。", "井": "jǐng（第三声）与 jīng（第一声）声调不同，意思是水井。", "兴": "xīng 与 jīng 声母不同（x 与 j），意思是兴旺。", "金": "jīn 与 jīng 韵母不同（in 与 ing），声调相同，意思是金子。", "轻": "qīng 与 jīng 声母不同（q 与 j），声调相同，意思是轻重的轻。"}, "sentence_index": null, "correct_answer": "精"}, "level_3": {"options": [{"text": "精", "is_correct": true, "explanation": "“精”指做工细致、不马虎，符合“刀工”的语境。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”说质地，不能用来评价刀工。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”说距离，与刀工的水平无关。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：“窄”说宽度或空间，不能用来形容刀工。"}], "explanations": {"精": "“精”指做工细致、不马虎，符合“刀工”的语境。", "软": "搭配：“软”说质地，不能用来评价刀工。", "远": "语义：“远”说距离，与刀工的水平无关。", "窄": "搭配：“窄”说宽度或空间，不能用来形容刀工。"}, "sentence_index": 6, "correct_answer": "精"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件东西很精，只要十块钱。", "explanation": "这里应该用〈便宜〉。“精”形容做工或技艺细致，不用来说价格，说价格低要用便宜。"}, {"text": "这间屋子很精，夏天住着很舒服。", "explanation": "这里应该用〈凉快〉。“精”形容做工细致，不用来形容屋子的温度，这里要用凉快。"}, {"text": "这辆车很精，一小时能开一百公里。", "explanation": "这里应该用〈快〉。“精”形容人精明或做工细致，不用来形容车的速度，形容车快要用快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件家具做很精。", "corrected_sentence": "这件家具做得很精。", "error_description": "“做很精”漏掉了补语标记“得”，应说“做得很精”。形容做的结果怎样，要用“动词＋得＋形容词”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做的木雕比我最精，连纹路都清清楚楚。", "corrected_sentence": "他做的木雕比我精，连纹路都清清楚楚。", "error_description": "错误在“最”：“比”字句已经表示比较，不能再用“最”，应说“比我精”；要强调程度可用“更”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
