INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家的类别或所属的国家。", "primary_collocate": null, "pronunciation": "guó bié", "ipa": "kwɔ˧˥ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这套书按国别分成三类。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告按国别列出了数据。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员的国别都写在牌子上。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的菜单按国别分类。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按国别排队。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同国别的人，习惯也不同。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆按国别整理地图。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的国别各不相同。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他分不清这些人的国别。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表是按国别统计的。", "target_word": "国别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "国别：按国家划分的类别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30121eb2-4bca-4011-9a89-398f42fd683f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93476, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不能作为把书分成三类的依据。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“按……分类”的依据多是书的内容或属性，“脾气”通常不用来给书分类。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不能作为给书分类的依据。"}, {"text": "国别", "is_correct": true, "explanation": "国别指按国家划分的类别，“按国别分成三类”正是按国家分类。"}], "explanations": {"天气": "语义：天气不能作为把书分成三类的依据。", "脾气": "搭配：“按……分类”的依据多是书的内容或属性，“脾气”通常不用来给书分类。", "作业": "语义：作业是学习任务，不能作为给书分类的依据。", "国别": "国别指按国家划分的类别，“按国别分成三类”正是按国家分类。"}, "sentence_index": 0, "correct_answer": "国别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的国别是山东。", "explanation": "这里应该用〈籍贯〉。籍贯指祖籍所在的地方，山东是省份而不是国家；国别指国家的类别或所属的国家，不能指地方。"}, {"text": "他越过了国别。", "explanation": "这里应该用〈国界〉。越过的是地理界线，国别是类别，不能被越过。"}, {"text": "我的国别在北京。", "explanation": "这里应该用〈地址〉。国别是按国家划分的类别，不用来说明住在什么地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：地图没有味道，“按味道整理地图”讲不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：地图没有体重，“按体重整理地图”不合句意。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”多用于食物饮品，不能用来整理地图。"}, {"text": "国别", "is_correct": true, "explanation": "国别指按国家划分的类别，图书馆按国别整理地图正合句意。"}], "explanations": {"味道": "语义：地图没有味道，“按味道整理地图”讲不通。", "体重": "语义：地图没有体重，“按体重整理地图”不合句意。", "口味": "搭配：“口味”多用于食物饮品，不能用来整理地图。", "国别": "国别指按国家划分的类别，图书馆按国别整理地图正合句意。"}, "sentence_index": 6, "correct_answer": "国别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面国别是红色的。", "explanation": "这里应该用〈国旗〉。国旗有颜色，国别是按国家划分的类别，没有颜色。"}, {"text": "我们唱国别。", "explanation": "这里应该用〈国歌〉。国歌可以唱，国别是类别名词，不能用来唱。"}, {"text": "他会说三种国别。", "explanation": "这里应该用〈语言〉。会说的是语言，国别指按国家划分的类别，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批书要国别分类整理。", "corrected_sentence": "这批书要按国别分类整理。", "error_description": "漏掉介词“按”：引进分类依据的“国别”前应加“按”，应写作“按国别分类”；直接写“国别分类”不符合汉语习惯，母语者会觉得句子不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些国别们的学生都来了。", "corrected_sentence": "这些国别的学生都来了。", "error_description": "“们”用法错误：“们”不能加在“国别”后面，应写作“这些国别的学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
