INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93477, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "绑是用绳子把东西缠起来，让它不会松开。", "primary_collocate": null, "pronunciation": "bǎng", "ipa": "pɑŋ²¹⁴", "syllable_count": 1, "sentences": [{"text": "小心点，把行李绑牢。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用绳子绑自行车上的箱子。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请帮我绑一下这个盒子。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把花绑成一束。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的鞋带总是绑不紧。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他腿上绑着一块布。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面风大，把帐篷绑好。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们把旗子绑在竹竿上。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没绑过这么大的包。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人用绳子绑柴火。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绑了", "label": "体标"}, {"form": "绑着", "label": "体标"}, {"form": "绑过", "label": "体标"}, {"form": "綁", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用绳子缠起东西，使它不松开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1163fc0d-9628-401a-8cdf-c361cf20c442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93477, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "绑", "is_correct": true, "explanation": "绑：bǎng（第三声），意思是用绳子等把东西缠紧、捆住。"}, {"text": "帮", "is_correct": false, "explanation": "bāng（第一声）与 bǎng（第三声）声调不同，意思是帮助。"}, {"text": "板", "is_correct": false, "explanation": "bǎn 与 bǎng 韵尾不同（n 与 ng），意思是木板。"}, {"text": "绷", "is_correct": false, "explanation": "běng 与 bǎng 主要元音不同（e 与 a），意思是拉紧。"}, {"text": "把", "is_correct": false, "explanation": "bǎ 比 bǎng 少了韵尾 ng，意思是握住、把手。"}], "explanations": {"绑": "绑：bǎng（第三声），意思是用绳子等把东西缠紧、捆住。", "帮": "bāng（第一声）与 bǎng（第三声）声调不同，意思是帮助。", "板": "bǎn 与 bǎng 韵尾不同（n 与 ng），意思是木板。", "绷": "běng 与 bǎng 主要元音不同（e 与 a），意思是拉紧。", "把": "bǎ 比 bǎng 少了韵尾 ng，意思是握住、把手。"}, "sentence_index": null, "correct_answer": "绑"}, "level_3": {"options": [{"text": "绑", "is_correct": true, "explanation": "“把行李绑牢”表示用绳子等把行李捆紧，符合句意。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指移动，不表示把东西固定住，与“牢”的意思不合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗牢”不能搭配，“洗”不能表示使行李固定。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉，与“小心点，把行李……牢”的意思不符。"}], "explanations": {"绑": "“把行李绑牢”表示用绳子等把行李捆紧，符合句意。", "搬": "语义：“搬”指移动，不表示把东西固定住，与“牢”的意思不合。", "洗": "搭配：“洗牢”不能搭配，“洗”不能表示使行李固定。", "扔": "语义：“扔”是丢掉，与“小心点，把行李……牢”的意思不符。"}, "sentence_index": 0, "correct_answer": "绑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用胶水把标签绑在瓶子上。", "explanation": "这里应该用“粘”。用胶水贴附应说“粘”，“绑”指用绳子等缠住，让东西不松开，不能用胶水。"}, {"text": "我把一个梦绑在了床头。", "explanation": "这里误把“绑”用于捆缚抽象之物。“绑”的对象须是能用绳子缠住、不让松开的实物，抽象的东西不能这样捆。"}, {"text": "她把一阵雨绑在了屋顶上。", "explanation": "这里误把“绑”用于捆缚无形之物。“绑”的对象须是能用绳子缠住的实物，无形的东西不能被这样捆住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93477, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "绑", "is_correct": true, "explanation": "绑：bǎng（第三声），意思是用绳子等把东西缠紧、捆住。"}, {"text": "棒", "is_correct": false, "explanation": "bàng（第四声）与 bǎng（第三声）声调不同，意思是棍子。"}, {"text": "磅", "is_correct": false, "explanation": "bàng（第四声）与 bǎng（第三声）声调不同，意思是重量单位。"}, {"text": "傍", "is_correct": false, "explanation": "bàng（第四声）与 bǎng（第三声）声调不同，意思是靠近。"}, {"text": "党", "is_correct": false, "explanation": "dǎng 与 bǎng 声母不同（d 与 b），意思是政党。"}], "explanations": {"绑": "绑：bǎng（第三声），意思是用绳子等把东西缠紧、捆住。", "棒": "bàng（第四声）与 bǎng（第三声）声调不同，意思是棍子。", "磅": "bàng（第四声）与 bǎng（第三声）声调不同，意思是重量单位。", "傍": "bàng（第四声）与 bǎng（第三声）声调不同，意思是靠近。", "党": "dǎng 与 bǎng 声母不同（d 与 b），意思是政党。"}, "sentence_index": null, "correct_answer": "绑"}, "level_3": {"options": [{"text": "绑", "is_correct": true, "explanation": "“把帐篷绑好”表示用绳子把帐篷固定住，符合“风大”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象应是食物，不能说“吃帐篷”。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是割开，与风大时固定帐篷的意思不合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，帐篷不能煮，与句意不合。"}], "explanations": {"绑": "“把帐篷绑好”表示用绳子把帐篷固定住，符合“风大”的语境。", "吃": "搭配：“吃”的对象应是食物，不能说“吃帐篷”。", "切": "语义：“切”是割开，与风大时固定帐篷的意思不合。", "煮": "语义：“煮”是加热食物，帐篷不能煮，与句意不合。"}, "sentence_index": 6, "correct_answer": "绑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在作业本上绑了自己的名字。", "explanation": "这里应该用“写”。在本子上写名字用“写”，“绑”指用绳子等缠住，不用于书写。"}, {"text": "他把外套最上面的纽扣绑上了。", "explanation": "这里应该用“扣”。纽扣要说“扣”，“绑”不用于扣纽扣。"}, {"text": "她绑上了一枚戒指。", "explanation": "这里应该用“戴”。戒指要说“戴”，“绑”强调用绳子缠紧，不用于戴戒指。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把木柴绑在了一捆。", "corrected_sentence": "他把木柴绑成了一捆。", "error_description": "结果补语错误：把东西捆成一捆应用“成”，“在”表示处所，不能说“绑在一捆”。正确说法是“绑成了一捆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没绑了这么大的行李包。", "corrected_sentence": "我从来没绑过这么大的行李包。", "error_description": "体标错误：“从来没……”表示没有过的经历，应用“过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
