INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93478, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用绳子等把东西缠紧、捆住。", "primary_collocate": null, "pronunciation": "bǎng", "ipa": "pɑŋ²¹⁴", "syllable_count": 1, "sentences": [{"text": "请把这些书绑起来。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲下来绑鞋带。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用绳子把箱子绑紧了。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头发绑在后面。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用绳子绑住了小船。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把树枝绑成一捆。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的鞋带松了，快绑一下。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把麦子绑好放在车上。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把气球绑在椅子上。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手上绑着一条红布。", "target_word": "绑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绑了", "label": "体标"}, {"form": "绑着", "label": "体标"}, {"form": "绑过", "label": "体标"}, {"form": "綁", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用绳子等把东西缠紧、捆住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1163fc0d-9628-401a-8cdf-c361cf20c442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93478, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "绑", "is_correct": true, "explanation": "绑：bǎng（第三声），意思是用绳子等把东西缠紧、捆住。"}, {"text": "帮", "is_correct": false, "explanation": "bāng（第一声）与 bǎng（第三声）声调不同，意思是帮助。"}, {"text": "板", "is_correct": false, "explanation": "bǎn 与 bǎng 韵尾不同（n 与 ng），意思是木板。"}, {"text": "绷", "is_correct": false, "explanation": "běng 与 bǎng 主要元音不同（e 与 a），意思是拉紧。"}, {"text": "把", "is_correct": false, "explanation": "bǎ 比 bǎng 少了韵尾 ng，意思是握住、把手。"}], "explanations": {"绑": "绑：bǎng（第三声），意思是用绳子等把东西缠紧、捆住。", "帮": "bāng（第一声）与 bǎng（第三声）声调不同，意思是帮助。", "板": "bǎn 与 bǎng 韵尾不同（n 与 ng），意思是木板。", "绷": "běng 与 bǎng 主要元音不同（e 与 a），意思是拉紧。", "把": "bǎ 比 bǎng 少了韵尾 ng，意思是握住、把手。"}, "sentence_index": null, "correct_answer": "绑"}, "level_3": {"options": [{"text": "绑", "is_correct": true, "explanation": "“绑起来”表示用绳子等把书捆紧，符合句意。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”需要的对象是食物或可切割之物，书不能切。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是把食物放入水中加热，句中的书不能煮。"}, {"text": "炒", "is_correct": false, "explanation": "语义：“炒”指用锅翻炒食物，与“把这些书”不相容。"}], "explanations": {"绑": "“绑起来”表示用绳子等把书捆紧，符合句意。", "切": "搭配：“切”需要的对象是食物或可切割之物，书不能切。", "煮": "语义：“煮”是把食物放入水中加热，句中的书不能煮。", "炒": "语义：“炒”指用锅翻炒食物，与“把这些书”不相容。"}, "sentence_index": 0, "correct_answer": "绑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用胶水把纸绑在墙上。", "explanation": "这里应该用“粘”。用胶水贴附应说“粘”，“绑”指用绳子等缠紧、捆住，不能用胶水。"}, {"text": "她把一阵风绑在了窗户上。", "explanation": "这里误把“绑”用于捆缚无形之物。“绑”的对象应是能用绳子缠紧的实物，无形的东西不能被这样捆住。"}, {"text": "他把一句承诺绑在了箱子上。", "explanation": "这里误把“绑”用于捆缚抽象之物。“绑”的对象须是能用绳子缠紧的实物，抽象的东西不能这样捆住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93478, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "绑", "is_correct": true, "explanation": "绑：bǎng（第三声），意思是用绳子等把东西缠紧、捆住。"}, {"text": "棒", "is_correct": false, "explanation": "bàng（第四声）与 bǎng（第三声）声调不同，意思是棍子。"}, {"text": "磅", "is_correct": false, "explanation": "bàng（第四声）与 bǎng（第三声）声调不同，意思是重量单位。"}, {"text": "傍", "is_correct": false, "explanation": "bàng（第四声）与 bǎng（第三声）声调不同，意思是靠近。"}, {"text": "党", "is_correct": false, "explanation": "dǎng 与 bǎng 声母不同（d 与 b），意思是政党。"}], "explanations": {"绑": "绑：bǎng（第三声），意思是用绳子等把东西缠紧、捆住。", "棒": "bàng（第四声）与 bǎng（第三声）声调不同，意思是棍子。", "磅": "bàng（第四声）与 bǎng（第三声）声调不同，意思是重量单位。", "傍": "bàng（第四声）与 bǎng（第三声）声调不同，意思是靠近。", "党": "dǎng 与 bǎng 声母不同（d 与 b），意思是政党。"}, "sentence_index": null, "correct_answer": "绑"}, "level_3": {"options": [{"text": "绑", "is_correct": true, "explanation": "“快绑一下”表示赶快把松了的鞋带系紧，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉，与鞋带松了需要紧固的意思不符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象应是食物，不能说“吃鞋带”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，与鞋带松了需要紧固的意思不符。"}], "explanations": {"绑": "“快绑一下”表示赶快把松了的鞋带系紧，符合句意。", "扔": "语义：“扔”是丢掉，与鞋带松了需要紧固的意思不符。", "吃": "搭配：“吃”的对象应是食物，不能说“吃鞋带”。", "咬": "语义：咬是用牙齿夹住，与鞋带松了需要紧固的意思不符。"}, "sentence_index": 6, "correct_answer": "绑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出门前用钥匙把门绑上了。", "explanation": "这里应该用“锁”。用钥匙关门要说“锁门”，“绑”指用绳子等缠紧、捆住，不用于锁门。"}, {"text": "他把衣服最上面的扣子绑好了。", "explanation": "这里应该用“扣”。扣子要说“扣”，“绑”不用于扣纽扣。"}, {"text": "她绑上了一对耳环。", "explanation": "这里应该用“戴”。耳环属于饰物，要说“戴”，“绑”不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用绳子把行李绑了紧。", "corrected_sentence": "我用绳子把行李绑紧了。", "error_description": "补语位置错误：“绑紧”是动补结构，“了”应放在补语之后，说“绑紧了”，不能说“绑了紧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你的鞋带松了，快绑着一下吧。", "corrected_sentence": "你的鞋带松了，快绑一下吧。", "error_description": "体标错误：“绑一下”表示短暂的动作，不加“着”。“着”表示持续状态，与催促动作不合，应说“快绑一下吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
