INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93483, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "外籍是说这个人是别的国家的人。", "primary_collocate": null, "pronunciation": "wài jí", "ipa": "wai̯˥˩ t͡ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "他是外籍老师，教我们英语。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司有三十名外籍员工。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位外籍朋友会说中文。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校有很多外籍学生。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位外籍医生来中国五年了。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的外籍同事喜欢吃饺子。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外籍游客在公园里拍照。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识一位外籍教练。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店有外籍厨师。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位外籍记者，常去北京。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外籍人士", "label": "复合"}, {"form": "外籍员工", "label": "复合"}], "register": "书面语", "sense_fingerprint": "说明某人是别的国家的人，常放在人的名称前面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06f273b2-8ada-4e9a-bf00-a5ca09e322b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93483, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中式", "is_correct": false, "explanation": "语义：〈中式〉说的是风格或做法，不指人的国籍，与句中要表达的身份不符。"}, {"text": "外籍", "is_correct": true, "explanation": "外籍：指具有外国国籍，用来修饰“老师”，与“教我们英语”的句意相合。"}, {"text": "国产", "is_correct": false, "explanation": "搭配：〈国产〉多用来说物品，不用来修饰人，不能说“国产老师”。"}, {"text": "纯棉", "is_correct": false, "explanation": "搭配：〈纯棉〉说布料的材质，不能修饰人，“纯棉老师”不通。"}], "explanations": {"中式": "语义：〈中式〉说的是风格或做法，不指人的国籍，与句中要表达的身份不符。", "外籍": "外籍：指具有外国国籍，用来修饰“老师”，与“教我们英语”的句意相合。", "国产": "搭配：〈国产〉多用来说物品，不用来修饰人，不能说“国产老师”。", "纯棉": "搭配：〈纯棉〉说布料的材质，不能修饰人，“纯棉老师”不通。"}, "sentence_index": 0, "correct_answer": "外籍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店卖很多外籍蔬菜。", "explanation": "这里应该用〈进口〉。〈外籍〉指人的国籍，不用于蔬菜等食品；说商品来自国外要用〈进口〉。"}, {"text": "她在外籍的医院工作。", "explanation": "这里应该用〈外地〉。〈外籍〉说的是国籍，不指地方；“外地的医院”指别的地区的医院。"}, {"text": "这家工厂的资金来自德国，属于外籍企业。", "explanation": "这里应该用〈外资〉。〈外籍〉指人的国籍，不指企业的外国投资；资金来自国外的企业要说〈外资企业〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93483, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "室内", "is_correct": false, "explanation": "语义：〈室内〉指屋子里面，与“在公园里”的户外场景矛盾。"}, {"text": "在职", "is_correct": false, "explanation": "搭配：〈在职〉说人在岗位上工作，不用来修饰游客。"}, {"text": "外籍", "is_correct": true, "explanation": "外籍：指具有外国国籍，修饰“游客”，符合句意。"}, {"text": "无线", "is_correct": false, "explanation": "语义：〈无线〉指不用线连接，不能修饰人，这里讲不通。"}], "explanations": {"室内": "语义：〈室内〉指屋子里面，与“在公园里”的户外场景矛盾。", "在职": "搭配：〈在职〉说人在岗位上工作，不用来修饰游客。", "外籍": "外籍：指具有外国国籍，修饰“游客”，符合句意。", "无线": "语义：〈无线〉指不用线连接，不能修饰人，这里讲不通。"}, "sentence_index": 6, "correct_answer": "外籍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他会说一门外籍语言，能和外国朋友交流。", "explanation": "这里应该用〈外语〉。〈外籍〉指国籍，不指语言；说某种外国语言要用〈外语〉。"}, {"text": "这是一次外籍会议，来了很多专家。", "explanation": "这里应该用〈国际〉。〈外籍〉指人的国籍，不修饰会议等活动；面向各国的会议要说〈国际会议〉。"}, {"text": "这家饭店的菜是外籍风味。", "explanation": "这里应该用〈外国〉。〈外籍〉指国籍，不用来说菜肴的风格；说外国风味要用〈外国风味〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位朋友很外籍人士，常来我家吃饭。", "corrected_sentence": "这位朋友是外籍人士，常来我家吃饭。", "error_description": "错误形式：「很外籍人士」；正确形式：「是外籍人士」。外籍是区别词，不能受“很”修饰，说明身份要用“是”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家饭店来了很多外籍，说各种语言。", "corrected_sentence": "这家饭店来了很多外籍客人，说各种语言。", "error_description": "错误形式：「很多外籍」；正确形式：「很多外籍客人」。外籍是区别词，只能放在名词前作定语，不能单独当名词用，后面要加上人的名称。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
