INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93484, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "具有外国国籍的。", "primary_collocate": null, "pronunciation": "wài jí", "ipa": "wai̯˥˩ t͡ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "他有外籍身份，办签证要多等几天。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外籍人员进公司要先登记。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队有两名外籍球员。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外籍乘客请排在这边。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的妻子是外籍人士。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里有外籍病人，需要翻译。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外籍司机不太熟悉这里的路。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛不让外籍选手参加。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲是外籍华人。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外籍家长也来参加了会议。", "target_word": "外籍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外籍人士", "label": "复合"}, {"form": "外籍华人", "label": "复合"}], "register": "书面语", "sense_fingerprint": "指具有外国国籍，多用来说明人员的身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06f273b2-8ada-4e9a-bf00-a5ca09e322b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本国", "is_correct": false, "explanation": "语义：〈本国〉指本国国籍，本国人不必办签证，与“办签证”的句意矛盾。"}, {"text": "外籍", "is_correct": true, "explanation": "外籍：指具有外国国籍，修饰“身份”，与办签证的情境相合。"}, {"text": "在校", "is_correct": false, "explanation": "搭配：〈在校〉说在学校读书，不用来修饰“身份”。"}, {"text": "年幼", "is_correct": false, "explanation": "搭配：〈年幼〉说年龄，不能用来修饰“身份”。"}], "explanations": {"本国": "语义：〈本国〉指本国国籍，本国人不必办签证，与“办签证”的句意矛盾。", "外籍": "外籍：指具有外国国籍，修饰“身份”，与办签证的情境相合。", "在校": "搭配：〈在校〉说在学校读书，不用来修饰“身份”。", "年幼": "搭配：〈年幼〉说年龄，不能用来修饰“身份”。"}, "sentence_index": 0, "correct_answer": "外籍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书有中文版和外籍版本。", "explanation": "这里应该用〈外文〉。〈外籍〉指国籍，不指语言或文字；外文的版本要说〈外文版〉。"}, {"text": "他在国外学会了两门外籍的语言。", "explanation": "这里应该用〈外语〉。〈外籍〉指国籍，不修饰语言；学的外国语言要说〈外语〉。"}, {"text": "他买了一台外籍相机，拍照很清楚。", "explanation": "这里应该用〈进口〉。〈外籍〉指人的国籍，不修饰相机等物品；说相机来自国外要用〈进口〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明", "is_correct": false, "explanation": "语义：〈透明〉说物体可以看穿，不用来修饰司机，这里讲不通。"}, {"text": "慢性", "is_correct": false, "explanation": "搭配：〈慢性〉用于病症，不能修饰司机。"}, {"text": "外籍", "is_correct": true, "explanation": "外籍：指具有外国国籍，修饰“司机”，与“不太熟悉这里的路”的句意相合。"}, {"text": "电动", "is_correct": false, "explanation": "语义：〈电动〉说动力方式，不指人的身份，这里讲不通。"}], "explanations": {"透明": "语义：〈透明〉说物体可以看穿，不用来修饰司机，这里讲不通。", "慢性": "搭配：〈慢性〉用于病症，不能修饰司机。", "外籍": "外籍：指具有外国国籍，修饰“司机”，与“不太熟悉这里的路”的句意相合。", "电动": "语义：〈电动〉说动力方式，不指人的身份，这里讲不通。"}, "sentence_index": 6, "correct_answer": "外籍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们买了一台外籍电视。", "explanation": "这里应该用〈进口〉。〈外籍〉指人的国籍，不修饰电视等商品；说商品来自国外要用〈进口〉。"}, {"text": "这场外籍比赛吸引了很多观众。", "explanation": "这里应该用〈国际〉。〈外籍〉指人的国籍，不修饰比赛等活动；面向各国的比赛要说〈国际比赛〉。"}, {"text": "她住的外籍小区环境很好。", "explanation": "这里应该用〈外国人〉。〈外籍〉指人的国籍，不修饰小区等居住地；以外国人为主的社区要说〈外国人社区〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的邻居很外籍人士，常帮我看孩子。", "corrected_sentence": "我的邻居是外籍人士，常帮我看孩子。", "error_description": "错误形式：「很外籍人士」；正确形式：「是外籍人士」。外籍是区别词，不能受“很”修饰，说明身份要用“是”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几位老师外籍人士，学生都很喜欢。", "corrected_sentence": "这几位老师是外籍人士，学生都很喜欢。", "error_description": "错误形式：「这几位老师外籍人士」；正确形式：「这几位老师是外籍人士」。“外籍人士”是名词短语，作谓语时前面须加“是”，缺少“是”即不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
