INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93485, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "多型是有很多种不同的样子。", "primary_collocate": null, "pronunciation": "duō xíng", "ipa": "twɔ˥˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这种蜜蜂是多型的，工蜂和蜂王的样子差别很大。", "target_word": "多型", "complexity_tier": "T3", "furigana": "zhè zhǒng mì fēng shì duō xíng de，gōng fēng hé fēng wáng de yàng zi chā bié hěn dà。", "sentence_source": "generated"}, {"text": "蚂蚁是多型的，有大的也有小的。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个物种是多型的。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这种鱼是多型的。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草是多型的，叶子的样子很难认。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种虫子为什么是多型的？", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里说这种鸟是多型的，同一种鸟的样子差别很大。", "target_word": "多型", "complexity_tier": "T3", "furigana": "shū lǐ shuō zhè zhǒng niǎo shì duō xíng de，tóng yī zhǒng niǎo de yàng zi chā bié hěn dà。", "sentence_source": "generated"}, {"text": "这些蘑菇是多型的，大小不同。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "它不是单一的，而是多型的。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家发现了一种多型的草。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "多型：同一种东西有很多种不同的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30121eb2-4bca-4011-9a89-398f42fd683f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93485, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多型", "is_correct": true, "explanation": "多型指同一种生物有多种不同的样子，与后句“工蜂和蜂王的样子差别很大”相符。"}, {"text": "单一", "is_correct": false, "explanation": "语义：单一指只有一种，与后句“样子差别很大”矛盾。"}, {"text": "相同", "is_correct": false, "explanation": "语义：相同指彼此一样，与后句“样子差别很大”矛盾。"}, {"text": "固定", "is_correct": false, "explanation": "语义：固定指不变，与后句“工蜂和蜂王的样子差别很大”矛盾。"}], "explanations": {"多型": "多型指同一种生物有多种不同的样子，与后句“工蜂和蜂王的样子差别很大”相符。", "单一": "语义：单一指只有一种，与后句“样子差别很大”矛盾。", "相同": "语义：相同指彼此一样，与后句“样子差别很大”矛盾。", "固定": "语义：固定指不变，与后句“工蜂和蜂王的样子差别很大”矛盾。"}, "sentence_index": 0, "correct_answer": "多型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个公园的植物是多型的。", "explanation": "这里应该用〈多样〉。多型指同一种生物有几种不同的形态，公园里的植物是许多不同种类，应说“多样”。"}, {"text": "这家餐厅的菜式是多型的。", "explanation": "这里应该用〈丰富〉。多型指同一事物表现出几种形态，说菜式种类多应用“丰富”。"}, {"text": "这段时间的天气是多型的。", "explanation": "这里应该用〈多变〉。多型指同一事物本身有几种形态，说天气变化多应用“多变”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93485, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多型", "is_correct": true, "explanation": "多型指同一种鸟有多种样子，与后句“同一种鸟的样子差别很大”相符。"}, {"text": "一致", "is_correct": false, "explanation": "语义：一致指彼此相同，与后句“样子差别很大”矛盾。"}, {"text": "固定", "is_correct": false, "explanation": "语义：固定指不变，与“同一种鸟的样子差别很大”矛盾。"}, {"text": "统一", "is_correct": false, "explanation": "语义：统一指彼此一致，与后句“同一种鸟的样子差别很大”矛盾。"}], "explanations": {"多型": "多型指同一种鸟有多种样子，与后句“同一种鸟的样子差别很大”相符。", "一致": "语义：一致指彼此相同，与后句“样子差别很大”矛盾。", "固定": "语义：固定指不变，与“同一种鸟的样子差别很大”矛盾。", "统一": "语义：统一指彼此一致，与后句“同一种鸟的样子差别很大”矛盾。"}, "sentence_index": 6, "correct_answer": "多型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道数学题的解法是多型的。", "explanation": "这里应该用〈复杂〉。多型指同一事物有几种形态，说解法难易应用“复杂”。"}, {"text": "这份报告的数据是多型的。", "explanation": "这里应该用〈繁杂〉。多型指同一事物有几种形态，说数据多而杂应用“繁杂”。"}, {"text": "这家超市的商品是多型的。", "explanation": "这里应该用〈繁多〉。多型指同一事物的形态有几种，说商品种类多应用“繁多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种蝴蝶很多型的，雌雄的样子差别也很大。", "corrected_sentence": "这种蝴蝶是多型的，雌雄的样子差别也很大。", "error_description": "错误在“很”。“多型”是描述同一物种形态的属性，不能被“很”修饰，判断句应用“是……的”。错误形式“很多型的”应改为“是多型的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员发现了一种多型了的鱼。", "corrected_sentence": "研究人员发现了一种多型的鱼。", "error_description": "错误在“了”。“多型”作定语修饰“鱼”时，应直接用“多型的”，不能加“了”。错误形式“多型了的鱼”应改为“多型的鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
