INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93486, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "具有多种形态的；生物或程序中同一事物表现出多种形式。", "primary_collocate": null, "pronunciation": "duō xíng", "ipa": "twɔ˥˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这段代码是多型的，同一个方法能用于不同的类型。", "target_word": "多型", "complexity_tier": "T3", "furigana": "zhè duàn dài mǎ shì duō xíng de，tóng yī gè fāng fǎ néng yòng yú bù tóng de lèi xíng。", "sentence_source": "generated"}, {"text": "这种细菌是多型的。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多型的代码可以用在很多地方。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种昆虫是多型的，同一群体的形态差别很大。", "target_word": "多型", "complexity_tier": "T3", "furigana": "zhè zhǒng kūn chóng shì duō xíng de，tóng yī qún tǐ de xíng tài chā bié hěn dà。", "sentence_source": "generated"}, {"text": "这个接口是多型的，可以处理不同的对象。", "target_word": "多型", "complexity_tier": "T3", "furigana": "zhè gè jiē kǒu shì duō xíng de，kě yǐ chǔ lǐ bù tóng de duì xiàng。", "sentence_source": "generated"}, {"text": "多型的生物更容易活下来。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段代码不是多型的。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种植物是多型的，叶子有三种形状。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多型的设计让程序更灵活。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蝴蝶是多型的，翅膀有很多样子。", "target_word": "多型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "多型：生物或程序中同一事物具有多种形态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30121eb2-4bca-4011-9a89-398f42fd683f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93486, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多型", "is_correct": true, "explanation": "多型指同一接口能处理不同类型，与句中“同一个方法能用于不同的类型”相符。"}, {"text": "固定", "is_correct": false, "explanation": "语义：固定指不变，与“同一个方法能用于不同的类型”矛盾。"}, {"text": "专用", "is_correct": false, "explanation": "语义：专用指只用于一种用途，与“能用于不同的类型”矛盾。"}, {"text": "单一", "is_correct": false, "explanation": "语义：单一指只有一种，与“能用于不同的类型”矛盾。"}], "explanations": {"多型": "多型指同一接口能处理不同类型，与句中“同一个方法能用于不同的类型”相符。", "固定": "语义：固定指不变，与“同一个方法能用于不同的类型”矛盾。", "专用": "语义：专用指只用于一种用途，与“能用于不同的类型”矛盾。", "单一": "语义：单一指只有一种，与“能用于不同的类型”矛盾。"}, "sentence_index": 0, "correct_answer": "多型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家书店的书是多型的。", "explanation": "这里应该用〈多样〉。多型指同一事物或群体表现出几种形态，书店里的书是不同种类，应说“多样”。"}, {"text": "这座公园的游客是多型的。", "explanation": "这里应该用〈繁多〉。多型指同一事物或群体表现出几种形态，游客是不同的人，并非同一群体的形态变化，应说“繁多”。"}, {"text": "这个菜单的选择是多型的。", "explanation": "这里应该用〈丰富〉。多型指同一事物有几种形态，说选择多应用“丰富”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多型", "is_correct": true, "explanation": "多型指同一接口或事物有多种形态，“这段代码不是多型的”表示代码不具备这一性质，句意相符。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容人的谈吐或性格，不用来形容代码。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：活泼指生动好动，多用于人或动物，不能用来形容代码。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描述身材或体积，不能用来形容代码。"}], "explanations": {"多型": "多型指同一接口或事物有多种形态，“这段代码不是多型的”表示代码不具备这一性质，句意相符。", "幽默": "搭配：“幽默”形容人的谈吐或性格，不用来形容代码。", "活泼": "语义：活泼指生动好动，多用于人或动物，不能用来形容代码。", "高大": "体貌：“高大”描述身材或体积，不能用来形容代码。"}, "sentence_index": 6, "correct_answer": "多型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题的答案是多型的。", "explanation": "这里应该用〈复杂〉。多型指同一事物表现出几种形态，说答案的难度应用“复杂”。"}, {"text": "这间屋子的摆设是多型的。", "explanation": "这里应该用〈杂乱〉。多型指同一事物有几种形态，说摆设乱而无序应用“杂乱”。"}, {"text": "他的想法是多型的。", "explanation": "这里应该用〈多变〉。多型指同一事物本身有几种形态，说想法经常改变应用“多变”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段程序很多型的，同一个接口能处理不同的对象。", "corrected_sentence": "这段程序是多型的，同一个接口能处理不同的对象。", "error_description": "错误在“很”。“多型”是描述同一事物形态的属性，不能被“很”修饰，判断句应用“是……的”。错误形式“很多型的”应改为“是多型的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个接口是不多型的，只能处理一种对象。", "corrected_sentence": "这个接口不是多型的，只能处理一种对象。", "error_description": "错误在否定词“不”的位置。判断句的否定应为“不是……的”，错误形式“是不多型的”应改为“不是多型的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
