INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93487, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大火是很大很大的火。", "primary_collocate": null, "pronunciation": "dà huǒ", "ipa": "ta˥˩ xuo˨˩˦", "syllable_count": 2, "sentences": [{"text": "山上的大火，晚上在远处都能看见。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看，那边有一场大火！", "target_word": "大火", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大火烧得很快，风一吹更大了。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里的大火把天空照得很红。", "target_word": "大火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火的热气让人不敢靠近。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远远看去，那是一片红红的大火。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防员彻夜奋战，终于把那场大火扑灭了。", "target_word": "大火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火冒出的黑烟，在天上飘了很远。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说城东有大火，路上的车都停了。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风很大，小火很快变成了大火。", "target_word": "大火", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场大火", "label": "量词"}, {"form": "森林大火", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，指规模很大、火势很旺的火", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe3a350-bc50-478f-b45d-f14fb4a51d8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93487, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大火", "is_correct": true, "explanation": "正确：大火，dà huǒ，指规模很大、火势很旺的火。"}, {"text": "搭伙", "is_correct": false, "explanation": "dā（第一声）与 dà（第四声）声调不同，huǒ 相同，意思是合伙、结伴。"}, {"text": "打火", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）只有声调不同，意思是点火。"}, {"text": "大户", "is_correct": false, "explanation": "dà 相同，hù（第四声）与 huǒ（第三声）韵母与声调都不同，意思是大户。"}], "explanations": {"大火": "正确：大火，dà huǒ，指规模很大、火势很旺的火。", "搭伙": "dā（第一声）与 dà（第四声）声调不同，huǒ 相同，意思是合伙、结伴。", "打火": "dǎ（第三声）与 dà（第四声）只有声调不同，意思是点火。", "大户": "dà 相同，hù（第四声）与 huǒ（第三声）韵母与声调都不同，意思是大户。"}, "sentence_index": null, "correct_answer": "大火"}, "level_3": {"options": [{"text": "大火", "is_correct": true, "explanation": "大火是火势很旺的火，能在远处看见，与“晚上在远处都能看见”相符。"}, {"text": "大风", "is_correct": false, "explanation": "搭配：风本身看不见，“看见”的对象应是可见的事物，“大风”一般说“刮”或“吹”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不可见，无法在远处看见。"}, {"text": "回声", "is_correct": false, "explanation": "语义：回声是听觉现象，不能在远处看见。"}], "explanations": {"大火": "大火是火势很旺的火，能在远处看见，与“晚上在远处都能看见”相符。", "大风": "搭配：风本身看不见，“看见”的对象应是可见的事物，“大风”一般说“刮”或“吹”。", "声音": "语义：声音不可见，无法在远处看见。", "回声": "语义：回声是听觉现象，不能在远处看见。"}, "sentence_index": 0, "correct_answer": "大火"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口挂着大火，照亮了整条街。", "explanation": "这里应该用〈灯笼〉。大火是很大的火，不能像灯笼一样挂在门口。"}, {"text": "他一拍桌子，溅出了大火，大家都吓了一跳。", "explanation": "这里应该用〈火花〉。大火指很大的火，不能像火花一样四处溅出。"}, {"text": "夜里一只大火把天空照得很红。", "explanation": "这里应该用〈场〉。大火是事件，计量用“场”；“只”用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93487, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大火", "is_correct": true, "explanation": "正确：大火，dà huǒ，指规模很大、火势很旺的火。"}, {"text": "大祸", "is_correct": false, "explanation": "dà 相同，huò（第四声）与 huǒ（第三声）只有声调不同，意思是大祸，指重大灾祸。"}, {"text": "大获", "is_correct": false, "explanation": "dà 相同，huò（第四声）与 huǒ（第三声）只有声调不同，意思是大量获得，如“大获全胜”。"}, {"text": "大湖", "is_correct": false, "explanation": "dà 相同，hú（第二声）与 huǒ（第三声）韵母和声调都不同，意思是很大的湖。"}], "explanations": {"大火": "正确：大火，dà huǒ，指规模很大、火势很旺的火。", "大祸": "dà 相同，huò（第四声）与 huǒ（第三声）只有声调不同，意思是大祸，指重大灾祸。", "大获": "dà 相同，huò（第四声）与 huǒ（第三声）只有声调不同，意思是大量获得，如“大获全胜”。", "大湖": "dà 相同，hú（第二声）与 huǒ（第三声）韵母和声调都不同，意思是很大的湖。"}, "sentence_index": null, "correct_answer": "大火"}, "level_3": {"options": [{"text": "大火", "is_correct": true, "explanation": "正确：大火是火势很旺的火，消防员扑灭的正是那场大火。"}, {"text": "大雨", "is_correct": false, "explanation": "语义：雨不能被“扑灭”，“扑灭”的对象是火。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：比赛可以“结束”，不能说“扑灭比赛”。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影不会燃烧，不能被消防员扑灭。"}], "explanations": {"大火": "正确：大火是火势很旺的火，消防员扑灭的正是那场大火。", "大雨": "语义：雨不能被“扑灭”，“扑灭”的对象是火。", "比赛": "搭配：比赛可以“结束”，不能说“扑灭比赛”。", "电影": "语义：电影不会燃烧，不能被消防员扑灭。"}, "sentence_index": 6, "correct_answer": "大火"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上的大火很小，照不亮整个房间。", "explanation": "这里应该用〈火苗〉。大火本指火势很旺，不能说“很小”；“很小”应形容火苗。"}, {"text": "屋里的大火轻轻地摇，很安静。", "explanation": "这里应该用〈烛火〉。大火火势猛烈，不能像烛火那样“轻轻地摇”。"}, {"text": "他用大火点着了蚊香。", "explanation": "这里应该用〈火柴〉。大火是猛烈燃烧的火，不能当作点火的工具；点火要用火柴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防队很快山上的大火扑灭了。", "corrected_sentence": "消防队很快把山上的大火扑灭了。", "error_description": "错误：漏掉介词“把”。“扑灭”需要把宾语“山上的大火”提到动词前，应说“把山上的大火扑灭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只大火烧光了村子的一半房子。", "corrected_sentence": "这场大火烧光了村子的一半房子。", "error_description": "错误：“大火”的量词用错。火灾是事件，应用“场”，“只”用于动物。正确说法是“这场大火”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
