INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93489, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93489, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天外是天空的外面，很远很远的地方。", "primary_collocate": null, "pronunciation": "tiān wài", "ipa": "tʰjɛn˥ wai̯˥˩", "syllable_count": 2, "sentences": [{"text": "从天外看，地球是蓝色的。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天外很大，也很安静。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇航员从天外回到了地球。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的目光越过山，望向天外。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭一直飞，飞向了天外。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事讲的是天外的世界。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天外那么远，我们去不了。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说天外还有别的人。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着天外的星星笑了。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明想坐飞船去天外玩。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天外来客", "label": "复合"}, {"form": "天外有天", "label": "复合"}], "register": "书面语", "sense_fingerprint": "天空的外面，非常遥远的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06f273b2-8ada-4e9a-bf00-a5ca09e322b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93489, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：〈厨房〉是做饭的地方，不是观察地球的位置，这里讲不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：〈课本〉是书，不能作为看地球的位置，句子不通。"}, {"text": "棉被", "is_correct": false, "explanation": "搭配：“从…看”要接视角或地点，〈棉被〉不能作为观察的位置。"}, {"text": "天外", "is_correct": true, "explanation": "天外：指天空之外，作观察的位置，从那里看地球，符合句意。"}], "explanations": {"厨房": "语义：〈厨房〉是做饭的地方，不是观察地球的位置，这里讲不通。", "课本": "语义：〈课本〉是书，不能作为看地球的位置，句子不通。", "棉被": "搭配：“从…看”要接视角或地点，〈棉被〉不能作为观察的位置。", "天外": "天外：指天空之外，作观察的位置，从那里看地球，符合句意。"}, "sentence_index": 0, "correct_answer": "天外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在天外等妈妈。", "explanation": "这里应该用〈门外〉。〈天外〉指天空之外，不指屋门外面的地方。"}, {"text": "农民在天外劳动到天黑。", "explanation": "这里应该用〈田间〉。〈天外〉指天空之外的遥远处，不指田野。"}, {"text": "渔民在天外晒网。", "explanation": "这里应该用〈岸边〉。〈天外〉指天空之外，不指岸上的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93489, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "门口", "is_correct": false, "explanation": "语义：〈门口〉离得很近，与“那么远，我们去不了”的句意矛盾。"}, {"text": "天外", "is_correct": true, "explanation": "天外：指天空之外的遥远处，作主语，与“那么远”相合。"}, {"text": "隔壁", "is_correct": false, "explanation": "语义：〈隔壁〉紧挨着，不可能“那么远”，句子讲不通。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：〈午饭〉不是地点或距离，不能用“那么远”来形容。"}], "explanations": {"门口": "语义：〈门口〉离得很近，与“那么远，我们去不了”的句意矛盾。", "天外": "天外：指天空之外的遥远处，作主语，与“那么远”相合。", "隔壁": "语义：〈隔壁〉紧挨着，不可能“那么远”，句子讲不通。", "午饭": "搭配：〈午饭〉不是地点或距离，不能用“那么远”来形容。"}, "sentence_index": 6, "correct_answer": "天外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们回天外看奶奶。", "explanation": "这里应该用〈乡下〉。〈天外〉指天空之外，不指农村。"}, {"text": "我的房间在天外，走上去很方便。", "explanation": "这里应该用〈楼上〉。〈天外〉指天空之外，不指房屋的上层。"}, {"text": "那辆车停在天外，我们等了很久。", "explanation": "这里应该用〈路边〉。〈天外〉指天空之外，车不会停在那里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那颗彗星很天外，我们看不见。", "corrected_sentence": "那颗彗星在天外，我们看不见。", "error_description": "错误形式：「很天外」；正确形式：「在天外」。“天外”是处所名词，不能用“很”修饰；说明位置要用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他仰望天外里，许久不说话。", "corrected_sentence": "他仰望天外，许久不说话。", "error_description": "错误形式：「天外里」；正确形式：「天外」。“天外”本身已表示遥远的方位，后面不必再加“里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
