INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天空之外；极远的地方。", "primary_collocate": null, "pronunciation": "tiān wài", "ipa": "tʰjɛn˥ wai̯˥˩", "syllable_count": 2, "sentences": [{"text": "那颗星星远在天外。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抬头望着天外，想了很久。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞船飞向了天外。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们想知道天外有什么。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的声音好像来自天外。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的梦想飞到了天外。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天外是什么样子，没有人看过。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，天外亮着一点光。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想去天外看看。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那束光从天外照了过来。", "target_word": "天外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天外来客", "label": "复合"}, {"form": "天外有天", "label": "复合"}], "register": "书面语", "sense_fingerprint": "天空以外的地方，也指极远的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06f273b2-8ada-4e9a-bf00-a5ca09e322b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海底", "is_correct": false, "explanation": "语义：〈海底〉在地球海洋之下，与“星星”所在的天空相反，句子讲不通。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“远在”后接处所，不能接人，〈老师〉不能用在这里。"}, {"text": "屋里", "is_correct": false, "explanation": "语义：〈屋里〉指房屋之内，星星不会远在屋里，与句意矛盾。"}, {"text": "天外", "is_correct": true, "explanation": "天外：指天空之外，正是星星所在的极远之处，与句意相合。"}], "explanations": {"海底": "语义：〈海底〉在地球海洋之下，与“星星”所在的天空相反，句子讲不通。", "老师": "搭配：“远在”后接处所，不能接人，〈老师〉不能用在这里。", "屋里": "语义：〈屋里〉指房屋之内，星星不会远在屋里，与句意矛盾。", "天外": "天外：指天空之外，正是星星所在的极远之处，与句意相合。"}, "sentence_index": 0, "correct_answer": "天外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他毕业后去天外工作了。", "explanation": "这里应该用〈海外〉。〈天外〉指天空之外、极远的地方，不指外国。"}, {"text": "周末我们去天外野餐。", "explanation": "这里应该用〈郊外〉。〈天外〉指天空之外、极远的地方，不指城市周围的地区。"}, {"text": "古代的天外有很多农田。", "explanation": "这里应该用〈城外〉。〈天外〉指天空之外，不指城墙之外的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天外", "is_correct": true, "explanation": "天外：指天空之外的遥远之处，作主语，与“没有人看过”的句意相合。"}, {"text": "大米", "is_correct": false, "explanation": "语义：〈大米〉是人人见过的日常食物，说“没有人看过”与事实不符。"}, {"text": "今天", "is_correct": false, "explanation": "搭配：〈今天〉是时间词，不能和“没有人看过”这样的经历说法搭配。"}, {"text": "教室", "is_correct": false, "explanation": "语义：〈教室〉是人们常去的地方，说“没有人看过”不合情理。"}], "explanations": {"天外": "天外：指天空之外的遥远之处，作主语，与“没有人看过”的句意相合。", "大米": "语义：〈大米〉是人人见过的日常食物，说“没有人看过”与事实不符。", "今天": "搭配：〈今天〉是时间词，不能和“没有人看过”这样的经历说法搭配。", "教室": "语义：〈教室〉是人们常去的地方，说“没有人看过”不合情理。"}, "sentence_index": 6, "correct_answer": "天外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天外的树叶变黄了。", "explanation": "这里应该用〈窗外〉。〈天外〉指天空之外的遥远处，树叶不会在天外变黄。"}, {"text": "我们一家住在天外。", "explanation": "这里应该用〈海边〉。〈天外〉指天空之外，不指地面上的居住地。"}, {"text": "这些管道埋在天外。", "explanation": "这里应该用〈地下〉。〈天外〉指天空之外，不能表示埋在土里的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那艘探测器很天外。", "corrected_sentence": "那艘探测器在天外。", "error_description": "错误形式：「很天外」；正确形式：「在天外」。“天外”是处所名词，不能用“很”修饰；说明位置要用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一颗流星向天外划过来。", "corrected_sentence": "一颗流星从天外划过来。", "error_description": "错误形式：「向天外划过来」；正确形式：「从天外划过来」。“向”引出目的地，“过来”指朝说话人的方向，两者方向矛盾；表示起点应用“从”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93491, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "索取", "is_correct": true, "explanation": "“索取”与“奉献”互为反义：奉献是不求回报地交出，索取是向别人要求得到。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”与“奉献”不构成反义关系，只是同为动词。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”与“奉献”不构成反义关系，只是同为动词。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”与“奉献”不构成反义关系，只是同为动词。"}], "correct_answer": "索取", "explanations": {"索取": "“索取”与“奉献”互为反义：奉献是不求回报地交出，索取是向别人要求得到。", "思考": "“思考”与“奉献”不构成反义关系，只是同为动词。", "散步": "“散步”与“奉献”不构成反义关系，只是同为动词。", "睡觉": "“睡觉”与“奉献”不构成反义关系，只是同为动词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
