INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93491, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "奉献是把自己的力气或东西送给别人，不要回报。", "primary_collocate": null, "pronunciation": "fèng xiàn", "ipa": "fɤŋ˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他每个周末都去养老院奉献爱心。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的钱奉献给了山区的孩子。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者们免费为大家奉献了一场演出。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈为这个家奉献了很多年。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他奉献了自己的时间，什么也不要。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我愿意为朋友奉献一点力气。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都愿意为这次活动奉献力量。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他奉献了一辈子，从来不要回报。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她过去为村里奉献过不少东西。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为别人奉献，别人也会记得你。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "奉献了", "label": "完成体"}, {"form": "奉献着", "label": "持续体"}, {"form": "奉献过", "label": "经历体"}, {"form": "奉献精神", "label": "复合词"}, {"form": "无私奉献", "label": "复合词"}], "register": "中性", "sense_fingerprint": "奉献|把力气或东西送给别人不要回报|动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2661f93-1077-4bd1-98fe-0202873548b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93491, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奉献", "is_correct": true, "explanation": "奉献 fèng xiàn，指把力气或东西送给别人而不要回报。"}, {"text": "风险", "is_correct": false, "explanation": "fēng（第一声）与 fèng（第四声）声调不同，xiǎn（第三声）与 xiàn（第四声）声调不同，意思是风险。"}, {"text": "锋线", "is_correct": false, "explanation": "fēng（第一声）与 fèng（第四声）声调不同，意思是足球等运动中的前锋线。"}, {"text": "凤仙", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是凤仙花，一种植物。"}, {"text": "奉贤", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是上海的奉贤区，一个地名。"}], "explanations": {"奉献": "奉献 fèng xiàn，指把力气或东西送给别人而不要回报。", "风险": "fēng（第一声）与 fèng（第四声）声调不同，xiǎn（第三声）与 xiàn（第四声）声调不同，意思是风险。", "锋线": "fēng（第一声）与 fèng（第四声）声调不同，意思是足球等运动中的前锋线。", "凤仙": "xiān（第一声）与 xiàn（第四声）声调不同，意思是凤仙花，一种植物。", "奉贤": "xián（第二声）与 xiàn（第四声）声调不同，意思是上海的奉贤区，一个地名。"}, "sentence_index": null, "correct_answer": "奉献"}, "level_3": {"options": [{"text": "奉献", "is_correct": true, "explanation": "“奉献”指无私地付出爱心，与“每个周末去养老院”相符。"}, {"text": "享用", "is_correct": false, "explanation": "语义：“享用”是享受所得，与“去养老院献出爱心”的方向相反。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”接商品，不说购买爱心。"}, {"text": "收取", "is_correct": false, "explanation": "语义：“收取”是接收或索取钱物，与“去养老院帮助老人”的语境相反。"}], "explanations": {"奉献": "“奉献”指无私地付出爱心，与“每个周末去养老院”相符。", "享用": "语义：“享用”是享受所得，与“去养老院献出爱心”的方向相反。", "购买": "搭配：“购买”接商品，不说购买爱心。", "收取": "语义：“收取”是接收或索取钱物，与“去养老院帮助老人”的语境相反。"}, "sentence_index": 0, "correct_answer": "奉献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这台机器奉献给了别人，每月收租金。", "explanation": "这里应该用〈租给〉。奉献不收回报，而“每月收租金”说明要收钱，应用租给。"}, {"text": "他把房子奉献给了银行，等还清贷款再拿回来。", "explanation": "这里应该用〈抵押〉。奉献是交出后不再取回，而“等还清贷款再拿回来”是抵押，应用抵押。"}, {"text": "我们奉献了一位司机，每月付他工资。", "explanation": "这里应该用〈雇〉。奉献不付报酬，“每月付他工资”说明是雇用关系，应用雇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93491, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奉献", "is_correct": true, "explanation": "“奉献”指付出力量，与“愿意为这次活动……力量”相符。"}, {"text": "索取", "is_correct": false, "explanation": "语义：“索取”是要求别人给予，与“愿意为活动出力”的意思相反。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”多接生活、待遇，不说享受力量。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”是白白耗费，与“愿意为活动出力”的积极语境冲突。"}], "explanations": {"奉献": "“奉献”指付出力量，与“愿意为这次活动……力量”相符。", "索取": "语义：“索取”是要求别人给予，与“愿意为活动出力”的意思相反。", "享受": "搭配：“享受”多接生活、待遇，不说享受力量。", "浪费": "语义：“浪费”是白白耗费，与“愿意为活动出力”的积极语境冲突。"}, "sentence_index": 6, "correct_answer": "奉献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我替朋友奉献这把钥匙，等他回来再还他。", "explanation": "这里应该用〈保管〉。奉献是交给别人后不再取回，而“等他回来再还他”说明只是代为照管，应用保管。"}, {"text": "他把钱奉献给了合作社，每月都能拿到利息。", "explanation": "这里应该用〈存〉。奉献不求回报，“每月都能拿到利息”说明有收益，把钱存入机构应用存。"}, {"text": "他向物业奉献了邻居的噪音。", "explanation": "这里应该用〈投诉〉。奉献的对象是物品、时间或精力，不能指把问题反映给别人处理，应用投诉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每年都把一部分收入奉献给。", "corrected_sentence": "我们每年都把一部分收入奉献给希望工程。", "error_description": "句末“奉献给”后缺少接受者，句子不完整。应补全为“奉献给希望工程”，即“把一部分收入奉献给希望工程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直为山区的学校奉献了着自己的力量。", "corrected_sentence": "他一直为山区的学校奉献着自己的力量。", "error_description": "“奉献”后同时用了“了”和“着”，两个体标重复。表示持续时只用“着”，应说“奉献着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93492, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "索取", "is_correct": true, "explanation": "“索取”与“奉献”互为反义：奉献是无私地交出，索取是向别人要求得到。"}, {"text": "学习", "is_correct": false, "explanation": "“学习”与“奉献”不构成反义关系，只是同为动词。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”与“奉献”不构成反义关系，只是同为动词。"}, {"text": "游玩", "is_correct": false, "explanation": "“游玩”与“奉献”不构成反义关系，只是同为动词。"}], "correct_answer": "索取", "explanations": {"索取": "“索取”与“奉献”互为反义：奉献是无私地交出，索取是向别人要求得到。", "学习": "“学习”与“奉献”不构成反义关系，只是同为动词。", "休息": "“休息”与“奉献”不构成反义关系，只是同为动词。", "游玩": "“游玩”与“奉献”不构成反义关系，只是同为动词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93492, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "索取", "is_correct": true, "explanation": "“索取”与“奉献”互为反义：奉献是无私地交出，索取是向别人要求得到。"}, {"text": "等待", "is_correct": false, "explanation": "“等待”与“奉献”不构成反义关系，只是同为动词。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”与“奉献”不构成反义关系，只是同为动词。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”与“奉献”不构成反义关系，只是同为动词。"}], "correct_answer": "索取", "explanations": {"索取": "“索取”与“奉献”互为反义：奉献是无私地交出，索取是向别人要求得到。", "等待": "“等待”与“奉献”不构成反义关系，只是同为动词。", "讨论": "“讨论”与“奉献”不构成反义关系，只是同为动词。", "旅行": "“旅行”与“奉献”不构成反义关系，只是同为动词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93492, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "恭敬地交付；无私地献出。", "primary_collocate": null, "pronunciation": "fèng xiàn", "ipa": "fɤŋ˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他把一生都奉献给了教育事业。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们为病人奉献了很多时间。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她愿意为家乡奉献自己的力量。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一辈子都在为学生奉献。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不想得到回报，只想默默奉献。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一直奉献着自己的爱心。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人应该为社会多奉献一点。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山区学校奉献过十年青春。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学会为别人奉献。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员为了大家的安全奉献出了生命。", "target_word": "奉献", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "奉献了", "label": "完成体"}, {"form": "奉献着", "label": "持续体"}, {"form": "奉献过", "label": "经历体"}, {"form": "奉献精神", "label": "复合词"}, {"form": "无私奉献", "label": "复合词"}], "register": "中性", "sense_fingerprint": "奉献|无私地献出|动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2661f93-1077-4bd1-98fe-0202873548b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93492, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奉献", "is_correct": true, "explanation": "奉献 fèng xiàn，指无私地献出或恭敬地交付。"}, {"text": "风险", "is_correct": false, "explanation": "fēng（第一声）与 fèng（第四声）声调不同，xiǎn（第三声）与 xiàn（第四声）声调不同，意思是风险。"}, {"text": "锋线", "is_correct": false, "explanation": "fēng（第一声）与 fèng（第四声）声调不同，意思是足球等运动中的前锋线。"}, {"text": "凤仙", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是凤仙花，一种植物。"}, {"text": "奉贤", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是上海的奉贤区，一个地名。"}], "explanations": {"奉献": "奉献 fèng xiàn，指无私地献出或恭敬地交付。", "风险": "fēng（第一声）与 fèng（第四声）声调不同，xiǎn（第三声）与 xiàn（第四声）声调不同，意思是风险。", "锋线": "fēng（第一声）与 fèng（第四声）声调不同，意思是足球等运动中的前锋线。", "凤仙": "xiān（第一声）与 xiàn（第四声）声调不同，意思是凤仙花，一种植物。", "奉贤": "xián（第二声）与 xiàn（第四声）声调不同，意思是上海的奉贤区，一个地名。"}, "sentence_index": null, "correct_answer": "奉献"}, "level_3": {"options": [{"text": "奉献", "is_correct": true, "explanation": "“奉献”指无私地把一生交给某项事业，与“都……给了教育事业”相符。"}, {"text": "出卖", "is_correct": false, "explanation": "语义：“出卖”指把东西卖掉以换取钱财，含贬义，与“把一生献给教育事业”的褒义语境相反。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是舍去、不再要，与“把一生献给教育事业”的主动付出相反；且不能说“放弃给某项事业”。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”是白白耗费，与“教育事业”的褒义语境冲突，句子会变成批评。"}], "explanations": {"奉献": "“奉献”指无私地把一生交给某项事业，与“都……给了教育事业”相符。", "出卖": "语义：“出卖”指把东西卖掉以换取钱财，含贬义，与“把一生献给教育事业”的褒义语境相反。", "放弃": "语义：“放弃”是舍去、不再要，与“把一生献给教育事业”的主动付出相反；且不能说“放弃给某项事业”。", "浪费": "语义：“浪费”是白白耗费，与“教育事业”的褒义语境冲突，句子会变成批评。"}, "sentence_index": 0, "correct_answer": "奉献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把那台旧电脑奉献给了邻居，还收了一百块钱。", "explanation": "这里应该用〈出售〉。奉献指无私地交出、不收回报，收钱的交易要用出售。"}, {"text": "我把书奉献给了朋友，过几天他要还给我。", "explanation": "这里应该用〈借给〉。奉献是无私地交出，不会要求归还；需要归还的是借给。"}, {"text": "他奉献这个机会赚了很多钱。", "explanation": "这里应该用〈利用〉。奉献指无私地献出，不表示凭借某个机会谋取好处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奉献", "is_correct": true, "explanation": "“奉献”指无私地付出，与“为社会多……一点”相符。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”一般接生活、待遇，不说为社会多享受一点。"}, {"text": "索要", "is_correct": false, "explanation": "语义：“索要”是向人要求给予，与“为社会多付出”的意思相反。"}, {"text": "占用", "is_correct": false, "explanation": "语义：“占用”是据为己有、使用别人的空间或时间，与“为社会付出”的语境冲突。"}], "explanations": {"奉献": "“奉献”指无私地付出，与“为社会多……一点”相符。", "享受": "搭配：“享受”一般接生活、待遇，不说为社会多享受一点。", "索要": "语义：“索要”是向人要求给予，与“为社会多付出”的意思相反。", "占用": "语义：“占用”是据为己有、使用别人的空间或时间，与“为社会付出”的语境冲突。"}, "sentence_index": 6, "correct_answer": "奉献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把自行车奉献给了小明，用来抵掉打坏窗户的损失。", "explanation": "这里应该用〈赔偿〉。奉献是无私地交出、不求补偿，而“抵掉损失”是赔偿义务，应用赔偿。"}, {"text": "他把这笔钱奉献给了那家公司，希望年底能分到红利。", "explanation": "这里应该用〈投资〉。奉献不求回报，“希望年底能分到红利”是为了获利，应用投资。"}, {"text": "他向警察奉献了那个小偷。", "explanation": "这里应该用〈举报〉。奉献的对象是物品、时间或精力，不能指把人告发给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把积蓄都奉献了给贫困地区的学校。", "corrected_sentence": "她把积蓄都奉献给了贫困地区的学校。", "error_description": "“奉献”后的“了”和“给”顺序颠倒。应说“奉献给了”，“给”是“奉献”的补语，“了”放在“给”之后，不能说“奉献了给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一直为社区奉献了着自己的时间。", "corrected_sentence": "她一直为社区奉献着自己的时间。", "error_description": "“奉献”后同时用了“了”和“着”，两个体标重复。表示持续时只用“着”，应说“奉献着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
