INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93493, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妹子是妹妹，也可以叫年轻的女孩。", "primary_collocate": null, "pronunciation": "mèi zi", "ipa": "meɪ˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "妹子在房间里写作业呢。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥对妹子特别好。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着妹子去公园玩了。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个妹子的声音真好听。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在门口的那个妹子是谁？", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的妹子明年要上大学了。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹子过生日，我送了她一本书。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里有两个妹子在帮客人拿东西。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他妹子在北京工作，很少回家。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那边的妹子们在唱歌。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "妹子们", "label": "复数"}], "register": "口语", "sense_fingerprint": "妹子|妹妹；年轻女孩|口语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2661f93-1077-4bd1-98fe-0202873548b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93493, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "妹子", "is_correct": true, "explanation": "妹子（mèi zi）指妹妹，与听到的读音一致。"}, {"text": "梅子", "is_correct": false, "explanation": "梅子（méi zi）与妹子的第一音节声调不同：第二声与第四声，意思是梅子（水果）。"}, {"text": "麦子", "is_correct": false, "explanation": "麦子（mài zi）与妹子的韵母不同：ai 与 ei，意思是小麦。"}, {"text": "辈子", "is_correct": false, "explanation": "辈子（bèi zi）与妹子的声母不同：b 与 m，意思是一生。"}], "explanations": {"妹子": "妹子（mèi zi）指妹妹，与听到的读音一致。", "梅子": "梅子（méi zi）与妹子的第一音节声调不同：第二声与第四声，意思是梅子（水果）。", "麦子": "麦子（mài zi）与妹子的韵母不同：ai 与 ei，意思是小麦。", "辈子": "辈子（bèi zi）与妹子的声母不同：b 与 m，意思是一生。"}, "sentence_index": null, "correct_answer": "妹子"}, "level_3": {"options": [{"text": "妹子", "is_correct": true, "explanation": "妹子指妹妹或年轻女子，“妹子在房间里写作业呢”符合句意。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不会写作业，句子说的是学生的学习活动。"}, {"text": "电视", "is_correct": false, "explanation": "配价：“写作业”要求有生命的人做主语，电视不能写作业。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能写作业，与句意不符。"}], "explanations": {"妹子": "妹子指妹妹或年轻女子，“妹子在房间里写作业呢”符合句意。", "猫": "语义：猫不会写作业，句子说的是学生的学习活动。", "电视": "配价：“写作业”要求有生命的人做主语，电视不能写作业。", "桌子": "语义：桌子不能写作业，与句意不符。"}, "sentence_index": 0, "correct_answer": "妹子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妹子是家里年纪最大的。", "explanation": "这里应该用〈姐姐〉。妹子指比自己小的妹妹，不能说她是家里年纪最大的。"}, {"text": "我的妹子是个男孩，今年八岁。", "explanation": "这里应该用〈弟弟〉。妹子只指女性，比自己小的男孩应该叫弟弟。"}, {"text": "我妈妈是我的妹子，声音真好听。", "explanation": "这里不能用〈妹子〉指母亲。妹子指妹妹，不能用来指母亲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妹子", "is_correct": true, "explanation": "妹子指妹妹，女性，与后面的代词“她”一致，句意通顺。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是无生命的物体，不会过生日。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会过生日，句子说的是有生命的人。"}, {"text": "地铁", "is_correct": false, "explanation": "配价：“过生日”要求有生命的人做主语，地铁不能过生日。"}], "explanations": {"妹子": "妹子指妹妹，女性，与后面的代词“她”一致，句意通顺。", "黑板": "语义：黑板是无生命的物体，不会过生日。", "冰箱": "语义：冰箱不会过生日，句子说的是有生命的人。", "地铁": "配价：“过生日”要求有生命的人做主语，地铁不能过生日。"}, "sentence_index": 6, "correct_answer": "妹子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视是我的妹子。", "explanation": "这里不能用〈妹子〉指物品。妹子只指人，不能指电视。"}, {"text": "那位老奶奶是个年轻的妹子。", "explanation": "这里应该用〈老太太〉。妹子指妹妹或年轻女子，不能用来称呼年纪大的女性。"}, {"text": "尊敬的各位妹子，请大家就座。", "explanation": "这里应该用〈女士们〉。“妹子”是口语，不能用于正式场合的称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
