INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那边有一个妹子们在唱歌。", "corrected_sentence": "那边有一个妹子在唱歌。", "error_description": "词尾错误：“们”表示复数，不能与“一个”同用，“妹子”指一个人时不加“们”。错误：那边有一个妹子们在唱歌。正确：那边有一个妹子在唱歌。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
