INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妹妹；也泛指年轻女子（口语）。", "primary_collocate": null, "pronunciation": "mèi zi", "ipa": "meɪ˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "我妹子今年十岁，在上小学。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一个妹子，也有一个哥哥。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹子每天早上都骑车去学校。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给妹子买了一个新书包。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个妹子笑起来很好看。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个妹子是我们公司的新同事。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹子做的饭比我做的好吃。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我和妹子一起去看电影了。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几个妹子正在路边等车。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家妹子很喜欢养小猫。", "target_word": "妹子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "妹子们", "label": "复数"}], "register": "口语", "sense_fingerprint": "妹子|妹妹；泛指年轻女子|口语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2661f93-1077-4bd1-98fe-0202873548b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93494, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "妹子", "is_correct": true, "explanation": "妹子（mèi zi）指妹妹，口语，与听到的读音一致。"}, {"text": "梅子", "is_correct": false, "explanation": "梅子（méi zi）与妹子的第一音节声调不同：第二声与第四声，意思是梅子（水果）。"}, {"text": "麦子", "is_correct": false, "explanation": "麦子（mài zi）与妹子的韵母不同：ai 与 ei，意思是小麦。"}, {"text": "辈子", "is_correct": false, "explanation": "辈子（bèi zi）与妹子的声母不同：b 与 m，意思是一生。"}], "explanations": {"妹子": "妹子（mèi zi）指妹妹，口语，与听到的读音一致。", "梅子": "梅子（méi zi）与妹子的第一音节声调不同：第二声与第四声，意思是梅子（水果）。", "麦子": "麦子（mài zi）与妹子的韵母不同：ai 与 ei，意思是小麦。", "辈子": "辈子（bèi zi）与妹子的声母不同：b 与 m，意思是一生。"}, "sentence_index": null, "correct_answer": "妹子"}, "level_3": {"options": [{"text": "妹子", "is_correct": true, "explanation": "妹子指妹妹，“我妹子今年十岁，在上小学”符合句意。"}, {"text": "妈妈", "is_correct": false, "explanation": "语义：妈妈不会是十岁的小学生，句子说的是“在上小学”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师不会十岁还在上小学。"}, {"text": "公司", "is_correct": false, "explanation": "配价：“上小学”要求有人做主语，公司不能上小学。"}], "explanations": {"妹子": "妹子指妹妹，“我妹子今年十岁，在上小学”符合句意。", "妈妈": "语义：妈妈不会是十岁的小学生，句子说的是“在上小学”。", "老师": "语义：老师不会十岁还在上小学。", "公司": "配价：“上小学”要求有人做主语，公司不能上小学。"}, "sentence_index": 0, "correct_answer": "妹子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个妹子是我的父亲。", "explanation": "这里不能用〈妹子〉指父亲。妹子指妹妹或年轻女子，不能用来指父亲这样的长辈。"}, {"text": "我的妹子是男生，喜欢踢足球。", "explanation": "这里应该用〈弟弟〉。妹子只指女性，不能指男生。"}, {"text": "我家妹子比我大两岁。", "explanation": "这里应该用〈姐姐〉。妹子指比自己小的妹妹，不能说比我大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妹子", "is_correct": true, "explanation": "妹子指妹妹，“我妹子做的饭比我做的好吃”符合句意。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会做饭，与“做的饭”不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能做饭，与句意不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱能储存食物，但不能“做饭”。"}], "explanations": {"妹子": "妹子指妹妹，“我妹子做的饭比我做的好吃”符合句意。", "小狗": "语义：小狗不会做饭，与“做的饭”不符。", "桌子": "语义：桌子不能做饭，与句意不符。", "冰箱": "搭配：冰箱能储存食物，但不能“做饭”。"}, "sentence_index": 6, "correct_answer": "妹子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈是我的妹子，很喜欢养小猫。", "explanation": "这里不能用〈妹子〉指母亲。妹子指妹妹，不能用来指母亲。"}, {"text": "这台电脑是我的新妹子。", "explanation": "这里不能用〈妹子〉指物品。妹子只指人，不能指电脑。"}, {"text": "我奶奶是个妹子。", "explanation": "这里不能用〈妹子〉称呼奶奶。妹子指妹妹或年轻女子，不能用于年纪大的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只妹子。", "corrected_sentence": "我有一个妹子。", "error_description": "量词错误：指人的“妹子”应用量词“个”，“只”用于动物等，不能用来数人。错误：我有一只妹子。正确：我有一个妹子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
