INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93497, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "美术是画画、做雕塑等要学习的学科和技能。", "primary_collocate": null, "pronunciation": "měi shù", "ipa": "meɪ˨˩˦ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "我最喜欢的课是美术，因为可以画画。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天下午我们上美术，老师教我们画水彩。", "target_word": "美术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的美术成绩很好，画得像照片一样。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟想学美术，每天都在练习画画。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的美术老师是一位年轻的画家。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈送我去学美术，我学会了画花。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在美术上很有天分，十岁就会画人像。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学美术的人要多看、多画，也要多想。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比起数学，我更喜欢美术，因为它不用算。", "target_word": "美术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥大学学的是美术，现在在做设计。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "美術", "label": "繁体"}, {"form": "美术课", "label": "复合"}, {"form": "美术家", "label": "复合"}], "register": "中性", "sense_fingerprint": "画画、雕塑等要学习的学科和技能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f09b97c-38a8-4ff2-bcb2-0a886cdc7162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美术", "is_correct": true, "explanation": "美术：画画、做雕塑等要学习的学科，这里指学科，与“可以画画”相合。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐课与“因为可以画画”的理由不符。"}, {"text": "体育", "is_correct": false, "explanation": "语义：体育课与“因为可以画画”的理由不符。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不是课程，“课”后面不能接“作业”。"}], "explanations": {"美术": "美术：画画、做雕塑等要学习的学科，这里指学科，与“可以画画”相合。", "音乐": "语义：音乐课与“因为可以画画”的理由不符。", "体育": "语义：体育课与“因为可以画画”的理由不符。", "作业": "搭配：“作业”不是课程，“课”后面不能接“作业”。"}, "sentence_index": 0, "correct_answer": "美术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去美术看画。", "explanation": "这里应该用〈美术馆〉。去看画要去美术馆，美术不是场所。"}, {"text": "那位美术一生都在画画。", "explanation": "这里应该用〈美术家〉。美术指学科或艺术，不指人。"}, {"text": "他学了一幅美术。", "explanation": "这里应该用〈门〉。美术作为学科用“门”计量，“幅”只用于画作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美术", "is_correct": true, "explanation": "美术：学科名称，这里指学习的学科，与“十岁就会画人像”相合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳与“十岁就会画人像”矛盾。"}, {"text": "围棋", "is_correct": false, "explanation": "语义：围棋与“会画人像”矛盾。"}, {"text": "球", "is_correct": false, "explanation": "搭配：“在……上”后面要接学科或领域，“球”不能这样用。"}], "explanations": {"美术": "美术：学科名称，这里指学习的学科，与“十岁就会画人像”相合。", "游泳": "语义：游泳与“十岁就会画人像”矛盾。", "围棋": "语义：围棋与“会画人像”矛盾。", "球": "搭配：“在……上”后面要接学科或领域，“球”不能这样用。"}, "sentence_index": 6, "correct_answer": "美术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的美术很迷人，大家都喜欢她。", "explanation": "这里应该用〈美貌〉。美术指艺术，不指人的容貌。"}, {"text": "这个美术很大，有很多人参观。", "explanation": "这里应该用〈画展〉。美术不指展览，不能用来指展览会。"}, {"text": "他写了一首美术，每天读。", "explanation": "这里应该用〈诗〉。美术指学科或艺术，不指诗歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这学期我选了一本美术课。", "corrected_sentence": "这学期我选了一门美术课。", "error_description": "量词错误：“美术课”这类课程要用〈门〉，不能用〈本〉。错误形式：一本美术课；正确形式：一门美术课。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐从小就美术，现在很厉害。", "corrected_sentence": "姐姐从小就学美术，现在很厉害。", "error_description": "漏掉了动词：“学美术”是动宾结构，“美术”前面要有动词“学”，去掉“学”后句子不通。错误形式：从小就美术；正确形式：从小就学美术。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
