INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以线条、色彩、形体造出可看的美的作品的艺术，如绘画、雕塑。", "primary_collocate": null, "pronunciation": "měi shù", "ipa": "meɪ˨˩˦ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "她特别喜欢中国古代的美术。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "美术包括画画和雕塑。", "target_word": "美术", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从小喜欢美术，常常去看画展。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在大学里研究中国美术的历史。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人一生都在研究西方美术。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "美术是给人看的，音乐是给人听的。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画是很有名的美术作品之一。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "展览上有雕塑、绘画等不同种类的美术。", "target_word": "美术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对美术很有兴趣，家里挂着很多画。", "target_word": "美术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国美术有几千年的历史。", "target_word": "美术", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "美術", "label": "繁体"}, {"form": "美术馆", "label": "复合"}, {"form": "美术家", "label": "复合"}], "register": "中性", "sense_fingerprint": "绘画、雕塑等造型艺术的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f09b97c-38a8-4ff2-bcb2-0a886cdc7162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美术", "is_correct": true, "explanation": "美术：以线条、色彩、形体造出作品的艺术，如绘画、雕塑，可以说“中国古代的美术”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是现代物品，与「中国古代的」矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是现代物品，与“中国古代的”矛盾。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“中国古代的”后面不能接“速度”，搭配不通。"}], "explanations": {"美术": "美术：以线条、色彩、形体造出作品的艺术，如绘画、雕塑，可以说“中国古代的美术”。", "电脑": "语义：电脑是现代物品，与「中国古代的」矛盾。", "手机": "语义：手机是现代物品，与“中国古代的”矛盾。", "速度": "搭配：“中国古代的”后面不能接“速度”，搭配不通。"}, "sentence_index": 0, "correct_answer": "美术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位美术一生都在画画，留下了很多作品。", "explanation": "这里应该用〈美术家〉。美术指艺术或学科，不指人；指从事美术的人要说美术家。"}, {"text": "这个美术里挂着很多名画，周末可以去看。", "explanation": "这里应该用〈美术馆〉。美术是艺术本身，不是展览的场所。"}, {"text": "她买了一幅美术，挂在客厅里。", "explanation": "这里的“美术”指艺术，不能用〈幅〉计量。幅只用于单幅画作，应说〈一幅画〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美术", "is_correct": true, "explanation": "美术：以线条、色彩、形体造出作品的艺术，这里指艺术作品，符合“有名的……作品”。"}, {"text": "文学", "is_correct": false, "explanation": "语义：这幅画是绘画作品，不能是“文学作品”。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：“这幅画”是画，不能是“音乐作品”。"}, {"text": "运动", "is_correct": false, "explanation": "搭配：“作品”不能与“运动”搭配，说“运动作品”不通。"}], "explanations": {"美术": "美术：以线条、色彩、形体造出作品的艺术，这里指艺术作品，符合“有名的……作品”。", "文学": "语义：这幅画是绘画作品，不能是“文学作品”。", "音乐": "语义：“这幅画”是画，不能是“音乐作品”。", "运动": "搭配：“作品”不能与“运动”搭配，说“运动作品”不通。"}, "sentence_index": 6, "correct_answer": "美术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件美术是他十年前完成的，很有名。", "explanation": "这里应该用〈作品〉。美术是艺术的总称，不指某一件具体的作品。"}, {"text": "这座美术立在广场中央，很漂亮。", "explanation": "这里应该用〈雕塑〉。美术是总称，不指一座具体的雕像。"}, {"text": "这个女孩的美术很好看，大家都夸她。", "explanation": "这里应该用〈美貌〉。美术指艺术，不指人的容貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一只美术作品。", "corrected_sentence": "他买了一件美术作品。", "error_description": "量词错误：「美术作品」泛指各类作品，要用〈件〉，〈只〉不能用于作品。错误形式：一只美术作品；正确形式：一件美术作品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校的很美术水平很高。", "corrected_sentence": "这所学校的美术水平很高。", "error_description": "词性错误：“美术”是名词，不能用“很”修饰。错误形式：很美术；正确形式：美术水平。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
