INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93499, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "容是能把东西装进去，放得下。", "primary_collocate": null, "pronunciation": "róng", "ipa": "ɻʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这个房间容不下十张桌子。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个大厅能容三百人。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小书包容不下这么多书。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车最多容五个人。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育馆很大，可以容两万人。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子容不下一瓶水。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小路只容一辆车通过。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的行李箱容得下这些衣服。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个冰箱太小，容不下大西瓜。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室不大，只容得下三十个学生。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "容得下", "label": "肯定可能补语"}, {"form": "容不下", "label": "否定可能补语"}], "register": "中性", "sense_fingerprint": "容：空间装得下、放得下（容得下、容不下）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53d5679f-77fa-4bf4-9eb8-f2e6cf29bb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93499, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "容", "is_correct": true, "explanation": "容（róng）：容纳、装得下，即本题的正确答案。"}, {"text": "仍", "is_correct": false, "explanation": "réng（第二声）与 róng 的韵母不同（eng/ong），意思是仍然。"}, {"text": "农", "is_correct": false, "explanation": "nóng（第二声）与 róng 的声母不同（n/r），意思是农业。"}, {"text": "龙", "is_correct": false, "explanation": "lóng（第二声）与 róng 的声母不同（l/r），意思是龙。"}, {"text": "冗", "is_correct": false, "explanation": "rǒng（第三声）与 róng 的声母、韵母相同，只是声调不同，意思是多余、繁杂。"}], "explanations": {"容": "容（róng）：容纳、装得下，即本题的正确答案。", "仍": "réng（第二声）与 róng 的韵母不同（eng/ong），意思是仍然。", "农": "nóng（第二声）与 róng 的声母不同（n/r），意思是农业。", "龙": "lóng（第二声）与 róng 的声母不同（l/r），意思是龙。", "冗": "rǒng（第三声）与 róng 的声母、韵母相同，只是声调不同，意思是多余、繁杂。"}, "sentence_index": null, "correct_answer": "容"}, "level_3": {"options": [{"text": "容", "is_correct": true, "explanation": "容：容纳、装得下。“容不下十张桌子”指房间装不下十张桌子。"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站”指人或物站立，不能说“站不下十张桌子”。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”指穿戴衣物，与“房间”“桌子”不搭，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与桌子和房间无关，句意不通。"}], "explanations": {"容": "容：容纳、装得下。“容不下十张桌子”指房间装不下十张桌子。", "站": "搭配：“站”指人或物站立，不能说“站不下十张桌子”。", "穿": "语义：“穿”指穿戴衣物，与“房间”“桌子”不搭，句意不通。", "吃": "语义：“吃”指进食，与桌子和房间无关，句意不通。"}, "sentence_index": 0, "correct_answer": "容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议容了一个小时。", "explanation": "这里应该用〈持续〉。“容”指容纳、装得下，不能用来说时间的长短。"}, {"text": "他容着一个大碗。", "explanation": "这里应该用〈拿〉。“容”表示能装下、放得下，不能表示用手握着东西。"}, {"text": "她今天容了一件红裙子。", "explanation": "这里应该用〈穿〉。“容”表示能装下，不能表示人身上穿着衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93499, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "容", "is_correct": true, "explanation": "容（róng）：容纳、装得下，即本题的正确答案。"}, {"text": "浓", "is_correct": false, "explanation": "nóng（第二声）与 róng 的声母不同（n/r），意思是浓稠。"}, {"text": "笼", "is_correct": false, "explanation": "lóng（第二声）与 róng 的声母不同（l/r），意思是笼子。"}, {"text": "聋", "is_correct": false, "explanation": "lóng（第二声）与 róng 的声母不同（l/r），意思是听不见。"}, {"text": "冗", "is_correct": false, "explanation": "rǒng（第三声）与 róng 的声母、韵母相同，只是声调不同，意思是多余、繁杂。"}], "explanations": {"容": "容（róng）：容纳、装得下，即本题的正确答案。", "浓": "nóng（第二声）与 róng 的声母不同（n/r），意思是浓稠。", "笼": "lóng（第二声）与 róng 的声母不同（l/r），意思是笼子。", "聋": "lóng（第二声）与 róng 的声母不同（l/r），意思是听不见。", "冗": "rǒng（第三声）与 róng 的声母、韵母相同，只是声调不同，意思是多余、繁杂。"}, "sentence_index": null, "correct_answer": "容"}, "level_3": {"options": [{"text": "容", "is_correct": true, "explanation": "容：容纳。“只容一辆车通过”指小路只能让一辆车通过。"}, {"text": "挡", "is_correct": false, "explanation": "语义：“挡”表示阻拦，与“通过”的意思相反，句意不通。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”表示买卖，与“小路”和“通过”无关，句意不通。"}, {"text": "抬", "is_correct": false, "explanation": "搭配：“抬”的对象多为重物，不能说“抬一辆车通过”。"}], "explanations": {"容": "容：容纳。“只容一辆车通过”指小路只能让一辆车通过。", "挡": "语义：“挡”表示阻拦，与“通过”的意思相反，句意不通。", "卖": "语义：“卖”表示买卖，与“小路”和“通过”无关，句意不通。", "抬": "搭配：“抬”的对象多为重物，不能说“抬一辆车通过”。"}, "sentence_index": 6, "correct_answer": "容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商店容了我十块钱。", "explanation": "这里应该用〈收〉。“容”表示能装下，不能用来说商店向顾客收取钱款。"}, {"text": "妈妈容了一件衣服。", "explanation": "这里应该用〈洗〉。“容”表示能装下，不能用来指清洗衣物。"}, {"text": "他容了一封信。", "explanation": "这里应该用〈写〉。“容”表示能装下，不能用来指写信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_v