INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93500, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "容忍；允许。", "primary_collocate": null, "pronunciation": "róng", "ipa": "ɻʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这个问题不容再拖了。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请容我先想一想。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里容不下别人的批评。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不容任何人破坏。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板脾气大，一点小错也容不得。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间不容我们再等下去了。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请容我说明一下情况。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种坏习惯，老师可容不得。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情很清楚，不容你不承认。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼里容不下一粒沙子。", "target_word": "容", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "容不得", "label": "否定可能补语"}, {"form": "容不下", "label": "否定可能补语"}], "register": "书面", "sense_fingerprint": "容：容忍、允许（多用于不容、容不得、容我）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53d5679f-77fa-4bf4-9eb8-f2e6cf29bb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93500, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "容", "is_correct": true, "explanation": "容（róng）：容纳、允许，即本题的正确答案。"}, {"text": "仍", "is_correct": false, "explanation": "réng（第二声）与 róng 的韵母不同（eng/ong），意思是仍然。"}, {"text": "农", "is_correct": false, "explanation": "nóng（第二声）与 róng 的声母不同（n/r），意思是农业。"}, {"text": "龙", "is_correct": false, "explanation": "lóng（第二声）与 róng 的声母不同（l/r），意思是龙。"}, {"text": "冗", "is_correct": false, "explanation": "rǒng（第三声）与 róng 的声母、韵母相同，只是声调不同，意思是多余、繁杂。"}], "explanations": {"容": "容（róng）：容纳、允许，即本题的正确答案。", "仍": "réng（第二声）与 róng 的韵母不同（eng/ong），意思是仍然。", "农": "nóng（第二声）与 róng 的声母不同（n/r），意思是农业。", "龙": "lóng（第二声）与 róng 的声母不同（l/r），意思是龙。", "冗": "rǒng（第三声）与 róng 的声母、韵母相同，只是声调不同，意思是多余、繁杂。"}, "sentence_index": null, "correct_answer": "容"}, "level_3": {"options": [{"text": "容", "is_correct": true, "explanation": "容：允许。“不容再拖了”即不允许再拖延，只有“容”符合句意。"}, {"text": "怕", "is_correct": false, "explanation": "语义：“怕”表示畏惧，“这个问题不怕再拖了”句意不通，与“不允许拖延”的意思不合。"}, {"text": "肯", "is_correct": false, "explanation": "配价：“肯”的主语应是有意愿的人，“这个问题”不能“肯”，句子不成立。"}, {"text": "碍", "is_correct": false, "explanation": "语义：“碍”指妨碍，与“不允许再拖”的意思相反，句意不通。"}], "explanations": {"容": "容：允许。“不容再拖了”即不允许再拖延，只有“容”符合句意。", "怕": "语义：“怕”表示畏惧，“这个问题不怕再拖了”句意不通，与“不允许拖延”的意思不合。", "肯": "配价：“肯”的主语应是有意愿的人，“这个问题”不能“肯”，句子不成立。", "碍": "语义：“碍”指妨碍，与“不允许再拖”的意思相反，句意不通。"}, "sentence_index": 0, "correct_answer": "容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他容了我送的礼物，很高兴。", "explanation": "这里应该用〈接受〉。“容”表示允许或包容人的言行，不能用来指收下别人送的东西。"}, {"text": "我一直容着牙疼，没去看医生。", "explanation": "这里应该用〈忍受〉。“容”只指允许或包容别人的言行，不能说承受身体上的疼痛。"}, {"text": "他容了我的邀请，没有回答。", "explanation": "这里应该用〈拒绝〉。“容”指允许或包容，不能指拒绝对方的邀请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93500, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "容", "is_correct": true, "explanation": "容（róng）：容纳、允许，即本题的正确答案。"}, {"text": "浓", "is_correct": false, "explanation": "nóng（第二声）与 róng 的声母不同（n/r），意思是浓稠。"}, {"text": "笼", "is_correct": false, "explanation": "lóng（第二声）与 róng 的声母不同（l/r），意思是笼子。"}, {"text": "聋", "is_correct": false, "explanation": "lóng（第二声）与 róng 的声母不同（l/r），意思是听不见。"}, {"text": "冗", "is_correct": false, "explanation": "rǒng（第三声）与 róng 的声母、韵母相同，只是声调不同，意思是多余、繁杂。"}], "explanations": {"容": "容（róng）：容纳、允许，即本题的正确答案。", "浓": "nóng（第二声）与 róng 的声母不同（n/r），意思是浓稠。", "笼": "lóng（第二声）与 róng 的声母不同（l/r），意思是笼子。", "聋": "lóng（第二声）与 róng 的声母不同（l/r），意思是听不见。", "冗": "rǒng（第三声）与 róng 的声母、韵母相同，只是声调不同，意思是多余、繁杂。"}, "sentence_index": null, "correct_answer": "容"}, "level_3": {"options": [{"text": "容", "is_correct": true, "explanation": "容：允许。“请容我说明”即请允许我说明，只有“容”符合句意。"}, {"text": "赔", "is_correct": false, "explanation": "搭配：“赔”的宾语多是钱或损失，不能接“说明”。"}, {"text": "逼", "is_correct": false, "explanation": "语义：“逼”表示强迫，与“请”的礼貌语气相冲突。"}, {"text": "惹", "is_correct": false, "explanation": "语义：“惹”表示招惹、引起麻烦，“惹我说明”意思不通。"}], "explanations": {"容": "容：允许。“请容我说明”即请允许我说明，只有“容”符合句意。", "赔": "搭配：“赔”的宾语多是钱或损失，不能接“说明”。", "逼": "语义：“逼”表示强迫，与“请”的礼貌语气相冲突。", "惹": "语义：“惹”表示招惹、引起麻烦，“惹我说明”意思不通。"}, "sentence_index": 6, "correct_answer": "容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他容了很多朋友。", "explanation": "这里应该用〈结交〉。“容”指允许或包容，不能表示交往、认识别人。"}, {"text": "他容了我一块钱。", "explanation": "这里应该用〈借〉。“容”不能表示把钱借给别人。"}, {"text": "他容了这本书。", "explanation": "这里应该用〈读〉。“容”不能表示阅读书籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个问题容不拖延。", "corrected_sentence": "这个问题容不得拖延。", "error_description": "错误在“容不拖延”。“容不”后面要补上补语“得”，构成“容不得”（容忍不了），应说“容不得拖延”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司容不员工撒谎。", "corrected_sentence": "公司容不得员工撒谎。", "error_description": "错误在“容不员工撒谎”。“容不”后面要带补语“得”，表示容忍不了，应说“公司容不得员工撒谎”；缺了“得”，句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
