INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93501, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93501, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "声称是公开地说某件事是这样的，但别人不一定相信。", "primary_collocate": null, "pronunciation": "shēng chēng", "ipa": "ʂɤŋ˥ tʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他声称自己从来没有迟到。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人声称自己是医生。", "target_word": "声称", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明声称他一口气跑了十公里。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她声称昨天晚上一直在家。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板声称这家店的东西都是真的。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他声称这件事跟自己没有关系。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个公司声称他们的手机最便宜。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他声称自己去过很多国家，可是没人相信。", "target_word": "声称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩声称窗户不是他打破的。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上有人声称喝这种茶能让人长高。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "声称了", "label": "体标"}, {"form": "声称过", "label": "体标"}, {"form": "聲稱", "label": "繁体"}], "register": "书面", "sense_fingerprint": "公开宣称某种说法，别人未必相信", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5996816f-6ae7-41cc-8154-694bc816de42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93501, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "声称", "is_correct": true, "explanation": "正确：声称 shēng chēng，大声对人说自己是某样，但别人未必相信。"}, {"text": "生成", "is_correct": false, "explanation": "与 声称 的第二音节声调不同（生成 chéng 为第二声，声称 chēng 为第一声），意思是产生、形成。"}, {"text": "省城", "is_correct": false, "explanation": "两个音节声调都不同（省 shěng 第三声，城 chéng 第二声），意思是省会城市。"}, {"text": "圣城", "is_correct": false, "explanation": "两个音节声调都不同（圣 shèng 第四声，城 chéng 第二声），意思是圣地。"}, {"text": "省称", "is_correct": false, "explanation": "第一音节声调不同（省 shěng 第三声，声 shēng 第一声），意思是省的简称。"}], "explanations": {"声称": "正确：声称 shēng chēng，大声对人说自己是某样，但别人未必相信。", "生成": "与 声称 的第二音节声调不同（生成 chéng 为第二声，声称 chēng 为第一声），意思是产生、形成。", "省城": "两个音节声调都不同（省 shěng 第三声，城 chéng 第二声），意思是省会城市。", "圣城": "两个音节声调都不同（圣 shèng 第四声，城 chéng 第二声），意思是圣地。", "省称": "第一音节声调不同（省 shěng 第三声，声 shēng 第一声），意思是省的简称。"}, "sentence_index": null, "correct_answer": "声称"}, "level_3": {"options": [{"text": "声称", "is_correct": true, "explanation": "正确：“声称自己从来没有迟到”是大声说出一种说法，句意相符。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：“抱怨”表示不满，与“从来没有迟到”这种值得肯定的说法不合。"}, {"text": "后悔", "is_correct": false, "explanation": "搭配：“后悔”后面接的应是做过、做错的事，“从来没有迟到”不能用来后悔。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是取笑别人，句中没有人被取笑，与语境不合。"}], "explanations": {"声称": "正确：“声称自己从来没有迟到”是大声说出一种说法，句意相符。", "抱怨": "语义：“抱怨”表示不满，与“从来没有迟到”这种值得肯定的说法不合。", "后悔": "搭配：“后悔”后面接的应是做过、做错的事，“从来没有迟到”不能用来后悔。", "嘲笑": "语义：“嘲笑”是取笑别人，句中没有人被取笑，与语境不合。"}, "sentence_index": 0, "correct_answer": "声称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他悄悄地声称自己是医生。", "explanation": "这里应该用〈告诉〉。声称 指公开地宣称某种说法，与“悄悄”矛盾；私下小声说要用告诉。"}, {"text": "我声称昨天晚上我吃了三碗饭。", "explanation": "这里应该用〈说〉。声称 指公开宣称有待证实的说法，报告吃饭这类日常小事要用说。"}, {"text": "班长声称请大家安静。", "explanation": "这里应该用〈要求〉。声称 只陈述说法，不能直接带出请求；让大家安静要用要求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93501, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声称", "is_correct": true, "explanation": "正确：“声称他们的手机最便宜”是公司大声说出的说法，句意相符。"}, {"text": "哭诉", "is_correct": false, "explanation": "语义：“哭诉”是哭着诉说委屈，与公司介绍手机价格的语境不合。"}, {"text": "埋怨", "is_correct": false, "explanation": "搭配：“埋怨”后接的是令人不满的人或事，“手机最便宜”是优点，不能埋怨。"}, {"text": "吐槽", "is_correct": false, "explanation": "语域：“吐槽”是网络口语，且指挑毛病，与公司自夸价格的语境不合。"}], "explanations": {"声称": "正确：“声称他们的手机最便宜”是公司大声说出的说法，句意相符。", "哭诉": "语义：“哭诉”是哭着诉说委屈，与公司介绍手机价格的语境不合。", "埋怨": "搭配：“埋怨”后接的是令人不满的人或事，“手机最便宜”是优点，不能埋怨。", "吐槽": "语域：“吐槽”是网络口语，且指挑毛病，与公司自夸价格的语境不合。"}, "sentence_index": 6, "correct_answer": "声称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的书包声称里面没有作业。", "explanation": "这里应该用〈显示〉。书包不能说话，声称 要求有能陈述的人或机构。"}, {"text": "这支笔声称它能写字。", "explanation": "这里应该用〈说明〉。笔不能陈述，声称 只用于能说话的人或机构。"}, {"text": "经理声称请大家下周开会。", "explanation": "这里应该用〈通知〉。声称 只陈述说法，不能直接带出命令；让大家开会要用通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板声称得自己没有时间。", "corrected_sentence": "老板声称自己没有时间。", "error_description": "错误：“声称”后面不能直接加“得”引出补语。正确：“声称”后直接接陈述的内容，即“老板声称自己没有时间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位邻居声称着他家的狗很听话。", "corrected_sentence": "这位邻居声称他家的狗很听话。", "error_description": "错误：“声称”是一次性说出某种说法，不能带“着”表示持续。正确：去掉“着”，即“这位邻居声称他家的狗很听话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
