INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93502, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开地说；宣称。常含有说法不一定真实的意思。", "primary_collocate": null, "pronunciation": "shēng chēng", "ipa": "ʂɤŋ˥ tʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "公司声称新产品完全没有问题。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在会上声称自己没有收过钱。", "target_word": "声称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上声称这种药能治所有的病。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对方声称他们已经把钱寄出去了。", "target_word": "声称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂声称自己的水很干净。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人声称在山里看见了大熊猫。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个国家声称这块地是他们的。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店声称所有东西都打五折。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他声称当时不在现场，但警察不信。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广告声称这种牙膏可以让牙齿变白。", "target_word": "声称", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "声称了", "label": "体标"}, {"form": "声称过", "label": "体标"}, {"form": "聲稱", "label": "繁体"}], "register": "书面", "sense_fingerprint": "公开宣称某种说法，真实性存疑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5996816f-6ae7-41cc-8154-694bc816de42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93502, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "声称", "is_correct": true, "explanation": "正确：声称 shēng chēng，公开地说，常含说法不一定真实的意思。"}, {"text": "生成", "is_correct": false, "explanation": "与 声称 的第二音节声调不同（生成 chéng 为第二声，声称 chēng 为第一声），意思是产生、形成。"}, {"text": "省城", "is_correct": false, "explanation": "两个音节声调都不同（省 shěng 第三声，城 chéng 第二声），意思是省会城市。"}, {"text": "圣城", "is_correct": false, "explanation": "两个音节声调都不同（圣 shèng 第四声，城 chéng 第二声），意思是圣地。"}, {"text": "省称", "is_correct": false, "explanation": "第一音节声调不同（省 shěng 第三声，声 shēng 第一声），意思是省的简称。"}], "explanations": {"声称": "正确：声称 shēng chēng，公开地说，常含说法不一定真实的意思。", "生成": "与 声称 的第二音节声调不同（生成 chéng 为第二声，声称 chēng 为第一声），意思是产生、形成。", "省城": "两个音节声调都不同（省 shěng 第三声，城 chéng 第二声），意思是省会城市。", "圣城": "两个音节声调都不同（圣 shèng 第四声，城 chéng 第二声），意思是圣地。", "省称": "第一音节声调不同（省 shěng 第三声，声 shēng 第一声），意思是省的简称。"}, "sentence_index": null, "correct_answer": "声称"}, "level_3": {"options": [{"text": "声称", "is_correct": true, "explanation": "正确：“公司声称新产品完全没有问题”是公开宣称一种说法，句意相符。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：“抱怨”表示不满，公司不会抱怨自家新产品没有问题。"}, {"text": "哭诉", "is_correct": false, "explanation": "语义：“哭诉”是哭着诉说委屈，与“没有问题”这种正面陈述不合。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”后接的是感谢的对象，不能直接以“新产品完全没有问题”这样的陈述作宾语。"}], "explanations": {"声称": "正确：“公司声称新产品完全没有问题”是公开宣称一种说法，句意相符。", "抱怨": "语义：“抱怨”表示不满，公司不会抱怨自家新产品没有问题。", "哭诉": "语义：“哭诉”是哭着诉说委屈，与“没有问题”这种正面陈述不合。", "感谢": "配价：“感谢”后接的是感谢的对象，不能直接以“新产品完全没有问题”这样的陈述作宾语。"}, "sentence_index": 0, "correct_answer": "声称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张地图声称这里有一条河。", "explanation": "这里应该用〈显示〉。地图不能说话，声称 的主语必须是能公开陈述的人或机构。"}, {"text": "这张收据声称我已经付款。", "explanation": "这里应该用〈证明〉。收据能证明付款；声称 需要有说话的主体，收据不能声称。"}, {"text": "老师声称请同学们交作业。", "explanation": "这里应该用〈要求〉。声称 只陈述说法，不能直接带出请求；让同学交作业要用要求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声称", "is_correct": true, "explanation": "正确：“那个国家声称这块地是他们的”是公开主张一种说法，句意相符。"}, {"text": "埋怨", "is_correct": false, "explanation": "语义：“埋怨”表示对某人或某事不满，句子是在主张所有权，与此不合。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”后接的是感谢的对象，不能以“这块地是他们的”这样的陈述作宾语。"}, {"text": "吐槽", "is_correct": false, "explanation": "语域：“吐槽”是口语，且指挑毛病，与国家正式主张领土的语境不合。"}], "explanations": {"声称": "正确：“那个国家声称这块地是他们的”是公开主张一种说法，句意相符。", "埋怨": "语义：“埋怨”表示对某人或某事不满，句子是在主张所有权，与此不合。", "感谢": "配价：“感谢”后接的是感谢的对象，不能以“这块地是他们的”这样的陈述作宾语。", "吐槽": "语域：“吐槽”是口语，且指挑毛病，与国家正式主张领土的语境不合。"}, "sentence_index": 6, "correct_answer": "声称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我声称昨天吃了五个包子。", "explanation": "这里应该用〈说〉。声称 指公开宣称有待证实的说法，报告吃东西这类日常小事要用说。"}, {"text": "我的牙齿声称它很白。", "explanation": "这里应该用〈看起来〉。声称 的主语必须是能说话的人或机构，牙齿不能声称。"}, {"text": "老板声称请大家加班。", "explanation": "这里应该用〈要求〉。声称 只陈述说法，不能直接带出命令；让大家加班要用要求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对方声称着自己收到了信。", "corrected_sentence": "对方声称自己收到了信。", "error_description": "错误：“声称”后面不能带“着”。正确：直接接陈述的内容，即“对方声称自己收到了信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司声称得他们的药很有效。", "corrected_sentence": "这家公司声称他们的药很有效。", "error_description": "错误：“声称”后面不能加“得”引出补语。正确：直接接陈述的内容，即“这家公司声称他们的药很有效”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
