INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93504, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为特定对象或用途设立的区域。", "primary_collocate": null, "pronunciation": "zhuān qū", "ipa": "ʈʂwan˥ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "医院为老人设立了就诊专区。", "target_word": "专区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场里有一个母婴专区。", "target_word": "专区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校新建了一个学生运动专区。", "target_word": "专区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站上有一个学生学习专区。", "target_word": "专区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站里有老人候车专区。", "target_word": "专区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的宠物专区需要牵绳。", "target_word": "专区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市设立了新的科技专区。", "target_word": "专区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车场的访客专区在门口。", "target_word": "专区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的发热门诊专区在东边。", "target_word": "专区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请到车站的军人专区买票。", "target_word": "专区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "專區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为特定对象或用途专门划出来的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b69c20c8-55e0-48cc-a4ad-ae6e68dd460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专区", "is_correct": true, "explanation": "正确。专区指为特定对象设立的区域，与“设立了就诊”搭配。"}, {"text": "机票", "is_correct": false, "explanation": "语义：机票是票证，不是可以设立的场所，不能用于“就诊”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是作品，不能被设立为就诊的地方。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不能被设立为就诊的区域。"}], "explanations": {"专区": "正确。专区指为特定对象设立的区域，与“设立了就诊”搭配。", "机票": "语义：机票是票证，不是可以设立的场所，不能用于“就诊”。", "歌曲": "语义：歌曲是作品，不能被设立为就诊的地方。", "汽油": "语义：汽油是燃料，不能被设立为就诊的区域。"}, "sentence_index": 0, "correct_answer": "专区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "网站上的学生学习专区生病了。", "explanation": "这里把专区误当作〈人〉。生病的是人，专区是划定的区域，不会生病。"}, {"text": "我把这个月的工资都存进了专区。", "explanation": "这里把专区误当作〈账户〉。工资要存进账户，专区是划定的区域，不能用来存钱。"}, {"text": "他是我们班的专区。", "explanation": "这里把专区误用为指人的〈专员〉。专区是划定的区域，不能指人，不能用来称呼某个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专区", "is_correct": true, "explanation": "正确。专区是为科技用途划出的区域，与“设立”搭配，符合句意。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是可以设立的区域，与“科技”的语境不符。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是食物，不能被设立为一个区域。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“科技鞋子”不是常用说法，与“设立”也不搭配。"}], "explanations": {"专区": "正确。专区是为科技用途划出的区域，与“设立”搭配，符合句意。", "饮料": "语义：饮料不是可以设立的区域，与“科技”的语境不符。", "早餐": "语义：早餐是食物，不能被设立为一个区域。", "鞋子": "搭配：“科技鞋子”不是常用说法，与“设立”也不搭配。"}, "sentence_index": 6, "correct_answer": "专区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车站的军人专区正在跑步。", "explanation": "这里把专区误当作指人的〈战士〉。专区指地方，不能跑步；跑步的应是人。"}, {"text": "我们把车站的军人专区吃掉了。", "explanation": "这里把专区误当作〈食物〉。专区是区域，不能被吃掉；“吃掉”要求宾语是可以吃的东西。"}, {"text": "这个军人专区的重量是五公斤。", "explanation": "这里把专区误当作〈货物〉。货物才有重量，专区是划定的区域，没有重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医院门口设有一条急诊专区。", "corrected_sentence": "医院门口设有一个急诊专区。", "error_description": "错误：专区是区域，量词应用“个”，“条”用于细长的东西。正确说法是“一个急诊专区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站里设有一张老年人候车专区。", "corrected_sentence": "车站里设有一个老年人候车专区。", "error_description": "错误：专区是区域，量词应用“个”，“张”用于平面的东西。正确说法是“一个老年人候车专区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
