INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93505, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93505, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "般放在词后面，是说像那样。比如说“雪般白”，就是像雪一样白。", "primary_collocate": null, "pronunciation": "bān", "ipa": "pan˥", "syllable_count": 1, "sentences": [{"text": "她的皮肤雪般白。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的夜晚，星星钻石般亮。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水镜子般平静。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的笑脸花儿般美。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手冰般凉。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的夜晚像梦境般安静。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的头发雪般白，眼睛却很亮。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的声音泉水般清甜。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的太阳火般热。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的态度钢铁般坚定。", "target_word": "般", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "放在词后，表示像那样，后面接形容词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e00da9fe-c9f4-4fde-8aa7-2a7d288258f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93505, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "般", "is_correct": true, "explanation": "般（bān）：助词，放在词后表示像那样，如“雪般白”。"}, {"text": "板", "is_correct": false, "explanation": "bǎn（第三声）与 bān（第一声）声调不同，意思是木板。"}, {"text": "帮", "is_correct": false, "explanation": "bāng 与 bān 韵母不同（ang 与 an），意思是帮助。"}, {"text": "奔", "is_correct": false, "explanation": "bēn 与 bān 韵母不同（en 与 an），意思是奔跑。"}], "explanations": {"般": "般（bān）：助词，放在词后表示像那样，如“雪般白”。", "板": "bǎn（第三声）与 bān（第一声）声调不同，意思是木板。", "帮": "bāng 与 bān 韵母不同（ang 与 an），意思是帮助。", "奔": "bēn 与 bān 韵母不同（en 与 an），意思是奔跑。"}, "sentence_index": null, "correct_answer": "般"}, "level_3": {"options": [{"text": "般", "is_correct": true, "explanation": "般：助词，放在词后表示像那样，此处表示像雪一样白。"}, {"text": "的", "is_correct": false, "explanation": "语义：“雪的白”成了名词短语，句子变成皮肤是雪的白色，不表示像雪一样。"}, {"text": "似", "is_correct": false, "explanation": "配价：“似”需要比较的对象，“雪似白”结构不通，应说“白似雪”。"}, {"text": "得", "is_correct": false, "explanation": "搭配：“得”引出补语，“雪得白”不通，应说“白得像雪”。"}], "explanations": {"般": "般：助词，放在词后表示像那样，此处表示像雪一样白。", "的": "语义：“雪的白”成了名词短语，句子变成皮肤是雪的白色，不表示像雪一样。", "似": "配价：“似”需要比较的对象，“雪似白”结构不通，应说“白似雪”。", "得": "搭配：“得”引出补语，“雪得白”不通，应说“白得像雪”。"}, "sentence_index": 0, "correct_answer": "般"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他同我般亲密，什么话都愿意说。", "explanation": "这里应该用〈一样〉。“般”不能与“同”连用，要说“同我一样亲密”。"}, {"text": "他跟哥哥般聪明，谁都看得出来。", "explanation": "这里应该用〈一样〉。“般”不能与“跟”连用，要说“跟哥哥一样聪明”。"}, {"text": "她的笑容和花儿般美。", "explanation": "这里应该用〈一样〉。“般”不能与“和”连用，要说“和花儿一样美”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93505, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "般", "is_correct": true, "explanation": "般（bān）：助词，放在词后表示像那样，如“钢铁般坚定”。"}, {"text": "办", "is_correct": false, "explanation": "bàn（第四声）与 bān（第一声）声调不同，意思是办理。"}, {"text": "翻", "is_correct": false, "explanation": "fān 与 bān 声母不同（f 与 b），意思是翻动。"}, {"text": "单", "is_correct": false, "explanation": "dān 与 bān 声母不同（d 与 b），意思是单独。"}, {"text": "干", "is_correct": false, "explanation": "gān 与 bān 声母不同（g 与 b），意思是干燥。"}], "explanations": {"般": "般（bān）：助词，放在词后表示像那样，如“钢铁般坚定”。", "办": "bàn（第四声）与 bān（第一声）声调不同，意思是办理。", "翻": "fān 与 bān 声母不同（f 与 b），意思是翻动。", "单": "dān 与 bān 声母不同（d 与 b），意思是单独。", "干": "gān 与 bān 声母不同（g 与 b），意思是干燥。"}, "sentence_index": null, "correct_answer": "般"}, "level_3": {"options": [{"text": "般", "is_correct": true, "explanation": "般：助词，放在词后表示像那样，此处表示像雪一样白。"}, {"text": "地", "is_correct": false, "explanation": "语义：“地”标明修饰关系，“雪地白”不能表示像雪一样白。"}, {"text": "着", "is_correct": false, "explanation": "搭配：“着”表示持续，不能接在“雪”后表示比较。"}, {"text": "过", "is_correct": false, "explanation": "语义：“过”表示经历，句子中不表示像雪一样。"}], "explanations": {"般": "般：助词，放在词后表示像那样，此处表示像雪一样白。", "地": "语义：“地”标明修饰关系，“雪地白”不能表示像雪一样白。", "着": "搭配：“着”表示持续，不能接在“雪”后表示比较。", "过": "语义：“过”表示经历，句子中不表示像雪一样。"}, "sentence_index": 6, "correct_answer": "般"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他带来了三般礼物。", "explanation": "这里应该用〈种〉。般只用于“诸般”“万般”这类词，不能直接接数词作量词，要说“三种礼物”。"}, {"text": "这孩子同父亲般倔强。", "explanation": "这里应该用〈一样〉。“般”不能与“同”连用，要说“同父亲一样倔强”。"}, {"text": "他的眼睛和星星般亮。", "explanation": "这里应该用〈一般〉。“般”不能与“和”连用，要说“和星星一般亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他像石头着沉默。", "corrected_sentence": "他像石头般沉默。", "error_description": "“像……般”结构中，名词后要用“般”表示像那样；“着”表示持续，不能用在这里。应说“像石头般沉默”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她和玻璃般脆弱。", "corrected_sentence": "她像玻璃般脆弱。", "error_description": "“像……般”中的“像”不能换成“和”：“和玻璃般脆弱”不成句，应说“像玻璃般脆弱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b336dbac-cba2-4518-9627-8968dafa0b0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
