INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93507, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "少来是叫别人不要说了，不要这样做。", "primary_collocate": null, "pronunciation": "shǎo lái", "ipa": "ʂaʊ˨˩˦ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "你少来这一套，我不会相信。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少来烦我，我现在很忙。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少来吵我，爸爸在睡觉。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你少来管我的事。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少来吓我，我才不怕呢。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少来这些没用的话，说重点。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少来给我讲大道理，我都懂。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少来麻烦我，自己的事自己做。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少来这种小把戏，我早就看出来了。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少来打扰他，他正在考试。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "少来：命令对方别做、别说（少来这一套、少来烦我）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53d5679f-77fa-4bf4-9eb8-f2e6cf29bb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93507, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "少来", "is_correct": true, "explanation": "少来：别这样做。“你少来这一套”即你别再耍这一套。"}, {"text": "穿戴", "is_correct": false, "explanation": "语义：“穿戴”指穿衣戴帽，与“这一套”及“不会相信”的语境不合。"}, {"text": "洗涤", "is_correct": false, "explanation": "语义：“洗涤”指洗东西，与“这一套”的意思不合，句意不通。"}, {"text": "坐下", "is_correct": false, "explanation": "搭配：“坐下”不能接“这一套”作宾语，搭配不当。"}], "explanations": {"少来": "少来：别这样做。“你少来这一套”即你别再耍这一套。", "穿戴": "语义：“穿戴”指穿衣戴帽，与“这一套”及“不会相信”的语境不合。", "洗涤": "语义：“洗涤”指洗东西，与“这一套”的意思不合，句意不通。", "坐下": "搭配：“坐下”不能接“这一套”作宾语，搭配不当。"}, "sentence_index": 0, "correct_answer": "少来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我少来管他的事。", "explanation": "这里应该用〈不该〉。“少来”是叫听话人别这样做，说话人自己不做时要用“不该”。"}, {"text": "这把椅子少来吵我。", "explanation": "“少来”只能对会说话、会做事的人说，不能用在“椅子”这样的物体上。"}, {"text": "这台电脑少来打扰我。", "explanation": "“少来”只能对会说话、会做事的人说，不能用在“电脑”这样的物体上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "少来", "is_correct": true, "explanation": "少来：别这样做。“少来给我讲大道理”即别再给我讲大道理。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”不能用来接“给我讲大道理”，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉”与“讲大道理”没有语义关联，句子不成立。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”不能用来与“讲大道理”搭配，句意不通。"}], "explanations": {"少来": "少来：别这样做。“少来给我讲大道理”即别再给我讲大道理。", "吃饭": "搭配：“吃饭”不能用来接“给我讲大道理”，句意不通。", "睡觉": "搭配：“睡觉”与“讲大道理”没有语义关联，句子不成立。", "洗澡": "搭配：“洗澡”不能用来与“讲大道理”搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "少来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我少来打扰他，让他安静。", "explanation": "这里应该用〈不去〉。“少来”是劝听话人停止某事，说话人自己克制时要用“不去”。"}, {"text": "这个杯子少来说话。", "explanation": "“少来”是对能说话的人说的，不能用在“杯子”这样的物体上。"}, {"text": "我少来吵醒他的孩子。", "explanation": "“少来”是叫听话人别这样做，说话人自己不做时要用“不该”，不能说“我少来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你少来了说大话。", "corrected_sentence": "你少来说大话。", "error_description": "错误在“少来”后面多加了“了”。“少来”是叫对方别这样做，后面直接接动作，不加“了”，应说“少来说大话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "少来了给我找麻烦，我很忙。", "corrected_sentence": "少来给我找麻烦，我很忙。", "error_description": "错误在“少来了”。“少来”后面直接接动作，不加“了”，应说“少来给我找麻烦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
