INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93508, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "（口语）插话，表示不相信或不赞成对方所说的话。", "primary_collocate": null, "pronunciation": "shǎo lái", "ipa": "ʂaʊ˨˩˦ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "少来！你昨天也这么说。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他不喜欢钱？少来吧。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说你不累？少来，我都看见了。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少来，你肯定又忘带钱包了。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说你没玩手机？少来！", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少来了，谁会相信你的话。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会做饭？少来，上次你连面都煮不好。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少来，我才不会上你的当。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己很穷？少来，他有三辆车。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少来吧，你每次都说马上就好。", "target_word": "少来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "少来：口语中表示不信、不赞成的插话（少来！少来吧）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53d5679f-77fa-4bf4-9eb8-f2e6cf29bb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "少来", "is_correct": true, "explanation": "少来：表示不相信。“少来！你昨天也这么说”即你少来，我不信。"}, {"text": "谢谢", "is_correct": false, "explanation": "语义：“谢谢”表示感谢，与前文的怀疑语气不合，句意不通。"}, {"text": "抱歉", "is_correct": false, "explanation": "语义：“抱歉”表示道歉，与“你昨天也这么说”的指责语境不合。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”用于迎接客人，不用于回应对方的说法。"}], "explanations": {"少来": "少来：表示不相信。“少来！你昨天也这么说”即你少来，我不信。", "谢谢": "语义：“谢谢”表示感谢，与前文的怀疑语气不合，句意不通。", "抱歉": "语义：“抱歉”表示道歉，与“你昨天也这么说”的指责语境不合。", "欢迎": "搭配：“欢迎”用于迎接客人，不用于回应对方的说法。"}, "sentence_index": 0, "correct_answer": "少来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "少来，谢谢你的帮助。", "explanation": "这里应该用〈谢谢〉。“少来”表示不相信或不赞成，不能用来表达感谢。"}, {"text": "少来，你说得对。", "explanation": "这里应该用〈没错〉，表示认同。“少来”表示不相信，语气相反。"}, {"text": "少来，我们明天去公园吧。", "explanation": "这里应该用〈好啊〉，表示同意。“少来”表示不相信，用在这里语气不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "少来", "is_correct": true, "explanation": "少来：表示不相信。“你会做饭？少来”即我不信你会做饭。"}, {"text": "请坐", "is_correct": false, "explanation": "搭配：“请坐”是邀请入座，与对方的质疑语境不合，句意不通。"}, {"text": "慢走", "is_correct": false, "explanation": "语义：“慢走”是告别语，与“你会做饭”的怀疑语境不合。"}, {"text": "干杯", "is_correct": false, "explanation": "语义：“干杯”是举杯祝酒，与前文的质疑语境不合，句意不通。"}], "explanations": {"少来": "少来：表示不相信。“你会做饭？少来”即我不信你会做饭。", "请坐": "搭配：“请坐”是邀请入座，与对方的质疑语境不合，句意不通。", "慢走": "语义：“慢走”是告别语，与“你会做饭”的怀疑语境不合。", "干杯": "语义：“干杯”是举杯祝酒，与前文的质疑语境不合，句意不通。"}, "sentence_index": 6, "correct_answer": "少来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "少来，请把窗户打开。", "explanation": "这里不该用〈少来〉，应直接说“请把窗户打开”。“少来”表示不相信或不赞成，不能用来提出请求。"}, {"text": "少来吧，我们一起去看电影。", "explanation": "这里应该用〈好吧〉，表示同意。“少来吧”表示不相信，语气相反。"}, {"text": "少来，我们一起吃晚饭吧。", "explanation": "这里应该用〈好啊〉，表示同意。“少来”表示不相信，不能用来发出邀请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "少来你，明天肯定又要迟到。", "corrected_sentence": "少来，你明天肯定又要迟到。", "error_description": "错误在“少来你”。作叹词的“少来”要独立成句，后面用逗号停顿；“少来你”把“你”直接接在“少来”后面，句子不通。应说“少来，你明天肯定又要迟到。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不少来，你昨天又迟到了。", "corrected_sentence": "少来，你昨天又迟到了。", "error_description": "错误在“不少来”。“少来”是表示不相信的固定叹词，前面不能加“不”，应说“少来，你昨天又迟到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
