INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93509, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蛋是鸡、鸭、鸟生下来的圆圆的东西，里面能长出小鸟。", "primary_collocate": null, "pronunciation": "dàn", "ipa": "tan˥˩", "syllable_count": 1, "sentences": [{"text": "母鸡每天都会下一个蛋。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟还在蛋里，没有出来。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟妈妈坐在蛋上，不让它变冷。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸭子在河边的草里下了蛋。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋里面的小鸡快出来了。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟的蛋是白色的，很小。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟窝里有三个蛋。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟妈妈一直守着窝里的蛋。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸭子是从蛋里孵出来的。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别动鸟窝里的蛋，鸟妈妈会难过。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "颗", "label": "量词"}, {"form": "鸡蛋", "label": "复合"}, {"form": "鸭蛋", "label": "复合"}], "register": "中性", "sense_fingerprint": "能孵出小鸟小鸡的蛋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81bc4bc-44c8-4cf6-a5b7-596f28b237e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93509, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蛋", "is_correct": true, "explanation": "正确：蛋（dàn）指禽鸟产下、能孵出小鸟或小鸡的卵。"}, {"text": "单", "is_correct": false, "explanation": "dàn（第四声）与 dān（第一声）声调不同，“单”意思是单独、单一。"}, {"text": "胆", "is_correct": false, "explanation": "dàn（第四声）与 dǎn（第三声）声调不同，“胆”意思是胆子、胆量。"}, {"text": "炭", "is_correct": false, "explanation": "dàn 与 tàn 声母不同（d 与 t），“炭”意思是木炭。"}, {"text": "荡", "is_correct": false, "explanation": "dàn 与 dàng 韵母不同（-n 与 -ng），“荡”意思是摇荡、晃动。"}, {"text": "烂", "is_correct": false, "explanation": "dàn 与 làn 声母不同（d 与 l），“烂”意思是腐烂、煮得很软。"}], "explanations": {"蛋": "正确：蛋（dàn）指禽鸟产下、能孵出小鸟或小鸡的卵。", "单": "dàn（第四声）与 dān（第一声）声调不同，“单”意思是单独、单一。", "胆": "dàn（第四声）与 dǎn（第三声）声调不同，“胆”意思是胆子、胆量。", "炭": "dàn 与 tàn 声母不同（d 与 t），“炭”意思是木炭。", "荡": "dàn 与 dàng 韵母不同（-n 与 -ng），“荡”意思是摇荡、晃动。", "烂": "dàn 与 làn 声母不同（d 与 l），“烂”意思是腐烂、煮得很软。"}, "sentence_index": null, "correct_answer": "蛋"}, "level_3": {"options": [{"text": "蛋", "is_correct": true, "explanation": "正确：母鸡“下”的是蛋，“下一个蛋”符合句意。"}, {"text": "球", "is_correct": false, "explanation": "语义：母鸡下的是蛋，不会下“球”。"}, {"text": "字", "is_correct": false, "explanation": "搭配：“下”后不接“字”，“字”是写出来的。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“下”后不接“礼物”，“礼物”是送出去的东西。"}], "explanations": {"蛋": "正确：母鸡“下”的是蛋，“下一个蛋”符合句意。", "球": "语义：母鸡下的是蛋，不会下“球”。", "字": "搭配：“下”后不接“字”，“字”是写出来的。", "礼物": "搭配：“下”后不接“礼物”，“礼物”是送出去的东西。"}, "sentence_index": 0, "correct_answer": "蛋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "精子和蛋细胞结合后，就形成了受精卵。", "explanation": "这里应该用〈卵细胞〉。“蛋”指禽类产下的蛋，人和动物的生殖细胞要说“卵细胞”。"}, {"text": "她每个月都会排出一个蛋，这是正常的生理现象。", "explanation": "这里应该用〈卵子〉或〈排卵〉。“蛋”指禽类产下的蛋，不用来指人的卵子，排出卵子要说“排卵”。"}, {"text": "人工授精时，医生把精子放进了蛋里。", "explanation": "这里应该用〈卵子〉。“蛋”指禽类产下的蛋，人的卵子要说“卵子”，不说“蛋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93509, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蛋", "is_correct": true, "explanation": "正确：蛋（dàn）指禽鸟产下、能孵出小鸟或小鸡的卵。"}, {"text": "单", "is_correct": false, "explanation": "dàn（第四声）与 dān（第一声）声调不同，“单”意思是单独、单一。"}, {"text": "叹", "is_correct": false, "explanation": "dàn 与 tàn 声母不同（d 与 t），“叹”意思是叹气。"}, {"text": "档", "is_correct": false, "explanation": "dàn 与 dàng 韵母不同（-n 与 -ng），“档”意思是档次、档案。"}, {"text": "滥", "is_correct": false, "explanation": "dàn 与 làn 声母不同（d 与 l），“滥”意思是过度、泛滥。"}], "explanations": {"蛋": "正确：蛋（dàn）指禽鸟产下、能孵出小鸟或小鸡的卵。", "单": "dàn（第四声）与 dān（第一声）声调不同，“单”意思是单独、单一。", "叹": "dàn 与 tàn 声母不同（d 与 t），“叹”意思是叹气。", "档": "dàn 与 dàng 韵母不同（-n 与 -ng），“档”意思是档次、档案。", "滥": "dàn 与 làn 声母不同（d 与 l），“滥”意思是过度、泛滥。"}, "sentence_index": null, "correct_answer": "蛋"}, "level_3": {"options": [{"text": "蛋", "is_correct": true, "explanation": "正确：鸟窝里放的是蛋，“三个蛋”符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：鸟窝里不会有窗户，与“鸟窝”的情境不符。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：盘子是人用的餐具，鸟窝里不会有盘子。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是人用的电器，鸟窝里不会有电视。"}], "explanations": {"蛋": "正确：鸟窝里放的是蛋，“三个蛋”符合句意。", "窗户": "语义：鸟窝里不会有窗户，与“鸟窝”的情境不符。", "盘子": "语义：盘子是人用的餐具，鸟窝里不会有盘子。", "电视": "语义：电视是人用的电器，鸟窝里不会有电视。"}, "sentence_index": 6, "correct_answer": "蛋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河边铺满了光滑的蛋石。", "explanation": "这里应该用〈卵石〉。“卵石”是固定词，指被水冲圆的小石头，不能把“卵”换成“蛋”。"}, {"text": "鸟类大多是蛋生动物，这是它们的特点。", "explanation": "这里应该用〈卵生〉。“卵生”是动物学术语，指动物从卵里孵出来，不说“蛋生”。"}, {"text": "医生说她的蛋巢有炎症，需要治疗。", "explanation": "这里应该用〈卵巢〉。“卵巢”是女性的器官，是固定名称，不说“蛋巢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只母鸡昨天下了两条蛋。", "corrected_sentence": "那只母鸡昨天下了两个蛋。", "error_description": "量词错误：“蛋”应用“个”或“颗”来计量，“条”用于鱼、蛇等细长的东西。正确说法是“两个蛋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "麻雀的窝里有四个蛋们。", "corrected_sentence": "麻雀的窝里有四个蛋。", "error_description": "词缀错误：“蛋”不指人，不能加“们”表示复数；应说“有四个蛋”，不说“有四个蛋们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
