INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鸟类、龟类、昆虫等产下的卵，尤指可食用的禽蛋。", "primary_collocate": null, "pronunciation": "dàn", "ipa": "tan˥˩", "syllable_count": 1, "sentences": [{"text": "我早上煮了两个蛋。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了十个蛋回家。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋已经煮熟了，快吃吧。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不吃蛋，也不喝牛奶。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我炒一个蛋。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的蛋很新鲜，卖得很快。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿走了桌上的蛋。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭时，她先把蛋打在碗里。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋太咸了，我吃不下。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里还有三个蛋，晚上吃吧。", "target_word": "蛋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "颗", "label": "量词"}, {"form": "鸡蛋", "label": "复合"}, {"form": "鸭蛋", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以煮着吃的禽蛋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81bc4bc-44c8-4cf6-a5b7-596f28b237e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93510, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蛋", "is_correct": true, "explanation": "正确：蛋（dàn）指可以煮着吃的禽蛋。"}, {"text": "单", "is_correct": false, "explanation": "dàn（第四声）与 dān（第一声）声调不同，“单”意思是单独、单一。"}, {"text": "胆", "is_correct": false, "explanation": "dàn（第四声）与 dǎn（第三声）声调不同，“胆”意思是胆子、胆量。"}, {"text": "炭", "is_correct": false, "explanation": "dàn 与 tàn 声母不同（d 与 t），“炭”意思是木炭。"}, {"text": "荡", "is_correct": false, "explanation": "dàn 与 dàng 韵母不同（-n 与 -ng），“荡”意思是摇荡、晃动。"}, {"text": "烂", "is_correct": false, "explanation": "dàn 与 làn 声母不同（d 与 l），“烂”意思是腐烂、煮得很软。"}], "explanations": {"蛋": "正确：蛋（dàn）指可以煮着吃的禽蛋。", "单": "dàn（第四声）与 dān（第一声）声调不同，“单”意思是单独、单一。", "胆": "dàn（第四声）与 dǎn（第三声）声调不同，“胆”意思是胆子、胆量。", "炭": "dàn 与 tàn 声母不同（d 与 t），“炭”意思是木炭。", "荡": "dàn 与 dàng 韵母不同（-n 与 -ng），“荡”意思是摇荡、晃动。", "烂": "dàn 与 làn 声母不同（d 与 l），“烂”意思是腐烂、煮得很软。"}, "sentence_index": null, "correct_answer": "蛋"}, "level_3": {"options": [{"text": "蛋", "is_correct": true, "explanation": "正确：“煮”的对象是禽蛋，“煮了两个蛋”符合句意。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能拿来煮，“煮”的对象应是食物。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能煮来吃，与“早上煮”的语境不符。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：面包通常烤或蒸，“煮”一般不接“面包”。"}], "explanations": {"蛋": "正确：“煮”的对象是禽蛋，“煮了两个蛋”符合句意。", "书": "语义：书不能拿来煮，“煮”的对象应是食物。", "钥匙": "语义：钥匙不能煮来吃，与“早上煮”的语境不符。", "面包": "搭配：面包通常烤或蒸，“煮”一般不接“面包”。"}, "sentence_index": 0, "correct_answer": "蛋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "生物课上，老师讲了蛋细胞的分裂过程。", "explanation": "这里应该用〈卵细胞〉。“蛋”指鸟类、龟类、昆虫等产下的卵，人和动物的生殖细胞要说“卵细胞”。"}, {"text": "医生说她这个月排出了一个蛋，身体很健康。", "explanation": "这里应该用〈卵子〉或〈排卵〉。“蛋”指动物产下的卵，不指人的卵子，排出卵子要说“排卵”。"}, {"text": "实验室里，研究员把精子放进了蛋里培养。", "explanation": "这里应该用〈卵子〉。“蛋”指动物产下的卵，人的卵子要说“卵子”，不说“蛋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93510, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蛋", "is_correct": true, "explanation": "正确：蛋（dàn）指可以煮着吃的禽蛋。"}, {"text": "单", "is_correct": false, "explanation": "dàn（第四声）与 dān（第一声）声调不同，“单”意思是单独、单一。"}, {"text": "叹", "is_correct": false, "explanation": "dàn 与 tàn 声母不同（d 与 t），“叹”意思是叹气。"}, {"text": "档", "is_correct": false, "explanation": "dàn 与 dàng 韵母不同（-n 与 -ng），“档”意思是档次、档案。"}, {"text": "滥", "is_correct": false, "explanation": "dàn 与 làn 声母不同（d 与 l），“滥”意思是过度、泛滥。"}], "explanations": {"蛋": "正确：蛋（dàn）指可以煮着吃的禽蛋。", "单": "dàn（第四声）与 dān（第一声）声调不同，“单”意思是单独、单一。", "叹": "dàn 与 tàn 声母不同（d 与 t），“叹”意思是叹气。", "档": "dàn 与 dàng 韵母不同（-n 与 -ng），“档”意思是档次、档案。", "滥": "dàn 与 làn 声母不同（d 与 l），“滥”意思是过度、泛滥。"}, "sentence_index": null, "correct_answer": "蛋"}, "level_3": {"options": [{"text": "蛋", "is_correct": true, "explanation": "正确：“拿走”的是桌上的实物蛋，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，不是桌上的东西，不能被拿走。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，不可能放在桌上被拿走。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“拿走”一般针对实物，“名字”是抽象的词，不说“拿走了桌上的名字”。"}], "explanations": {"蛋": "正确：“拿走”的是桌上的实物蛋，符合句意。", "空气": "语义：空气看不见，不是桌上的东西，不能被拿走。", "月亮": "语义：月亮在天上，不可能放在桌上被拿走。", "名字": "搭配：“拿走”一般针对实物，“名字”是抽象的词，不说“拿走了桌上的名字”。"}, "sentence_index": 6, "correct_answer": "蛋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海滩上铺满了圆圆的蛋石。", "explanation": "这里应该用〈卵石〉。“卵石”是固定词，指被水冲圆的小石头，不能把“卵”换成“蛋”。"}, {"text": "爬行动物中有很多是蛋生动物。", "explanation": "这里应该用〈卵生〉。“卵生”是动物学术语，指动物从卵里孵出来，不说“蛋生”。"}, {"text": "她去医院检查蛋巢，医生说一切正常。", "explanation": "这里应该用〈卵巢〉。“卵巢”是女性的器官，是固定名称，不说“蛋巢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈早上煮了三条蛋，给我们当早饭。", "corrected_sentence": "妈妈早上煮了三个蛋，给我们当早饭。", "error_description": "量词错误：“蛋”应用“个”或“颗”来计量，“条”用于鱼、蛇等细长的东西。正确说法是“三个蛋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天买了四个蛋们，全都吃完了。", "corrected_sentence": "我昨天买了四个蛋，全都吃完了。", "error_description": "词缀错误：“蛋”不指人，不能加“们”表示复数；应说“买了四个蛋”，不说“买了四个蛋们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93513, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93513, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93513, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "装饰是把东西弄得更漂亮，比如挂上彩带和小灯。", "primary_collocate": null, "pronunciation": "zhuāng shì", "ipa": "tʂwaŋ˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "我们用彩带装饰教室。", "target_word": "装饰", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈用小灯装饰圣诞树。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在门上挂彩带装饰房间。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年前，我们把家装饰得很漂亮。", "target_word": "装饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用气球和彩带装饰了舞台。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店门口装饰着红色的小灯。", "target_word": "装饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一些彩带来装饰房间。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生日那天，朋友们用花装饰了我的桌子。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用小灯把阳台装饰得像一座小花园。", "target_word": "装饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日快到了，学生们挂上小灯装饰校园。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "装饰了", "label": "体标"}, {"form": "装饰着", "label": "体标"}, {"form": "装饰过", "label": "体标"}, {"form": "装饰品", "label": "复合"}, {"form": "裝飾", "label": "繁体"}], "register": "中性", "sense_fingerprint": "挂彩带、小灯等，把地方或东西布置得更漂亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5996816f-6ae7-41cc-8154-694bc816de42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93513, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "装饰", "is_correct": true, "explanation": "正确：装饰 zhuāng shì，把东西弄得更漂亮，如挂彩带和小灯。"}, {"text": "壮士", "is_correct": false, "explanation": "zhuàng（第四声）与 zhuāng（第一声）声调不同，意思是勇士。"}, {"text": "专事", "is_correct": false, "explanation": "zhuān 与 zhuāng 韵母不同（an 与 ang），意思是专门做某件事。"}, {"text": "装置", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是机器设备。"}, {"text": "壮实", "is_correct": false, "explanation": "zhuàng（第四声）与 zhuāng（第一声）声调不同，意思是身体强壮结实。"}], "explanations": {"装饰": "正确：装饰 zhuāng shì，把东西弄得更漂亮，如挂彩带和小灯。", "壮士": "zhuàng（第四声）与 zhuāng（第一声）声调不同，意思是勇士。", "专事": "zhuān 与 zhuāng 韵母不同（an 与 ang），意思是专门做某件事。", "装置": "zhì 与 shì 声母不同（zh 与 sh），意思是机器设备。", "壮实": "zhuàng（第四声）与 zhuāng（第一声）声调不同，意思是身体强壮结实。"}, "sentence_index": null, "correct_answer": "装饰"}, "level_3": {"options": [{"text": "装饰", "is_correct": true, "explanation": "正确：“用彩带装饰教室”指用彩带把教室弄得更漂亮，句意相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”要用扫把、抹布等工具，不能说用彩带打扫教室。"}, {"text": "擦洗", "is_correct": false, "explanation": "语义：“擦洗”指用水和抹布除去污垢，与用彩带美化教室不合。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”是修复坏掉的东西，教室没有坏，与语境不合。"}], "explanations": {"装饰": "正确：“用彩带装饰教室”指用彩带把教室弄得更漂亮，句意相符。", "打扫": "搭配：“打扫”要用扫把、抹布等工具，不能说用彩带打扫教室。", "擦洗": "语义：“擦洗”指用水和抹布除去污垢，与用彩带美化教室不合。", "修理": "语义：“修理”是修复坏掉的东西，教室没有坏，与语境不合。"}, "sentence_index": 0, "correct_answer": "装饰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天装饰得很漂亮，像个小公主。", "explanation": "这里应该用〈打扮〉。装饰 多用于物品或场所；修饰人的外貌要用打扮。"}, {"text": "我们把房间装饰得很干净。", "explanation": "这里应该用〈收拾〉。装饰 强调美化，不指清洁；把房间弄干净要用收拾。"}, {"text": "他把坏了的椅子装饰得很结实。", "explanation": "这里应该用〈修理〉。装饰 不表示修复坏东西；修好椅子要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93513, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装饰", "is_correct": true, "explanation": "正确：“买一些彩带来装饰房间”指用彩带布置房间，句意相符。"}, {"text": "清洁", "is_correct": false, "explanation": "语义：“清洁”是去掉污垢，买彩带不能用来清洁房间。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：“粉刷”要用油漆或涂料刷墙面，不能说用彩带粉刷。"}, {"text": "收拾", "is_correct": false, "explanation": "语义：“收拾”是整理归位，与买彩带的目的不合。"}], "explanations": {"装饰": "正确：“买一些彩带来装饰房间”指用彩带布置房间，句意相符。", "清洁": "语义：“清洁”是去掉污垢，买彩带不能用来清洁房间。", "粉刷": "搭配：“粉刷”要用油漆或涂料刷墙面，不能说用彩带粉刷。", "收拾": "语义：“收拾”是整理归位，与买彩带的目的不合。"}, "sentence_index": 6, "correct_answer": "装饰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天装饰生病的孩子。", "explanation": "这里应该用〈照顾〉。装饰 的对象是物品或场所，不能用来指照顾人。"}, {"text": "医生装饰病人的伤口。", "explanation": "这里应该用〈治疗〉。装饰 不能用于人的伤口；治疗伤口要用治疗。"}, {"text": "老师装饰调皮的学生。", "explanation": "这里应该用〈教育〉。装饰 不表示教育或管教人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93513, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要用花把客厅装饰很漂亮。", "corrected_sentence": "我们要用花把客厅装饰得很漂亮。", "error_description": "错误：“装饰”后接补语“很漂亮”时漏掉了“得”。正确：“把客厅装饰得很漂亮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93513, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春节的时候，大家用红灯笼装饰得门口。", "corrected_sentence": "春节的时候，大家用红灯笼装饰门口。", "error_description": "错误：“装饰”后面不能直接加“得”。正确：去掉“得”，直接接宾语“门口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
