INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93514, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用饰物或图案使物体或环境更美观。", "primary_collocate": null, "pronunciation": "zhuāng shì", "ipa": "tʂwaŋ˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "她用花纹装饰杯子。", "target_word": "装饰", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "墙上的画装饰着整个客厅。", "target_word": "装饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在帽子上画了图案来装饰它。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆用中国结装饰墙面。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工匠在木门上刻出花纹来装饰它。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢用小石头装饰花盆。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间太空了，可以挂几张画装饰一下。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒店用金色的灯装饰大厅，看起来很漂亮。", "target_word": "装饰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用旧报纸和彩纸装饰自己的书桌。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在裙子的边上缝了花来装饰它。", "target_word": "装饰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "装饰了", "label": "体标"}, {"form": "装饰着", "label": "体标"}, {"form": "装饰过", "label": "体标"}, {"form": "装饰品", "label": "复合"}, {"form": "裝飾", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用饰物或图案点缀物体、环境，使之更美观", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5996816f-6ae7-41cc-8154-694bc816de42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93514, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "装饰", "is_correct": true, "explanation": "正确：装饰 zhuāng shì，用饰物或图案使物体或环境更美观。"}, {"text": "壮士", "is_correct": false, "explanation": "zhuàng（第四声）与 zhuāng（第一声）声调不同，意思是勇士。"}, {"text": "装置", "is_correct": false, "explanation": "第二音节声母不同（置 zhì 为 zh，饰 shì 为 sh），意思是设备、装置。"}, {"text": "专事", "is_correct": false, "explanation": "zhuān 与 zhuāng 韵母不同（an 与 ang），意思是专门做某件事。"}], "explanations": {"装饰": "正确：装饰 zhuāng shì，用饰物或图案使物体或环境更美观。", "壮士": "zhuàng（第四声）与 zhuāng（第一声）声调不同，意思是勇士。", "装置": "第二音节声母不同（置 zhì 为 zh，饰 shì 为 sh），意思是设备、装置。", "专事": "zhuān 与 zhuāng 韵母不同（an 与 ang），意思是专门做某件事。"}, "sentence_index": null, "correct_answer": "装饰"}, "level_3": {"options": [{"text": "装饰", "is_correct": true, "explanation": "正确：“用花纹装饰杯子”指用花纹使杯子更美观，句意相符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”要用布或纸去除污渍，不能说用花纹擦杯子。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修复破损，杯子没有破损，与句意不合。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”会破坏杯子，与“用花纹”使其美观的目的相反。"}], "explanations": {"装饰": "正确：“用花纹装饰杯子”指用花纹使杯子更美观，句意相符。", "擦": "搭配：“擦”要用布或纸去除污渍，不能说用花纹擦杯子。", "修": "语义：“修”是修复破损，杯子没有破损，与句意不合。", "打碎": "语义：“打碎”会破坏杯子，与“用花纹”使其美观的目的相反。"}, "sentence_index": 0, "correct_answer": "装饰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士用纱布装饰伤口。", "explanation": "这里应该用〈包扎〉。装饰 不指包裹伤口；包扎伤口要用包扎。"}, {"text": "他用抹布装饰玻璃。", "explanation": "这里应该用〈擦〉。装饰 是美化，不是去除污渍；擦玻璃要用擦。"}, {"text": "医生装饰病人的眼睛。", "explanation": "这里应该用〈检查〉。装饰 不指检查身体；看病人的眼睛要用检查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装饰", "is_correct": true, "explanation": "正确：“挂几张画装饰一下”指用画美化房间，句意相符。"}, {"text": "清洁", "is_correct": false, "explanation": "语义：“清洁”是去除污垢，挂画不能清洁房间。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”的对象应是场所或环境，不能以“画”作宾语。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”是补好破损，房间并没有破损，与句意不合。"}], "explanations": {"装饰": "正确：“挂几张画装饰一下”指用画美化房间，句意相符。", "清洁": "语义：“清洁”是去除污垢，挂画不能清洁房间。", "打扫": "配价：“打扫”的对象应是场所或环境，不能以“画”作宾语。", "修补": "语义：“修补”是补好破损，房间并没有破损，与句意不合。"}, "sentence_index": 6, "correct_answer": "装饰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用勺子装饰宝宝。", "explanation": "这里应该用〈喂〉。装饰 只用于物品或场所，不能用来指喂饭。"}, {"text": "司机装饰乘客的行李。", "explanation": "这里应该用〈搬〉。装饰 不表示搬运；搬行李要用搬。"}, {"text": "他总是装饰弟弟。", "explanation": "这里应该用〈欺负〉。装饰 不能指欺负人，且只用于物件或场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
