INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93516, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以工科专业为主的高等学校。", "primary_collocate": null, "pronunciation": "gōng yè dà xué", "ipa": "kʊŋ˥ jɛ˥˩ ta˥˩ ɕɥɛ˧˥", "syllable_count": 4, "sentences": [{"text": "工业大学以工科为主，文科专业很少。", "target_word": "工业大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所工业大学的工科专业很强。", "target_word": "工业大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在工业大学里，大多数学生学工科。", "target_word": "工业大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他报考了工业大学，因为想学电子工程。", "target_word": "工业大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业大学和综合大学不一样，专业比较集中。", "target_word": "工业大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多工程师毕业于工业大学。", "target_word": "工业大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所工业大学新建了一个机械学院。", "target_word": "工业大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐正在工业大学读研究生。", "target_word": "工业大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业大学今年多招了五百名学生。", "target_word": "工业大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明年我打算去工业大学读建筑专业。", "target_word": "工业大学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}], "register": "中性", "sense_fingerprint": "工业大学：以工科专业为主的高等学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53d5679f-77fa-4bf4-9eb8-f2e6cf29bb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业大学", "is_correct": true, "explanation": "工业大学以工科专业为主，与句中“以工科为主”一致。"}, {"text": "综合大学", "is_correct": false, "explanation": "语义：综合大学文理科都有，文科专业不会很少，与“文科专业很少”冲突。"}, {"text": "美术学院", "is_correct": false, "explanation": "语义：美术学院属于文科艺术类，不会以工科为主，与整句矛盾。"}, {"text": "中学", "is_correct": false, "explanation": "搭配：“以工科为主”是高等学校的办学特点，中学不说“以工科为主”。"}], "explanations": {"工业大学": "工业大学以工科专业为主，与句中“以工科为主”一致。", "综合大学": "语义：综合大学文理科都有，文科专业不会很少，与“文科专业很少”冲突。", "美术学院": "语义：美术学院属于文科艺术类，不会以工科为主，与整句矛盾。", "中学": "搭配：“以工科为主”是高等学校的办学特点，中学不说“以工科为主”。"}, "sentence_index": 0, "correct_answer": "工业大学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他报考了工业大学，因为想学舞蹈。", "explanation": "这里应该用〈舞蹈学院〉。工业大学以工科为主，学习舞蹈要去舞蹈学院。"}, {"text": "她报考了工业大学，因为想学绘画。", "explanation": "这里应该用〈艺术学院〉。工业大学以工科为主，学绘画要报考艺术学院。"}, {"text": "我姐姐在一所工业大学读研究生，专业是临床医学。", "explanation": "这里应该用〈医科大学〉。工业大学以工科为主，学习临床医学要去医科大学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工业大学", "is_correct": true, "explanation": "工业大学是以工科专业为主的高等学校，可以新建机械学院。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园是学前教育机构，不会设立机械学院，与句意冲突。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不设机械学院，“医院新建了一个机械学院”说不通。"}, {"text": "动物园", "is_correct": false, "explanation": "搭配：“机械学院”不是动物园的内设机构，“新建”与动物园不搭配。"}], "explanations": {"工业大学": "工业大学是以工科专业为主的高等学校，可以新建机械学院。", "幼儿园": "语义：幼儿园是学前教育机构，不会设立机械学院，与句意冲突。", "医院": "语义：医院不设机械学院，“医院新建了一个机械学院”说不通。", "动物园": "搭配：“机械学院”不是动物园的内设机构，“新建”与动物园不搭配。"}, "sentence_index": 6, "correct_answer": "工业大学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明年我打算去工业大学读医学专业。", "explanation": "这里应该用〈医科大学〉。工业大学以工科为主，学习医学要去医科大学。"}, {"text": "明年我打算去工业大学读钢琴专业。", "explanation": "这里应该用〈音乐学院〉。工业大学以工科为主，学习钢琴要去音乐学院。"}, {"text": "明年我打算去工业大学读体育专业。", "explanation": "这里应该用〈体育学院〉。工业大学以工科为主，学习体育要去体育学院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹在一家工业大学读研究生。", "corrected_sentence": "我妹妹在一所工业大学读研究生。", "error_description": "量词错误：“大学”应该用量词“所”，“家”多用于公司、商店等，“一家工业大学”是错误的，应改为“一所工业大学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位工业大学今年新建了一个实验中心。", "corrected_sentence": "这所工业大学今年新建了一个实验中心。", "error_description": "量词错误：“大学”应该用量词“所”，“位”用于人，不能说“这位工业大学”，应改为“这所工业大学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
