INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93517, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设有是那里已经准备好了某种东西。", "primary_collocate": null, "pronunciation": "shè yǒu", "ipa": "ʂɤ˥˩ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "每间教室都设有空调。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的房间里设有小冰箱。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶设有休息的椅子，累了可以坐。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站里设有免费的饮用水。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的路边设有垃圾桶。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里设有电视和书桌。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站设有电梯，老人很方便。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼里每层都设有洗手间。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边设有长椅，大家可以休息。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的两边设有路灯。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "某处事先备好了某种用品或设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81bc4bc-44c8-4cf6-a5b7-596f28b237e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93517, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "设有", "is_correct": true, "explanation": "正确：“设有”表示教室里配备了空调，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：空调不能被吃，“吃”不能接“空调”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”接“教室、房间”，不接“空调”这类设备。"}, {"text": "骑", "is_correct": false, "explanation": "语义：空调不能被骑，“骑”的对象是车或马。"}], "explanations": {"设有": "正确：“设有”表示教室里配备了空调，符合句意。", "吃": "语义：空调不能被吃，“吃”不能接“空调”。", "打扫": "搭配：“打扫”接“教室、房间”，不接“空调”这类设备。", "骑": "语义：空调不能被骑，“骑”的对象是车或马。"}, "sentence_index": 0, "correct_answer": "设有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我设有一台新电脑，很好用。", "explanation": "这里应该用〈有〉。“设有”用于场所备好的设备或设施，个人拥有物品要说“有”。"}, {"text": "我们设有一个新的计划，下个月开始执行。", "explanation": "这里应该用〈制订〉。“设有”指场所备好设施，不用于制定计划，制定计划要说“制订”。"}, {"text": "老师设有一次考试。", "explanation": "这里应该用〈进行〉。“设有”不用于考试这类活动，活动要说“进行”或“举办”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93517, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设有", "is_correct": true, "explanation": "正确：地铁站备有电梯，老人可以使用，与后句“很方便”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：电梯不能吃，“吃”不能接“电梯”。"}, {"text": "缺少", "is_correct": false, "explanation": "语义：“缺少”电梯与后句“老人很方便”的意思矛盾。"}, {"text": "排队", "is_correct": false, "explanation": "搭配：“排队”的对象是人，不说“排队电梯”。"}], "explanations": {"设有": "正确：地铁站备有电梯，老人可以使用，与后句“很方便”相符。", "吃": "语义：电梯不能吃，“吃”不能接“电梯”。", "缺少": "语义：“缺少”电梯与后句“老人很方便”的意思矛盾。", "排队": "搭配：“排队”的对象是人，不说“排队电梯”。"}, "sentence_index": 6, "correct_answer": "设有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈设有一只小猫，很可爱。", "explanation": "这里应该用〈养〉。“设有”指场所备有设施，不用于饲养动物。"}, {"text": "校长设有一次重要的演讲。", "explanation": "这里应该用〈安排〉。“设有”指设置机构或设备，不用于安排活动。"}, {"text": "奶奶设有一个有趣的故事。", "explanation": "这里应该用〈讲〉。“设有”不用于讲故事，故事是要说出来的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "图书馆的每层都设有有电脑。", "corrected_sentence": "图书馆的每层都设有电脑。", "error_description": "重复错误：“设有”本身已含“有”，后面不能再加“有”，应删去多余的“有”，说“设有电脑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼的每个房间都设有在空调。", "corrected_sentence": "这栋楼的每个房间都设有空调。", "error_description": "混用错误：“设有”后直接接宾语“空调”，不能加“在”；“在”属于“设在”，应删去，说“设有空调”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
