INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93518, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设置有；具有某种设施或机构。", "primary_collocate": null, "pronunciation": "shè yǒu", "ipa": "ʂɤ˥˩ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家医院设有急诊室。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校设有图书馆和体育馆。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在北京设有分公司。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园设有儿童游乐区。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府设有专门的办公室。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学设有中文系和历史系。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行设有二十四小时服务窗口。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市设有三个大型车站。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里设有免费的休息区。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里设有心理咨询中心。", "target_word": "设有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "单位或场所设置有某种机构或设施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81bc4bc-44c8-4cf6-a5b7-596f28b237e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "设有", "is_correct": true, "explanation": "正确：“设有”表示医院设置了急诊室这一部门，符合句意。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”的主体一般是人，医院不会“参观”科室。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”的对象不能是科室，说“欢迎急诊室”不通。"}, {"text": "办理", "is_correct": false, "explanation": "搭配：“办理”后接“手续、业务”，不接“急诊室”这类部门。"}], "explanations": {"设有": "正确：“设有”表示医院设置了急诊室这一部门，符合句意。", "参观": "语义：“参观”的主体一般是人，医院不会“参观”科室。", "欢迎": "语义：“欢迎”的对象不能是科室，说“欢迎急诊室”不通。", "办理": "搭配：“办理”后接“手续、业务”，不接“急诊室”这类部门。"}, "sentence_index": 0, "correct_answer": "设有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们设有三个孩子，都很可爱。", "explanation": "这里应该用〈有〉。“设有”用于机构、场所设置设施或部门，不用于人的家庭成员。"}, {"text": "他设有一场精彩的讲座，大家都很期待。", "explanation": "这里应该用〈举办〉。“设有”的主语要是机构或场所，个人办讲座要说“举办”。"}, {"text": "公司设有五名新员工。", "explanation": "这里应该用〈招聘〉。“设有”指设置机构或设施，不用于录用人员，公司招人要说“招聘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设有", "is_correct": true, "explanation": "正确：银行设置了二十四小时服务窗口，符合句意。"}, {"text": "进行", "is_correct": false, "explanation": "搭配：“进行”接“工作、活动”，不接“窗口”这类设施。"}, {"text": "喝", "is_correct": false, "explanation": "语义：窗口不能喝，“喝”的对象是饮料。"}, {"text": "了解", "is_correct": false, "explanation": "语义：“了解”的对象是情况、信息，不能说“了解服务窗口”。"}], "explanations": {"设有": "正确：银行设置了二十四小时服务窗口，符合句意。", "进行": "搭配：“进行”接“工作、活动”，不接“窗口”这类设施。", "喝": "语义：窗口不能喝，“喝”的对象是饮料。", "了解": "语义：“了解”的对象是情况、信息，不能说“了解服务窗口”。"}, "sentence_index": 6, "correct_answer": "设有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师设有丰富的教学经验。", "explanation": "这里应该用〈具备〉。“设有”指设置机构或设施，不用于能力或经验。"}, {"text": "他设有一套珍贵的邮票。", "explanation": "这里应该用〈收藏〉。“设有”只说机构或场所设置设施，不用于个人的收藏品。"}, {"text": "这位建筑师设有一座漂亮的房子。", "explanation": "这里应该用〈设计〉。“设有”不用于个人的设计工作，设计房子要说“设计”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区设有有健身房和游泳池。", "corrected_sentence": "这个小区设有健身房和游泳池。", "error_description": "重复错误：“设有”本身已含“有”，后面不能再加“有”，应删去多余的“有”，说“设有健身房和游泳池”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋大楼里设有在会议室和休息室。", "corrected_sentence": "这栋大楼里设有会议室和休息室。", "error_description": "混用错误：“设有”是固定词组，后面直接接宾语，不能加“在”；“在”属于“设在”，应删去，说“设有会议室和休息室”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
