INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93519, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工业学校是教人学做机器和工厂里的活儿的学校。", "primary_collocate": null, "pronunciation": "gōng yè xué xiào", "ipa": "kʊŋ˥ jɛ˥˩ ɕɥɛ˧˥ ɕjaʊ˥˩", "syllable_count": 4, "sentences": [{"text": "他中学毕业后去了一所工业学校。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业学校的学生要学开机器。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在工业学校学修机器。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所工业学校离我家很近。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业学校的老师常带学生去工厂。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想进工业学校，以后当工人。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业学校里有很多大机器。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸年轻时上过工业学校。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业学校的学生每天都在工厂里练习。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李从工业学校毕业后，进了一家工厂。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}], "register": "中性", "sense_fingerprint": "教人学机器和工厂工作的学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30121eb2-4bca-4011-9a89-398f42fd683f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93519, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业学校", "is_correct": true, "explanation": "工业学校教人学机器和工厂的活儿，中学毕业后去读它，与句意相符。"}, {"text": "小学", "is_correct": false, "explanation": "语义：小学在中学之前，与“中学毕业后”矛盾。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园比中学早，与“中学毕业后去了”矛盾。"}, {"text": "托儿所", "is_correct": false, "explanation": "语义：托儿所是学龄前儿童的看护机构，早于中学，与“中学毕业后去了”矛盾。"}], "explanations": {"工业学校": "工业学校教人学机器和工厂的活儿，中学毕业后去读它，与句意相符。", "小学": "语义：小学在中学之前，与“中学毕业后”矛盾。", "幼儿园": "语义：幼儿园比中学早，与“中学毕业后去了”矛盾。", "托儿所": "语义：托儿所是学龄前儿童的看护机构，早于中学，与“中学毕业后去了”矛盾。"}, "sentence_index": 0, "correct_answer": "工业学校"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在工业学校学种地。", "explanation": "这里应该用〈农业学校〉。工业学校教人学做机器和工厂里的活儿，学种地应去农业学校。"}, {"text": "她在工业学校学跳舞。", "explanation": "这里应该用〈舞蹈学校〉。工业学校教人学做机器和工厂里的活儿，学跳舞应去舞蹈学校。"}, {"text": "他在工业学校学写诗。", "explanation": "这里应该用〈艺术学校〉。工业学校教人学做机器和工厂里的活儿，学写诗不在这里学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93519, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工业学校", "is_correct": true, "explanation": "工业学校有机器和实习设备，与“里有很多大机器”相符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆里主要是书，不会有很多大机器。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店里主要是书，不会有很多大机器，与句意矛盾。"}, {"text": "学生", "is_correct": false, "explanation": "配价：“里”前应是处所名词，“学生”是人，不能作处所。"}], "explanations": {"工业学校": "工业学校有机器和实习设备，与“里有很多大机器”相符。", "图书馆": "语义：图书馆里主要是书，不会有很多大机器。", "书店": "语义：书店里主要是书，不会有很多大机器，与句意矛盾。", "学生": "配价：“里”前应是处所名词，“学生”是人，不能作处所。"}, "sentence_index": 6, "correct_answer": "工业学校"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在工业学校学烹饪。", "explanation": "这里应该用〈烹饪学校〉。工业学校教机器和工厂里的活儿，学烹饪应去烹饪学校。"}, {"text": "她在工业学校学习画画。", "explanation": "这里应该用〈艺术学校〉。工业学校教机器和工厂的活儿，学画画应去艺术学校。"}, {"text": "她在工业学校学习护理。", "explanation": "这里应该用〈护士学校〉。工业学校不教护理，学护理应去护士学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他高中毕业后考上了一位工业学校。", "corrected_sentence": "他高中毕业后考上了一所工业学校。", "error_description": "错误在量词。学校应用“所”，“位”只用于人，不能用于学校。错误形式“一位工业学校”应改为“一所工业学校”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想进所工业学校，以后当工人。", "corrected_sentence": "他想进一所工业学校，以后当工人。", "error_description": "错误在量词用法：量词“所”前要有数词或指示词，“进所工业学校”漏掉了“一”，应改为“进一所工业学校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
