INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "培养工业技术人才的中等职业学校。", "primary_collocate": null, "pronunciation": "gōng yè xué xiào", "ipa": "kʊŋ˥ jɛ˥˩ ɕɥɛ˧˥ ɕjaʊ˥˩", "syllable_count": 4, "sentences": [{"text": "这所工业学校培养了很多技术人才。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他初中毕业后考进了工业学校。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业学校是一种中等职业学校。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家需要工业学校培养技术工人。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在工业学校学了三年电工技术。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市有两所工业学校。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业学校的毕业生很容易找到工作。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我表弟想上工业学校，学一门技术。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工业学校和普通高中不一样，更重视技术。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从工业学校毕业，现在是技术员。", "target_word": "工业学校", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}], "register": "书面", "sense_fingerprint": "培养工业技术人才的中等职业学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30121eb2-4bca-4011-9a89-398f42fd683f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业学校", "is_correct": true, "explanation": "工业学校培养工业技术人才，与“培养了很多技术人才”相符。"}, {"text": "小学", "is_correct": false, "explanation": "语义：小学不以培养技术人才为主，与句意矛盾。"}, {"text": "博物馆", "is_correct": false, "explanation": "语义：博物馆不培养技术人才，与句意矛盾。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：量词“所”只用于机构，“这所老师”不成立，“老师”不是机构。"}], "explanations": {"工业学校": "工业学校培养工业技术人才，与“培养了很多技术人才”相符。", "小学": "语义：小学不以培养技术人才为主，与句意矛盾。", "博物馆": "语义：博物馆不培养技术人才，与句意矛盾。", "老师": "搭配：量词“所”只用于机构，“这所老师”不成立，“老师”不是机构。"}, "sentence_index": 0, "correct_answer": "工业学校"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在工业学校学医。", "explanation": "这里应该用〈卫生学校〉。工业学校培养工业技术人才，学医应去卫生学校。"}, {"text": "他在工业学校学外语。", "explanation": "这里应该用〈外国语学校〉。工业学校培养工业技术人才，学外语应去外国语学校。"}, {"text": "工业学校培养了很多画家。", "explanation": "这里应该用〈美术学院〉。工业学校培养工业技术人才，培养画家应去美术学院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工业学校", "is_correct": true, "explanation": "工业学校培养技术人才，其毕业生容易就业，与句意相符。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不培养学生，没有毕业生，句意不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是学校，没有毕业生，与句意矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“毕业生”指学校的学生，“石头”不能毕业，也不能说“石头的毕业生”。"}], "explanations": {"工业学校": "工业学校培养技术人才，其毕业生容易就业，与句意相符。", "公园": "语义：公园不培养学生，没有毕业生，句意不通。", "花园": "语义：花园不是学校，没有毕业生，与句意矛盾。", "石头": "搭配：“毕业生”指学校的学生，“石头”不能毕业，也不能说“石头的毕业生”。"}, "sentence_index": 6, "correct_answer": "工业学校"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在工业学校学钢琴。", "explanation": "这里应该用〈音乐学院〉。工业学校培养工业技术人才，学钢琴应去音乐学院。"}, {"text": "他在工业学校接受运动员训练。", "explanation": "这里应该用〈体育学校〉。工业学校培养工业技术人才，不培养运动员，接受运动员训练应去体育学校。"}, {"text": "她在工业学校学习教育学。", "explanation": "这里应该用〈师范学校〉。工业学校培养工业技术人才，学教育学应去师范学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位工业学校培养了很多技术工人。", "corrected_sentence": "那所工业学校培养了很多技术工人。", "error_description": "错误在量词。学校应用“所”，“位”只用于人，不能用于学校。错误形式“那位工业学校”应改为“那所工业学校”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从一位工业学校毕业后，成了技术员。", "corrected_sentence": "他从一所工业学校毕业后，成了技术员。", "error_description": "错误在量词。学校应用“所”，“位”只用于人，不能用于学校。错误形式“一位工业学校”应改为“一所工业学校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
