INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93521, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一首诗歌是分行写成、讲究节奏和韵律、读起来好听的一篇作品。", "primary_collocate": null, "pronunciation": "shī gē", "ipa": "ʂɻ̩˥ kɤ˥", "syllable_count": 2, "sentences": [{"text": "我每天晚上读一首诗歌。", "target_word": "诗歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗歌很短，也很好听。", "target_word": "诗歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在教室里学着念诗歌。", "target_word": "诗歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈常给我读诗歌。", "target_word": "诗歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的诗歌我都看过。", "target_word": "诗歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的诗歌写的是春天。", "target_word": "诗歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们背一首诗歌。", "target_word": "诗歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多好听的诗歌。", "target_word": "诗歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这首诗歌送给你。", "target_word": "诗歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的夜晚，他一个人写诗歌。", "target_word": "诗歌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "首", "label": "量词"}, {"form": "詩歌", "label": "繁体"}, {"form": "诗歌集", "label": "复合"}], "register": "中性", "sense_fingerprint": "分行写成、讲究节奏的一首诗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1163fc0d-9628-401a-8cdf-c361cf20c442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诗歌", "is_correct": true, "explanation": "诗歌是可以阅读的短文章，“读一首诗歌”自然，符合句意。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“读”的对象须是文字，“电视”不能读，也不能用“首”计量。"}, {"text": "舞曲", "is_correct": false, "explanation": "语义：舞曲是用来伴舞的乐曲，不能被“读”。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：报纸虽然可以读，但不能用量词“首”，应说“一份报纸”。"}], "explanations": {"诗歌": "诗歌是可以阅读的短文章，“读一首诗歌”自然，符合句意。", "电视": "搭配：“读”的对象须是文字，“电视”不能读，也不能用“首”计量。", "舞曲": "语义：舞曲是用来伴舞的乐曲，不能被“读”。", "报纸": "搭配：报纸虽然可以读，但不能用量词“首”，应说“一份报纸”。"}, "sentence_index": 0, "correct_answer": "诗歌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了一把诗歌。", "explanation": "这里量词用错。“把”用于有柄的器物，诗歌应用量词“首”计量。"}, {"text": "妈妈是一位很温柔的诗歌。", "explanation": "这里误用“诗歌”指人。诗歌是文学体裁，指写诗的人应说“诗人”。"}, {"text": "这首诗歌长得很矮。", "explanation": "这里把“诗歌”误当成有形体的生命。诗歌是抽象的文学体裁，“长得很矮”只能用于人或植物等有形体的生命，不能用于诗歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诗歌", "is_correct": true, "explanation": "“背一首诗歌”是常见说法，诗歌可以背诵，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“背”的对象须是可背诵的文字，“桌子”不能背诵。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是供观看的影像作品，不能被背诵。"}, {"text": "汤", "is_correct": false, "explanation": "语义：汤是食物，不能被背诵，句意不通。"}], "explanations": {"诗歌": "“背一首诗歌”是常见说法，诗歌可以背诵，符合句意。", "桌子": "搭配：“背”的对象须是可背诵的文字，“桌子”不能背诵。", "电影": "语义：电影是供观看的影像作品，不能被背诵。", "汤": "语义：汤是食物，不能被背诵，句意不通。"}, "sentence_index": 6, "correct_answer": "诗歌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上吃一首诗歌。", "explanation": "这里误用“诗歌”作食物的宾语。“吃”只用于食物，诗歌是文学作品，不能吃。"}, {"text": "她把这首诗歌戴在头上。", "explanation": "这里误用“诗歌”作饰物的宾语。“戴”只用于帽子、饰物等，诗歌不能戴在头上。"}, {"text": "他用诗歌修好了自行车。", "explanation": "这里误用“诗歌”作修理工具。修理的工具应是螺丝刀等实物，诗歌不能用来修车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天晚上都读一个诗歌。", "corrected_sentence": "我每天晚上都读一首诗歌。", "error_description": "量词错误：诗歌计量应用“首”，不能用“个”。正确说法是“一首诗歌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师请我们每人背一个诗歌。", "corrected_sentence": "老师请我们每人背一首诗歌。", "error_description": "量词错误：诗歌计量应用“首”，不能用“个”。正确说法是“一首诗歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
