INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93523, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年级是学校里按学了几年分开的班。", "primary_collocate": null, "pronunciation": "nián jí", "ipa": "ni̯ɛn˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我弟弟的年级比我低。", "target_word": "年级", "complexity_tier": "T3", "furigana": "nián jí", "sentence_source": "generated"}, {"text": "她和我是同一个年级的。", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在哪个年级？", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们年级有五个班。", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比我高一个年级。", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校有几个年级？", "target_word": "年级", "complexity_tier": "T3", "furigana": "nián jí", "sentence_source": "generated"}, {"text": "我们学校一共有六个年级。", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年级的老师都很忙。", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今年升入了新的年级。", "target_word": "年级", "complexity_tier": "T3", "furigana": "nián jí", "sentence_source": "generated"}, {"text": "我们年级的同学常常帮助我。", "target_word": "年级", "complexity_tier": "T3", "furigana": "nián jí", "sentence_source": "generated"}], "morphological_forms": [{"form": "高年级", "label": "复合"}, {"form": "低年级", "label": "复合"}, {"form": "年級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学校里按学习年数分的班", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2661f93-1077-4bd1-98fe-0202873548b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93523, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "年级", "is_correct": true, "explanation": "年级（nián jí）指学校里按学习年数划分的班次，与听到的读音一致。"}, {"text": "年纪", "is_correct": false, "explanation": "年纪（nián jì）与年级的第二音节声调不同：jì（第四声）与 jí（第二声），意思是年龄。"}, {"text": "连级", "is_correct": false, "explanation": "连级（lián jí）与年级的声母不同：l 与 n，意思是连队的级别。"}, {"text": "南极", "is_correct": false, "explanation": "南极（nán jí）与年级的第一音节只差一个介音：nán 没有 i，nián 有，意思是地球的南端。"}], "explanations": {"年级": "年级（nián jí）指学校里按学习年数划分的班次，与听到的读音一致。", "年纪": "年纪（nián jì）与年级的第二音节声调不同：jì（第四声）与 jí（第二声），意思是年龄。", "连级": "连级（lián jí）与年级的声母不同：l 与 n，意思是连队的级别。", "南极": "南极（nán jí）与年级的第一音节只差一个介音：nán 没有 i，nián 有，意思是地球的南端。"}, "sentence_index": null, "correct_answer": "年级"}, "level_3": {"options": [{"text": "年级", "is_correct": true, "explanation": "年级指学校里的班次，“我弟弟的年级比我低”符合句意。"}, {"text": "学期", "is_correct": false, "explanation": "语义：学期是一段时间，不能说“比我低”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字没有高低，不能说“名字比我低”。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是日期，只能说早晚，不能说“比我低”。"}], "explanations": {"年级": "年级指学校里的班次，“我弟弟的年级比我低”符合句意。", "学期": "语义：学期是一段时间，不能说“比我低”。", "名字": "语义：名字没有高低，不能说“名字比我低”。", "生日": "语义：生日是日期，只能说早晚，不能说“比我低”。"}, "sentence_index": 0, "correct_answer": "年级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我奶奶的年级很大了。", "explanation": "这里应该用〈年纪〉。年级指学校里的班次，说人的岁数要用年纪。"}, {"text": "这家饭店的年级很高。", "explanation": "这里应该用〈等级〉。年级指学校里的班次，说饭店的档次要用等级。"}, {"text": "这场比赛按难度分成了几个年级。", "explanation": "这里应该用〈级别〉。年级只用于学校的班次，比赛的分组不能说年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年级", "is_correct": true, "explanation": "年级指学校里的班次，“我们学校一共有六个年级”符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是学校的组成部分，学校没有“六个月亮”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人的岁数，学校没有“六个年龄”。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，不是学校的组成部分。"}], "explanations": {"年级": "年级指学校里的班次，“我们学校一共有六个年级”符合句意。", "月亮": "语义：月亮不是学校的组成部分，学校没有“六个月亮”。", "年龄": "语义：年龄指人的岁数，学校没有“六个年龄”。", "星期": "语义：星期是时间单位，不是学校的组成部分。"}, "sentence_index": 6, "correct_answer": "年级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我弟弟出生在2014年级。", "explanation": "这里应该用〈年份〉。年级指学校里的班次，不能表示出生的年份。"}, {"text": "这份合同的年级是三年。", "explanation": "这里应该用〈期限〉。年级不能用来说合同的时间长度。"}, {"text": "这门课是数学年级。", "explanation": "这里应该用〈学科〉。年级是学校里的班次，不是学科类别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校有四只年级。", "corrected_sentence": "我们学校有四个年级。", "error_description": "量词错误：年级应用“个”计数，“只”用于动物等，不能用来数年级。错误：我们学校有四只年级。正确：我们学校有四个年级。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们年级们有三个班。", "corrected_sentence": "我们年级有三个班。", "error_description": "词尾错误：“们”只用于指人的名词，“年级”不能加“们”。错误：我们年级们有三个班。正确：我们年级有三个班。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
