INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93524, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学校中按学习年限划分的班级。", "primary_collocate": null, "pronunciation": "nián jí", "ipa": "ni̯ɛn˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "小学的孩子按年级分班上课。", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个年级都有一个班长。", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读初中，年级比我高。", "target_word": "年级", "complexity_tier": "T3", "furigana": "nián jí", "sentence_source": "generated"}, {"text": "我女儿明年要进入新的年级。", "target_word": "年级", "complexity_tier": "T3", "furigana": "nián jí", "sentence_source": "generated"}, {"text": "这个年级的作业比较少。", "target_word": "年级", "complexity_tier": "T3", "furigana": "nián jí", "sentence_source": "generated"}, {"text": "今天全年级的学生去公园玩。", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年级的语文课在三楼。", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥比我低两个年级。", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，年级不同，书也不同。", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给每个年级发了新书。", "target_word": "年级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高年级", "label": "复合"}, {"form": "低年级", "label": "复合"}, {"form": "年級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学校按学习年限划分的班级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2661f93-1077-4bd1-98fe-0202873548b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93524, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "年级", "is_correct": true, "explanation": "年级（nián jí）指学校里按学习年限划分的班级，与听到的读音一致。"}, {"text": "年纪", "is_correct": false, "explanation": "年纪（nián jì）与年级的第二音节声调不同：jì（第四声）与 jí（第二声），意思是年龄。"}, {"text": "连级", "is_correct": false, "explanation": "连级（lián jí）与年级的声母不同：l 与 n，意思是连队的级别。"}, {"text": "南极", "is_correct": false, "explanation": "南极（nán jí）与年级的第一音节只差一个介音：nán 没有 i，nián 有，意思是地球的南端。"}], "explanations": {"年级": "年级（nián jí）指学校里按学习年限划分的班级，与听到的读音一致。", "年纪": "年纪（nián jì）与年级的第二音节声调不同：jì（第四声）与 jí（第二声），意思是年龄。", "连级": "连级（lián jí）与年级的声母不同：l 与 n，意思是连队的级别。", "南极": "南极（nán jí）与年级的第一音节只差一个介音：nán 没有 i，nián 有，意思是地球的南端。"}, "sentence_index": null, "correct_answer": "年级"}, "level_3": {"options": [{"text": "年级", "is_correct": true, "explanation": "年级指按学习年限划分的班级，“按年级分班”符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是学校分班的依据。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不是学校分班的标准。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“分班”通常按学习相关的标准进行，不说“按星期”。"}], "explanations": {"年级": "年级指按学习年限划分的班级，“按年级分班”符合句意。", "颜色": "语义：颜色不是学校分班的依据。", "体重": "语义：体重不是学校分班的标准。", "星期": "搭配：“分班”通常按学习相关的标准进行，不说“按星期”。"}, "sentence_index": 0, "correct_answer": "年级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姥姥的年级已经很大了。", "explanation": "这里应该用〈年纪〉。年级指学校的班次，说人的岁数要用年纪。"}, {"text": "小学和初中属于同一个年级。", "explanation": "这里应该用〈学段〉。学段指小学、初中、高中这样的教育阶段，年级只指同一学段中的某一学年。"}, {"text": "这场比赛按难度分成了几个年级。", "explanation": "这里应该用〈级别〉。年级只用于学校的班次，比赛的分组不能说年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年级", "is_correct": true, "explanation": "年级指学校里的班次，“这个年级的语文课”符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用来划分年级或课程，“这个颜色的语文课”说不通。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节不是划分课程的标准，“这个季节的语文课”说不通。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“尺寸”多用于物品，不修饰“语文课”。"}], "explanations": {"年级": "年级指学校里的班次，“这个年级的语文课”符合句意。", "颜色": "语义：颜色不能用来划分年级或课程，“这个颜色的语文课”说不通。", "季节": "语义：季节不是划分课程的标准，“这个季节的语文课”说不通。", "尺寸": "搭配：“尺寸”多用于物品，不修饰“语文课”。"}, "sentence_index": 6, "correct_answer": "年级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈出生在1975年级。", "explanation": "这里应该用〈年份〉。年级指学校里的班次，不能表示出生的年份。"}, {"text": "这次旅行的年级是三天。", "explanation": "这里应该用〈期限〉。年级不能用来说旅行的时长。"}, {"text": "这本书属于文学年级。", "explanation": "这里应该用〈类别〉。年级是学校的班次，不能用来划分书的类别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校有五只年级。", "corrected_sentence": "这所学校有五个年级。", "error_description": "量词错误：年级应用“个”计数，“只”用于动物等，不能用来数年级。错误：这所学校有五只年级。正确：这所学校有五个年级。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校给每个年级们买了新书。", "corrected_sentence": "学校给每个年级买了新书。", "error_description": "词尾错误：“们”只用于指人的名词，“年级”不能加“们”。错误：学校给每个年级们买了新书。正确：学校给每个年级买了新书。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
