INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在医院等处负责护理病人的医务人员。", "primary_collocate": null, "pronunciation": "hù shi", "ipa": "xu˥˩ ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "她在市医院当护士。", "target_word": "护士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士要先洗手，再给病人检查。", "target_word": "护士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的护士和医生都很忙。", "target_word": "护士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位护士工作了十年，很有经验。", "target_word": "护士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他妈妈是一名护士。", "target_word": "护士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士在医院里负责护理病人。", "target_word": "护士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里有两个护士在病房值班。", "target_word": "护士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士穿着白色的衣服。", "target_word": "护士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问护士，今天什么时候能出院。", "target_word": "护士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人感谢护士的照顾。", "target_word": "护士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "医院等处负责护理病人的医务人员，职业名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d775a5-892d-44cd-bef3-8500762883a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93526, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "护理", "is_correct": false, "explanation": "词性：“护理”是动作或学科名，不是职业名词，“当护理”不成立"}, {"text": "护士", "is_correct": true, "explanation": "“护士”是在市医院工作的职业，符合“当”的语境"}, {"text": "农民", "is_correct": false, "explanation": "语义：市医院与农民这个职业不相关，句子语境不通"}, {"text": "作家", "is_correct": false, "explanation": "语义：作家与医院工作不相关，句子语境不通"}], "explanations": {"护理": "词性：“护理”是动作或学科名，不是职业名词，“当护理”不成立", "护士": "“护士”是在市医院工作的职业，符合“当”的语境", "农民": "语义：市医院与农民这个职业不相关，句子语境不通", "作家": "语义：作家与医院工作不相关，句子语境不通"}, "sentence_index": 0, "correct_answer": "护士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位护士每天在体育馆教游泳，是我们的游泳老师。", "explanation": "这里应该用〈教练〉。“护士”指在医院护理病人的医务人员，不能指在体育馆教游泳的人"}, {"text": "他毕业后在书店当护士两年，每天卖书。", "explanation": "这里应该用〈店员〉。“护士”指医务人员，不能指在书店卖书的人"}, {"text": "我家旁边新开了一家护士，看病很方便。", "explanation": "这里应该用〈医院〉。“护士”指人，不是看病的地方，不能说“开了一家护士”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "司机", "is_correct": false, "explanation": "搭配：“值班”一般指医护人员在岗，司机不说“在病房值班”"}, {"text": "护士", "is_correct": true, "explanation": "“护士”是在病房值班的人员，符合句子语境"}, {"text": "花匠", "is_correct": false, "explanation": "语义：花匠与病房值班不相关，句子语境不通"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员不在病房值班，与句子语境不符"}], "explanations": {"司机": "搭配：“值班”一般指医护人员在岗，司机不说“在病房值班”", "护士": "“护士”是在病房值班的人员，符合句子语境", "花匠": "语义：花匠与病房值班不相关，句子语境不通", "演员": "语义：演员不在病房值班，与句子语境不符"}, "sentence_index": 6, "correct_answer": "护士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妹妹是护士，每天在工厂里装配汽车。", "explanation": "这里应该用〈工人〉。“护士”指医务人员，与在工厂装配汽车的工作相矛盾"}, {"text": "这位护士每天在厨房炒菜，是饭店的大厨。", "explanation": "这里应该用〈厨师〉。“护士”指医务人员，不能指在厨房炒菜的人"}, {"text": "这位护士每天在农田里种庄稼，很辛苦。", "explanation": "这里应该用〈农民〉。“护士”指医务人员，不能指在农田里种庄稼的人"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她毕业后就护士了。", "corrected_sentence": "她毕业后就当护士了。", "error_description": "动词缺失：“护士”是名词，前面要有动词“当”。应把“就护士了”改为“就当护士了”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位阿姨三十年前就护士了。", "corrected_sentence": "这位阿姨三十年前就当护士了。", "error_description": "动词缺失：“护士”是名词，表示担任该职业前面需要动词“当”。应把“就护士了”改为“就当护士了”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
