INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93528, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在假期中休息游玩。", "primary_collocate": null, "pronunciation": "dù jià", "ipa": "tu˥˩ tɕia˥˩", "syllable_count": 2, "sentences": [{"text": "夏天我们全家去海边度假。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每年冬天都去南方度假。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想在国外度假，不想在家。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下个月我打算度假一周。", "target_word": "度假", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们正在三亚度假，没有上班。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们去年去云南度假，玩得很开心。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作太累了，他想去山里度假。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人喜欢在海岛上度假。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们打算春节去北京度假。", "target_word": "度假", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板说，大家可以带着家人去度假。", "target_word": "度假", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "度了假", "label": "体标"}, {"form": "度过假", "label": "体标"}, {"form": "度假村", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，指利用假期到某地休息、游玩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe3a350-bc50-478f-b45d-f14fb4a51d8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93528, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "度假", "is_correct": true, "explanation": "正确：度假，dù jià，指在假期中休息游玩。"}, {"text": "独家", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）、jiā（第一声）与 jià（第四声）声调都不同，意思是独家。"}, {"text": "代价", "is_correct": false, "explanation": "dài 与 dù 只有韵母不同（ai 与 u），声调相同，意思是代价。"}, {"text": "地价", "is_correct": false, "explanation": "dì 与 dù 只有韵母不同（i 与 u），声调相同，意思是地价。"}], "explanations": {"度假": "正确：度假，dù jià，指在假期中休息游玩。", "独家": "dú（第二声）与 dù（第四声）、jiā（第一声）与 jià（第四声）声调都不同，意思是独家。", "代价": "dài 与 dù 只有韵母不同（ai 与 u），声调相同，意思是代价。", "地价": "dì 与 dù 只有韵母不同（i 与 u），声调相同，意思是地价。"}, "sentence_index": null, "correct_answer": "度假"}, "level_3": {"options": [{"text": "度假", "is_correct": true, "explanation": "度假指在假期中外出休息游玩，与“夏天全家去海边”的情境相符。"}, {"text": "上班", "is_correct": false, "explanation": "语义：上班指去单位工作，与全家夏天一起去海边放松的情境相反。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：考试要在考场进行，不能用“去海边”表示考试的地点。"}, {"text": "面试", "is_correct": false, "explanation": "语义：面试属于求职环节，与全家夏天去海边的休闲场景不符。"}], "explanations": {"度假": "度假指在假期中外出休息游玩，与“夏天全家去海边”的情境相符。", "上班": "语义：上班指去单位工作，与全家夏天一起去海边放松的情境相反。", "考试": "搭配：考试要在考场进行，不能用“去海边”表示考试的地点。", "面试": "语义：面试属于求职环节，与全家夏天去海边的休闲场景不符。"}, "sentence_index": 0, "correct_answer": "度假"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下个月学校度假一周，老师和学生都不用上课。", "explanation": "这里应该用〈放假〉。度假的主语应是个人，指个人离开日常生活去休息游玩；整个学校停课要用放假。"}, {"text": "他每天在工地度假，从早上干到晚上。", "explanation": "这里应该用〈打工〉。度假指假期中休息游玩，不是干活；在工地从早干到晚是打工。"}, {"text": "她在图书馆度假，每天准备期末考试。", "explanation": "这里应该用〈复习〉。度假指假期中休息游玩，不是在图书馆准备考试；准备考试应说复习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93528, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "度假", "is_correct": true, "explanation": "正确：度假，dù jià，指在假期中休息游玩。"}, {"text": "赌家", "is_correct": false, "explanation": "dǔ（第三声）与 dù（第四声）、jiā（第一声）与 jià（第四声）声调都不同，意思是赌徒。"}, {"text": "对价", "is_correct": false, "explanation": "duì 与 dù 只有韵母不同（ui 与 u），声调相同，意思是对价，即对等的代价。"}, {"text": "地价", "is_correct": false, "explanation": "dì 与 dù 只有韵母不同（i 与 u），声调相同，意思是地价。"}], "explanations": {"度假": "正确：度假，dù jià，指在假期中休息游玩。", "赌家": "dǔ（第三声）与 dù（第四声）、jiā（第一声）与 jià（第四声）声调都不同，意思是赌徒。", "对价": "duì 与 dù 只有韵母不同（ui 与 u），声调相同，意思是对价，即对等的代价。", "地价": "dì 与 dù 只有韵母不同（i 与 u），声调相同，意思是地价。"}, "sentence_index": null, "correct_answer": "度假"}, "level_3": {"options": [{"text": "度假", "is_correct": true, "explanation": "度假指离开工作去休息游玩，与“工作太累了，想去山里”的心情相符。"}, {"text": "加班", "is_correct": false, "explanation": "语义：加班是延长工作时间，与“工作太累了”想去休息的意思相反。"}, {"text": "上课", "is_correct": false, "explanation": "语义：上课是学习，与“工作太累了”后想去山里休息的意思不符。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：开学指学校学期开始，搭配的地点应是学校，不能说“去山里开学”。"}], "explanations": {"度假": "度假指离开工作去休息游玩，与“工作太累了，想去山里”的心情相符。", "加班": "语义：加班是延长工作时间，与“工作太累了”想去休息的意思相反。", "上课": "语义：上课是学习，与“工作太累了”后想去山里休息的意思不符。", "开学": "搭配：开学指学校学期开始，搭配的地点应是学校，不能说“去山里开学”。"}, "sentence_index": 6, "correct_answer": "度假"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子发烧了，我们带他去医院度假。", "explanation": "这里应该用〈看病〉。度假是去风景地休息游玩，不能去医院；去医院应说看病。"}, {"text": "他在考场上度假，一直低头答题。", "explanation": "这里应该用〈考试〉。度假指假期中休息游玩，不能用于考场答题；在考场答题应说考试。"}, {"text": "我每天早上都去公园度假。", "explanation": "这里应该用〈锻炼〉。度假指离开日常生活的较长假期，不能每天早上去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每年夏天都在海边度假着。", "corrected_sentence": "我们每年夏天都在海边度假。", "error_description": "错误：“着”不能直接接在离合词“度假”后面；此句应删去“着”，说“每年夏天都在海边度假”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去山里度假着，每天爬山。", "corrected_sentence": "他去山里度假，每天爬山。", "error_description": "错误：“着”不能直接接在离合词“度假”后面；带“着”时应插在中间，说“度着假”。此句应删去“着”，说“去山里度假”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c886c344-0829-4027-ba92-315db1a0543e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93529, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93529, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93529, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "这边是离说话的人近的那一边。", "primary_collocate": null, "pronunciation": "zhè biān", "ipa": "tʂɤ˥˩ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "这边是我的房间。", "target_word": "这边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你到这边来。", "target_word": "这边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这边的路比那边的宽。", "target_word": "这边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河这边有一家小商店。", "target_word": "这边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那边是你的，这边是我的。", "target_word": "这边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你看这边，那边太黑了。", "target_word": "这边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这边的椅子比那边的新。", "target_word": "这边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把书放到这边的桌子上。", "target_word": "这边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路这边有一棵很大的树。", "target_word": "这边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这边坐满了人，那边还有空位。", "target_word": "这边", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "這邊", "label": "繁体"}], "register": "口语", "sense_fingerprint": "离说话人近的一侧，常与那边相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5996816f-6ae7-41cc-8154-694bc816de42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93529, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "这边", "is_correct": true, "explanation": "正确答案。这边（zhè biān）指离说话人近的一侧，常与“那边”相对。"}, {"text": "这般", "is_correct": false, "explanation": "这般（zhè bān）与“这边”的韵母不同（少了介音 i），意思是“这样”，多用于书面语。"}, {"text": "折边", "is_correct": false, "explanation": "折边（zhé biān）与“这边”的第一个音节声调不同（zhé 第二声，zhè 第四声），意思是折叠衣物的边。"}, {"text": "这遍", "is_correct": false, "explanation": "这遍（zhè biàn）与“这边”的第二个音节声调不同（biàn 第四声，biān 第一声），意思是“这一次”。"}], "explanations": {"这边": "正确答案。这边（zhè biān）指离说话人近的一侧，常与“那边”相对。", "这般": "这般（zhè bān）与“这边”的韵母不同（少了介音 i），意思是“这样”，多用于书面语。", "折边": "折边（zhé biān）与“这边”的第一个音节声调不同（zhé 第二声，zhè 第四声），意思是折叠衣物的边。", "这遍": "这遍（zhè biàn）与“这边”的第二个音节声调不同（biàn 第四声，biān 第一声），意思是“这一次”。"}, "sentence_index": null, "correct_answer": "这边"}, "level_3": {"options": [{"text": "这边", "is_correct": true, "explanation": "正确答案。“这边”表示位置，可以作主语，与“我的房间”的所属关系相符。"}, {"text": "他", "is_correct": false, "explanation": "语义：“他”指人，“房间”不是人，“他是我的房间”说不通。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，句子变成疑问句，与陈述句“是我的房间”不符。"}, {"text": "因为", "is_correct": false, "explanation": "语法：“因为”是连词，不能作主语，“因为是我的房间”缺少主语。"}], "explanations": {"这边": "正确答案。“这边”表示位置，可以作主语，与“我的房间”的所属关系相符。", "他": "语义：“他”指人，“房间”不是人，“他是我的房间”说不通。", "谁": "语义：“谁”是疑问代词，句子变成疑问句，与陈述句“是我的房间”不符。", "因为": "语法：“因为”是连词，不能作主语，“因为是我的房间”缺少主语。"}, "sentence_index": 0, "correct_answer": "这边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那座山很高，它在河的这边，离我们很远。", "explanation": "这里应该用〈那边〉。“这边”指离说话人近的一侧，与“离我们很远”矛盾；远处的一侧要用“那边”。"}, {"text": "我昨天在商店买了这边。", "explanation": "这里应该用〈这个〉。“这边”只指方位，不能指代买的东西，要说“买了这个”。"}, {"text": "这边真好吃，你也尝尝。", "explanation": "这里应该用〈这个〉。“这边”只指方位，不能指代食物，要说“这个真好吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93529, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这边", "is_correct": true, "explanation": "正确答案。“这边的椅子”指这一侧的椅子，与后半句的“那边”相对。"}, {"text": "那边", "is_correct": false, "explanation": "语义：“那边”与后面的“那边”指同一个地方，自己和自己比较，句意不通。"}, {"text": "哪边", "is_correct": false, "explanation": "语义：“哪边”是疑问代词，放在陈述句里会变成疑问，与句子的陈述语气不符。"}, {"text": "那些", "is_correct": false, "explanation": "语法：“那些”后面要接名词，不能说“那些的椅子”。"}], "explanations": {"这边": "正确答案。“这边的椅子”指这一侧的椅子，与后半句的“那边”相对。", "那边": "语义：“那边”与后面的“那边”指同一个地方，自己和自己比较，句意不通。", "哪边": "语义：“哪边”是疑问代词，放在陈述句里会变成疑问，与句子的陈述语气不符。", "那些": "语法：“那些”后面要接名词，不能说“那些的椅子”。"}, "sentence_index": 6, "correct_answer": "这边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这边今年八岁了，很喜欢唱歌。", "explanation": "这里应该用〈他〉。“这边”指方位，不能作主语指代人。"}, {"text": "我很喜欢这边，所以买了两本。", "explanation": "这里应该用〈这本书〉。“这边”指方位，不能指代买的书。"}, {"text": "那个小岛远得看不清，它就在这边的海上。", "explanation": "这里应该用〈那边〉。“这边”指离说话人近的一侧，与“远得看不清”矛盾；远处的一侧要用“那边”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93529, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的伞这边。", "corrected_sentence": "我的伞在这边。", "error_description": "错误：表示位置时漏掉了动词“在”。正确：“我的伞在这边”，“在”要放在“这边”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93529, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这边得路很宽。", "corrected_sentence": "这边的路很宽。", "error_description": "错误：修饰名词“路”的结构助词应为“的”，不能用“得”。正确：“这边的路很宽”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
