INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93530, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指说话人所在的一方或附近的位置。", "primary_collocate": null, "pronunciation": "zhè biān", "ipa": "tʂɤ˥˩ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "我在这边等你。", "target_word": "这边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这边下雨了，你那边呢？", "target_word": "这边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这边的东西都很便宜。", "target_word": "这边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你来这边的时候给我打电话。", "target_word": "这边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们这边明天不上课。", "target_word": "这边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这边没有地铁，只能坐公共汽车。", "target_word": "这边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家在这边，你家在哪边？", "target_word": "这边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这边的天气很冷，你要多穿衣服。", "target_word": "这边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚搬到这边，不认识什么人。", "target_word": "这边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们这边的人喜欢吃辣的。", "target_word": "这边", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "這邊", "label": "繁体"}], "register": "口语", "sense_fingerprint": "说话人所在的地方或一方，相当于这里、我们这里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5996816f-6ae7-41cc-8154-694bc816de42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93530, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "这边", "is_correct": true, "explanation": "正确答案。这边（zhè biān）指说话人所在的地方，相当于“这里”。"}, {"text": "这般", "is_correct": false, "explanation": "这般（zhè bān）与“这边”的韵母不同（少了介音 i），意思是“这样”，多用于书面语。"}, {"text": "折边", "is_correct": false, "explanation": "折边（zhé biān）与“这边”的第一个音节声调不同（zhé 第二声，zhè 第四声），意思是折叠衣物的边。"}, {"text": "这遍", "is_correct": false, "explanation": "这遍（zhè biàn）与“这边”的第二个音节声调不同（biàn 第四声，biān 第一声），意思是“这一次”。"}], "explanations": {"这边": "正确答案。这边（zhè biān）指说话人所在的地方，相当于“这里”。", "这般": "这般（zhè bān）与“这边”的韵母不同（少了介音 i），意思是“这样”，多用于书面语。", "折边": "折边（zhé biān）与“这边”的第一个音节声调不同（zhé 第二声，zhè 第四声），意思是折叠衣物的边。", "这遍": "这遍（zhè biàn）与“这边”的第二个音节声调不同（biàn 第四声，biān 第一声），意思是“这一次”。"}, "sentence_index": null, "correct_answer": "这边"}, "level_3": {"options": [{"text": "这边", "is_correct": true, "explanation": "正确答案。“这边”表示地点，可以作介词“在”的宾语，与“等你”的语境相符。"}, {"text": "他", "is_correct": false, "explanation": "配价：“在”后面要接处所，“他”指人，不能作处所宾语，“我在他等你”说不通。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，句子变成疑问，与陈述句“等你”不符。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指一群人，不表示地点，与“在”后面的处所宾语相矛盾。"}], "explanations": {"这边": "正确答案。“这边”表示地点，可以作介词“在”的宾语，与“等你”的语境相符。", "他": "配价：“在”后面要接处所，“他”指人，不能作处所宾语，“我在他等你”说不通。", "谁": "语义：“谁”是疑问代词，句子变成疑问，与陈述句“等你”不符。", "大家": "语义：“大家”指一群人，不表示地点，与“在”后面的处所宾语相矛盾。"}, "sentence_index": 0, "correct_answer": "这边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想喝这边。", "explanation": "这里应该用〈这个〉。“这边”指方位，不能指代要喝的东西，要说“我想喝这个”。"}, {"text": "我的家人远在英国，他们就住在这边。", "explanation": "这里应该用〈那边〉。“这边”指说话人附近，与“远在英国”矛盾；远处的地方要用“那边”。"}, {"text": "这边很好看，我想买。", "explanation": "这里应该用〈这件〉。“这边”指地方，不能指代要买的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这边", "is_correct": true, "explanation": "正确答案。“我家在这边”指说话人这一侧，与后半句的“你家在哪边”相对。"}, {"text": "你", "is_correct": false, "explanation": "配价：“在”后面要接处所，“你”指人，“我家在你”说不通。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”指说话人自己，“我家在我”是同指矛盾，句意不通。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指人，不能表示地点，“我家在自己”句意不通。"}], "explanations": {"这边": "正确答案。“我家在这边”指说话人这一侧，与后半句的“你家在哪边”相对。", "你": "配价：“在”后面要接处所，“你”指人，“我家在你”说不通。", "我": "语义：“我”指说话人自己，“我家在我”是同指矛盾，句意不通。", "自己": "语义：“自己”指人，不能表示地点，“我家在自己”句意不通。"}, "sentence_index": 6, "correct_answer": "这边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这边今天生病了，没来上课。", "explanation": "这里应该用〈他〉。“这边”指地方，不能指代具体的人。"}, {"text": "这边一下子长大了，比我还高。", "explanation": "这里应该用〈他〉。“这边”指方位，不能作主语指代人，指人要用“他”。"}, {"text": "我把这边吃完了，一点都没剩。", "explanation": "这里应该用〈这个〉。“这边”指方位，不能指代食物，要说“把这个吃完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你的包这边。", "corrected_sentence": "你的包在这边。", "error_description": "错误：表示位置时漏掉了动词“在”。正确：“你的包在这边”，“在”要放在“这边”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这边得人都很友好。", "corrected_sentence": "这边的人都很友好。", "error_description": "错误：修饰名词“人”的结构助词应为“的”，不能用“得”。正确：“这边的人都很友好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
