INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93531, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "爱好者是特别喜欢做一件事的人。", "primary_collocate": null, "pronunciation": "ài hào zhě", "ipa": "ai̯˥˩ xaʊ̯˥˩ ʈ͡ʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他是一位音乐爱好者。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俱乐部有很多摄影爱好者。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小店里常有咖啡爱好者。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸是足球爱好者，每场比赛都看。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱好者们在公园里一起唱歌。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是个旅游爱好者，去过很多地方。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很受历史爱好者喜欢。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想认识更多读书爱好者。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步爱好者每天早上都来这里。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有个小组，里面都是画画爱好者。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "爱好者们", "label": "复数"}, {"form": "音乐爱好者", "label": "复合"}], "register": "中性", "sense_fingerprint": "特别喜欢某件事或某种东西的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06f273b2-8ada-4e9a-bf00-a5ca09e322b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93531, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱好者", "is_correct": true, "explanation": "爱好者指特别喜欢某事物的人，“一位音乐”之后接此词正合语境。"}, {"text": "作品", "is_correct": false, "explanation": "语义：作品是创作成果，不能指人，“他是一位音乐作品”不成立。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“一位”只用于计量人，乐器不能用“位”来数。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是记录音乐的书面材料，不能说“他是一位乐谱”。"}], "explanations": {"爱好者": "爱好者指特别喜欢某事物的人，“一位音乐”之后接此词正合语境。", "作品": "语义：作品是创作成果，不能指人，“他是一位音乐作品”不成立。", "乐器": "搭配：“一位”只用于计量人，乐器不能用“位”来数。", "乐谱": "语义：乐谱是记录音乐的书面材料，不能说“他是一位乐谱”。"}, "sentence_index": 0, "correct_answer": "爱好者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的爱好者每月发放全体员工的工资。", "explanation": "“爱好者”只表示出于兴趣的人，不表示负责发薪的管理者；这里应该用〈老板〉。"}, {"text": "这位经济学爱好者是大学讲师，每周讲课三次，领取固定工资。", "explanation": "“爱好者”只表示出于兴趣的人，不表示领固定工资的授课者；这里应该用〈讲师〉。"}, {"text": "这位爱好者明天起到市政府上班，担任副市长。", "explanation": "“爱好者”只表示出于兴趣的人，不表示任职的政府官员；这里应该用〈官员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93531, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱好者", "is_correct": true, "explanation": "爱好者指喜欢某事物的人，“受……喜欢”的对象正是这类人。"}, {"text": "历史书", "is_correct": false, "explanation": "语义：书不能喜欢书，“很受历史书喜欢”语义不通。"}, {"text": "历史人物", "is_correct": false, "explanation": "配价：“喜欢”的主语须是有感情的人，已故的历史人物无法喜欢这本书。"}, {"text": "历史博物馆", "is_correct": false, "explanation": "语义：博物馆是场所，不能作为喜欢书的主体。"}], "explanations": {"爱好者": "爱好者指喜欢某事物的人，“受……喜欢”的对象正是这类人。", "历史书": "语义：书不能喜欢书，“很受历史书喜欢”语义不通。", "历史人物": "配价：“喜欢”的主语须是有感情的人，已故的历史人物无法喜欢这本书。", "历史博物馆": "语义：博物馆是场所，不能作为喜欢书的主体。"}, "sentence_index": 6, "correct_answer": "爱好者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是职业电竞爱好者，每天训练十个小时。", "explanation": "“爱好者”只表示出于兴趣的人，与“职业”矛盾；职业运动员应说〈选手〉。"}, {"text": "他是这家俱乐部的足球爱好者，聘期三年，年薪很高。", "explanation": "“爱好者”不表示有聘期和薪水的职务；这里应该用〈教练〉。"}, {"text": "我们班的钢琴爱好者每节课收费三百元，学生很多。", "explanation": "“爱好者”不表示收费授课的职业身份；这里应该用〈老师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟是一位围棋爱好者们。", "corrected_sentence": "我弟弟是一位围棋爱好者。", "error_description": "“爱好者们”是复数形式，不能与数量词“一位”同用。单人应说“一位围棋爱好者”，多人可说“几位围棋爱好者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的表妹是一台美食爱好者。", "corrected_sentence": "她的表妹是一位美食爱好者。", "error_description": "错误形式：「一台美食爱好者」；正确形式：「一位美食爱好者」。“台”用于机器等物品，计量人要用“位”或“个”，这里应改为“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
