INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93532, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对某事物特别喜爱并经常从事的人。", "primary_collocate": null, "pronunciation": "ài hào zhě", "ipa": "ai̯˥˩ xaʊ̯˥˩ ʈ͡ʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这位爱好者每周都去爬山。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钓鱼爱好者带着鱼竿来到河边。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是电影爱好者，家里有很多电影碟。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位自行车爱好者正在比赛。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书法爱好者在这里练字。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一个舞蹈爱好者，每天都练舞。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店为茶叶爱好者准备了新茶。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是篮球爱好者，常和朋友打球。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏爱好者排队买新游戏。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是专家，只是一个植物爱好者。", "target_word": "爱好者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "爱好者们", "label": "复数"}, {"form": "电影爱好者", "label": "复合"}], "register": "中性", "sense_fingerprint": "对某事物特别喜爱并经常去做的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06f273b2-8ada-4e9a-bf00-a5ca09e322b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱好者", "is_correct": true, "explanation": "爱好者指对某事物特别喜爱并经常去做的人，与“每周都去爬山”相符。"}, {"text": "山", "is_correct": false, "explanation": "语义：山是地形，不能去爬山的主体，“这位山”不成立。"}, {"text": "文件", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能数文件，且文件不会去爬山。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能每周去爬山。"}], "explanations": {"爱好者": "爱好者指对某事物特别喜爱并经常去做的人，与“每周都去爬山”相符。", "山": "语义：山是地形，不能去爬山的主体，“这位山”不成立。", "文件": "搭配：量词“位”只用于人，不能数文件，且文件不会去爬山。", "窗户": "语义：窗户是建筑部件，不能每周去爬山。"}, "sentence_index": 0, "correct_answer": "爱好者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位自行车爱好者是车队签约的职业车手，每月领工资比赛。", "explanation": "“爱好者”只表示出于兴趣的人，不表示签约领薪的职业运动员；这里应该用〈选手〉。"}, {"text": "他是医院的一位爱好者，每天给病人做手术。", "explanation": "“爱好者”只表示兴趣，不表示职业身份；这里应该用〈医生〉。"}, {"text": "这位书法爱好者是我的上级，每天给我安排工作。", "explanation": "“爱好者”只表示出于兴趣的人，不表示有职务的人；这里应该用〈上级〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱好者", "is_correct": true, "explanation": "爱好者指喜爱茶叶的人，“为……准备”的对象应是这类人。"}, {"text": "茶壶", "is_correct": false, "explanation": "语义：茶壶是器具，不能作为接受“准备”的人，“为茶叶茶壶准备新茶”不通。"}, {"text": "茶杯", "is_correct": false, "explanation": "语义：茶杯是器具，不能被“为”引出作为服务对象。"}, {"text": "茶盘", "is_correct": false, "explanation": "搭配：“茶叶茶盘”不是常见组合，茶盘不能作为接受新茶的对象。"}], "explanations": {"爱好者": "爱好者指喜爱茶叶的人，“为……准备”的对象应是这类人。", "茶壶": "语义：茶壶是器具，不能作为接受“准备”的人，“为茶叶茶壶准备新茶”不通。", "茶杯": "语义：茶杯是器具，不能被“为”引出作为服务对象。", "茶盘": "搭配：“茶叶茶盘”不是常见组合，茶盘不能作为接受新茶的对象。"}, "sentence_index": 6, "correct_answer": "爱好者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是这家公司的爱好者，每天负责审批所有员工的报销。", "explanation": "“爱好者”只表示出于兴趣的人，不表示有审批权的管理者；这里应该用〈主管〉。"}, {"text": "他是被老师逼着学书法的爱好者，每次都很不情愿。", "explanation": "“爱好者”要求特别喜爱，不能用于被迫、不情愿的人；这里应该用〈学习者〉。"}, {"text": "这家店的咖啡爱好者只来过一次，之后再也没有来过。", "explanation": "“爱好者”要求经常从事某事，只来过一次不能称为爱好者；这里应该用〈顾客〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈是一只园艺爱好者。", "corrected_sentence": "我妈妈是一位园艺爱好者。", "error_description": "量词用错：“爱好者”指人，应用量词“位”，不能用“只”（“只”用于动物等），应写作“一位园艺爱好者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我表哥是一位摄影爱好者们。", "corrected_sentence": "我表哥是一位摄影爱好者。", "error_description": "“爱好者们”表示复数，不能与数量词“一位”同用。单人应说“一位摄影爱好者”，多人可说“几位摄影爱好者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
