INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93533, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "达人是对某件事特别会、特别厉害的人。", "primary_collocate": null, "pronunciation": "dá rén", "ipa": "ta˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "她很会找好吃的店，大家都说她是吃的达人。", "target_word": "达人", "complexity_tier": "T3", "furigana": "tā hěn huì zhǎo hǎo chī de diàn, dà jiā dōu shuō tā shì chī de dá rén.", "sentence_source": "generated"}, {"text": "小李是买东西的达人，总能找到便宜货。", "target_word": "达人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟是跳舞的达人，一听音乐就能跳。", "target_word": "达人", "complexity_tier": "T3", "furigana": "wǒ dì di shì tiào wǔ de dá rén, yì tīng yīn yuè jiù néng tiào.", "sentence_source": "generated"}, {"text": "我姐姐是订机票的达人，每次都能订到好位子。", "target_word": "达人", "complexity_tier": "T3", "furigana": "wǒ jiě jie shì dìng jī piào de dá rén, měi cì dōu néng dìng dào hǎo wèi zi.", "sentence_source": "generated"}, {"text": "这位达人教大家怎么做蛋糕。", "target_word": "达人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍的照片每张都好看，是拍照的达人。", "target_word": "达人", "complexity_tier": "T3", "furigana": "tā pāi de zhào piàn měi zhāng dōu hǎo kàn, shì pāi zhào de dá rén.", "sentence_source": "generated"}, {"text": "他是班里打游戏的达人，每次都能过关。", "target_word": "达人", "complexity_tier": "T3", "furigana": "tā shì bān lǐ dǎ yóu xì de dá rén, měi cì dōu néng guò guān.", "sentence_source": "generated"}, {"text": "她是收拾房间的达人，家里总是很干净。", "target_word": "达人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈是存钱的达人，每个月都能省下一些钱。", "target_word": "达人", "complexity_tier": "T3", "furigana": "wǒ mā ma shì cún qián de dá rén, měi gè yuè dōu néng shěng xià yì xiē qián.", "sentence_source": "generated"}, {"text": "这个达人会做二十多种面条。", "target_word": "达人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位达人", "label": "量词"}, {"form": "美食达人", "label": "复合"}, {"form": "摄影达人", "label": "复合"}], "register": "口语", "sense_fingerprint": "对某件事特别会、特别厉害的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8a7dd2-9f6a-4ef8-b570-0eaeae1a1cd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "达人", "is_correct": true, "explanation": "达人指在某件事上特别会、特别厉害的人，与“很会找好吃的店”的描述相符。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”含贬义，与“很会找好吃的店”的褒义评价冲突。"}, {"text": "老板", "is_correct": false, "explanation": "搭配：“吃的X”要求X是可以钻研或擅长的事或人，“老板”是职业身份，“吃的老板”不成立。"}, {"text": "演员", "is_correct": false, "explanation": "语义：“演员”指表演的人，与“找好吃的店”的语境无关，句意说不通。"}], "explanations": {"达人": "达人指在某件事上特别会、特别厉害的人，与“很会找好吃的店”的描述相符。", "小偷": "语义：“小偷”含贬义，与“很会找好吃的店”的褒义评价冲突。", "老板": "搭配：“吃的X”要求X是可以钻研或擅长的事或人，“老板”是职业身份，“吃的老板”不成立。", "演员": "语义：“演员”指表演的人，与“找好吃的店”的语境无关，句意说不通。"}, "sentence_index": 0, "correct_answer": "达人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妹妹第一次学游泳，连水都不敢下，却已经是游泳的达人了。", "explanation": "这里应该用〈新手〉。“达人”指特别会、特别厉害的人，刚学、还不敢下水的人要用“新手”。"}, {"text": "这位达人一次都没下过厨，连葱和蒜都分不清。", "explanation": "这里应该用〈外行〉。“达人”指特别会、特别厉害的人，连基本食材都分不清的人要用“外行”。"}, {"text": "这位达人被任命为市长，大家都很期待。", "explanation": "这里应该用〈领导〉。达人指在某件具体事情上特别拿手的人，被任命为职务、主持工作的人要用领导。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "达人", "is_correct": true, "explanation": "达人指在某件事上特别会、特别厉害的人，与“打游戏、每次都能过关”相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”指做菜的人，与“打游戏”“过关”的语境无关。"}, {"text": "歌手", "is_correct": false, "explanation": "搭配：“打游戏的X”要求X与游戏相关，“歌手”指唱歌的人，二者不能这样组合。"}, {"text": "护士", "is_correct": false, "explanation": "语义：“护士”指护理病人的人，与班里打游戏的语境不符。"}], "explanations": {"达人": "达人指在某件事上特别会、特别厉害的人，与“打游戏、每次都能过关”相符。", "厨师": "语义：“厨师”指做菜的人，与“打游戏”“过关”的语境无关。", "歌手": "搭配：“打游戏的X”要求X与游戏相关，“歌手”指唱歌的人，二者不能这样组合。", "护士": "语义：“护士”指护理病人的人，与班里打游戏的语境不符。"}, "sentence_index": 6, "correct_answer": "达人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位达人才学了两个月，连基本概念都还没弄清楚。", "explanation": "这里应该用〈初学者〉。“达人”指特别会、特别厉害的人，才学两个月、基本概念都不清的人要用“初学者”。"}, {"text": "这位达人第一次上场比赛，连基本动作都还不熟，就被淘汰了。", "explanation": "这里应该用〈参赛者〉。“达人”指特别会、特别厉害的人，第一次上场、动作都不熟的人要用“参赛者”。"}, {"text": "这位达人平时连账都算不清，却被派去负责公司的财务。", "explanation": "这里应该用〈外行〉。“达人”指特别会、特别厉害的人，账都算不清的人要用“外行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一只做饭的达人，朋友们都爱去她家吃饭。", "corrected_sentence": "她是一位做饭的达人，朋友们都爱去她家吃饭。", "error_description": "错误在量词：“达人”指人，量词应用“位”，“一只”多用于动物和小件物品。正确说法是“一位做饭的达人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹是跑步得达人，每天都跑五公里。", "corrected_sentence": "我妹妹是跑步的达人，每天都跑五公里。", "error_description": "错误在结构助词：“得”是补语标记，不能修饰名词“达人”，应用结构助词“的”。正确说法是“跑步的达人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
