INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93534, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93534, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在某一领域技艺高超、经验丰富的人。", "primary_collocate": null, "pronunciation": "dá rén", "ipa": "ta˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他是做木工的达人，做了三十年。", "target_word": "达人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位泡茶的达人，每次都能泡出好喝的茶。", "target_word": "达人", "complexity_tier": "T3", "furigana": "zhè wèi pào chá de dá rén, měi cì dōu néng pào chū hǎo hē de chá.", "sentence_source": "generated"}, {"text": "老张的花园里什么花都有，大家都叫他种花的达人。", "target_word": "达人", "complexity_tier": "T3", "furigana": "lǎo zhāng de huā yuán lǐ shén me huā dōu yǒu, dà jiā dōu jiào tā zhòng huā de dá rén.", "sentence_source": "generated"}, {"text": "她跑得很快，是长跑的达人。", "target_word": "达人", "complexity_tier": "T3", "furigana": "tā pǎo de hěn kuài, shì cháng pǎo de dá rén.", "sentence_source": "generated"}, {"text": "想学做蛋糕，就去请教烘焙的达人。", "target_word": "达人", "complexity_tier": "T3", "furigana": "xiǎng xué zuò dàn gāo, jiù qù qǐng jiào hōng bèi de dá rén.", "sentence_source": "generated"}, {"text": "这位修电器的达人已经干了二十年。", "target_word": "达人", "complexity_tier": "T3", "furigana": "zhè wèi xiū diàn qì de dá rén yǐ jīng gàn le èr shí nián.", "sentence_source": "generated"}, {"text": "电视里请来了一位练瑜伽的达人。", "target_word": "达人", "complexity_tier": "T3", "furigana": "diàn shì lǐ qǐng lái le yí wèi liàn yú jiā de dá rén.", "sentence_source": "generated"}, {"text": "他一听声音就知道哪里坏了，是修车的达人。", "target_word": "达人", "complexity_tier": "T3", "furigana": "tā yì tīng shēng yīn jiù zhī dào nǎ lǐ huài le, shì xiū chē de dá rén.", "sentence_source": "generated"}, {"text": "王老师是写毛笔字的达人，每个字都很漂亮。", "target_word": "达人", "complexity_tier": "T3", "furigana": "wáng lǎo shī shì xiě máo bǐ zì de dá rén, měi gè zì dōu hěn piào liang.", "sentence_source": "generated"}, {"text": "这个领域的达人都来参加了会议。", "target_word": "达人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位达人", "label": "量词"}, {"form": "茶艺达人", "label": "复合"}, {"form": "健身达人", "label": "复合"}], "register": "口语", "sense_fingerprint": "某一领域技艺高超、经验丰富的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8a7dd2-9f6a-4ef8-b570-0eaeae1a1cd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "达人", "is_correct": true, "explanation": "达人指在某一领域技艺高超、经验丰富的人，与“做木工”“做了三十年”相符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”指在学校求学的人，与“做了三十年”的经验描述矛盾。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：“做木工的X”要求X与木工相关，“司机”是驾驶职业，不能这样组合。"}, {"text": "游客", "is_correct": false, "explanation": "语义：“游客”指外出旅游的人，与长期从事木工的经验不符。"}], "explanations": {"达人": "达人指在某一领域技艺高超、经验丰富的人，与“做木工”“做了三十年”相符。", "学生": "语义：“学生”指在学校求学的人，与“做了三十年”的经验描述矛盾。", "司机": "搭配：“做木工的X”要求X与木工相关，“司机”是驾驶职业，不能这样组合。", "游客": "语义：“游客”指外出旅游的人，与长期从事木工的经验不符。"}, "sentence_index": 0, "correct_answer": "达人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "刚学做木工，还不会用刨子，却是做木工的达人。", "explanation": "这里应该用〈新手〉。“达人”指在某一领域技艺高超、经验丰富的人，刚入门、还不熟练的人要用“新手”。"}, {"text": "他字写得歪歪扭扭，却是书法的达人。", "explanation": "这里应该用〈爱好者〉。“达人”指技艺高超的人，只是喜欢、却并不精通的人要用“爱好者”。"}, {"text": "这位达人才来厂里三天，连基本工序都还没学会。", "explanation": "这里应该用〈学徒〉。“达人”指经验丰富、技艺高超的人，入行才三天、还在学工序的人要用“学徒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "达人", "is_correct": true, "explanation": "达人指在某一领域技艺高超、经验丰富的人，与“请来”的练瑜伽高手的语境相符。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”含贬义，电视节目不会请小偷做嘉宾，与“请来”的语境冲突。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“婴儿”不能自己练瑜伽，与“练瑜伽的”的描述不符。"}, {"text": "骗子", "is_correct": false, "explanation": "搭配：“请来”多用于请有专长或有名望的人，不说请“骗子”。"}], "explanations": {"达人": "达人指在某一领域技艺高超、经验丰富的人，与“请来”的练瑜伽高手的语境相符。", "小偷": "语义：“小偷”含贬义，电视节目不会请小偷做嘉宾，与“请来”的语境冲突。", "婴儿": "语义：“婴儿”不能自己练瑜伽，与“练瑜伽的”的描述不符。", "骗子": "搭配：“请来”多用于请有专长或有名望的人，不说请“骗子”。"}, "sentence_index": 6, "correct_answer": "达人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位达人还没有入门，刚刚拿到第一本教材。", "explanation": "这里应该用〈初学者〉。“达人”指在某一领域技艺高超、经验丰富的人，刚入门的人要用“初学者”。"}, {"text": "这位达人第一次进实验室，连仪器都不会开。", "explanation": "这里应该用〈实习生〉。“达人”指在某一领域技艺高超、经验丰富的人，刚进实验室、连仪器都不会开的人要用“实习生”。"}, {"text": "这位达人每次比赛都垫底，连基本动作都做不标准。", "explanation": "这里应该用〈参赛者〉。“达人”指技艺高超的人，比赛总是垫底、动作都做不标准的人要用“参赛者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是修钟表地达人，店里的客人很多。", "corrected_sentence": "她是修钟表的达人，店里的客人很多。", "error_description": "错误在结构助词：“地”修饰动词，不能修饰名词“达人”，应用“的”。正确说法是“修钟表的达人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位练瑜伽得达人每天教我们做动作。", "corrected_sentence": "这位练瑜伽的达人每天教我们做动作。", "error_description": "错误在结构助词：“得”不能修饰名词“达人”，应用“的”。正确说法是“练瑜伽的达人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
