INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93535, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "应市是东西做好了，拿到店里开始卖。", "primary_collocate": null, "pronunciation": "yìng shì", "ipa": "iŋ⁵¹ ʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "面包做好了，早上七点就应市。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的新蛋糕周末应市。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新鞋已经做好，明天就应市。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚做好的月饼，今天下午应市。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的新玩具马上要应市了。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天一到，新茶就应市了。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种冰淇淋夏天才应市。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新书印好后，下周一应市。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，新款酸奶下个月应市。", "target_word": "应市", "complexity_tier": "T3", "furigana": "lǎo bǎn shuō xīn kuǎn suān nǎi xià gè yuè yìng shì", "sentence_source": "generated"}, {"text": "这批饼干周三做好，周四就应市。", "target_word": "应市", "complexity_tier": "T3", "furigana": "zhè pī bǐng gān zhōu sān zuò hǎo zhōu sì jiù yìng shì", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "做好的东西开始上店出售", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbbcbc0-280a-4f0c-a3f1-46de88612a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93535, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应市", "is_correct": true, "explanation": "应市：做好的东西开始上店出售。"}, {"text": "影视", "is_correct": false, "explanation": "yǐng（第三声）与 yìng（第四声）声调不同，影视 指电影和电视。"}, {"text": "英式", "is_correct": false, "explanation": "yīng（第一声）与 yìng（第四声）声调不同，英式 指英国式的。"}, {"text": "影史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，影史 指电影的历史。"}, {"text": "英使", "is_correct": false, "explanation": "yīng（第一声）与 yìng（第四声）声调不同，英使 指英国派驻他国的使节。"}], "explanations": {"应市": "应市：做好的东西开始上店出售。", "影视": "yǐng（第三声）与 yìng（第四声）声调不同，影视 指电影和电视。", "英式": "yīng（第一声）与 yìng（第四声）声调不同，英式 指英国式的。", "影史": "shǐ（第三声）与 shì（第四声）声调不同，影史 指电影的历史。", "英使": "yīng（第一声）与 yìng（第四声）声调不同，英使 指英国派驻他国的使节。"}, "sentence_index": null, "correct_answer": "应市"}, "level_3": {"options": [{"text": "上映", "is_correct": false, "explanation": "搭配：“上映”用于影视作品，面包不能上映。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：面包不能毕业，与“面包做好了”的语境不合。"}, {"text": "应市", "is_correct": true, "explanation": "应市：做好的东西开始上店出售，与“面包做好了，早上七点就……”相合。"}, {"text": "放假", "is_correct": false, "explanation": "语义：面包不会放假，句子主语是面包，说不通。"}], "explanations": {"上映": "搭配：“上映”用于影视作品，面包不能上映。", "毕业": "语义：面包不能毕业，与“面包做好了”的语境不合。", "应市": "应市：做好的东西开始上店出售，与“面包做好了，早上七点就……”相合。", "放假": "语义：面包不会放假，句子主语是面包，说不通。"}, "sentence_index": 0, "correct_answer": "应市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "展览明天就要应市了。", "explanation": "这里应该用〈开幕〉。展览开始对外开放说开幕；“应市”只用于产品。"}, {"text": "这条高速明年应市。", "explanation": "这里应该用〈通车〉。道路建成开放交通说通车；“应市”不用于道路。"}, {"text": "新员工下周应市。", "explanation": "这里应该用〈上岗〉。人员开始工作说上岗；“应市”只用于产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开演", "is_correct": false, "explanation": "搭配：“开演”用于演出、戏剧，冰淇淋不能开演。"}, {"text": "应市", "is_correct": true, "explanation": "应市：做好的东西开始上店出售，与“夏天才”的季节语境相合。"}, {"text": "结业", "is_correct": false, "explanation": "语义：“结业”指学习或培训结束，冰淇淋不能结业。"}, {"text": "退休", "is_correct": false, "explanation": "语义：冰淇淋不会退休，与“夏天才”的语境不合。"}], "explanations": {"开演": "搭配：“开演”用于演出、戏剧，冰淇淋不能开演。", "应市": "应市：做好的东西开始上店出售，与“夏天才”的季节语境相合。", "结业": "语义：“结业”指学习或培训结束，冰淇淋不能结业。", "退休": "语义：冰淇淋不会退休，与“夏天才”的语境不合。"}, "sentence_index": 6, "correct_answer": "应市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新机场下月应市。", "explanation": "这里应该用〈启用〉。设施开始投入使用说启用；“应市”只用于产品。"}, {"text": "卫星下周应市。", "explanation": "这里应该用〈发射〉。卫星升空说发射；“应市”不用于卫星。"}, {"text": "这门课下学期应市。", "explanation": "这里应该用〈开课〉。课程开始上课说开课；“应市”不用于课程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新冰箱下周要就应市了。", "corrected_sentence": "新冰箱下周就要应市了。", "error_description": "语序错误：副词“就要”应放在动词“应市”前，说“下周就要应市了”；“要就”不是这样的副词搭配，应把“要就”改为“就要”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种点心从没应市了。", "corrected_sentence": "这种点心从没应市过。", "error_description": "了／过错用：“从没”表示从未有过的经历，应与“过”搭配，说“从没应市过”；“了”表示完成，与“从没”不搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
