INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93536, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（产品）投放市场出售。", "primary_collocate": null, "pronunciation": "yìng shì", "ipa": "iŋ⁵¹ ʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "新手机下个月就要应市了。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果每年六月应市。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新米刚收完，十月就应市了。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂家说，新车春天应市。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款饮料夏天应市，很受欢迎。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新茶还没应市，价格不便宜。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月饼一般中秋节前一个月应市。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了早点应市，工人们天天加班。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批新衣服什么时候应市？", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "螃蟹秋天应市，大家都想去买。", "target_word": "应市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "产品投放市场出售", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbbcbc0-280a-4f0c-a3f1-46de88612a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93536, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应市", "is_correct": true, "explanation": "应市：（产品）投放市场出售。"}, {"text": "影视", "is_correct": false, "explanation": "yǐng（第三声）与 yìng（第四声）声调不同，影视 指电影和电视。"}, {"text": "英式", "is_correct": false, "explanation": "yīng（第一声）与 yìng（第四声）声调不同，英式 指英国式的。"}, {"text": "影史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，影史 指电影的历史。"}, {"text": "英使", "is_correct": false, "explanation": "yīng（第一声）与 yìng（第四声）声调不同，英使 指英国派驻他国的使节。"}], "explanations": {"应市": "应市：（产品）投放市场出售。", "影视": "yǐng（第三声）与 yìng（第四声）声调不同，影视 指电影和电视。", "英式": "yīng（第一声）与 yìng（第四声）声调不同，英式 指英国式的。", "影史": "shǐ（第三声）与 shì（第四声）声调不同，影史 指电影的历史。", "英使": "yīng（第一声）与 yìng（第四声）声调不同，英使 指英国派驻他国的使节。"}, "sentence_index": null, "correct_answer": "应市"}, "level_3": {"options": [{"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”的主体须是人，手机不能结婚。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”用于书刊、音像制品，不用于手机。"}, {"text": "应市", "is_correct": true, "explanation": "应市：（产品）投放市场出售，与“新手机下个月就要……了”的语境相合。"}, {"text": "放假", "is_correct": false, "explanation": "语义：手机不会放假，与“新手机下个月就要……了”的语境不合。"}], "explanations": {"结婚": "语义：“结婚”的主体须是人，手机不能结婚。", "出版": "搭配：“出版”用于书刊、音像制品，不用于手机。", "应市": "应市：（产品）投放市场出售，与“新手机下个月就要……了”的语境相合。", "放假": "语义：手机不会放假，与“新手机下个月就要……了”的语境不合。"}, "sentence_index": 0, "correct_answer": "应市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部新电影下周就要应市了。", "explanation": "这里应该用〈上映〉。电影放映说上映；“应市”只用于产品投放市场。"}, {"text": "这家公司计划明年应市。", "explanation": "这里应该用〈上市〉。公司股票发行说上市；“应市”不用于公司。"}, {"text": "他下个月就要应市了。", "explanation": "这里应该用〈出差〉之类表示人的活动的词。“应市”只用于产品投放市场，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上映", "is_correct": false, "explanation": "搭配：“上映”用于电影等影视作品，月饼不能上映。"}, {"text": "失业", "is_correct": false, "explanation": "语义：月饼不会失业，与“月饼”的主体不合。"}, {"text": "应市", "is_correct": true, "explanation": "应市：（产品）投放市场出售，与“中秋节前一个月”的时间语境相合。"}, {"text": "结业", "is_correct": false, "explanation": "语义：“结业”指学习或培训结束，月饼不能结业。"}], "explanations": {"上映": "搭配：“上映”用于电影等影视作品，月饼不能上映。", "失业": "语义：月饼不会失业，与“月饼”的主体不合。", "应市": "应市：（产品）投放市场出售，与“中秋节前一个月”的时间语境相合。", "结业": "语义：“结业”指学习或培训结束，月饼不能结业。"}, "sentence_index": 6, "correct_answer": "应市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店明天应市。", "explanation": "这里应该用〈开业〉。店铺开张营业说开业；“应市”只用于产品。"}, {"text": "这座大楼明年应市。", "explanation": "这里应该用〈竣工〉。建筑完工说竣工；“应市”不用于建筑。"}, {"text": "这场比赛下周应市。", "explanation": "这里应该用〈举行〉。比赛、活动的开展说举行；“应市”不用于比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新款耳机下个月已经应市了。", "corrected_sentence": "新款耳机下个月就要应市了。", "error_description": "时间副词错用：“下个月”指将来，应与“就要……了”搭配；“已经”表示已经发生，与“下个月”矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款饮料明年应市过。", "corrected_sentence": "这款饮料明年应市。", "error_description": "了／过错用：“明年”指将来，“过”表示已发生的经历，二者矛盾；应去掉“过”，说“明年应市”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
