INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93537, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "长号是一种很长的铜管乐器，用嘴吹，拉一拉就能吹出不同的声音。", "primary_collocate": null, "pronunciation": "cháng hào", "ipa": "ʈʂʰɑŋ˧˥ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "弟弟昨天第一次吹长号。", "target_word": "长号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长号一拉，声音就变了。", "target_word": "长号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会上，长号的声音很低。", "target_word": "长号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女孩儿拿着长号站在台上。", "target_word": "长号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吹长号的时候，手要不停地动。", "target_word": "长号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在生日那天得到一支长号。", "target_word": "长号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸年轻时吹过长号。", "target_word": "长号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长号和小号都是铜管乐器。", "target_word": "长号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把长号放在椅子旁边。", "target_word": "长号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学长号比学小号难。", "target_word": "长号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "長號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用嘴吹、拉动管子变音的长形铜管乐器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d775a5-892d-44cd-bef3-8500762883a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93537, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长号", "is_correct": true, "explanation": "“吹”搭配靠气流发声的乐器，长号是用嘴吹的铜管乐器，正是答案。"}, {"text": "小提琴", "is_correct": false, "explanation": "搭配：小提琴靠拉弓发声，“吹”不能搭配小提琴，应说拉。"}, {"text": "吉他", "is_correct": false, "explanation": "搭配：吉他靠拨弦发声，不能说“吹吉他”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”不是可以吹奏的东西，“吹手机”说不通。"}], "explanations": {"长号": "“吹”搭配靠气流发声的乐器，长号是用嘴吹的铜管乐器，正是答案。", "小提琴": "搭配：小提琴靠拉弓发声，“吹”不能搭配小提琴，应说拉。", "吉他": "搭配：吉他靠拨弦发声，不能说“吹吉他”。", "手机": "语义：“手机”不是可以吹奏的东西，“吹手机”说不通。"}, "sentence_index": 0, "correct_answer": "长号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹妹在台上弹长号。", "explanation": "搭配：长号靠吹奏发声，不能说“弹”，应说“吹长号”。"}, {"text": "她有一张长号。", "explanation": "量词错误：长号的量词应为“把”或“支”，不能用“张”。"}, {"text": "哥哥在台上敲长号。", "explanation": "搭配：“敲”用于鼓、锣等打击乐器，长号要靠吹奏发声，应说“吹长号”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长号", "is_correct": true, "explanation": "“吹”搭配靠气流发声的乐器，长号是铜管乐器，正是答案。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“吹”只用于靠气流发声的乐器，钢琴靠击键发声，不能说吹钢琴。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不是能演奏的东西，“吹黑板”没有意义。"}, {"text": "唱片", "is_correct": false, "explanation": "搭配：唱片是播放的载体，不能用“吹”，“吹唱片”不是说法。"}], "explanations": {"长号": "“吹”搭配靠气流发声的乐器，长号是铜管乐器，正是答案。", "钢琴": "搭配：“吹”只用于靠气流发声的乐器，钢琴靠击键发声，不能说吹钢琴。", "黑板": "语义：黑板不是能演奏的东西，“吹黑板”没有意义。", "唱片": "搭配：唱片是播放的载体，不能用“吹”，“吹唱片”不是说法。"}, "sentence_index": 6, "correct_answer": "长号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸会打长号。", "explanation": "搭配：长号靠吹奏发声，不能说“打”，应说“吹长号”。"}, {"text": "我买了一面长号。", "explanation": "量词错误：长号的量词应为“把”或“支”，“面”用于鼓、镜子等平面的东西。"}, {"text": "她在台上唱长号给大家听。", "explanation": "搭配：“唱”用于人声，长号靠吹奏发声，不能说“唱”，应说“吹长号”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一面长号。", "corrected_sentence": "他有一把长号。", "error_description": "量词错误：长号用“把”或“支”计量，“面”用于鼓、镜子等平面的东西，不能用于长号。错误句中的“面”应改为“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给我买了一张长号。", "corrected_sentence": "妈妈给我买了一把长号。", "error_description": "量词错误：长号用“把”或“支”计量，“张”用于平面的东西，不能用于长号。错误句中的“张”应改为“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
