INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93539, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雨是从天上的云里掉下来的水滴。", "primary_collocate": null, "pronunciation": "yǔ", "ipa": "y²¹⁴", "syllable_count": 1, "sentences": [{"text": "天上的雨越下越大了，快去拿伞。", "target_word": "雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大，我们不去了。", "target_word": "雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市夏天雨很多。", "target_word": "雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下了一整天。", "target_word": "雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在雨里等朋友。", "target_word": "雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最爱春天的雨。", "target_word": "雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去公园时遇到了雨。", "target_word": "雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，雨还在下。", "target_word": "雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，快把衣服收进来。", "target_word": "雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云越来越黑，雨要来了。", "target_word": "雨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "雨水", "label": "复合"}, {"form": "雨伞", "label": "复合"}], "register": "中性", "sense_fingerprint": "从天上云里掉下来的水滴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1163fc0d-9628-401a-8cdf-c361cf20c442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93539, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雨", "is_correct": true, "explanation": "正确。雨 yǔ（第三声）指从天上云里掉下来的水滴。"}, {"text": "鱼", "is_correct": false, "explanation": "yú（第二声）与 yǔ（第三声）声调不同，意思是鱼。"}, {"text": "玉", "is_correct": false, "explanation": "yù（第四声）与 yǔ（第三声）声调不同，意思是玉石。"}, {"text": "女", "is_correct": false, "explanation": "nǚ 与 yǔ 声母不同（n 与 y），意思是女性。"}, {"text": "许", "is_correct": false, "explanation": "xǔ 与 yǔ 声母不同（x 与 y），意思是允许。"}], "explanations": {"雨": "正确。雨 yǔ（第三声）指从天上云里掉下来的水滴。", "鱼": "yú（第二声）与 yǔ（第三声）声调不同，意思是鱼。", "玉": "yù（第四声）与 yǔ（第三声）声调不同，意思是玉石。", "女": "nǚ 与 yǔ 声母不同（n 与 y），意思是女性。", "许": "xǔ 与 yǔ 声母不同（x 与 y），意思是允许。"}, "sentence_index": null, "correct_answer": "雨"}, "level_3": {"options": [{"text": "雨", "is_correct": true, "explanation": "正确。“下”与“雨”搭配，“越下越大”说的是雨越来越大。"}, {"text": "风", "is_correct": false, "explanation": "搭配：风说“刮”，不说“下”，“天上的风越下越大”不成立。"}, {"text": "烟", "is_correct": false, "explanation": "语义：烟不会从天上落下，“天上的烟越下越大”与常识矛盾。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星是天体，不会降落，与“越下越大”矛盾。"}], "explanations": {"雨": "正确。“下”与“雨”搭配，“越下越大”说的是雨越来越大。", "风": "搭配：风说“刮”，不说“下”，“天上的风越下越大”不成立。", "烟": "语义：烟不会从天上落下，“天上的烟越下越大”与常识矛盾。", "星星": "语义：星星是天体，不会降落，与“越下越大”矛盾。"}, "sentence_index": 0, "correct_answer": "雨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一朵雨下了很久。", "explanation": "这里应该用量词〈场〉。“朵”用于云、花等，不用于雨。"}, {"text": "地上结了一层雨，早上一出门就滑倒了。", "explanation": "这里应该用〈霜〉。“结一层”说的是霜，雨不会结成一层。"}, {"text": "碗里装满了雨，可以喝。", "explanation": "这里应该用〈水〉。雨是降落的现象，碗里装的、能喝的是水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93539, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "雨", "is_correct": true, "explanation": "正确。雨 yǔ（第三声）指从天上云里掉下来的水滴。"}, {"text": "举", "is_correct": false, "explanation": "jǔ 与 yǔ 声母不同（j 与 y），意思是举起。"}, {"text": "以", "is_correct": false, "explanation": "yǐ 与 yǔ 韵母不同（i 与 ü），意思是用、凭借。"}, {"text": "旅", "is_correct": false, "explanation": "lǚ 与 yǔ 声母不同（l 与 y），意思是旅行。"}, {"text": "余", "is_correct": false, "explanation": "yú（第二声）与 yǔ（第三声）声调不同，意思是剩余。"}, {"text": "取", "is_correct": false, "explanation": "qǔ 与 yǔ 声母不同（q 与 y），意思是拿、取。"}], "explanations": {"雨": "正确。雨 yǔ（第三声）指从天上云里掉下来的水滴。", "举": "jǔ 与 yǔ 声母不同（j 与 y），意思是举起。", "以": "yǐ 与 yǔ 韵母不同（i 与 ü），意思是用、凭借。", "旅": "lǚ 与 yǔ 声母不同（l 与 y），意思是旅行。", "余": "yú（第二声）与 yǔ（第三声）声调不同，意思是剩余。", "取": "qǔ 与 yǔ 声母不同（q 与 y），意思是拿、取。"}, "sentence_index": null, "correct_answer": "雨"}, "level_3": {"options": [{"text": "雨", "is_correct": true, "explanation": "正确。“遇到了雨”指在公园时碰上下雨，符合句意。"}, {"text": "大海", "is_correct": false, "explanation": "语义：公园里不会有大海，与“在公园”的场景矛盾。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是室内学习的地方，与“去公园”矛盾。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“遇到”后接的多是意外的人、事或天气，“遇到作业”在这里不自然。"}], "explanations": {"雨": "正确。“遇到了雨”指在公园时碰上下雨，符合句意。", "大海": "语义：公园里不会有大海，与“在公园”的场景矛盾。", "教室": "语义：教室是室内学习的地方，与“去公园”矛盾。", "作业": "搭配：“遇到”后接的多是意外的人、事或天气，“遇到作业”在这里不自然。"}, "sentence_index": 6, "correct_answer": "雨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窗玻璃上挂着许多雨。", "explanation": "这里应该用〈水滴〉。雨指从天上落下的现象，附着在玻璃上的是水滴。"}, {"text": "运动后，他的额头上全是雨。", "explanation": "这里应该用〈汗〉。雨来自天空，额头上流出的是汗。"}, {"text": "天空突然飘来一座雨，我们赶紧跑回了屋里。", "explanation": "这里应该用量词〈场〉。“座”用于山、桥、楼等大型固定物，不用于雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天的早晨下了一场的雨，空气很清新。", "corrected_sentence": "春天的早晨下了一场雨，空气很清新。", "error_description": "多余的“的”：“一场”后直接接“雨”，中间不能加“的”，应为“一场雨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈说，明天还会下一场雨大。", "corrected_sentence": "妈妈说，明天还会下一场大雨。", "error_description": "词序错误：“大”作定语应放在“雨”前，写成“一场雨大”不对，应为“一场大雨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
