INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93541, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "题材是写故事或画画时用来写、用来画的内容。", "primary_collocate": null, "pronunciation": "tí cái", "ipa": "tʰi˧˥ tsʰai˧˥", "syllable_count": 2, "sentences": [{"text": "我想写故事，可是没有题材。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们自己选画画的题材。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天找新的题材来画。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物是孩子们最爱的画画题材。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的题材很有意思。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的作文用了什么题材？", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在生活里找到了好题材。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画画常常选花做题材。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个题材太旧了，大家都写过。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先想一个题材，再开始写。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "通用", "sense_fingerprint": "写故事或画画时用的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168ad27f-59af-419a-aeff-3d9250db54ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93541, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "题材", "is_correct": true, "explanation": "题材指写故事或画画时用的内容，“没有题材”指想写的内容没有着落。"}, {"text": "画笔", "is_correct": false, "explanation": "语义：“画笔”是画画的工具，写故事用不到。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：“颜料”用于上色，与写故事无关。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“写故事”不需要“乐器”，二者不搭配。"}], "explanations": {"题材": "题材指写故事或画画时用的内容，“没有题材”指想写的内容没有着落。", "画笔": "语义：“画笔”是画画的工具，写故事用不到。", "颜料": "语义：“颜料”用于上色，与写故事无关。", "乐器": "搭配：“写故事”不需要“乐器”，二者不搭配。"}, "sentence_index": 0, "correct_answer": "题材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗的题材是七言律诗。", "explanation": "这里应该用〈体裁〉。七言律诗是诗的格律形式，属于体裁；题材指作品写的内容。"}, {"text": "这次数学考试的题材很难。", "explanation": "这里应该用〈题目〉。考试的题目才有难易之分，题材不用于考试。"}, {"text": "这本书的题材很长。", "explanation": "这里应该用〈篇幅〉。题材指作品写的内容，不说长短；书的长短要说“篇幅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93541, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "题材", "is_correct": true, "explanation": "题材指写作或画画的内容，“找到了好题材”说在生活中发现了可写可画的内容。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是日期，不是可以“找到”并用作素材的东西。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”说人的轻重，不能用来形容被找到的素材。"}, {"text": "学号", "is_correct": false, "explanation": "语义：“学号”是编号，不是创作素材。"}], "explanations": {"题材": "题材指写作或画画的内容，“找到了好题材”说在生活中发现了可写可画的内容。", "生日": "语义：“生日”是日期，不是可以“找到”并用作素材的东西。", "体重": "体貌：“体重”说人的轻重，不能用来形容被找到的素材。", "学号": "语义：“学号”是编号，不是创作素材。"}, "sentence_index": 6, "correct_answer": "题材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们先找一些题材，再开始做饭。", "explanation": "这里应该用〈材料〉。题材指写作或画画的内容，做饭用的原料要说“材料”。"}, {"text": "我们先想一个题材，再从孩子的题材来写。", "explanation": "这里应该用〈角度〉。题材指写作的内容，从孩子的视角来写要说“角度”。"}, {"text": "老师让我们先买一些题材，再开始画画。", "explanation": "这里应该用〈颜料〉。题材指画画的内容，画画要买的是颜料，应说“颜料”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找到了一只好题材。", "corrected_sentence": "我找到了一个好题材。", "error_description": "量词错误：“题材”应用量词“个”，“只”用于动物，不能修饰题材。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她写小说常常以爱情题材。", "corrected_sentence": "她写小说常常以爱情为题材。", "error_description": "结构错误：“以……为题材”中漏掉“为”，应说“以爱情为题材”，不能说“以爱情题材”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
