INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "文艺作品中所选取的、用以表现主题的材料。", "primary_collocate": null, "pronunciation": "tí cái", "ipa": "tʰi˧˥ tsʰai˧˥", "syllable_count": 2, "sentences": [{"text": "这部电影的题材很新。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家喜欢选择历史题材。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位导演擅长农村题材。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说的题材来自真实生活。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画以战争为题材。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现实题材的电视剧越来越受欢迎。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部作品题材重大，内容深刻。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者为新书选了一个好题材。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科幻题材的小说他读过很多。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗以思乡为题材。", "target_word": "题材", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "文艺作品选取的用来表现主题的材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168ad27f-59af-419a-aeff-3d9250db54ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "题材", "is_correct": true, "explanation": "题材指作品所选取的材料，“这部电影的题材很新”说所选材料新颖。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说贵贱高低，不能用“新”来形容。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”只说人或生物的岁数，不用于形容电影。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描述人的身体高矮，不能用来形容电影。"}], "explanations": {"题材": "题材指作品所选取的材料，“这部电影的题材很新”说所选材料新颖。", "价格": "搭配：“价格”说贵贱高低，不能用“新”来形容。", "年龄": "语义：“年龄”只说人或生物的岁数，不用于形容电影。", "身高": "体貌：“身高”描述人的身体高矮，不能用来形容电影。"}, "sentence_index": 0, "correct_answer": "题材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的题材很难。", "explanation": "这里应该用〈题目〉。考试的“题目”可以说难易，“题材”指作品所写的材料，不能用于考试。"}, {"text": "这部小说的题材是长篇小说。", "explanation": "这里应该用〈体裁〉。长篇小说是文体形式，属于体裁；题材指作品写的内容。"}, {"text": "这张桌子的题材是橡木。", "explanation": "这里应该用〈材料〉。题材指文艺作品所写的内容，做桌子的木料要说“材料”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "题材", "is_correct": true, "explanation": "题材指作品所写的材料，“题材重大”说题材范围广、分量大。"}, {"text": "作者", "is_correct": false, "explanation": "语义：“作者”指写作的人，不能用“重大”来修饰。"}, {"text": "色彩", "is_correct": false, "explanation": "搭配：“重大”修饰事件、影响、问题，不修饰色彩。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”是位置信息，作品没有地址可言。"}], "explanations": {"题材": "题材指作品所写的材料，“题材重大”说题材范围广、分量大。", "作者": "语义：“作者”指写作的人，不能用“重大”来修饰。", "色彩": "搭配：“重大”修饰事件、影响、问题，不修饰色彩。", "地址": "语义：“地址”是位置信息，作品没有地址可言。"}, "sentence_index": 6, "correct_answer": "题材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说的题材是对自由的追求。", "explanation": "这里应该用〈主题〉。题材指作品所写的材料，如历史、战争；作品表达的中心思想要说“主题”。"}, {"text": "这部小说的题材是简洁的风格。", "explanation": "这里应该用〈风格〉。题材指作品写的内容，“简洁”是语言风格，要说“风格”。"}, {"text": "这部电影的题材是跌宕起伏的情节。", "explanation": "这里应该用〈情节〉。题材指作品所写的内容范围，“跌宕起伏”形容的是故事的发展，要说“情节”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他选了一只历史题材。", "corrected_sentence": "他选了一个历史题材。", "error_description": "量词错误：“题材”应用量词“个”或“种”，“只”用于动物，不能修饰题材。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
