INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93543, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "臭", "is_correct": true, "explanation": "“臭”与“香”的气味相反，是“香”的反义词。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”说味道，不与“香”构成反义关系。"}, {"text": "软", "is_correct": false, "explanation": "“软”说质地，不是“香”的反义词。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”说光线或颜色，不与“香”构成反义关系。"}], "correct_answer": "臭", "explanations": {"臭": "“臭”与“香”的气味相反，是“香”的反义词。", "甜": "“甜”说味道，不与“香”构成反义关系。", "软": "“软”说质地，不是“香”的反义词。", "亮": "“亮”说光线或颜色，不与“香”构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
