INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93543, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "香是闻起来很好闻。", "primary_collocate": null, "pronunciation": "xiāng", "ipa": "ɕiɑŋ˥", "syllable_count": 1, "sentences": [{"text": "这朵花很香，你闻闻。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用了什么，身上这么香？", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的花开了，闻起来很香。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块肥皂闻起来真香。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的头发洗过以后很香。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这束百合很香，放在桌上吧。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的茶很香，你闻闻。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花不太香，可是很好看。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的花园里，花开得又香又美。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新洗的衣服闻起来很香。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "香香的", "label": "重叠"}, {"form": "香喷喷", "label": "复合"}], "register": "中性", "sense_fingerprint": "香：气味好闻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4240d01-219b-4bd2-9ad0-703dd789f62b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93543, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "香", "is_correct": true, "explanation": "香：xiāng（第一声），意思是气味好闻。"}, {"text": "想", "is_correct": false, "explanation": "想：xiǎng（第三声）与 xiāng（第一声）声调不同，意思是想念或想法。"}, {"text": "详", "is_correct": false, "explanation": "详：xiáng（第二声）与 xiāng（第一声）声调不同，意思是详细。"}, {"text": "星", "is_correct": false, "explanation": "星：xīng 与 xiāng 韵母不同（ing 与 iang），意思是星星。"}, {"text": "先", "is_correct": false, "explanation": "先：xiān 与 xiāng 韵母不同（ian 与 iang），意思是先后。"}], "explanations": {"香": "香：xiāng（第一声），意思是气味好闻。", "想": "想：xiǎng（第三声）与 xiāng（第一声）声调不同，意思是想念或想法。", "详": "详：xiáng（第二声）与 xiāng（第一声）声调不同，意思是详细。", "星": "星：xīng 与 xiāng 韵母不同（ing 与 iang），意思是星星。", "先": "先：xiān 与 xiāng 韵母不同（ian 与 iang），意思是先后。"}, "sentence_index": null, "correct_answer": "香"}, "level_3": {"options": [{"text": "香", "is_correct": true, "explanation": "正确：“香”说气味好闻，与“你闻闻”相合。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”说颜色，句中要的是气味，与“你闻闻”不合。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”说高度，与要人去闻的花不合。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”说质地，花不能用“很硬”来形容。"}], "explanations": {"香": "正确：“香”说气味好闻，与“你闻闻”相合。", "红": "语义：“红”说颜色，句中要的是气味，与“你闻闻”不合。", "高": "语义：“高”说高度，与要人去闻的花不合。", "硬": "搭配：“硬”说质地，花不能用“很硬”来形容。"}, "sentence_index": 0, "correct_answer": "香"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的字写得很香。", "explanation": "“香”指气味好闻，不能形容字迹；字写得好看要说“好看”或“工整”。"}, {"text": "这首歌很香，听起来很舒服。", "explanation": "“香”只形容气味，不能形容声音；这里应该用“好听”。"}, {"text": "这件衣服的颜色很香。", "explanation": "“香”不能形容颜色；这里应该用“鲜艳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93543, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "香", "is_correct": true, "explanation": "香：xiāng（第一声），意思是气味好闻。"}, {"text": "响", "is_correct": false, "explanation": "响：xiǎng（第三声）与 xiāng（第一声）声调不同，意思是声音大。"}, {"text": "降", "is_correct": false, "explanation": "降：xiáng（第二声）与 xiāng（第一声）声调不同，意思是下降。"}, {"text": "兴", "is_correct": false, "explanation": "兴：xīng 与 xiāng 韵母不同（ing 与 iang），意思是兴趣。"}, {"text": "鲜", "is_correct": false, "explanation": "鲜：xiān 与 xiāng 韵母不同（ian 与 iang），意思是新鲜。"}], "explanations": {"香": "香：xiāng（第一声），意思是气味好闻。", "响": "响：xiǎng（第三声）与 xiāng（第一声）声调不同，意思是声音大。", "降": "降：xiáng（第二声）与 xiāng（第一声）声调不同，意思是下降。", "兴": "兴：xīng 与 xiāng 韵母不同（ing 与 iang），意思是兴趣。", "鲜": "鲜：xiān 与 xiāng 韵母不同（ian 与 iang），意思是新鲜。"}, "sentence_index": null, "correct_answer": "香"}, "level_3": {"options": [{"text": "香", "is_correct": true, "explanation": "正确：“香”说气味好闻，与“你闻闻”相合。"}, {"text": "好看", "is_correct": false, "explanation": "语义：“好看”说外观，句中要的是气味，与“你闻闻”不合。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”说味道的刺激，茶不能用“很辣”让人去闻。"}, {"text": "脆", "is_correct": false, "explanation": "搭配：“脆”形容口感或易碎的东西，茶不能用“很脆”来形容。"}], "explanations": {"香": "正确：“香”说气味好闻，与“你闻闻”相合。", "好看": "语义：“好看”说外观，句中要的是气味，与“你闻闻”不合。", "辣": "语义：“辣”说味道的刺激，茶不能用“很辣”让人去闻。", "脆": "搭配：“脆”形容口感或易碎的东西，茶不能用“很脆”来形容。"}, "sentence_index": 6, "correct_answer": "香"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个垃圾桶很香，大家都爱闻。", "explanation": "语义矛盾：“香”说气味好闻，垃圾桶的气味应该用“臭”。"}, {"text": "他的心情很香。", "explanation": "“香”只形容气味，不能形容心情；这里应该用“愉快”。"}, {"text": "这个房间的温度很香。", "explanation": "“香”不能形容温度；这里应该用“暖和”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这束玫瑰香很，你闻闻。", "corrected_sentence": "这束玫瑰很香，你闻闻。", "error_description": "语序错误：程度副词“很”应放在形容词“香”的前面，应说“很香”，不能说“香很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这瓶香水很的香，你闻闻。", "corrected_sentence": "这瓶香水很香，你闻闻。", "error_description": "语法错误：程度副词“很”后不能直接加“的”，应说“很香”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
