INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93544, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "气味好闻；与“臭”相对。也指食物味道好。", "primary_collocate": null, "pronunciation": "xiāng", "ipa": "ɕiɑŋ˥", "syllable_count": 1, "sentences": [{"text": "这碗面很香，我想再吃一碗。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红烧肉做得真香。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜又香又辣。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的菜闻起来很香。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花是香的，垃圾是臭的。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种米饭很香，不放别的菜也好吃。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包刚做好，又香又软。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得妈妈做的饭最香。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵花比那朵更香。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个汤不够香，再放一点盐吧。", "target_word": "香", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "香香的", "label": "重叠"}, {"form": "香喷喷", "label": "复合"}], "register": "中性", "sense_fingerprint": "香：气味好闻，也指食物味道好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4240d01-219b-4bd2-9ad0-703dd789f62b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93544, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "香", "is_correct": true, "explanation": "香：xiāng（第一声），意思是气味好闻，也指食物味道好。"}, {"text": "响", "is_correct": false, "explanation": "响：xiǎng（第三声）与 xiāng（第一声）声调不同，意思是声音大。"}, {"text": "降", "is_correct": false, "explanation": "降：读 xiáng（第二声）时意思是投降，与 xiāng（第一声）声调不同。"}, {"text": "星", "is_correct": false, "explanation": "星：xīng 与 xiāng 韵母不同（ing 与 iang），意思是星星。"}, {"text": "心", "is_correct": false, "explanation": "心：xīn 与 xiāng 韵母不同（in 与 iang），意思是心脏或心情。"}, {"text": "鲜", "is_correct": false, "explanation": "鲜：xiān 与 xiāng 韵母不同（ian 与 iang），意思是新鲜。"}], "explanations": {"香": "香：xiāng（第一声），意思是气味好闻，也指食物味道好。", "响": "响：xiǎng（第三声）与 xiāng（第一声）声调不同，意思是声音大。", "降": "降：读 xiáng（第二声）时意思是投降，与 xiāng（第一声）声调不同。", "星": "星：xīng 与 xiāng 韵母不同（ing 与 iang），意思是星星。", "心": "心：xīn 与 xiāng 韵母不同（in 与 iang），意思是心脏或心情。", "鲜": "鲜：xiān 与 xiāng 韵母不同（ian 与 iang），意思是新鲜。"}, "sentence_index": null, "correct_answer": "香"}, "level_3": {"options": [{"text": "香", "is_correct": true, "explanation": "正确：“香”说食物味道好，与“想再吃一碗”相合。"}, {"text": "难吃", "is_correct": false, "explanation": "语义：“难吃”与“想再吃一碗”矛盾。"}, {"text": "脏", "is_correct": false, "explanation": "体貌：“脏”说外观，句中说的是味道，与“想再吃一碗”不合。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”说味道，与“想再吃一碗”的满意语气矛盾。"}], "explanations": {"香": "正确：“香”说食物味道好，与“想再吃一碗”相合。", "难吃": "语义：“难吃”与“想再吃一碗”矛盾。", "脏": "体貌：“脏”说外观，句中说的是味道，与“想再吃一碗”不合。", "苦": "语义：“苦”说味道，与“想再吃一碗”的满意语气矛盾。"}, "sentence_index": 0, "correct_answer": "香"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个声音听起来很香。", "explanation": "“香”说气味或食物味道，不能形容声音；这里应该用“好听”。"}, {"text": "这幅画的颜色很香。", "explanation": "“香”说气味或食物味道，不能形容颜色；这里应该用“鲜艳”。"}, {"text": "他这次考试考得很香。", "explanation": "“香”不能用来形容考试成绩；这里应该用“好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93544, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "香", "is_correct": true, "explanation": "香：xiāng（第一声），意思是气味好闻，也指食物味道好。"}, {"text": "想", "is_correct": false, "explanation": "想：xiǎng（第三声）与 xiāng（第一声）声调不同，意思是想念。"}, {"text": "详", "is_correct": false, "explanation": "详：xiáng（第二声）与 xiāng（第一声）声调不同，意思是详细。"}, {"text": "兴", "is_correct": false, "explanation": "兴：xīng 与 xiāng 韵母不同（ing 与 iang），意思是兴趣。"}, {"text": "先", "is_correct": false, "explanation": "先：xiān 与 xiāng 韵母不同（ian 与 iang），意思是先后。"}, {"text": "新", "is_correct": false, "explanation": "新：xīn 与 xiāng 韵母不同（in 与 iang），意思是新旧。"}], "explanations": {"香": "香：xiāng（第一声），意思是气味好闻，也指食物味道好。", "想": "想：xiǎng（第三声）与 xiāng（第一声）声调不同，意思是想念。", "详": "详：xiáng（第二声）与 xiāng（第一声）声调不同，意思是详细。", "兴": "兴：xīng 与 xiāng 韵母不同（ing 与 iang），意思是兴趣。", "先": "先：xiān 与 xiāng 韵母不同（ian 与 iang），意思是先后。", "新": "新：xīn 与 xiāng 韵母不同（in 与 iang），意思是新旧。"}, "sentence_index": null, "correct_answer": "香"}, "level_3": {"options": [{"text": "香", "is_correct": true, "explanation": "正确：“香”说食物味道好，与“又软”并列相合。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”与句中的“软”相反，并列起来自相矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "体貌：“亮”说光泽，句中说的是气味与口感，不合。"}, {"text": "冰", "is_correct": false, "explanation": "语义：“冰”说温度，刚做好的面包不是冰的。"}], "explanations": {"香": "正确：“香”说食物味道好，与“又软”并列相合。", "硬": "语义：“硬”与句中的“软”相反，并列起来自相矛盾。", "亮": "体貌：“亮”说光泽，句中说的是气味与口感，不合。", "冰": "语义：“冰”说温度，刚做好的面包不是冰的。"}, "sentence_index": 6, "correct_answer": "香"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯的光线很香。", "explanation": "“香”指气味或食物味道，不能形容光线；光线明亮应该用“亮”。"}, {"text": "这块布摸起来很香。", "explanation": "“香”只说气味或食物味道，不能形容触感；这里应该用“柔软”。"}, {"text": "这次旅行很香。", "explanation": "“香”不能形容活动或经历；这里应该用“愉快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这锅汤香很，闻起来不错。", "corrected_sentence": "这锅汤很香，闻起来不错。", "error_description": "语序错误：程度副词“很”应放在形容词“香”的前面，应说“很香”，不能说“香很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这碗粥很的香，我喝了两碗。", "corrected_sentence": "这碗粥很香，我喝了两碗。", "error_description": "语法错误：程度副词“很”后不能直接加“的”，应说“很香”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
