INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93546, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连接对举的两个方面中的一个，常与“另一方面”配合使用。", "primary_collocate": null, "pronunciation": "yì fāng miàn", "ipa": "i˥˩ fɑŋ˥ mjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "一方面要工作，另一方面要学习，他很累。", "target_word": "一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一方面表扬了他，另一方面也提了意见。", "target_word": "一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一方面是钱不够，另一方面是时间太少。", "target_word": "一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在城市，一方面方便，另一方面空气不好。", "target_word": "一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一方面很开心，另一方面又有点儿紧张。", "target_word": "一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一方面想买，另一方面觉得太贵了。", "target_word": "一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一方面他爱运动，另一方面他也爱看书。", "target_word": "一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法一方面省时间，另一方面省钱。", "target_word": "一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一方面高兴，另一方面有点儿担心。", "target_word": "一方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一方面你要听老师的，另一方面也要多想。", "target_word": "一方面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连接对举的两个方面，与另一方面配合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdffcdca-4576-4326-9e48-c5ba571a4003') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93546, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一方面", "is_correct": true, "explanation": "正确：“一方面”与后面的“另一方面”对举，说明他要做的两件事。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，句中是在并列两个方面，不是因果。"}, {"text": "不仅", "is_correct": false, "explanation": "搭配：“不仅”要与“而且/也”配合，不与“另一方面”成对。"}, {"text": "即使", "is_correct": false, "explanation": "语义：“即使”表示假设让步，与后面的“另一方面”的并列不相容。"}], "explanations": {"一方面": "正确：“一方面”与后面的“另一方面”对举，说明他要做的两件事。", "因此": "语义：“因此”表示结果，句中是在并列两个方面，不是因果。", "不仅": "搭配：“不仅”要与“而且/也”配合，不与“另一方面”成对。", "即使": "语义：“即使”表示假设让步，与后面的“另一方面”的并列不相容。"}, "sentence_index": 0, "correct_answer": "一方面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气很冷，一方面我们没去公园。", "explanation": "这里应该用〈因此〉。一方面只列出一个方面，不能表示结果。"}, {"text": "他一方面生病了，所以没来。", "explanation": "这里应该用〈因为〉。一方面只列出一个方面，不能引出原因。"}, {"text": "双方签约，一方面违约了。", "explanation": "这里应该用〈甲方〉。一方面指同一事物的一个层面，不能指双方中的一方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一方面", "is_correct": true, "explanation": "正确：“一方面”与后面的“另一方面”对举，分别说明他的两种爱好。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，句子是在并列两个方面，不是因果。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，句中没有前因后果，与“另一方面”不相配。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，后面应接“但/却”，与“另一方面”的并列不相容。"}], "explanations": {"一方面": "正确：“一方面”与后面的“另一方面”对举，分别说明他的两种爱好。", "因为": "语义：“因为”引出原因，句子是在并列两个方面，不是因果。", "所以": "语义：“所以”表示结果，句中没有前因后果，与“另一方面”不相配。", "尽管": "语义：“尽管”表示让步，后面应接“但/却”，与“另一方面”的并列不相容。"}, "sentence_index": 6, "correct_answer": "一方面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一方面你不来，我就走。", "explanation": "这里应该用〈如果〉。一方面不表示假设条件，只列出一个方面。"}, {"text": "一方面会唱歌，还会跳舞。", "explanation": "这里应该用〈不但〉。“一方面”只列出一个方面，不能表示递进。"}, {"text": "一方面下雨，我也去。", "explanation": "这里应该用〈即使〉。“一方面”不表示假设让步，只列出一个方面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一面爱读书，另一方面也爱旅行。", "corrected_sentence": "她一方面爱读书，另一方面也爱旅行。", "error_description": "错误：“一方面”写成了“一面”。“一面”与“另一方面”不能对举，应改为“一方面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事一面有好处，另一方面也有风险。", "corrected_sentence": "这件事一方面有好处，另一方面也有风险。", "error_description": "错误：第一项应用“一方面”，不能用“一面”。“一面”与“另一方面”不能对举。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
