INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93547, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "之内是在一个范围里面，没有出去。", "primary_collocate": null, "pronunciation": "zhī nèi", "ipa": "ʈʂɨ˥ nei̯˥˩", "syllable_count": 2, "sentences": [{"text": "请把车停在白线之内。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友只能在院子的范围之内玩。", "target_word": "之内", "complexity_tier": "T3", "furigana": "xiǎo péng yǒu zhǐ néng zài yuàn zi de fàn wéi zhī nèi wán.", "sentence_source": "generated"}, {"text": "所有的树都在围墙之内。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事在我的责任之内。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛只能在场地之内进行。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家留在警戒线之内。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题不在今天的讨论之内。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生只在校园范围之内活动。", "target_word": "之内", "complexity_tier": "T3", "furigana": "lǎo shī ràng xué shēng zhǐ zài xiào yuán fàn wéi zhī nèi huó dòng.", "sentence_source": "generated"}, {"text": "城墙之内有一座老庙。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作在公司规定之内。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "之内：在某个空间或范围的里面，没有超出边界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1163fc0d-9628-401a-8cdf-c361cf20c442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93547, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之内", "is_correct": true, "explanation": "正确。“在白线之内”表示车停在白线所界定的范围里面。"}, {"text": "根据", "is_correct": false, "explanation": "语义：“根据”表依据，不能指明停车的位置，与“停在白线”矛盾。"}, {"text": "关于", "is_correct": false, "explanation": "配价：“关于”引出话题，不能接在“停在白线”之后组成位置。"}, {"text": "按照", "is_correct": false, "explanation": "配价：“按照”需接依据或标准，后面不能直接接“白线”表示位置。"}], "explanations": {"之内": "正确。“在白线之内”表示车停在白线所界定的范围里面。", "根据": "语义：“根据”表依据，不能指明停车的位置，与“停在白线”矛盾。", "关于": "配价：“关于”引出话题，不能接在“停在白线”之后组成位置。", "按照": "配价：“按照”需接依据或标准，后面不能直接接“白线”表示位置。"}, "sentence_index": 0, "correct_answer": "之内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小狗跑出了院子之内，怎么也叫不回来。", "explanation": "这里应该用〈之外〉。“跑出”表示离开，离开的地方要说“之外”，“院子之内”与“跑出”矛盾。"}, {"text": "两国之内的关系一直很好。", "explanation": "这里应该用〈之间〉。两国的关系要说“之间”，“之内”表示在某个范围里面，不能用于两者的关系。"}, {"text": "他住在城市之内的一个小村子里，离市区很远。", "explanation": "这里应该用〈之外〉。“离市区很远”的小村子在城市范围外面，要说“城市之外”；“之内”表示在范围里面，与句意矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93547, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之内", "is_correct": true, "explanation": "正确。“不在今天的讨论之内”表示问题不属于讨论的范围。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表目的，不能表示范围，与“不在…的讨论”矛盾。"}, {"text": "对于", "is_correct": false, "explanation": "配价：“对于”引出对象，后面不能接“讨论”组成“不在…”的范围结构。"}, {"text": "通过", "is_correct": false, "explanation": "配价：“通过”需接方式或途径，不能用来表示“不在…的范围”。"}], "explanations": {"之内": "正确。“不在今天的讨论之内”表示问题不属于讨论的范围。", "为了": "语义：“为了”表目的，不能表示范围，与“不在…的讨论”矛盾。", "对于": "配价：“对于”引出对象，后面不能接“讨论”组成“不在…”的范围结构。", "通过": "配价：“通过”需接方式或途径，不能用来表示“不在…的范围”。"}, "sentence_index": 6, "correct_answer": "之内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的船已经驶出了港口之内。", "explanation": "这里应该用〈之外〉。“驶出”表示离开，离开的地方要说“之外”，“港口之内”与“驶出”矛盾。"}, {"text": "他离开了会场之内，大家却还在等他。", "explanation": "这里应该用〈之外〉。“离开”表示走出，走出的地方要说“之外”，“会场之内”与“离开”矛盾。"}, {"text": "孩子们走出了校园之内，去对面的书店买书。", "explanation": "这里应该用〈之外〉。“走出”表示离开，离开的地方要说“之外”，“校园之内”与“走出”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们都在院子的之内玩耍。", "corrected_sentence": "孩子们都在院子之内玩耍。", "error_description": "多余的“的”：“院子之内”是方位短语，“之内”前不能加“的”，应为“院子之内”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "所有的工具都要收在柜子的之内。", "corrected_sentence": "所有的工具都要收在柜子之内。", "error_description": "多余的“的”：“柜子之内”是方位短语，“之内”前不能加“的”，应为“柜子之内”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
