INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93548, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "在一定范围、时间或数量的里面。", "primary_collocate": null, "pronunciation": "zhī nèi", "ipa": "ʈʂɨ˥ nei̯˥˩", "syllable_count": 2, "sentences": [{"text": "三天之内我一定回信。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在一周之内交作业。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服一百元之内能买到。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十分钟之内他就到家了。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年之内我要学会游泳。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五公里之内都有地铁站。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的预算要在两千元之内。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试时间在一小时之内。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个月之内他瘦了十斤。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一公里之内没有超市。", "target_word": "之内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "之内：在某个时间、数量或距离的限度以内，不超过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1163fc0d-9628-401a-8cdf-c361cf20c442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之内", "is_correct": true, "explanation": "正确。“三天之内”表示在三天的时限里面，符合句意。"}, {"text": "按照", "is_correct": false, "explanation": "配价：“按照”需接依据或标准，不能表示时间限度，“三天按照我一定回信”不通。"}, {"text": "关于", "is_correct": false, "explanation": "配价：“关于”引出话题，不能直接接“三天”表示期限。"}, {"text": "通过", "is_correct": false, "explanation": "语义：“通过”表方式或途径，与时间期限无关，与句意矛盾。"}], "explanations": {"之内": "正确。“三天之内”表示在三天的时限里面，符合句意。", "按照": "配价：“按照”需接依据或标准，不能表示时间限度，“三天按照我一定回信”不通。", "关于": "配价：“关于”引出话题，不能直接接“三天”表示期限。", "通过": "语义：“通过”表方式或途径，与时间期限无关，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "之内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃饭之内我们去散步。", "explanation": "这里应该用〈之后〉。吃完饭以后的时间要说“之后”，“之内”表示时限里面。"}, {"text": "下午三点之内我们开会。", "explanation": "这里应该用〈之前〉。“之内”表示一段时间的范围，“三点”是时间点，要说“三点之前”。"}, {"text": "从明天之内我们开始练习。", "explanation": "这里应该用〈起〉。“之内”表示范围，不能与“从……开始”搭配表示起点，应说“从明天起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之内", "is_correct": true, "explanation": "正确。“两千元之内”表示预算不超过两千元，符合句意。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表目的，不能表示数额的限度，与“预算”无关。"}, {"text": "对于", "is_correct": false, "explanation": "配价：“对于”引出对象，不能接在“两千元”后表示数额限度。"}, {"text": "依照", "is_correct": false, "explanation": "配价：“依照”需接依据，不能表示数额的限度，“两千元依照”不通。"}], "explanations": {"之内": "正确。“两千元之内”表示预算不超过两千元，符合句意。", "为了": "语义：“为了”表目的，不能表示数额的限度，与“预算”无关。", "对于": "配价：“对于”引出对象，不能接在“两千元”后表示数额限度。", "依照": "配价：“依照”需接依据，不能表示数额的限度，“两千元依照”不通。"}, "sentence_index": 6, "correct_answer": "之内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下课之内我们要交作业。", "explanation": "这里应该用〈之前〉。“下课”是时间点，不是一段时间的限度，要说“下课之前”；“之内”后面需接一段时间。"}, {"text": "毕业之内他去了北京。", "explanation": "这里应该用〈以后〉。毕业以后的时间要说“以后”，“之内”表示限度里面。"}, {"text": "从九月之内开始放假。", "explanation": "这里应该用〈起〉。“之内”表示范围，不能表示起点；“从九月”开始要说“从九月起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
