INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情（口语）。", "primary_collocate": null, "pronunciation": "shìr", "ipa": "ʂɚ˥˩", "syllable_count": 1, "sentences": [{"text": "你今天有什么事儿?", "target_word": "事儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这事儿不难,我来做吧。", "target_word": "事儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别管我的事儿。", "target_word": "事儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有点儿事儿,先走了。", "target_word": "事儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都有很多事儿要做。", "target_word": "事儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事儿你别告诉别人。", "target_word": "事儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出什么事儿了?", "target_word": "事儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这事儿我自己能处理，不用麻烦你。", "target_word": "事儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是爱管别人的事儿。", "target_word": "事儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的事儿,你还记得吗?", "target_word": "事儿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "事兒", "label": "繁体"}], "register": "口语", "sense_fingerprint": "口语里指事情、要办的事或麻烦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d775a5-892d-44cd-bef3-8500762883a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事儿", "is_correct": true, "explanation": "“有什么”后接可以有或会发生的事情，口语中指事情、要办的事，正是“事儿”。"}, {"text": "大象", "is_correct": false, "explanation": "语义：“大象”是动物，“今天有什么大象”不指事情，句子说不通。"}, {"text": "今年", "is_correct": false, "explanation": "语义：“今年”是时间词，不是要办的事情，“有什么今年”说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“有什么”后接事情，“钢琴”不是事情，“有什么钢琴”说不通。"}], "explanations": {"事儿": "“有什么”后接可以有或会发生的事情，口语中指事情、要办的事，正是“事儿”。", "大象": "语义：“大象”是动物，“今天有什么大象”不指事情，句子说不通。", "今年": "语义：“今年”是时间词，不是要办的事情，“有什么今年”说不通。", "钢琴": "语义：“有什么”后接事情，“钢琴”不是事情，“有什么钢琴”说不通。"}, "sentence_index": 0, "correct_answer": "事儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有一台事儿要办。", "explanation": "量词错误：“事儿”的量词应为“件”，“台”用于机器等，不能用于事情。"}, {"text": "他把那件事儿吃掉了。", "explanation": "搭配：“吃”的对象是食物等可以吃的东西，事情应说“办”或“处理”，不能说“吃掉”。"}, {"text": "他把那件事儿修好了。", "explanation": "搭配：“修”用于修理有形之物或修复关系，事情应说“办”或“处理”，不能说“修好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事儿", "is_correct": true, "explanation": "“出什么”后接发生的事情，口语中指出了什么事，正是“事儿”。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“出饭”说不通，“饭”不是可以“出”的事情或结果。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“出桌子”没有意义，与“出什么”的语境不符。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“出”后接事件或结果，钢琴不能“出”。"}], "explanations": {"事儿": "“出什么”后接发生的事情，口语中指出了什么事，正是“事儿”。", "饭": "语义：“出饭”说不通，“饭”不是可以“出”的事情或结果。", "桌子": "语义：“出桌子”没有意义，与“出什么”的语境不符。", "钢琴": "搭配：“出”后接事件或结果，钢琴不能“出”。"}, "sentence_index": 6, "correct_answer": "事儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我有一张事儿要跟你说。", "explanation": "量词错误：“事儿”的量词应为“件”，“张”不能用于事情。"}, {"text": "他喝掉了那件事儿。", "explanation": "搭配：“喝”的对象是饮品等可以喝的东西，事情应说“办”或“处理”，不能说“喝掉”。"}, {"text": "你去把那件事儿擦干净。", "explanation": "搭配：“擦”用于可以擦拭的东西，事情应说“办好”或“处理好”，不能擦干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一张事儿想问你。", "corrected_sentence": "他有一件事儿想问你。", "error_description": "量词错误：“事儿”用“件”计量，“张”用于平面的东西，不能用于事情。错误句中的“张”应改为“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张事儿他办得很顺利。", "corrected_sentence": "这件事儿他办得很顺利。", "error_description": "量词错误：“事儿”用“件”计量，“张”不能用于事情。错误句中的“张”应改为“件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
