INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93551, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "住房是人住的房子。", "primary_collocate": null, "pronunciation": "zhù fáng", "ipa": "tʂu˥˩ fɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他们家的住房很大，有三个房间。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套住房离地铁站只有五分钟。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在市中心买一套住房。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的住房价格每年都在涨。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给新来的员工提供住房。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的住房在二楼，窗户朝南。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他租了一套小住房，一个人住。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的住房都是新盖的。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王终于有了自己的住房。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住房太小，放不下这么多书。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套住房", "label": "量词"}, {"form": "住房贷款", "label": "复合"}, {"form": "住房补贴", "label": "复合"}], "register": "中性", "sense_fingerprint": "人居住的房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8a7dd2-9f6a-4ef8-b570-0eaeae1a1cd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93551, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房只是家中的一个区域，不是整套居所，与“有三个房间”的描述不合。"}, {"text": "住房", "is_correct": true, "explanation": "“住房”指人住的房子，与“很大，有三个房间”的描述相符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是户外空地，不会“有三个房间”。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的场所，不是人住的房子，与句中“他们家”的描述不合。"}], "explanations": {"厨房": "语义：厨房只是家中的一个区域，不是整套居所，与“有三个房间”的描述不合。", "住房": "“住房”指人住的房子，与“很大，有三个房间”的描述相符。", "花园": "语义：花园是户外空地，不会“有三个房间”。", "教室": "语义：教室是上课的场所，不是人住的房子，与句中“他们家”的描述不合。"}, "sentence_index": 0, "correct_answer": "住房"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座住房原来是仓库，现在改成了书店。", "explanation": "这里应该用〈房屋〉。“住房”专指供人居住的房子，仓库和书店不能叫住房；泛指房子时用“房屋”。"}, {"text": "这套住房的病床排得很满，医生每天来查房。", "explanation": "这里应该用〈病房〉。住房供人居住，摆满病床、医生查房的场所要用“病房”。"}, {"text": "这栋住房有二十层，每天有很多学生来上课。", "explanation": "这里应该用〈教学楼〉。住房供人居住，学生上课的场所要用“教学楼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93551, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仓库", "is_correct": false, "explanation": "搭配：量词“套”多用于住宅，不说“一套仓库”，而且仓库不能住人。"}, {"text": "车库", "is_correct": false, "explanation": "语义：车库是停车的地方，与“一个人住”矛盾。"}, {"text": "住房", "is_correct": true, "explanation": "“住房”是人住的房子，符合“租了一套小住房，一个人住”的语境。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室是工作的场所，不用于“一个人住”。"}], "explanations": {"仓库": "搭配：量词“套”多用于住宅，不说“一套仓库”，而且仓库不能住人。", "车库": "语义：车库是停车的地方，与“一个人住”矛盾。", "住房": "“住房”是人住的房子，符合“租了一套小住房，一个人住”的语境。", "办公室": "语义：办公室是工作的场所，不用于“一个人住”。"}, "sentence_index": 6, "correct_answer": "住房"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间住房在二楼，每天很多学生在这里上课。", "explanation": "这里应该用〈教室〉。住房供人居住，学生上课的场所要用“教室”。"}, {"text": "这座住房的大厅里摆满了书架，每天有很多人来借书。", "explanation": "这里应该用〈图书馆〉。住房供人居住，摆满书架、供人借书的场所要用“图书馆”。"}, {"text": "这座住房的跑道很长，每天有很多运动员在这里训练。", "explanation": "这里应该用〈体育场〉。住房供人居住，有跑道、供运动员训练的场所要用“体育场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们刚搬进一只新住房。", "corrected_sentence": "他们刚搬进一套新住房。", "error_description": "错误形式：“一只新住房”。正确形式：“一套新住房”。住房作为房产的量词是“套”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我住房。", "corrected_sentence": "这是我的住房。", "error_description": "错误形式：“这是我住房”，漏掉了“的”。正确形式：“这是我的住房”。“我”修饰“住房”这类普通名词时，中间一般要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
