INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93552, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人居住的房屋。", "primary_collocate": null, "pronunciation": "zhù fáng", "ipa": "tʂu˥˩ fɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "政府为老人建了很多住房。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些住房是给学生住的。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里的住房越来越贵。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在检查住房的安全。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，很多人没有住房。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些住房周围环境很安静。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新住房有电梯，老人很方便。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司帮年轻人解决住房问题。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校附近的住房不多。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个家庭都需要一套合适的住房。", "target_word": "住房", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套住房", "label": "量词"}, {"form": "住房贷款", "label": "复合"}, {"form": "住房补贴", "label": "复合"}], "register": "中性", "sense_fingerprint": "供人居住的房屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8a7dd2-9f6a-4ef8-b570-0eaeae1a1cd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，与“为老人”建造的用途不合。"}, {"text": "住房", "is_correct": true, "explanation": "“住房”指供人居住的房屋，与“政府为老人建了很多”相符。"}, {"text": "仓库", "is_correct": false, "explanation": "语义：仓库用于存放货物，不是为老人准备的建筑。"}, {"text": "厂房", "is_correct": false, "explanation": "搭配：“厂房”专指工业生产用房，不用于为老人建造的居住设施，搭配不当。"}], "explanations": {"工厂": "语义：工厂是生产场所，与“为老人”建造的用途不合。", "住房": "“住房”指供人居住的房屋，与“政府为老人建了很多”相符。", "仓库": "语义：仓库用于存放货物，不是为老人准备的建筑。", "厂房": "搭配：“厂房”专指工业生产用房，不用于为老人建造的居住设施，搭配不当。"}, "sentence_index": 0, "correct_answer": "住房"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座住房的站台上挤满了等车的人，列车一直在进站。", "explanation": "这里应该用〈车站〉。住房供人居住，有站台、列车进站的场所要用“车站”。"}, {"text": "这座住房的生产线上机器轰鸣，每天能做出几千个零件。", "explanation": "这里应该用〈工厂〉。住房供人居住，有生产线、大量生产零件的场所要用“工厂”。"}, {"text": "这座住房的跑道上每天都有很多运动员在训练。", "explanation": "这里应该用〈体育场〉。住房供人居住，有跑道、供运动员训练的场所要用“体育场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，不是老人居住的地方，“老人很方便”的说法与句意不合。"}, {"text": "住房", "is_correct": true, "explanation": "“住房”是供人居住的房屋，有电梯便于老人居住，符合句意。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是露天运动的场地，不会“有电梯”，也不是老人居住的地方。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不是供老人居住的房屋，与句意不合。"}], "explanations": {"工厂": "语义：工厂是生产场所，不是老人居住的地方，“老人很方便”的说法与句意不合。", "住房": "“住房”是供人居住的房屋，有电梯便于老人居住，符合句意。", "操场": "语义：操场是露天运动的场地，不会“有电梯”，也不是老人居住的地方。", "教室": "语义：教室是上课的地方，不是供老人居住的房屋，与句意不合。"}, "sentence_index": 6, "correct_answer": "住房"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个住房有很多工人，每天生产零件。", "explanation": "这里应该用〈车间〉。住房供人居住，生产零件的场所要用“车间”。"}, {"text": "这座住房的手术室里灯光很亮，医生正在做手术。", "explanation": "这里应该用〈医院〉。住房供人居住，有手术室、做手术的场所要用“医院”。"}, {"text": "这座住房的审判庭每天都开庭，很多案件在这里审理。", "explanation": "这里应该用〈法院〉。住房供人居住，审理案件的机构要用“法院”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在城里买了一住房。", "corrected_sentence": "他们在城里买了一套住房。", "error_description": "错误形式：“一住房”，漏掉了量词“套”。正确形式：“一套住房”。住房作为可数的房产要用量词“套”，不能直接用数词“一”加名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于分到了一张住房。", "corrected_sentence": "他们终于分到了一套住房。", "error_description": "错误形式：“一张住房”。正确形式：“一套住房”。住房的量词是“套”，“张”用于纸张、桌子等平面物品，不能用于住房。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
