INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93553, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "其次是排在第一个后面的，是第二个。", "primary_collocate": null, "pronunciation": "qí cì", "ipa": "t͡ɕʰi˧˥ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "首先要洗手，其次要吃饭。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首先要看天气，其次要看时间。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店首先便宜，其次干净。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首先我没钱，其次我也没时间。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语首先要多听，其次要多说。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首先要买票，其次才能进去。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首先请大家安静，其次请关手机。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市首先是风景好，其次是人好。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我首先去银行，其次去超市。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选房子首先看价格，其次看位置。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "其次：列举理由或步骤时，接在“首先”之后引出第二项", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1163fc0d-9628-401a-8cdf-c361cf20c442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93553, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "其次", "is_correct": true, "explanation": "正确答案。其次指排在第一之后的第二项。"}, {"text": "歧视", "is_correct": false, "explanation": "shì（第四声）与 cì（第四声）声母不同（sh／c），意思是歧视。"}, {"text": "其实", "is_correct": false, "explanation": "shí（第二声）与 cì（第四声）声母和声调都不同，意思是其实、实际上。"}, {"text": "七次", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是七次。"}, {"text": "几次", "is_correct": false, "explanation": "jǐ（第三声）与 qí（第二声）声母和声调都不同，意思是几次。"}, {"text": "奇迹", "is_correct": false, "explanation": "jì 与 cì 声母不同（j／c），意思是奇迹。"}], "explanations": {"其次": "正确答案。其次指排在第一之后的第二项。", "歧视": "shì（第四声）与 cì（第四声）声母不同（sh／c），意思是歧视。", "其实": "shí（第二声）与 cì（第四声）声母和声调都不同，意思是其实、实际上。", "七次": "qī（第一声）与 qí（第二声）声调不同，意思是七次。", "几次": "jǐ（第三声）与 qí（第二声）声母和声调都不同，意思是几次。", "奇迹": "jì 与 cì 声母不同（j／c），意思是奇迹。"}, "sentence_index": null, "correct_answer": "其次"}, "level_3": {"options": [{"text": "其次", "is_correct": true, "explanation": "其次：与“首先”呼应，引出列举中的第二项，符合句意。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，与“首先”的列举顺序不合。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，与“首先”并列列举的结构不合。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”需与后句的“但是”等呼应，此处没有对应的转折词。"}], "explanations": {"其次": "其次：与“首先”呼应，引出列举中的第二项，符合句意。", "但是": "语义：“但是”表示转折，与“首先”的列举顺序不合。", "因为": "语义：“因为”引出原因，与“首先”并列列举的结构不合。", "虽然": "搭配：“虽然”需与后句的“但是”等呼应，此处没有对应的转折词。"}, "sentence_index": 0, "correct_answer": "其次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班上其次的同学都去了。", "explanation": "这里应该用〈其余〉。“其次”表示排在第一个后面的次序，不表示剩下的人；剩下的人要用“其余”。"}, {"text": "他看起来很年轻，其次已经四十岁了。", "explanation": "这里应该用〈其实〉。“其次”不用于引出与表面相反的真实情况，这里要用“其实”。"}, {"text": "他没有复习，其次考试没及格。", "explanation": "这里应该用〈因此〉。“其次”只用于列举，不表示因果关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93553, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其次", "is_correct": true, "explanation": "其次：与“首先”呼应，引出列举中的第二项，符合句意。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示转折，与“首先”并列列举的结构不合。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，安静并不是关手机的原因。"}, {"text": "即使", "is_correct": false, "explanation": "搭配：“即使”需与后句的“也”呼应，此句没有对应成分。"}], "explanations": {"其次": "其次：与“首先”呼应，引出列举中的第二项，符合句意。", "不过": "语义：“不过”表示转折，与“首先”并列列举的结构不合。", "所以": "语义：“所以”表示因果，安静并不是关手机的原因。", "即使": "搭配：“即使”需与后句的“也”呼应，此句没有对应成分。"}, "sentence_index": 6, "correct_answer": "其次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气很好，其次很冷。", "explanation": "这里应该用〈但是〉。“其次”表示列举的次序，不表示转折。"}, {"text": "他迟到了，其次错过了车。", "explanation": "这里应该用〈所以〉。“其次”不表示因果，此处是前因后果的关系。"}, {"text": "我们其次感谢大家。", "explanation": "这里应该用〈首先〉。“其次”必须排在第一项之后，不能单独用来开启列举；这里要用“首先”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告首先要检查数据，其次了要检查格式。", "corrected_sentence": "这份报告首先要检查数据，其次要检查格式。", "error_description": "“其次”是连词，后面不能加“了”。应去掉“了”，写为“其次要检查格式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要先选地点，其次了安排日程。", "corrected_sentence": "我们要先选地点，其次安排日程。", "error_description": "“其次”是连词，后面不能加“了”。应为“其次安排日程”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
