INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93554, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "表示次序在最重要的之后；第二。", "primary_collocate": null, "pronunciation": "qí cì", "ipa": "t͡ɕʰi˧˥ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "对我来说，健康最重要，工作其次。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买手机，质量第一，价格其次。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习成绩是其次，身体更重要。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输赢其次，大家玩得开心最重要。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找工作，钱多是其次，我更看重兴趣。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人最重要，朋友其次。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最爱音乐，其次是画画。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行，吃饭是其次，看风景才是重点。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭味道最要紧，样子其次。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先保证安全，速度其次。", "target_word": "其次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "其次：重要程度排在最重要的之后，居第二位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1163fc0d-9628-401a-8cdf-c361cf20c442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCL