INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93554, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "其次", "is_correct": true, "explanation": "正确答案。其次指重要程度排在最重要的之后，居第二位。"}, {"text": "歧视", "is_correct": false, "explanation": "shì（第四声）与 cì（第四声）声母不同（sh／c），意思是歧视。"}, {"text": "其实", "is_correct": false, "explanation": "shí（第二声）与 cì（第四声）声母和声调都不同，意思是其实、实际上。"}, {"text": "七次", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是七次。"}, {"text": "几次", "is_correct": false, "explanation": "jǐ（第三声）与 qí（第二声）声母和声调都不同，意思是几次。"}, {"text": "奇迹", "is_correct": false, "explanation": "jì 与 cì 声母不同（j／c），意思是奇迹。"}], "explanations": {"其次": "正确答案。其次指重要程度排在最重要的之后，居第二位。", "歧视": "shì（第四声）与 cì（第四声）声母不同（sh／c），意思是歧视。", "其实": "shí（第二声）与 cì（第四声）声母和声调都不同，意思是其实、实际上。", "七次": "qī（第一声）与 qí（第二声）声调不同，意思是七次。", "几次": "jǐ（第三声）与 qí（第二声）声母和声调都不同，意思是几次。", "奇迹": "jì 与 cì 声母不同（j／c），意思是奇迹。"}, "sentence_index": null, "correct_answer": "其次"}, "level_3": {"options": [{"text": "其次", "is_correct": true, "explanation": "其次：指重要程度排在最重要的之后，符合句意。"}, {"text": "首要", "is_correct": false, "explanation": "语义：“首要”说工作排在最前，与“最重要”的健康相矛盾。"}, {"text": "第一", "is_correct": false, "explanation": "语义：“第一”与前句“最重要”的健康占据首位，两者冲突。"}, {"text": "最要紧", "is_correct": false, "explanation": "语义：前句说健康最重要，这里说工作也“最要紧”，两者相矛盾。"}], "explanations": {"其次": "其次：指重要程度排在最重要的之后，符合句意。", "首要": "语义：“首要”说工作排在最前，与“最重要”的健康相矛盾。", "第一": "语义：“第一”与前句“最重要”的健康占据首位，两者冲突。", "最要紧": "语义：前句说健康最重要，这里说工作也“最要紧”，两者相矛盾。"}, "sentence_index": 0, "correct_answer": "其次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里其次的同学都回家了。", "explanation": "这里应该用〈其余〉。“其次”表示次要、排在最重要之后，不表示剩下的人；剩下的人要用“其余”。"}, {"text": "他很努力，其次获得了第一名。", "explanation": "这里应该用〈然后〉。“其次”表示重要程度居第二，不表示动作的先后接续；先后动作要用“然后”。"}, {"text": "其次最重要的是健康。", "explanation": "这里应该用〈首先〉。“其次”表示排在最重要的之后，不能用来引出最重要的一项；最重要的一项要用“首先”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其次", "is_correct": true, "explanation": "其次：引出排在“最爱音乐”之后的第二项，符合句意。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示“只是”，与“最爱音乐”的强调不合。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”需与前句的否定形式呼应，此句前句是肯定句，不能搭配。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，爱音乐与画画之间不是因果关系。"}], "explanations": {"其次": "其次：引出排在“最爱音乐”之后的第二项，符合句意。", "不过": "语义：“不过”表示“只是”，与“最爱音乐”的强调不合。", "而是": "搭配：“而是”需与前句的否定形式呼应，此句前句是肯定句，不能搭配。", "因此": "语义：“因此”表示因果，爱音乐与画画之间不是因果关系。"}, "sentence_index": 6, "correct_answer": "其次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想去，其次没有时间。", "explanation": "这里应该用〈但是〉。“其次”表示排序，不表示转折。"}, {"text": "雨下得很大，其次我们没有出门。", "explanation": "这里应该用〈所以〉。“其次”不表示因果，此处是前因后果的关系。"}, {"text": "他一边唱歌，其次跳舞。", "explanation": "这里应该用〈一边〉。“一边……一边……”表示两个动作同时进行；“其次”表示重要程度排第二，不能与“一边”呼应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "成本最重要，进度不其次。", "corrected_sentence": "成本最重要，进度其次。", "error_description": "“其次”作谓语时不能直接用“不”否定，此句在“其次”前加了“不”，应去掉，说“进度其次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
